window.INCIL_DATA = [{"id":"matta","name":"Matta","chapters":[{"ch":1,"verses":[{"n":"1-2","t":"İbrahim oğlu, Davut oğlu İsa Mesih'in soy kaydı şöyledir:İbrahim İshak'ın babasıydı,İshak Yakup'un babasıydı,Yakup Yahuda ve kardeşlerinin babasıydı,"},{"n":"3","t":"Yahuda, Tamar'dan doğan Peres'le Zerah'ın babasıydı,Peres Hesron'un babasıydı,Hesron Ram'ın babasıydı,"},{"n":"4","t":"Ram Amminadav'ın babasıydı,Amminadav Nahşon'un babasıydı,Nahşon Salmon'un babasıydı,"},{"n":"5","t":"Salmon, Rahav'dan doğan Boaz'ın babasıydı,Boaz, Rut'tan doğan Ovet'in babasıydı,Ovet İşay'ın babasıydı,"},{"n":"6","t":"İşay Kral Davut'un babasıydı,Davut, Uriya'nın karısından doğan Süleyman'ın babasıydı,"},{"n":"7","t":"Süleyman Rehavam'ın babasıydı,Rehavam Aviya'nın babasıydı,Aviya Asa'nın babasıydı,"},{"n":"8","t":"Asa Yehoşafat'ın babasıydı,Yehoşafat Yoram'ın babasıydı,Yoram Uzziya'nın babasıydı,"},{"n":"9","t":"Uzziya Yotam'ın babasıydı,Yotam Ahaz'ın babasıydı,Ahaz Hizkiya'nın babasıydı,"},{"n":"10","t":"Hizkiya Manaşşe'nin babasıydı,Manaşşe Amon'un babasıydı,Amon Yoşiya'nın babasıydı,"},{"n":"11","t":"Yoşiya, Babil sürgünü* sırasında doğan Yehoyakin'le kardeşlerinin babasıydı,"},{"n":"12","t":"Yehoyakin, Babil sürgününden sonra doğan Şealtiel'in babasıydı,Şealtiel Zerubbabil'in babasıydı,"},{"n":"13","t":"Zerubbabil Avihut'un babasıydı,Avihut Elyakim'in babasıydı,Elyakim Azor'un babasıydı,"},{"n":"14","t":"Azor Sadok'un babasıydı,Sadok Ahim'in babasıydı,Ahim Elihut'un babasıydı,"},{"n":"15","t":"Elihut Elazar'ın babasıydı,Elazar Mattan'ın babasıydı,Mattan Yakup'un babasıydı,"},{"n":"16","t":"Yakup Meryem'in kocası Yusuf'un babasıydı.Meryem'den Mesih* diye tanınan İsa doğdu."},{"n":"17","t":"Buna göre, İbrahim'den Davut'a kadar toplam on dört kuşak, Davut'tan Babil sürgününe kadar on dört kuşak, Babil sürgününden Mesih'e kadar on dört kuşak vardır. İsa Mesih'in Doğumu (Luk.2:1-7)"},{"n":"18","t":"İsa Mesih'in doğumu şöyle oldu: Annesi Meryem, Yusuf'la nişanlıydı. Ama birlikte olmalarından önce Meryem'in Kutsal Ruh'tan gebe olduğu anlaşıldı."},{"n":"19","t":"Nişanlısı Yusuf, doğru bir adam olduğu ve onu herkesin önünde utandırmak istemediği için ondan sessizce ayrılmak niyetindeydi."},{"n":"20","t":"Ama böyle düşünmesi üzerine Rab'bin bir meleği rüyada ona görünerek şöyle dedi: \"Davut oğlu Yusuf, Meryem'i kendine eş olarak almaktan korkma. Çünkü onun rahminde oluşan, Kutsal Ruh'tandır."},{"n":"21","t":"Meryem bir oğul doğuracak. Adını İsa*fx* koyacaksın. Çünkü halkını günahlarından O kurtaracak.\""},{"n":"22","t":"Bütün bunlar, Rab'bin peygamber aracılığıyla bildirdiği şu söz yerine gelsin diye oldu:"},{"n":"23","t":"\"İşte, kız gebe kalıp bir oğul doğuracak; adını İmmanuel koyacaklar.\"İmmanuel, Tanrı bizimle demektir."},{"n":"24","t":"Yusuf uyanınca Rab'bin meleğinin buyruğuna uydu ve Meryem'i eş olarak yanına aldı."},{"n":"25","t":"Ama oğlunu doğuruncaya dek Yusuf ona dokunmadı. Doğan çocuğun adını İsa koydu."}]},{"ch":2,"verses":[{"n":"1-2","t":"İsa'nın Kral Hirodes* devrinde Yahudiye'nin Beytlehem Kenti'nde doğmasından sonra bazı yıldızbilimciler doğudan Yeruşalim'e* gelip şöyle dediler: \"Yahudiler'in Kralı olarak doğan çocuk nerede? Doğuda O'nun yıldızını gördük*fx* ve O'na tapınmaya geldik.\""},{"n":"3","t":"Kral Hirodes bunu duyunca kendisi de bütün Yeruşalim halkı da tedirgin oldu."},{"n":"4","t":"Bütün başkâhinleri ve halkın din bilginlerini* toplayarak onlara Mesih'in nerede doğacağını sordu."},{"n":"5","t":"\"Yahudiye'nin Beytlehem Kenti'nde\" dediler. \"Çünkü peygamber aracılığıyla şöyle yazılmıştır:"},{"n":"6","t":"'Ey sen, Yahuda'daki Beytlehem,Yahuda önderleri arasında hiç de en önemsizi değilsin! Çünkü halkım İsrail'i güdecek önder Senden çıkacak.'\""},{"n":"7","t":"Bunun üzerine Hirodes yıldızbilimcileri gizlice çağırıp onlardan yıldızın göründüğü anı tam olarak öğrendi."},{"n":"8","t":"\"Gidin, çocuğu dikkatle arayın, bulunca bana haber verin, ben de gelip O'na tapınayım\" diyerek onları Beytlehem'e gönderdi."},{"n":"9","t":"Yıldızbilimciler, kralı dinledikten sonra yola çıktılar. Doğuda*fx* görmüş oldukları yıldız onlara yol gösteriyordu, çocuğun bulunduğu yerin üzerine varınca durdu."},{"n":"10","t":"Yıldızı gördüklerinde olağanüstü bir sevinç duydular."},{"n":"11","t":"Eve girip çocuğu annesi Meryem'le birlikte görünce yere kapanarak O'na tapındılar. Hazinelerini açıp O'na armağan olarak altın, günnük ve mür* sundular."},{"n":"12","t":"Sonra gördükleri bir düşte Hirodes'in yanına dönmemeleri için uyarılınca ülkelerine başka yoldan döndüler. Mısır'a Kaçış"},{"n":"13","t":"Yıldızbilimciler gittikten sonra Rab'bin bir meleği Yusuf'a rüyada görünerek, \"Kalk!\" dedi, \"Çocukla annesini al, Mısır'a kaç. Ben sana haber verinceye dek orada kal. Çünkü Hirodes öldürmek için çocuğu aratacak.\""},{"n":"14","t":"Böylece Yusuf kalktı, aynı gece çocukla annesini alıp Mısır'a doğru yola çıktı."},{"n":"15","t":"Hirodes'in ölümüne dek orada kaldı. Bu, Rab'bin peygamber aracılığıyla bildirdiği şu söz yerine gelsin diye oldu: \"Oğlumu Mısır'dan çağırdım.\""},{"n":"16","t":"Hirodes, yıldızbilimciler tarafından aldatıldığını anlayınca çok öfkelendi. Onlardan öğrendiği vakti göz önüne alarak Beytlehem ve bütün yöresinde bulunan iki ve iki yaşından küçük erkek çocukların hepsini öldürttü."},{"n":"17","t":"Böylelikle Peygamber Yeremya aracılığıyla bildirilen şu söz yerine gelmiş oldu:"},{"n":"18","t":"\"Rama'da bir ses duyuldu, Ağlayış ve acı feryat sesleri! Çocukları için ağlayan Rahel Avutulmak istemiyor. Çünkü onlar yok artık!\" Nasıra'ya Dönüş"},{"n":"19-20","t":"Hirodes öldükten sonra, Rab'bin bir meleği Mısır'da Yusuf'a rüyada görünerek, \"Kalk!\" dedi, \"Çocukla annesini al, İsrail'e dön. Çünkü çocuğun canına kıymak isteyenler öldü.\""},{"n":"21","t":"Bunun üzerine Yusuf kalktı, çocukla annesini alıp İsrail'e döndü."},{"n":"22","t":"Ama Yahudiye'de Hirodes'in yerine oğlu Arhelas'ın kral olduğunu duyunca oraya gitmekten korktu. Rüyada uyarılınca Celile bölgesine gitti."},{"n":"23","t":"Oraya varınca Nasıra denen kente yerleşti. Bu, peygamberler aracılığıyla bildirilen, \"O'na Nasıralı denecektir\" sözü yerine gelsin diye oldu."}]},{"ch":3,"verses":[{"n":"1-2","t":"O günlerde Vaftizci Yahya Yahudiye Çölü'nde ortaya çıktı. Şu çağrıyı yapıyordu: \"Tövbe edin! Göklerin Egemenliği yaklaşmıştır.\""},{"n":"3","t":"Nitekim Peygamber Yeşaya aracılığıyla sözü edilen kişi Yahya'dır. Yeşaya şöyle demişti: \"Çölde haykıran,'Rab'bin yolunu hazırlayın,Geçeceği patikaları düzleyin' diye sesleniyor.\""},{"n":"4","t":"Yahya'nın deve tüyünden giysisi, belinde deri kuşağı vardı. Yediği,çekirge ve yaban balıydı."},{"n":"5-6","t":"Yeruşalim, bütün Yahudiye ve Şeria yöresinin halkı ona geliyor,günahlarını itiraf ediyor, onun tarafından Şeria Irmağı'nda vaftiz ediliyordu."},{"n":"7","t":"Ne var ki, birçok Ferisi'yle Saduki'nin* vaftiz olmak için kendisine geldiğini gören Yahya onlara şöyle seslendi: \"Ey engerekler soyu! Gelecek gazaptan kaçmak için sizi kim uyardı?"},{"n":"8","t":"Bundan böyle tövbeye yaraşır meyveler verin."},{"n":"9","t":"Kendi kendinize, 'Biz İbrahim'in soyundanız' diye düşünmeyin. Ben size şunu söyleyeyim: Tanrı, İbrahim'e şu taşlardan da çocuk yaratabilir."},{"n":"10","t":"Balta ağaçların köküne dayanmış bile. İyi meyve vermeyen her ağaç kesilip ateşe atılır."},{"n":"11","t":"Gerçi ben sizi tövbe için suyla vaftiz ediyorum, ama benden sonra gelen benden daha güçlüdür. Ben O'nun çarıklarını çıkarmaya bile layık değilim. O sizi Kutsal Ruh'la ve ateşle vaftiz edecek."},{"n":"12","t":"Yabası elindedir. Harman yerini temizleyecek, buğdayını toplayıp ambara yığacak, samanı ise sönmeyen ateşte yakacak.\" İsa Vaftiz Oluyor (Mar.1:9-11; Luk.3:21-22)"},{"n":"13","t":"Bu sırada İsa, Yahya tarafından vaftiz edilmek üzere Celile'den Şeria Irmağı'na, Yahya'nın yanına geldi."},{"n":"14","t":"Ne var ki Yahya, \"Benim senin tarafından vaftiz edilmem gerekirken sen mi bana geliyorsun?\" diyerek O'na engel olmak istedi."},{"n":"15","t":"İsa ona şu karşılığı verdi: \"Şimdilik buna razı ol! Çünkü doğru olan her şeyi bu şekilde yerine getirmemiz gerekir.\" O zaman Yahya O'nun dediğine razı oldu."},{"n":"16","t":"İsa vaftiz olur olmaz sudan çıktı. O anda gökler açıldı ve İsa,Tanrı'nın Ruhu'nun güvercin gibi inip üzerine konduğunu gördü."},{"n":"17","t":"Göklerden gelen bir ses, \"Sevgili Oğlum budur, O'ndan hoşnudum\" dedi."}]},{"ch":4,"verses":[{"n":"1","t":"Bundan sonra İsa, İblis tarafından denenmek üzere Ruh aracılığıyla çöle götürüldü."},{"n":"2","t":"İsa kırk gün kırk gece oruç* tuttuktan sonra acıktı."},{"n":"3","t":"O zaman Ayartıcı*fx* yaklaşıp, \"Tanrı'nın Oğlu'ysan, söyle şu taşlar ekmek olsun\" dedi."},{"n":"4","t":"İsa ona şu karşılığı verdi: \"'İnsan yalnız ekmekle yaşamaz, Tanrı'nın ağzından çıkan her sözle yaşar' diye yazılmıştır.\""},{"n":"5-6","t":"Sonra İblis O'nu kutsal kente* götürdü. Tapınağın tepesine çıkarıp,\"Tanrı'nın Oğlu'ysan, kendini aşağı at\" dedi, \"Çünkü şöyle yazılmıştır:'Tanrı, senin için meleklerine buyruk verecek.''Ayağın bir taşa çarpmasın diyeSeni elleri üzerinde taşıyacaklar.'\""},{"n":"7","t":"İsa İblis'e şu karşılığı verdi: \"'Tanrın Rab'bi denemeyeceksin' diye de yazılmıştır.\""},{"n":"8","t":"İblis bu kez İsa'yı çok yüksek bir dağa çıkardı. O'na bütün görkemiyle dünya ülkelerini göstererek,"},{"n":"9","t":"\"Yere kapanıp bana taparsan, bütün bunları sana vereceğim\" dedi."},{"n":"10","t":"İsa ona şöyle karşılık verdi: \"Çekil git, Şeytan! 'Tanrın Rab'be tapacak, yalnız O'na kulluk edeceksin' diye yazılmıştır.\""},{"n":"11","t":"Bunun üzerine İblis İsa'yı bırakıp gitti. Melekler gelip İsa'ya hizmet ettiler. İsa Müjde'yi Duyurmaya Başlıyor (Mar.1:14-15; Luk.4:14-15)"},{"n":"12","t":"İsa, Yahya'nın tutuklandığını duyunca Celile'ye döndü."},{"n":"13","t":"Nasıra'dan ayrılarak Zevulun ve Naftali yöresinde, Celile Gölü kıyısında bulunan Kefarnahum'a yerleşti."},{"n":"14-15","t":"Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu:\"Zevulun ve Naftali bölgeleri,Şeria Irmağı'nın ötesinde, Deniz Yolu'nda,Ulusların yaşadığı Celile!"},{"n":"16","t":"Karanlıkta yaşayan halk,Büyük bir ışık gördü.Ölümün gölgelediği diyarda Yaşayanlara ışık doğdu.\""},{"n":"17","t":"O günden sonra İsa şu çağrıda bulunmaya başladı: \"Tövbe edin! Çünkü Göklerin Egemenliği yaklaştı.\" İsa İlk Öğrencilerini Seçiyor (Mar.1:16-20; Luk.5:1-11)"},{"n":"18","t":"İsa, Celile Gölü'nün kıyısında yürürken Petrus diye de anılan Simun'la kardeşi Andreas'ı gördü. Balıkçı olan bu iki kardeş göle ağ atıyorlardı."},{"n":"19","t":"Onlara, \"Ardımdan gelin\" dedi, \"Sizleri insan tutan balıkçılar yapacağım.\""},{"n":"20","t":"Onlar da hemen ağlarını bırakıp O'nun ardından gittiler."},{"n":"21","t":"İsa daha ileri gidince başka iki kardeşi, Zebedi'nin oğulları Yakup'la Yuhanna'yı gördü. Babaları Zebedi'yle birlikte teknede ağlarını onarıyorlardı.Onları da çağırdı."},{"n":"22","t":"Hemen tekneyi ve babalarını bırakıp İsa'nın ardından gittiler. İsa Hastaları İyileştiriyor (Luk.6:17-19)"},{"n":"23","t":"İsa, Celile bölgesinin her tarafını dolaştı. Buralardaki havralarda öğretiyor, göksel egemenliğin Müjdesi'ni duyuruyor, halk arasında rastlanan her hastalığı, her illeti iyileştiriyordu."},{"n":"24","t":"Ünü bütün Suriye'ye yayılmıştı. Türlü hastalıklara yakalanmış bütün hastaları, acı çekenleri, cinlileri, saralıları, felçlileri O'na getirdiler; hepsini iyileştirdi."},{"n":"25","t":"Celile, Dekapolis, Yeruşalim, Yahudiye ve Şeria Irmağı'nın karşı yakasından gelen büyük kalabalıklar O'nun ardından gidiyordu."}]},{"ch":5,"verses":[{"n":"1","t":"İsa kalabalıkları görünce dağa çıktı. Oturunca öğrencileri yanına geldi."},{"n":"2","t":"İsa konuşmaya başlayıp onlara şunları öğretti:"},{"n":"3","t":"\"Ne mutlu ruhta yoksul olanlara!Çünkü Göklerin Egemenliği onlarındır."},{"n":"4","t":"Ne mutlu yaslı olanlara!Çünkü onlar teselli edilecekler."},{"n":"5","t":"Ne mutlu yumuşak huylu olanlara!Çünkü onlar yeryüzünü miras alacaklar."},{"n":"6","t":"Ne mutlu doğruluğa acıkıp susayanlara!Çünkü onlar doyurulacaklar."},{"n":"7","t":"Ne mutlu merhametli olanlara!Çünkü onlar merhamet bulacaklar."},{"n":"8","t":"Ne mutlu yüreği temiz olanlara!Çünkü onlar Tanrı'yı görecekler."},{"n":"9","t":"Ne mutlu barışı sağlayanlara!Çünkü onlara Tanrı oğulları denecek."},{"n":"10","t":"Ne mutlu doğruluk uğruna zulüm görenlere!Çünkü Göklerin Egemenliği onlarındır."},{"n":"11","t":"\"Benim yüzümden insanlar size sövüp zulmettikleri, yalan yere size karşı her türlü kötü sözü söyledikleri zaman ne mutlu size!"},{"n":"12","t":"Sevinin, sevinçle coşun! Çünkü göklerdeki ödülünüz büyüktür. Sizden önce yaşayan peygamberlere de böyle zulmettiler.\" Tuz ve Işık (Mar.9:50; Luk.14:34-35)"},{"n":"13","t":"\"Yeryüzünün tuzu sizsiniz. Ama tuz tadını yitirirse, bir daha ona nasıl tuz tadı verilebilir? Artık dışarı atılıp ayak altında çiğnenmekten başka işe yaramaz."},{"n":"14","t":"\"Dünyanın ışığı sizsiniz. Tepeye kurulan kent gizlenemez."},{"n":"15","t":"Kimse kandil yakıp tahıl ölçeğinin altına koymaz. Tersine, kandilliğe koyar; evdekilerin hepsine ışık sağlar."},{"n":"16","t":"Sizin ışığınız insanların önünde öyle parlasın ki, iyi işlerinizi görerek göklerdeki Babanız'ı yüceltsinler!\" Kutsal Yasa"},{"n":"17","t":"\"Kutsal Yasa'yı* ya da peygamberlerin sözlerini geçersiz kılmak için geldiğimi sanmayın. Ben geçersiz kılmaya değil, tamamlamaya geldim."},{"n":"18","t":"Size doğrusunu söyleyeyim, yer ve gök ortadan kalkmadan, her şey gerçekleşmeden, Kutsal Yasa'dan ufacık bir harf ya da bir nokta bile yok olmayacak."},{"n":"19","t":"Bu nedenle, bu buyrukların en küçüğünden birini kim çiğner ve başkalarına öyle öğretirse, Göklerin Egemenliği'nde en küçük sayılacak. Ama bu buyrukları kim yerine getirir ve başkalarına öğretirse, Göklerin Egemenliği'nde büyük sayılacak."},{"n":"20","t":"Size şunu söyleyeyim: Doğruluğunuz din bilginleriyle* Ferisiler'inkini* aşmadıkça, Göklerin Egemenliği'ne asla giremezsiniz!\" Öfke ve Cinayet"},{"n":"21","t":"\"Atalarımıza, 'Adam öldürmeyeceksin. Öldüren yargılanacak' dendiğini duydunuz."},{"n":"22","t":"Ama ben size diyorum ki, kardeşine öfkelenen herkes yargılanacaktır. Kim kardeşine aşağılayıcı bir söz*fx* söylerse, Yüksek Kurul'da* yargılanacaktır.Kim kardeşine ahmak derse, cehennem ateşini hak edecektir."},{"n":"23-24","t":"Bu yüzden, sunakta adak sunarken kardeşinin sana karşı bir şikâyeti olduğunu anımsarsan, adağını orada, sunağın önünde bırak, git önce kardeşinle barış; sonra gelip adağını sun."},{"n":"25","t":"Senden davacı olanla daha yoldayken çabucak anlaş. Yoksa o seni yargıca, yargıç da gardiyana teslim edebilir; sonunda da hapse atılabilirsin."},{"n":"26","t":"Sana doğrusunu söyleyeyim, borcunun son kuruşunu*fx* ödemeden oradan asla çıkamazsın.\" Zina ve Boşanma"},{"n":"27","t":"\"'Zina etmeyeceksin' dendiğini duydunuz."},{"n":"28","t":"Ama ben size diyorum ki, bir kadına şehvetle bakan her adam, yüreğinde o kadınla zina etmiş olur."},{"n":"29","t":"Eğer sağ gözün günah işlemene neden olursa, onu çıkar at. Çünkü vücudunun bir üyesinin yok olması, bütün vücudunun cehenneme atılmasından iyidir."},{"n":"30","t":"Eğer sağ elin günah işlemene neden olursa, onu kes at. Çünkü vücudunun bir üyesinin yok olması, bütün vücudunun cehenneme gitmesinden iyidir."},{"n":"31","t":"\"'Kim karısını boşarsa ona boşanma belgesi versin' denmiştir."},{"n":"32","t":"Ama ben size diyorum ki, karısını fuhuş dışında bir nedenle boşayan onu zinaya itmiş olur. Boşanmış bir kadınla evlenen de zina etmiş olur.\" Ant İçmek"},{"n":"33","t":"\"Yine atalarımıza, 'Yalan yere ant içmeyeceksin, ama Rab'bin önünde içtiğin antları yerine getireceksin' dendiğini duydunuz."},{"n":"34-35","t":"Oysa ben size diyorum ki, hiç ant içmeyin: Ne gök üzerine, çünkü orası Tanrı'nın tahtıdır; ne yer üzerine, çünkü orası O'nun ayak taburesidir;ne de Yeruşalim üzerine, çünkü orası Büyük Kral'ın kentidir."},{"n":"36","t":"Başınızın üzerine de ant içmeyin. Çünkü saçınızın tek telini ak ya da kara edemezsiniz."},{"n":"37","t":"'Evet'iniz evet, 'hayır'ınız hayır olsun. Bundan fazlası Şeytan'dandır*fx*.\" Göze Göz, Dişe Diş (Luk.6:29-30)"},{"n":"38","t":"\"'Göze göz, dişe diş' dendiğini duydunuz."},{"n":"39","t":"Ama ben size diyorum ki, kötüye karşı direnmeyin. Sağ yanağınıza bir tokat atana öbür yanağınızı da çevirin."},{"n":"40","t":"Size karşı davacı olup mintanınızı almak isteyene abanızı da verin."},{"n":"41","t":"Sizi bin adım yol yürümeye zorlayanla iki bin adım yürüyün."},{"n":"42","t":"Sizden bir şey dileyene verin, sizden ödünç isteyeni geri çevirmeyin.\" Düşmanlarınızı Sevin (Luk.6:27-28,32-36)"},{"n":"43","t":"\"'Komşunu seveceksin, düşmanından nefret edeceksin' dendiğini duydunuz."},{"n":"44","t":"Ama ben size diyorum ki, düşmanlarınızı sevin, size zulmedenler için dua edin."},{"n":"45","t":"Öyle ki, göklerdeki Babanız'ın oğulları olasınız. Çünkü O, güneşini hem kötülerin hem iyilerin üzerine doğdurur; yağmurunu hem doğruların hem eğrilerin üzerine yağdırır."},{"n":"46","t":"Eğer yalnız sizi sevenleri severseniz, ne ödülünüz olur? Vergi görevlileri* de öyle yapmıyor mu?"},{"n":"47","t":"Yalnız kardeşlerinize selam verirseniz, fazladan ne yapmış olursunuz?Putperestler de öyle yapmıyor mu?"},{"n":"48","t":"Bu nedenle, göksel Babanız yetkin olduğu gibi, siz de yetkin olun.\""}]},{"ch":6,"verses":[{"n":"1","t":"\"Doğruluğunuzu insanların gözü önünde gösteriş amacıyla sergilemekten kaçının. Yoksa göklerdeki Babanız'dan ödül alamazsınız."},{"n":"2","t":"\"Bu nedenle, birisine sadaka verirken bunu borazan çaldırarak ilan etmeyin. İkiyüzlüler, insanların övgüsünü kazanmak için havralarda ve sokaklarda böyle yaparlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"3","t":"Siz sadaka verirken, sol eliniz sağ elinizin ne yaptığını bilmesin."},{"n":"4","t":"Öyle ki, verdiğiniz sadaka gizli kalsın. Gizlice yapılanı gören Babanız sizi ödüllendirecektir.\" Dua (Luk.11:2-4)"},{"n":"5","t":"\"Dua ettiğiniz zaman ikiyüzlüler gibi olmayın. Onlar, herkes kendilerini görsün diye havralarda ve caddelerin köşe başlarında dikilip dua etmekten zevk alırlar. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"6","t":"Ama siz dua edeceğiniz zaman iç odanıza çekilip kapıyı örtün ve gizlide olan Babanız'a dua edin. Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir."},{"n":"7","t":"Dua ettiğinizde, putperestler gibi boş sözler tekrarlayıp durmayın. Onlar söz kalabalığıyla seslerini duyurabileceklerini sanırlar."},{"n":"8","t":"Siz onlara benzemeyin! Çünkü Babanız nelere gereksinmeniz olduğunu siz daha O'ndan dilemeden önce bilir."},{"n":"9","t":"\"Bunun için siz şöyle dua edin:'Göklerdeki Babamız,Adın kutsal kılınsın."},{"n":"10","t":"Egemenliğin gelsin.Gökte olduğu gibi, yeryüzünde deSenin istediğin olsun."},{"n":"11","t":"Bugün bize gündelik ekmeğimizi ver."},{"n":"12","t":"Bize karşı suç işleyenleri bağışladığımız gibi,Sen de bizim suçlarımızı bağışla."},{"n":"13","t":"Ayartılmamıza izin verme.Bizi kötü olandan kurtar.Çünkü egemenlik, güç ve yücelik Sonsuzlara dek senindir! Amin*fx*'."},{"n":"14","t":"\"Başkalarının suçlarını bağışlarsanız, göksel Babanız da sizin suçlarınızı bağışlar."},{"n":"15","t":"Ama siz başkalarının suçlarını bağışlamazsanız, Babanız da sizin suçlarınızı bağışlamaz.\" Oruç"},{"n":"16","t":"\"Oruç* tuttuğunuz zaman, ikiyüzlüler gibi surat asmayın. Onlar oruç tuttuklarını insanlara belli etmek için kendilerine perişan bir görünüm verirler. Size doğrusunu söyleyeyim, onlar ödüllerini almışlardır."},{"n":"17","t":"Siz oruç tuttuğunuz zaman, başınıza yağ sürüp yüzünüzü yıkayın."},{"n":"18","t":"Öyle ki, insanlara değil, gizlide olan Babanız'a oruçlu görünesiniz.Gizlilik içinde yapılanı gören Babanız sizi ödüllendirecektir.\" Göksel Hazineler (Luk.12:33-36; 16:13)"},{"n":"19","t":"\"Yeryüzünde kendinize hazineler biriktirmeyin. Burada güve ve pas onları yiyip bitirir, hırsızlar da girip çalarlar."},{"n":"20","t":"Bunun yerine kendinize gökte hazineler biriktirin. Orada ne güve ne pas onları yiyip bitirir, ne de hırsızlar girip çalar."},{"n":"21","t":"Hazineniz neredeyse, yüreğiniz de orada olacaktır."},{"n":"22","t":"\"Bedenin ışığı gözdür. Gözünüz sağlamsa*fx*, bütün bedeniniz aydınlık olur."},{"n":"23","t":"Gözünüz bozuksa*fx*, bütün bedeniniz karanlık olur. Buna göre,içinizdeki 'ışık' karanlıksa, ne korkunçtur o karanlık!"},{"n":"24","t":"\"Hiç kimse iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrı'ya, hem de paraya*fx* kulluk edemezsiniz.\" Kaygılanmayın (Luk.12:22-31)"},{"n":"25","t":"\"Bu nedenle size şunu söylüyorum: 'Ne yiyip ne içeceğiz?' diye canınız için, 'Ne giyeceğiz?' diye bedeniniz için kaygılanmayın. Can yiyecekten, beden de giyecekten daha önemli değil mi?"},{"n":"26","t":"Gökte uçan kuşlara bakın! Ne eker, ne biçer, ne de ambarlarda yiyecek biriktirirler. Göksel Babanız yine de onları doyurur. Siz onlardan çok daha değerli değil misiniz?"},{"n":"27","t":"Hangi biriniz kaygılanmakla ömrünü bir anlık*fx* uzatabilir?"},{"n":"28","t":"Giyecek konusunda neden kaygılanıyorsunuz? Kır zambaklarının nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler."},{"n":"29","t":"Ama size şunu söyleyeyim, bütün görkemine karşın Süleyman bile bunlardan biri gibi giyinmiş değildi."},{"n":"30","t":"Bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrı'nın sizi de giydireceği çok daha kesin değil mi, ey kıt imanlılar?"},{"n":"31","t":"\"Öyleyse, 'Ne yiyeceğiz?' 'Ne içeceğiz?' ya da 'Ne giyeceğiz?' diyerek kaygılanmayın."},{"n":"32","t":"Uluslar hep bu şeylerin peşinden giderler. Oysa göksel Babanız bütün bunlara gereksinmeniz olduğunu bilir."},{"n":"33","t":"Siz öncelikle O'nun egemenliğinin ve doğruluğunun ardından gidin, o zaman size bütün bunlar da verilecektir."},{"n":"34","t":"O halde yarın için kaygılanmayın. Yarının kaygısı yarının olsun. Her günün derdi kendine yeter.\""}]},{"ch":7,"verses":[{"n":"1","t":"\"Başkasını yargılamayın ki, siz de yargılanmayasınız."},{"n":"2","t":"Çünkü nasıl yargılarsanız öyle yargılanacaksınız. Hangi ölçekle verirseniz, aynı ölçekle alacaksınız."},{"n":"3","t":"Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?"},{"n":"4","t":"Kendi gözünde mertek varken kardeşine nasıl, 'İzin ver, gözündeki çöpü çıkarayım' dersin?"},{"n":"5","t":"Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün."},{"n":"6","t":"\"Kutsal olanı köpeklere vermeyin. İncilerinizi domuzların önüne atmayın. Yoksa bunları ayaklarıyla çiğnedikten sonra dönüp sizi parçalayabilirler.\" Tanrı'dan Dileyin (Luk.11:9-13)"},{"n":"7","t":"\"Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır."},{"n":"8","t":"Çünkü her dileyen alır, arayan bulur, kapı çalana açılır."},{"n":"9","t":"Hanginiz kendisinden ekmek isteyen oğluna taş verir?"},{"n":"10","t":"Ya da balık isterse yılan verir?"},{"n":"11","t":"Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, göklerdeki Babanız'ın, kendisinden dileyenlere güzel armağanlar vereceği çok daha kesin değil mi?"},{"n":"12","t":"\"İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın. Çünkü Kutsal Yasa'nın ve peygamberlerin söylediği budur.\" Dar Kapı, Geniş Kapı (Luk.13:24)"},{"n":"13","t":"\"Dar kapıdan girin. Çünkü yıkıma götüren kapı geniş ve yol enlidir. Bu kapıdan girenler çoktur."},{"n":"14","t":"Oysa yaşama götüren kapı dar, yol da çetindir. Bu yolu bulanlar azdır.\" Ağaç ve Meyvesi (Mat.12:33-35; Luk.6:43-44)"},{"n":"15","t":"\"Sahte peygamberlerden sakının! Onlar size kuzu postuna bürünerek yaklaşırlar, ama özde yırtıcı kurtlardır."},{"n":"16","t":"Onları meyvelerinden tanıyacaksınız. Dikenli bitkilerden üzüm,devedikenlerinden incir toplanabilir mi?"},{"n":"17","t":"Bunun gibi, her iyi ağaç iyi meyve verir, kötü ağaç ise kötü meyve verir."},{"n":"18","t":"İyi ağaç kötü meyve, kötü ağaç da iyi meyve veremez."},{"n":"19","t":"İyi meyve vermeyen her ağaç kesilip ateşe atılır."},{"n":"20","t":"Böylece sahte peygamberleri meyvelerinden tanıyacaksınız."},{"n":"21","t":"\"Bana, 'Ya Rab, ya Rab!' diye seslenen herkes Göklerin Egemenliği'ne girmeyecek. Ancak göklerdeki Babam'ın isteğini yerine getiren girecektir."},{"n":"22","t":"O gün birçokları bana diyecek ki, 'Ya Rab, ya Rab! Biz senin adınla peygamberlik etmedik mi? Senin adınla cinler kovmadık mı? Senin adınla birçok mucize yapmadık mı?'"},{"n":"23","t":"O zaman ben de onlara açıkça, 'Sizi hiç tanımadım, uzak durun benden, ey kötülük yapanlar!' diyeceğim.\" Sağlam Temel, Çürük Temel (Luk.6:47-49)"},{"n":"24","t":"\"İşte bu sözlerimi duyup uygulayan herkes, evini kaya üzerine kuran akıllı adama benzer."},{"n":"25","t":"Yağmur yağar, seller basar, yeller eser, eve saldırır; ama ev yıkılmaz.Çünkü kaya üzerine kurulmuştur."},{"n":"26","t":"Bu sözlerimi duyup da uygulamayan herkes, evini kum üzerine kuran budala adama benzer."},{"n":"27","t":"Yağmur yağar, seller basar, yeller eser, evi sarsar. Ev yıkılır; yıkılışı da korkunç olur.\""},{"n":"28","t":"İsa konuşmasını bitirince, halk O'nun öğretişine şaşıp kaldı."},{"n":"29","t":"Çünkü onlara kendi din bilginleri gibi değil, yetkili biri gibi öğretiyordu."}]},{"ch":8,"verses":[{"n":"1","t":"İsa dağdan inince büyük bir kalabalık O'nun ardından gitti."},{"n":"2","t":"Bu sırada cüzamlı* bir adam yaklaşıp, \"Ya Rab, istersen beni temiz kılabilirsin\" diyerek O'nun ayaklarına kapandı."},{"n":"3","t":"İsa elini uzatıp adama dokundu, \"İsterim, temiz ol!\" dedi. Adam anında cüzamdan temizlendi."},{"n":"4","t":"Sonra İsa adama, \"Sakın kimseye bir şey söyleme!\" dedi. \"Git, kâhine* görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu sunuyu sun.\" Yüzbaşının İmanı (Luk.7:1-10)"},{"n":"5-6","t":"İsa Kefarnahum'a varınca bir yüzbaşı O'na gelip, \"Ya Rab\" diye yalvardı, \"Uşağım felç oldu, evde yatıyor; korkunç acı çekiyor.\""},{"n":"7","t":"İsa, \"Gelip onu iyileştireceğim\" dedi."},{"n":"8","t":"Ama yüzbaşı, \"Ya Rab, evime girmene layık değilim\" dedi, \"Yeter ki bir söz söyle, uşağım iyileşir."},{"n":"9","t":"Ben de buyruk altında bir adamım, benim de buyruğumda askerlerim var. Birine, 'Git' derim, gider; ötekine, 'Gel' derim, gelir; köleme, 'Şunu yap'derim, yapar.\""},{"n":"10","t":"İsa, duyduğu bu sözlere hayran kaldı. Ardından gelenlere, \"Size doğrusunu söyleyeyim\" dedi, \"Ben İsrail'de böyle imanı olan birini görmedim."},{"n":"11","t":"Size şunu söyleyeyim, doğudan ve batıdan birçok insan gelecek, Göklerin Egemenliği'nde İbrahim'le, İshak'la ve Yakup'la birlikte sofraya oturacaklar."},{"n":"12","t":"Ama bu egemenliğin asıl mirasçıları dışarıdaki karanlığa atılacak. Orada ağlayış ve diş gıcırtısı olacak.\""},{"n":"13","t":"Sonra İsa yüzbaşıya, \"Git, inandığın gibi olsun\" dedi.Ve uşak o anda iyileşti. İsa Birçoklarını İyileştiriyor (Mar.1:29-34; Luk.4:38-41)"},{"n":"14","t":"İsa Petrus'un evine geldiğinde onun kaynanasının ateşler içinde yattığını gördü."},{"n":"15","t":"Eline dokununca kadının ateşi düştü. Kadın kalkıp İsa'ya hizmet etmeye başladı."},{"n":"16","t":"Akşam olunca birçok cinliyi kendisine getirdiler. İsa onlardaki kötü ruhları tek sözle kovdu, hastaların hepsini iyileştirdi."},{"n":"17","t":"Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu:\"Zayıflıklarımızı O kaldırdı,Hastalıklarımızı O üstlendi.\" İsa'yı İzlemenin Bedeli (Luk.9:57-62)"},{"n":"18","t":"İsa, çevresindeki kalabalığı görünce gölün karşı yakasına geçilmesini buyurdu."},{"n":"19","t":"O sırada din bilginlerinden* biri O'na yaklaşıp, \"Öğretmenim\" dedi,\"Nereye gidersen, senin ardından geleceğim.\""},{"n":"20","t":"İsa ona, \"Tilkilerin ini, kuşların yuvası var, ama İnsanoğlu'nun* başını yaslayacak bir yeri yok\" dedi."},{"n":"21","t":"Başka bir öğrencisi İsa'ya, \"Ya Rab, izin ver, önce gidip babamı gömeyim\" dedi."},{"n":"22","t":"İsa ona, \"Ardımdan gel\" dedi. \"Bırak ölüleri, kendi ölülerini kendileri gömsün.\" İsa Fırtınayı Dindiriyor (Mar.4:35-41; Luk.8:22-25)"},{"n":"23","t":"İsa tekneye binince, ardından öğrencileri de bindi."},{"n":"24","t":"Gölde ansızın büyük bir fırtına koptu. Öyle ki, dalgalar teknenin üzerinden aşıyordu. İsa bu arada uyuyordu."},{"n":"25","t":"Öğrenciler gidip O'nu uyandırarak, \"Ya Rab, kurtar bizi, yoksa öleceğiz!\" dediler."},{"n":"26","t":"İsa, \"Neden korkuyorsunuz, ey kıt imanlılar?\" dedi. Sonra kalkıp rüzgarı ve gölü azarladı. Ortalık sütliman oldu."},{"n":"27","t":"Hepsi hayret içinde kaldı. \"Bu nasıl bir adam ki, rüzgar da göl de O'nun sözünü dinliyor?\" dediler. İki Cinlinin İyileştirilmesi (Mar.5:1-20; Luk.8:26-39)"},{"n":"28","t":"İsa gölün karşı yakasında Gadaralılar'ın memleketine vardı. Orada O'nu mezarlık mağaralardan çıkan iki cinli karşıladı. Bunlar öyle tehlikeliydi ki,kimse o yoldan geçemiyordu."},{"n":"29","t":"İsa'ya, \"Ey Tanrı'nın Oğlu, bizden ne istiyorsun?\" diye bağırdılar.\"Buraya, vaktinden önce bize işkence etmek için mi geldin?\""},{"n":"30","t":"Onlardan uzakta otlayan büyük bir domuz sürüsü vardı."},{"n":"31","t":"Cinler İsa'ya, \"Bizi kovacaksan, şu domuz sürüsüne gönder\" diye yalvardılar."},{"n":"32","t":"İsa onlara, \"Gidin!\" dedi. Cinler de adamlardan çıkıp domuzların içine girdiler. O anda bütün sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"33","t":"Domuzları güdenler kaçıp kente gittiler. Cinli adamlarla ilgili haberler dahil, olup bitenlerin hepsini anlattılar."},{"n":"34","t":"Bunun üzerine bütün kent halkı İsa'yı karşılamaya çıktı. O'nu görünce bölgelerinden ayrılması için yalvardılar."}]},{"ch":9,"verses":[{"n":"1","t":"İsa tekneye binip karşı kıyıya geçti ve kendi kentine gitti."},{"n":"2","t":"Kendisine, yatak üzerinde felçli bir adam getirdiler. İsa onların imanını görünce felçliye, \"Cesur ol, oğlum, günahların bağışlandı\" dedi."},{"n":"3","t":"Bunun üzerine bazı din bilginleri içlerinden, \"Bu adam Tanrı'ya küfrediyor!\" dediler."},{"n":"4","t":"Onların ne düşündüklerini bilen İsa dedi ki, \"Yüreğinizde neden kötü düşüncelere yer veriyorsunuz?"},{"n":"5","t":"Hangisi daha kolay? 'Günahların bağışlandı' demek mi, yoksa 'Kalk, yürü' demek mi?"},{"n":"6","t":"Ne var ki, İnsanoğlu'nun* yeryüzünde günahları bağışlama yetkisine sahipolduğunu bilesiniz diye...\" Sonra felçliye, \"Kalk, yatağını topla, evine git!\" dedi."},{"n":"7","t":"Adam da kalkıp evine gitti."},{"n":"8","t":"Halk bunu görünce korkuya kapıldı. İnsana böyle bir yetki veren Tanrı'yı yücelttiler. Matta'nın Öğrencilere Katılması (Mar.2:13-17; Luk.5:27-32)"},{"n":"9","t":"İsa oradan geçerken, vergi toplama yerinde oturan birini gördü. Matta adındaki bu adama, \"Ardımdan gel\" dedi. Adam da kalkıp İsa'nın ardından gitti."},{"n":"10","t":"Sonra İsa, Matta'nın evinde sofrada otururken, birçok vergi görevlisiyle* günahkâr gelip O'nunla ve öğrencileriyle birlikte sofraya oturdu."},{"n":"11","t":"Bunu gören Ferisiler, İsa'nın öğrencilerine, \"Sizin öğretmeniniz neden vergi görevlileri ve günahkârlarla birlikte yemek yiyor?\" diye sordular."},{"n":"12","t":"İsa bunu duyunca şöyle dedi: \"Sağlamların değil, hastaların hekime ihtiyacı var."},{"n":"13","t":"Gidin de, 'Ben kurban değil, merhamet isterim' sözünün anlamını öğrenin. Çünkü ben doğru kişileri değil, günahkârları çağırmaya geldim.\" Oruçla İlgili Soru (Mar.2:18-22; Luk.5:33-39)"},{"n":"14","t":"Bu arada Yahya'nın öğrencileri gelip İsa'ya, \"Neden biz ve Ferisiler oruç tutuyoruz da senin öğrencilerin tutmuyor?\" diye sordular."},{"n":"15","t":"İsa şöyle karşılık verdi: \"Güvey aralarındayken, davetliler yas tutar mı? Ama güveyin aralarından alınacağı günler gelecek, o zaman oruç tutacaklar."},{"n":"16","t":"Hiç kimse eski giysiyi yeni kumaş parçasıyla yamamaz. Çünkü yeni kumaş çeker, giysiden kopar, yırtık daha beter olur."},{"n":"17","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa tulumlar patlar; hem şarap dökülür, hem de tulumlar mahvolur. Yeni şarap yeni tulumlara konur,böylece her ikisi de korunmuş olur.\" Dirilen Kız, İyileşen Kadın (Mar.5:21-43; Luk.8:40-56)"},{"n":"18","t":"İsa onlara bu sözleri söylerken bir havra yöneticisi gelip O'nun önünde yere kapanarak, \"Kızım az önce öldü. Ama sen gelip elini onun üzerine koyarsan, dirilecek\" dedi."},{"n":"19","t":"İsa kalkıp öğrencileriyle birlikte adamın ardından gitti."},{"n":"20","t":"Tam o sırada, on iki yıldır kanaması olan bir kadın İsa'nın arkasından yetişip giysisinin eteğine dokundu."},{"n":"21","t":"İçinden, \"Giysisine bir dokunsam kurtulurum\" diyordu."},{"n":"22","t":"İsa arkasına dönüp onu görünce, \"Cesur ol, kızım! İmanın seni kurtardı\" dedi. Ve kadın o anda iyileşti."},{"n":"23-24","t":"İsa, yöneticinin evine varıp kaval çalanlarla gürültülü kalabalığı görünce, \"Çekilin!\" dedi. \"Kız ölmedi, uyuyor.\" Onlar ise kendisiyle alay ettiler."},{"n":"25","t":"Kalabalık dışarı çıkarılınca İsa içeri girip kızın elini tuttu, kız ayağa kalktı."},{"n":"26","t":"Bu haber bütün bölgeye yayıldı. İki Körle Bir Dilsizin İyileştirilmesi"},{"n":"27","t":"İsa oradan ayrılırken iki kör, \"Ey Davut Oğlu, halimize acı!\" diye feryat ederek O'nun ardından gittiler."},{"n":"28","t":"İsa eve girince körler yanına geldi. Onlara, \"İstediğinizi yapabileceğime inanıyor musunuz?\" diye sordu. Körler, \"İnanıyoruz, ya Rab!\" dediler."},{"n":"29","t":"Bunun üzerine İsa körlerin gözlerine dokunarak, \"İmanınıza göre olsun\" dedi."},{"n":"30","t":"Ve adamların gözleri açıldı İsa, \"Sakın kimse bunu bilmesin\" diyerek onları sıkı sıkı uyardı."},{"n":"31","t":"Onlar ise çıkıp İsa'yla ilgili haberi bütün bölgeye yaydılar."},{"n":"32","t":"Adamlar çıkarken İsa'ya dilsiz bir cinli getirdiler."},{"n":"33","t":"Cin kovulunca adamın dili çözüldü. Halk hayret içinde, \"İsrail'de böylesi hiç görülmemiştir\" diyordu."},{"n":"34","t":"Ferisiler ise, \"Cinleri, cinlerin önderinin gücüyle kovuyor\" diyorlardı. Ürün Bol, İşçi Az"},{"n":"35","t":"İsa bütün kent ve köyleri dolaşarak havralarda öğretiyor, göksel egemenliğin Müjdesi'ni duyuruyor, her hastalığı, her illeti iyileştiriyordu."},{"n":"36","t":"Kalabalıkları görünce onlara acıdı. Çünkü çobansız koyunlar gibi şaşkın ve perişandılar."},{"n":"37","t":"O zaman İsa öğrencilerine, \"Ürün bol, ama işçi az\" dedi,"},{"n":"38","t":"\"Bu nedenle ürünün sahibi Rab'be yalvarın, ürününü kaldıracak işçiler göndersin.\""}]},{"ch":10,"verses":[{"n":"1","t":"İsa on iki öğrencisini yanına çağırıp onlara kötü ruhlar üzerinde yetki verdi. Böylece kötü ruhları kovacak, her hastalığı, her illeti iyileştireceklerdi."},{"n":"2-4","t":"Bu on iki elçinin adları şöyle: Birincisi Petrus adıyla bilinen Simun,onun kardeşi Andreas, Zebedi'nin oğulları Yakup ve Yuhanna, Filipus ve Bartalmay, Tomas ve vergi görevlisi Matta, Alfay oğlu Yakup ve Taday,Yurtsever* Simun ve İsa'ya ihanet eden Yahuda İskariot."},{"n":"5","t":"İsa Onikiler'i şu buyrukla halkın arasına gönderdi: \"Öteki ulusların arasına girmeyin. Samiriyeliler'in kentlerine de uğramayın."},{"n":"6","t":"Bunun yerine, İsrail halkının yitik koyunlarına gidin."},{"n":"7","t":"Gittiğiniz her yerde Göklerin Egemenliği'nin yaklaştığını duyurun."},{"n":"8","t":"Hastaları iyileştirin, ölüleri diriltin, cüzamlıları* temiz kılın,cinleri kovun. Karşılıksız aldınız, karşılıksız verin."},{"n":"9","t":"Kuşağınıza altın, gümüş, ya da bakır para koymayın."},{"n":"10","t":"Yolculuk için ne torba, ne yedek mintan, ne çarık, ne de değnek alın.Çünkü işçi yiyeceğini hak eder."},{"n":"11","t":"Hangi kent ya da köye girerseniz, orada saygıdeğer birini arayın ve ayrılıncaya dek onunla kalın."},{"n":"12","t":"Onun evine girerken, evdekilere esenlik dileyin."},{"n":"13","t":"Eğer evdekiler buna layıksa, dilediğiniz esenlik üzerlerinde kalsın; layık değillerse, size geri dönsün."},{"n":"14","t":"Sizi kabul etmez, sözlerinizi dinlemezlerse o evden ya da kentten ayrılırken, ayaklarınızın tozunu silkin."},{"n":"15","t":"Size doğrusunu söyleyeyim, yargı günü o kentin hali Sodom'la Gomora bölgesinin halinden beter olacaktır.\" Gelecekteki Sıkıntılar (Mar.13:9-13; Luk.21:12-17)"},{"n":"16","t":"\"İşte, sizi koyunlar gibi kurtların arasına gönderiyorum. Yılan gibi zeki, güvercin gibi saf olun."},{"n":"17","t":"İnsanlardan sakının. Çünkü sizi mahkemelere verecek, havralarında kamçılayacaklar."},{"n":"18","t":"Benden ötürü valilerin, kralların önüne çıkarılacak, böylece onlara ve uluslara tanıklık edeceksiniz."},{"n":"19","t":"Sizleri mahkemeye verdiklerinde, neyi nasıl söyleyeceğinizi düşünerek kaygılanmayın. Ne söyleyeceğiniz o anda size bildirilecek."},{"n":"20","t":"Çünkü konuşan siz değil, aracılığınızla konuşan Babanız'ın Ruhu olacak."},{"n":"21","t":"\"Kardeş kardeşi, baba çocuğunu ölüme teslim edecek. Çocuklar anne babaya başkaldırıp onları öldürtecek. Mat.10: :22 Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır."},{"n":"23","t":"Bir kentte size zulmettikleri zaman ötekine kaçın. Size doğrusunu söyleyeyim, İnsanoğlu* gelinceye dek İsrail'in bütün kentlerini dolaşmışolmayacaksınız."},{"n":"24","t":"\"Öğrenci öğretmeninden, köle efendisinden üstün değildir."},{"n":"25","t":"Öğrencinin öğretmeni gibi, kölenin de efendisi gibi olması yeterlidir.İnsanlar evin efendisine Baalzevul* derlerse, ev halkına neler demezler!\" Kimden Korkmalı (Luk.12:2-9)"},{"n":"26","t":"\"Bu yüzden onlardan korkmayın. Çünkü örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur."},{"n":"27","t":"Size karanlıkta söylediklerimi, siz gün ışığında söyleyin. Kulağınıza fısıldananı, damlardan duyurun."},{"n":"28","t":"Bedeni öldüren, ama canı öldüremeyenlerden korkmayın. Canı da bedeni de cehennemde mahvedebilen Tanrı'dan korkun."},{"n":"29","t":"İki serçe bir meteliğe satılmıyor mu? Ama Babanız'ın izni olmadan bunlardan bir teki bile yere düşmez."},{"n":"30","t":"Size gelince, başınızdaki bütün saçlar bile sayılıdır."},{"n":"31","t":"Onun için korkmayın, siz birçok serçeden daha değerlisiniz."},{"n":"32","t":"\"İnsanların önünde beni açıkça kabul eden herkesi, ben de göklerdeki Babam'ın önünde açıkça kabul edeceğim."},{"n":"33","t":"İnsanların önünde beni inkâr edeni, ben de göklerdeki Babam'ın önünde inkâr edeceğim.\" İsa'ya Layık Olmak (Mar.9:41; Luk.12:51-53; 14:26-27)"},{"n":"34","t":"\"Yeryüzüne barış getirmeye geldiğimi sanmayın! Barış değil, kılıç getirmeye geldim."},{"n":"35","t":"Çünkü ben babayla oğulun, anneyle kızın, gelinle kaynananın arasına ayrılık sokmaya geldim."},{"n":"36","t":"'İnsanın düşmanı kendi ev halkı olacak.'"},{"n":"37","t":"Annesini ya da babasını beni sevdiğinden çok seven bana layık değildir. Oğlunu ya da kızını beni sevdiğinden çok seven bana layık değildir."},{"n":"38","t":"Çarmıhını yüklenip ardımdan gelmeyen bana layık değildir."},{"n":"39","t":"Canını kurtaran onu yitirecek. Canını benim uğruma yitiren ise onu kurtaracaktır."},{"n":"40","t":"\"Sizi kabul eden beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur."},{"n":"41","t":"Bir peygamberi peygamber olduğu için kabul eden, peygambere yaraşan bir ödül alacaktır. Doğru birini doğru olduğu için kabul eden, doğru kişiye yaraşan bir ödül alacaktır."},{"n":"42","t":"Bu sıradan kişilerden birine, öğrencim olduğu için bir bardak soğuk su bile veren, size doğrusunu söyleyeyim, ödülsüz kalmayacaktır.\""}]},{"ch":11,"verses":[{"n":"1","t":"İsa, on iki öğrencisine bu buyrukları verdikten sonra onların kentlerinde öğretmek ve Tanrı sözünü duyurmak üzere oradan ayrıldı."},{"n":"2-3","t":"Tutukevinde bulunan Yahya, Mesih'in yaptığı işleri duyunca, O'na gönderdiği öğrencileri aracılığıyla şunu sordu: \"Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?\""},{"n":"4","t":"İsa onlara şöyle karşılık verdi: \"Gidin, işitip gördüklerinizi Yahya'ya bildirin."},{"n":"5","t":"Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve Müjde yoksullara duyuruluyor."},{"n":"6","t":"Benden ötürü sendeleyip düşmeyene ne mutlu!\""},{"n":"7","t":"Yahya'nın öğrencileri ayrılırken İsa halka Yahya'dan söz etmeye başladı. \"Çöle ne görmeye gittiniz?\" dedi. \"Rüzgarda sallanan bir kamış mı?"},{"n":"8","t":"Söyleyin, ne görmeye gittiniz? Pahalı giysiler giymiş bir adam mı? Oysa pahalı giysi giyenler, kral saraylarında bulunur."},{"n":"9","t":"Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür."},{"n":"10","t":"'İşte, habercimi senin önünden gönderiyorum; O önden gidip senin yolunu hazırlayacak' diye yazılmış olan sözler onunla ilgilidir."},{"n":"11","t":"Size doğrusunu söyleyeyim, kadından doğanlar arasında Vaftizci Yahya'dan daha üstün biri çıkmamıştır. Bununla birlikte, Göklerin Egemenliği'nde en küçük olan ondan üstündür."},{"n":"12","t":"Vaftizci Yahya'nın ortaya çıktığı günden bu yana Göklerin Egemenliği zorlanıyor, zorlu kişiler onu ele geçirmeye çalışıyor*fx*."},{"n":"13","t":"Yahya'ya dek bütün peygamberlerle Kutsal Yasa, olacakları önceden bildirdiler."},{"n":"14","t":"Eğer bunu kabul etmek isterseniz, gelecek olan İlyas odur."},{"n":"15","t":"Kulağı olan, işitsin!"},{"n":"16-17","t":"\"Bu kuşağın insanlarını neye benzeteyim? Çarşı meydanlarında oturup arkadaşlarına, 'Size kaval çaldık, oynamadınız; Ağıt yaktık, dövünmediniz' diye seslenen çocuklara benziyorlar."},{"n":"18","t":"Yahya geldiği zaman oruç tutup içkiden kaçındı, ona 'cinli' diyorlar."},{"n":"19","t":"İnsanoğlu* geldiği zaman yiyip içti. Bu kez de diyorlar ki, 'Şu obur ve ayyaş adama bakın! Vergi görevlileri* ve günahkârlarla dost oldu!' Ne var ki bilgelik, ortaya koyduğu işlerle doğrulanır.\" Tövbe Etmeyen Kentler (Luk.10:13-15)"},{"n":"20-21","t":"Sonra İsa, mucizelerinin çoğunu yapmış olduğu kentleri, tövbe etmedikleri için şöyle azarlamaya başladı: \"Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Sayda'da yapılmış olsaydı, çoktan çul* kuşanıp kül içinde oturarak tövbe etmiş olurlardı."},{"n":"22","t":"Size şunu söyleyeyim, yargı günü sizin haliniz Sur ve Sayda'nın halinden beter olacaktır!"},{"n":"23","t":"Ya sen, ey Kefarnahum, göğe mi çıkarılacaksın? Hayır, ölüler diyarına indirileceksin! Çünkü sende yapılan mucizeler Sodom'da yapılmış olsaydı, bugüne dek ayakta kalırdı."},{"n":"24","t":"Sana şunu söyleyeyim, yargı günü senin halin Sodom bölgesinin halinden beter olacaktır!\" Yorgunlara Müjde (Luk.10:21-22)"},{"n":"25","t":"İsa bundan sonra şöyle dedi: \"Baba, yerin ve göğün Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim."},{"n":"26","t":"Evet Baba, senin isteğin buydu."},{"n":"27","t":"\"Babam her şeyi bana teslim etti. Oğul'u, Baba'dan başka kimse tanımaz. Baba'yı da Oğul'dan ve Oğul'un O'nu tanıtmak istediği kişilerden başkası tanımaz."},{"n":"28","t":"\"Ey bütün yorgunlar ve yükü ağır olanlar! Bana gelin, ben size rahat veririm."},{"n":"29","t":"Boyunduruğumu yüklenin, benden öğrenin. Çünkü ben yumuşak huylu, alçakgönüllüyüm. Böylece canlarınız rahata kavuşur."},{"n":"30","t":"Boyunduruğumu taşımak kolay, yüküm hafiftir.\""}]},{"ch":12,"verses":[{"n":"1","t":"O sıralarda, bir Şabat Günü* İsa ekinler arasından geçiyordu. Öğrencileri acıkınca başakları koparıp yemeye başladılar."},{"n":"2","t":"Bunu gören Ferisiler İsa'ya, \"Bak, öğrencilerin Şabat Günü yasak olanı yapıyor\" dediler."},{"n":"3","t":"İsa onlara, \"Davut'la yanındakiler acıkınca Davut'un ne yaptığını okumadınız mı?\" diye sordu."},{"n":"4","t":"\"Tanrı'nın evine girdi, kendisinin ve yanındakilerin yemesi yasak olan, ancak kâhinlerin yiyebileceği adak ekmeklerini* yedi."},{"n":"5","t":"Ayrıca kâhinlerin her hafta tapınakta Şabat Günü'yle ilgili buyruğu çiğnedikleri halde suçlu sayılmadıklarını Kutsal Yasa'da okumadınız mı?"},{"n":"6","t":"Size şunu söyleyeyim, burada tapınaktan daha üstün bir şey var."},{"n":"7","t":"Eğer siz, 'Ben kurban değil, merhamet isterim' sözünün anlamını bilseydiniz, suçsuzları yargılamazdınız."},{"n":"8","t":"Çünkü İnsanoğlu* Şabat Günü'nün de Rabbi'dir.\""},{"n":"9","t":"İsa oradan ayrılıp onların havrasına gitti."},{"n":"10","t":"Orada eli sakat bir adam vardı. İsa'yı suçlamak amacıyla kendisine, \"Şabat Günü bir hastayı iyileştirmek Kutsal Yasa'ya uygun mudur?\" diye sordular."},{"n":"11","t":"İsa onlara şu karşılığı verdi: \"Hanginizin bir koyunu olur da Şabat Günü çukura düşerse onu tutup çıkarmaz?"},{"n":"12","t":"İnsan koyundan çok daha değerlidir! Demek ki, Şabat Günü iyilik yapmak Yasa'ya uygundur.\""},{"n":"13","t":"Sonra adama, \"Elini uzat\" dedi. Adam elini uzattı. Eli öteki gibi yine sapasağlam oluverdi."},{"n":"14","t":"Bunun üzerine Ferisiler dışarı çıktılar, İsa'yı yok etmek için anlaştılar. Tanrı'nın Seçtiği Kul"},{"n":"15","t":"İsa bunu bildiği için oradan ayrıldı. Birçok kişi ardından gitti. İsa hepsini iyileştirdi."},{"n":"16","t":"Kim olduğunu açıklamamaları için onları uyardı."},{"n":"17-18","t":"Bu, Peygamber Yeşaya aracılığıyla bildirilen şu söz yerine gelsin diye oldu: \"İşte Kulum, O'nu ben seçtim. Gönlümün hoşnut olduğu sevgili Kulum O'dur. Ruhum'u O'nun üzerine koyacağım, O da adaleti uluslara bildirecek."},{"n":"19","t":"Çekişip bağırmayacak, Sokaklarda kimse O'nun sesini duymayacak."},{"n":"20","t":"Ezilmiş kamışı kırmayacak, Tüten fitili söndürmeyecek, Ve sonunda adaleti zafere ulaştıracak."},{"n":"21","t":"Uluslar da O'nun adına umut bağlayacak.\" İsa ve Baalzevul (Mar.3:20-30; Luk.6:43-45; 11:14-23)"},{"n":"22","t":"Daha sonra İsa'ya kör ve dilsiz bir cinli getirdiler. İsa adamı iyileştirdi. Adam konuşmaya, görmeye başladı."},{"n":"23","t":"Bütün kalabalık şaşırıp kaldı. \"Bu, Davut'un Oğlu* olabilir mi?\" diye soruyorlardı."},{"n":"24","t":"Ferisiler bunu duyunca, \"Bu adam cinleri, ancak cinlerin önderi Baalzevul'un* gücüyle kovuyor\" dediler."},{"n":"25","t":"Onların ne düşündüğünü bilen İsa şöyle dedi: \"Kendi içinde bölünen ülke yıkılır. Kendi içinde bölünen kent ya da ev ayakta kalamaz."},{"n":"26","t":"Eğer Şeytan Şeytan'ı kovarsa, kendi içinde bölünmüş demektir. Bu durumda onun egemenliği nasıl ayakta kalabilir?"},{"n":"27","t":"Eğer ben cinleri Baalzevul'un gücüyle kovuyorsam, sizin adamlarınız kimin gücüyle kovuyor? Bu durumda sizi kendi adamlarınız yargılayacak."},{"n":"28","t":"Ama ben cinleri Tanrı'nın Ruhu'yla kovuyorsam, Tanrı'nın Egemenliği üzerinize gelmiş demektir."},{"n":"29","t":"\"Bir kimse güçlü adamın evine girip malını nasıl çalabilir? Ancak onu bağladıktan sonra evini soyabilir."},{"n":"30","t":"\"Benden yana olmayan bana karşıdır. Benimle birlikte toplamayan dağıtıyor demektir."},{"n":"31","t":"Bunun için size diyorum ki, insanların işlediği her günah, ettiği her küfür bağışlanacak; ama Ruh'a edilen küfür bağışlanmayacaktır."},{"n":"32","t":"İnsanoğlu'na* karşı bir söz söyleyen, bağışlanacak; ama Kutsal Ruh'a karşı bir söz söyleyen, ne bu çağda, ne de gelecek çağda bağışlanacaktır."},{"n":"33","t":"\"Ya ağacı iyi, meyvesini de iyi sayın; ya da ağacı kötü, meyvesini de kötü sayın. Çünkü her ağaç meyvesinden tanınır."},{"n":"34","t":"Sizi engerekler soyu! Kötü olan sizler nasıl iyi sözler söyleyebilirsiniz? Çünkü ağız yürekten taşanı söyler."},{"n":"35","t":"İyi insan içindeki iyilik hazinesinden iyilik, kötü insan içindeki kötülük hazinesinden kötülük çıkarır."},{"n":"36","t":"Size şunu söyleyeyim, insanlar söyledikleri her boş söz için yargı günü hesap verecekler."},{"n":"37","t":"Kendi sözlerinizle aklanacak, yine kendi sözlerinizle suçlu çıkarılacaksınız.\" Yunus'un Belirtisi (Mar.8:11-12; Luk.11:24-26,29-32)"},{"n":"38","t":"Bunun üzerine bazı din bilginleri ve Ferisiler, \"Öğretmenimiz, senden doğaüstü bir belirti görmek istiyoruz\" dediler."},{"n":"39","t":"İsa onlara şu karşılığı verdi: \"Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Peygamber Yunus'un belirtisinden başka bir belirti gösterilmeyecektir."},{"n":"40","t":"Yunus, nasıl üç gün üç gece o koca balığın karnında kaldıysa, İnsanoğlu* da üç gün üç gece yerin bağrında kalacaktır."},{"n":"41","t":"Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunus'un çağrısı üzerine tövbe ettiler. Bakın, Yunus'tan daha üstün olan buradadır."},{"n":"42","t":"Güney Kraliçesi, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü kraliçe, Süleyman'ın bilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleyman'dan daha üstün olan buradadır."},{"n":"43","t":"\"Kötü ruh insandan çıkınca kurak yerlerde dolanıp huzur arar, ama bulamaz."},{"n":"44","t":"O zaman, 'Çıktığım eve, kendi evime döneyim' der. Eve gelince orayı bomboş, süpürülmüş, düzeltilmiş bulur."},{"n":"45","t":"Bunun üzerine gider, yanına kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur. Bu kötü kuşağın başına gelecek olan da budur.\" İsa'nın Annesi ve Kardeşleri (Mar.3:31-35; Luk.8:19-21)"},{"n":"46","t":"İsa daha halka konuşurken, annesiyle kardeşleri geldi. Dışarıda durmuş, O'nunla konuşmak istiyorlardı."},{"n":"47","t":"Birisi İsa'ya, \"Bak, annenle kardeşlerin dışarıda duruyor, seninle görüşmek istiyorlar\" dedi."},{"n":"48","t":"İsa, kendisiyle konuşana, \"Kimdir annem, kimdir kardeşlerim?\" karşılığını verdi."},{"n":"49","t":"Eliyle öğrencilerini göstererek, \"İşte annem, işte kardeşlerim!\" dedi."},{"n":"50","t":"\"Göklerdeki Babam'ın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.\""}]},{"ch":13,"verses":[{"n":"1","t":"Aynı gün İsa evden çıktı, gidip göl kıyısında oturdu."},{"n":"2","t":"Çevresinde büyük bir kalabalık toplandı. Bu yüzden İsa tekneye binip oturdu. Bütün kalabalık kıyıda duruyordu."},{"n":"3","t":"İsa onlara benzetmelerle birçok şey anlattı. \"Bakın\" dedi, \"Ekincinin biri tohum ekmeye çıktı."},{"n":"4","t":"Ektiği tohumlardan kimi yol kenarına düştü. Kuşlar gelip bunları yedi."},{"n":"5","t":"Kimi, toprağı az, kayalık yerlere düştü; toprak derin olmadığından hemen filizlendi."},{"n":"6","t":"Ne var ki, güneş doğunca kavruldular, kök salamadıkları için kuruyup gittiler."},{"n":"7","t":"Kimi, dikenler arasına düştü. Dikenler büyüdü, filizleri boğdu."},{"n":"8","t":"Kimi ise iyi toprağa düştü. Bazısı yüz, bazısı altmış, bazısı da otuz kat ürün verdi."},{"n":"9","t":"Kulağı olan işitsin!\""},{"n":"10","t":"Öğrencileri gelip İsa'ya, \"Halka neden benzetmelerle konuşuyorsun?\" diye sordular."},{"n":"11","t":"İsa şöyle yanıtladı: \"Göklerin Egemenliği'nin sırlarını bilme ayrıcalığı size verildi, ama onlara verilmedi."},{"n":"12","t":"Çünkü kimde varsa, ona daha çok verilecek, bolluğa kavuşturulacak. Ama kimde yoksa, elindeki de alınacak."},{"n":"13","t":"Onlara benzetmelerle konuşmamın nedeni budur. Çünkü, 'Gördükleri halde görmezler, Duydukları halde duymaz ve anlamazlar.'"},{"n":"14","t":"\"Böylece Yeşaya'nın peygamberlik sözü onlar için gerçekleşmiş oldu: 'Duyacak duyacak, ama hiç anlamayacaksınız, Bakacak bakacak, ama hiç görmeyeceksiniz!"},{"n":"15","t":"Çünkü bu halkın yüreği duygusuzlaştı, Kulakları ağırlaştı. Gözlerini kapadılar. Öyle ki, gözleri görmesin, Kulakları duymasın, yürekleri anlamasın Ve bana dönmesinler. Dönselerdi, onları iyileştirirdim.'"},{"n":"16","t":"\"Ama ne mutlu size ki, gözleriniz görüyor, kulaklarınız işitiyor!"},{"n":"17","t":"Size doğrusunu söyleyeyim, nice peygamberler, nice doğru kişiler sizin gördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler."},{"n":"18","t":"\"Şimdi ekinciyle ilgili benzetmeyi siz dinleyin."},{"n":"19","t":"Kim göksel egemenlikle ilgili sözü işitir de anlamazsa, kötü olan* gelir, onun yüreğine ekileni söker götürür. Yol kenarına ekilen tohum işte budur."},{"n":"20-21","t":"Kayalık yerlere ekilen ise işittiği sözü hemen sevinçle kabul eden, ama kök salamadığı için ancak bir süre dayanan kişidir. Böyle biri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşer."},{"n":"22","t":"Dikenler arasında ekilen de şudur: Sözü işitir, ama dünyasal kaygılar ve zenginliğin aldatıcılığı sözü boğar ve ürün vermesini engeller."},{"n":"23","t":"İyi toprağa ekilen tohum ise, sözü işitip anlayan birine benzer. Böylesi elbette ürün verir, kimi yüz, kimi altmış, kimi de otuz kat.\" Deliceler Benzetmesi"},{"n":"24","t":"İsa onlara başka bir benzetme anlattı: \"Göklerin Egemenliği, tarlasına iyi tohum eken adama benzer\" dedi."},{"n":"25","t":"\"Herkes uyurken, adamın düşmanı geldi, buğdayın arasına delice ekip gitti."},{"n":"26","t":"Ekin gelişip başak salınca, deliceler de göründü."},{"n":"27","t":"\"Mal sahibinin köleleri gelip ona şöyle dediler: 'Efendimiz, sen tarlana iyi tohum ekmedin mi? Bu deliceler nereden çıktı?'"},{"n":"28","t":"\"Mal sahibi, 'Bunu bir düşman yapmıştır' dedi. \"'Gidip deliceleri toplamamızı ister misin?' diye sordu köleler."},{"n":"29","t":"\"'Hayır' dedi adam. 'Deliceleri toplarken belki buğdayı da sökersiniz."},{"n":"30","t":"Bırakın biçim vaktine dek birlikte büyüsünler. Biçim vakti orakçılara, önce deliceleri toplayın diyeceğim, yakmak için demet yapın. Buğdayı ise toplayıp ambarıma koyun.'\" Hardal Tanesi ve Maya Benzetmeleri (Mar.4:30-34; Luk.13:18-21)"},{"n":"31","t":"İsa onlara bir benzetme daha anlattı: \"Göklerin Egemenliği, bir adamın tarlasına ektiği hardal tanesine benzer\" dedi."},{"n":"32","t":"\"Hardal tohumların en küçüğü olduğu halde, gelişince bahçe bitkilerinin boyunu aşar, ağaç olur. Böylece kuşlar gelip dallarında barınır.\""},{"n":"33","t":"İsa onlara başka bir benzetme anlattı: \"Göklerin Egemenliği, bir kadının üç ölçek*fx* una karıştırdığı mayaya benzer. Sonunda bütün hamur kabarır.\""},{"n":"34","t":"İsa bütün bunları halka benzetmelerle anlattı. Benzetme kullanmadan onlara hiçbir şey anlatmazdı."},{"n":"35","t":"Bu, peygamber aracılığıyla bildirilen şu söz yerine gelsin diye oldu: \"Ağzımı benzetmeler anlatarak açacağım, Dünyanın kuruluşundan beri Gizli kalmış sırları dile getireceğim.\" Deliceler Benzetmesi Açıklanıyor"},{"n":"36","t":"Bundan sonra İsa halktan ayrılıp eve gitti. Öğrencileri yanına gelip, \"Tarladaki delicelerle ilgili benzetmeyi bize açıkla\" dediler."},{"n":"37","t":"İsa, \"İyi tohumu eken, İnsanoğlu'dur*\" diye karşılık verdi."},{"n":"38","t":"\"Tarla ise dünyadır. İyi tohum, göksel egemenliğin oğulları, deliceler de kötü olanın* oğullarıdır."},{"n":"39","t":"Deliceleri eken düşman, İblis'tir. Biçim vakti, çağın sonu; orakçılar ise meleklerdir."},{"n":"40","t":"\"Deliceler nasıl toplanıp yakılırsa, çağın sonunda da böyle olacaktır."},{"n":"41-42","t":"İnsanoğlu meleklerini gönderecek, onlar da insanları günaha düşüren her şeyi, kötülük yapan herkesi O'nun egemenliğinden toplayıp kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır."},{"n":"43","t":"Doğru kişiler o zaman Babaları'nın egemenliğinde güneş gibi parlayacaklar. Kulağı olan işitsin!\" Define ve İnci Benzetmeleri"},{"n":"44","t":"\"Göklerin Egemenliği, tarlada saklı bir defineye benzer. Onu bulan yeniden sakladı, sevinçle koşup gitti, varını yoğunu satıp tarlayı satın aldı."},{"n":"45","t":"\"Yine Göklerin Egemenliği, güzel inciler arayan bir tüccara benzer."},{"n":"46","t":"Tüccar, çok değerli bir inci bulunca gitti, varını yoğunu satıp o inciyi satın aldı.\" Ağ Benzetmesi"},{"n":"47","t":"\"Yine Göklerin Egemenliği, denize atılan ve her çeşit balığı toplayan ağa benzer."},{"n":"48","t":"Ağ dolunca onu kıyıya çekerler. Oturup işe yarayan balıkları kaplara koyar, yaramayanları atarlar."},{"n":"49-50","t":"Çağın sonunda da böyle olacak. Melekler gelecek, kötü kişileri doğruların arasından ayırıp kızgın fırına atacaklar. Orada ağlayış ve diş gıcırtısı olacaktır.\""},{"n":"51","t":"İsa, \"Bütün bunları anladınız mı?\" diye sordu. \"Evet\" karşılığını verdiler."},{"n":"52","t":"O da onlara, \"İşte böylece Göklerin Egemenliği için eğitilmiş her din bilgini, hazinesinden hem yeni hem eski değerler çıkaran bir mal sahibine benzer\" dedi. İsa Reddediliyor (Mar.6:1-6; Luk.4:16-30)"},{"n":"53","t":"İsa bütün bu benzetmeleri anlattıktan sonra oradan ayrıldı."},{"n":"54","t":"Kendi memleketine gitti ve oradaki havrada halka öğretmeye başladı. Halk şaşıp kalmıştı. \"Adamın bu bilgeliği ve mucizeler yaratan gücü nereden geliyor?\" diyorlardı."},{"n":"55","t":"\"Marangozun oğlu değil mi bu? Annesinin adı Meryem değil mi? Yakup, Yusuf, Simun ve Yahuda O'nun kardeşleri değil mi?"},{"n":"56","t":"Kızkardeşlerinin hepsi aramızda yaşamıyor mu? O halde O'nun bütün bu yaptıkları nereden geliyor?\""},{"n":"57","t":"Ve gücenip O'nu reddettiler. Ama İsa onlara şöyle dedi: \"Bir peygamber, kendi memleketinden ve evinden başka yerde hor görülmez.\""},{"n":"58","t":"İmansızlıkları yüzünden İsa orada pek fazla mucize yapmadı."}]},{"ch":14,"verses":[{"n":"1-2","t":"O günlerde İsa'yla ilgili haberleri duyan bölge kralı* Hirodes, adamlarına, \"Bu, Vaftizci Yahya'dır\" dedi. \"Ölümden dirildi. Olağanüstü güçlerin onda etkin olmasının nedeni budur.\""},{"n":"3","t":"Hirodes, kardeşi Filipus'un karısı Hirodiya yüzünden Yahya'yı tutuklatmış, bağlatıp zindana attırmıştı."},{"n":"4","t":"Çünkü Yahya Hirodes'e, \"O kadınla evlenmen Kutsal Yasa'ya aykırıdır\" demişti."},{"n":"5","t":"Hirodes Yahya'yı öldürtmek istemiş, ama halktan korkmuştu. Çünkü halk Yahya'yı peygamber sayıyordu."},{"n":"6-7","t":"Hirodes'in doğum günü şenliği sırasında Hirodiya'nın kızı ortaya çıkıp dans etti. Bu, Hirodes'in öyle hoşuna gitti ki, ant içerek kıza ne dilerse vereceğini söyledi."},{"n":"8","t":"Kız, annesinin kışkırtmasıyla, \"Bana şimdi, bir tepsi üzerinde Vaftizci Yahya'nın başını ver\" dedi."},{"n":"9","t":"Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü bu dileğin yerine getirilmesini buyurdu."},{"n":"10","t":"Adam gönderip zindanda Yahya'nın başını kestirdi."},{"n":"11","t":"Kesik baş tepsiyle getirilip kıza verildi, kız da bunu annesine götürdü."},{"n":"12","t":"Yahya'nın öğrencileri gelip cesedi aldılar ve gömdüler. Sonra gidip İsa'ya haber verdiler. İsa Beş Bin Kişiyi Doyuruyor (Mar.6:30-44; Luk.9:10-17; Yu.6:1-14)"},{"n":"13","t":"İsa bunu duyunca, tek başına tenha bir yere çekilmek üzere bir tekneyle oradan ayrıldı. Bunu öğrenen halk, kentlerden çıkıp O'nu yaya olarak izledi."},{"n":"14","t":"İsa tekneden inince büyük bir kalabalıkla karşılaştı. Onlara acıdı ve hasta olanlarını iyileştirdi."},{"n":"15","t":"Akşama doğru öğrencileri yanına gelip, \"Burası ıssız bir yer\" dediler, \"Vakit de geç oldu. Halkı salıver de köylere gidip kendilerine yiyecek alsınlar.\""},{"n":"16","t":"İsa, \"Gitmelerine gerek yok, onlara siz yiyecek verin\" dedi."},{"n":"17","t":"Öğrenciler, \"Burada beş ekmekle iki balıktan başka bir şeyimiz yok ki\" dediler."},{"n":"18","t":"İsa, \"Onları buraya, bana getirin\" dedi."},{"n":"19","t":"Halka çayıra oturmalarını buyurduktan sonra, beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra ekmekleri bölüp öğrencilerine verdi, onlar da halka dağıttılar."},{"n":"20","t":"Herkes yiyip doydu. Artakalan parçalardan on iki sepet dolusu topladılar."},{"n":"21","t":"Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, yaklaşık beş bin erkekti. İsa Su Üstünde Yürüyor (Mar.6:45-56; Yu.6:15-21)"},{"n":"22","t":"Bundan hemen sonra İsa öğrencilerine, tekneye binip kendisinden önce karşı yakaya geçmelerini buyurdu. Bu arada halkı evlerine gönderecekti."},{"n":"23","t":"Halkı gönderdikten sonra dua etmek için tek başına dağa çıktı. Akşam olurken orada yalnızdı."},{"n":"24","t":"O sırada tekne kıyıdan bir hayli uzakta*fx* dalgalarla boğuşuyordu. Çünkü rüzgar karşı yönden esiyordu."},{"n":"25","t":"Sabaha karşı*fx* İsa, gölün üstünde yürüyerek onlara yaklaştı."},{"n":"26","t":"Öğrenciler, O'nun gölün üstünde yürüdüğünü görünce dehşete kapıldılar. \"Bu bir hayalet!\" diyerek korkuyla bağrıştılar."},{"n":"27","t":"Ama İsa hemen onlara seslenerek, \"Cesur olun, benim, korkmayın!\" dedi."},{"n":"28","t":"Petrus buna karşılık, \"Ya Rab\" dedi, \"Eğer sen isen, buyruk ver suyun üstünden yürüyerek sana geleyim.\""},{"n":"29","t":"İsa, \"Gel!\" dedi. Petrus da tekneden indi, suyun üstünden yürüyerek İsa'ya yaklaştı."},{"n":"30","t":"Ama rüzgarın ne kadar güçlü estiğini görünce korktu, batmaya başladı. \"Ya Rab, beni kurtar!\" diye bağırdı."},{"n":"31","t":"İsa hemen elini uzatıp onu tuttu. Ona, \"Ey kıt imanlı, neden kuşku duydun?\" dedi."},{"n":"32","t":"Onlar tekneye bindikten sonra rüzgar dindi."},{"n":"33","t":"Teknedekiler, \"Sen gerçekten Tanrı'nın Oğlu'sun\" diyerek O'na tapındılar."},{"n":"34","t":"Gölü aşıp Ginnesar'da karaya çıktılar."},{"n":"35","t":"Yöre halkı İsa'yı tanıyınca çevreye haber saldı. Bütün hastaları O'na getirdiler."},{"n":"36","t":"Giysisinin eteğine bir dokunsak diye yalvarıyorlardı. Dokunanların hepsi iyileşti."}]},{"ch":15,"verses":[{"n":"1-2","t":"Bu sırada Yeruşalim'den bazı Ferisiler ve din bilginleri İsa'ya gelip, \"Öğrencilerin neden atalarımızın töresini çiğniyor?\" diye sordular, \"Yemekten önce ellerini yıkamıyorlar.\""},{"n":"3","t":"İsa onlara şu karşılığı verdi: \"Ya siz, neden töreniz uğruna Tanrı buyruğunu çiğniyorsunuz?"},{"n":"4","t":"Çünkü Tanrı şöyle buyurdu: 'Annene babana saygı göstereceksin'; 'Annesine ya da babasına söven kesinlikle öldürülecektir.'"},{"n":"5-6","t":"Ama siz, 'Her kim anne ya da babasına, benden alacağın bütün yardım Tanrı'ya adanmıştır derse, artık babasına saygı göstermek zorunda değildir' diyorsunuz. Böylelikle, töreniz uğruna Tanrı'nın sözünü geçersiz kılmış oluyorsunuz."},{"n":"7-8","t":"Ey ikiyüzlüler! Yeşaya'nın sizinle ilgili şu peygamberlik sözü ne kadar yerindedir: 'Bu halk dudaklarıyla beni sayar, Ama yürekleri benden uzak."},{"n":"9","t":"Bana boşuna taparlar. Çünkü öğrettikleri, sadece insan buyruklarıdır.'\" İnsanı Kirleten Nedir? (Mar.7:14-23)"},{"n":"10","t":"İsa, halkı yanına çağırıp onlara, \"Dinleyin ve şunu belleyin\" dedi."},{"n":"11","t":"\"Ağızdan giren şey insanı kirletmez. İnsanı kirleten ağızdan çıkandır.\""},{"n":"12","t":"Bu sırada öğrencileri O'na gelip, \"Biliyor musun?\" dediler, \"Ferisiler bu sözü duyunca gücendiler.\""},{"n":"13","t":"İsa şu karşılığı verdi: \"Göksel Babam'ın dikmediği her fidan kökünden sökülecektir."},{"n":"14","t":"Bırakın onları; onlar körlerin kör kılavuzlarıdır. Eğer kör köre kılavuzluk ederse, ikisi de çukura düşer.\""},{"n":"15","t":"Petrus, \"Bu benzetmeyi bize açıkla\" dedi."},{"n":"16","t":"\"Siz de mi hâlâ anlamıyorsunuz?\" diye sordu İsa."},{"n":"17","t":"\"Ağza giren her şeyin mideye indiğini, oradan da helaya atıldığını bilmiyor musunuz?"},{"n":"18","t":"Ne var ki ağızdan çıkan, yürekten kaynaklanır. İnsanı kirleten de budur."},{"n":"19","t":"Çünkü kötü düşünceler, cinayet, zina, fuhuş, hırsızlık, yalan yere tanıklık ve iftira hep yürekten kaynaklanır."},{"n":"20","t":"İnsanı kirleten bunlardır. Yıkanmamış ellerle yemek yemek insanı kirletmez.\" Kenanlı Kadının İmanı (Mar.7:24-30)"},{"n":"21","t":"İsa oradan ayrılıp Sur ve Sayda bölgesine geçti."},{"n":"22","t":"O yöreden Kenanlı bir kadın İsa'ya gelip, \"Ya Rab, ey Davut Oğlu, halime acı! Kızım cine tutuldu, çok kötü durumda\" diye feryat etti."},{"n":"23","t":"İsa kadına hiçbir karşılık vermedi. Öğrencileri yaklaşıp, \"Sal şunu, gitsin!\" diye rica ettiler. \"Arkamızdan bağırıp duruyor.\""},{"n":"24","t":"İsa, \"Ben yalnız İsrail halkının kaybolmuş koyunlarına gönderildim\" diye yanıtladı."},{"n":"25","t":"Kadın ise yaklaşıp, \"Ya Rab, bana yardım et!\" diyerek O'nun önünde yere kapandı*fx*."},{"n":"26","t":"İsa ona, \"Çocukların ekmeğini alıp köpeklere atmak doğru değildir\" dedi."},{"n":"27","t":"Kadın, \"Haklısın, ya Rab\" dedi. \"Ama köpekler de efendilerinin sofrasından düşen kırıntıları yer.\""},{"n":"28","t":"O zaman İsa ona şu karşılığı verdi: \"Ey kadın, imanın büyük! Dilediğin gibi olsun.\" Ve kadının kızı o saatte iyileşti. İsa Dört Bin Kişiyi Doyuruyor (Mar.8:1-10)"},{"n":"29","t":"İsa oradan ayrıldı, Celile Gölü'nün kıyısından geçerek dağa çıkıp oturdu."},{"n":"30","t":"Yanına büyük bir kalabalık geldi. Beraberlerinde kötürüm, kör, çolak, dilsiz ve daha birçok hasta getirdiler. Hastaları O'nun ayaklarının dibine bıraktılar. O da onları iyileştirdi."},{"n":"31","t":"Halk, dilsizlerin konuştuğunu, çolakların iyileştiğini, körlerin gördüğünü, kötürümlerin yürüdüğünü görünce şaştı ve İsrail'in Tanrısı'nı yüceltti."},{"n":"32","t":"İsa öğrencilerini yanına çağırıp, \"Halka acıyorum\" dedi. \"Üç gündür yanımdalar, yiyecek hiçbir şeyleri yok. Onları aç aç evlerine göndermek istemiyorum, yolda bayılabilirler.\""},{"n":"33","t":"Öğrenciler kendisine, \"Böyle ıssız bir yerde bu kadar kalabalığı doyuracak ekmeği nereden bulalım?\" dediler."},{"n":"34","t":"İsa, \"Kaç ekmeğiniz var?\" diye sordu. \"Yedi ekmekle birkaç küçük balığımız var\" dediler."},{"n":"35","t":"Bunun üzerine İsa, halka yere oturmalarını buyurdu."},{"n":"36","t":"Yedi ekmekle balıkları aldı, şükredip bunları böldü, öğrencilerine verdi. Onlar da halka dağıttılar."},{"n":"37","t":"Herkes yiyip doydu. Artakalan parçalardan yedi küfe dolusu topladılar."},{"n":"38","t":"Yemek yiyenlerin sayısı, kadın ve çocuklar hariç, dört bin erkekti."},{"n":"39","t":"İsa, halkı evlerine gönderdikten sonra tekneye binip Magadan bölgesine geçti."}]},{"ch":16,"verses":[{"n":"1","t":"Ferisiler'le Sadukiler* İsa'nın yanına geldiler. O'nu denemek amacıyla kendilerine gökten bir belirti göstermesini istediler."},{"n":"2","t":"İsa onlara şu karşılığı verdi: \"Akşam, 'Gökyüzü kızıl olduğuna göre hava iyi olacak' dersiniz."},{"n":"3","t":"Sabah, 'Bugün gök kızıl ve bulutlu, hava bozacak' dersiniz. Gökyüzünün görünümünü yorumlayabiliyorsunuz da, zamanın belirtilerini yorumlayamıyor musunuz?"},{"n":"4","t":"Kötü ve vefasız kuşak bir belirti istiyor! Ama ona Yunus'un belirtisinden başka bir belirti gösterilmeyecek.\" Sonra İsa onları bırakıp gitti. Ferisiler'le Sadukiler'in Mayası (Mar.8:14-21)"},{"n":"5","t":"Öğrenciler gölün karşı yakasına geçerken ekmek almayı unutmuşlardı."},{"n":"6","t":"İsa onlara, \"Dikkatli olun, Ferisiler'in ve Sadukiler'in mayasından kaçının!\" dedi."},{"n":"7","t":"Onlar ise kendi aralarında tartışarak, \"Ekmek almadığımız için böyle diyor\" dediler."},{"n":"8","t":"Bunun farkında olan İsa şöyle dedi: \"Ey kıt imanlılar! Ekmeğiniz yok diye niçin tartışıyorsunuz?"},{"n":"9-10","t":"Hâlâ anlamıyor musunuz? Beş ekmekle beş bin kişinin doyduğunu, kaç sepet dolusu yemek fazlası topladığınızı hatırlamıyor musunuz? Yedi ekmekle dört bin kişinin doyduğunu, kaç küfe dolusu yemek fazlası topladığınızı hatırlamıyor musunuz?"},{"n":"11","t":"Ben size, 'Ferisiler'in ve Sadukiler'in mayasından kaçının' derken, ekmekten söz etmediğimi nasıl olur da anlamazsınız?\""},{"n":"12","t":"Ekmek mayasından değil de, Ferisiler'le Sadukiler'in öğretisinden kaçının dediğini o zaman anladılar. Petrus'un Mesih'i Tanıması (Mar.8:27-30; Luk.9:18-21)"},{"n":"13","t":"İsa, Filipus Sezariyesi bölgesine geldiğinde öğrencilerine şunu sordu: \"Halk, İnsanoğlu'nun* kim olduğunu söylüyor?\""},{"n":"14","t":"Öğrencileri şu karşılığı verdiler: \"Kimi Vaftizci Yahya, kimi İlyas, kimi de Yeremya ya da peygamberlerden biridir diyor.\""},{"n":"15","t":"İsa onlara, \"Siz ne dersiniz\" dedi, \"Sizce ben kimim?\""},{"n":"16","t":"Simun Petrus, \"Sen, yaşayan Tanrı'nın Oğlu Mesih'sin*\" yanıtını verdi."},{"n":"17","t":"İsa ona, \"Ne mutlu sana, Yunus oğlu Simun!\" dedi. \"Bu sırrı sana açan insan*fx* değil, göklerdeki Babam'dır."},{"n":"18","t":"Ben de sana şunu söyleyeyim, sen Petrus'sun*fx* ve ben kilisemi* bu kayanın*fx* üzerine kuracağım. Ölüler diyarının kapıları ona karşı direnemeyecek."},{"n":"19","t":"Göklerin Egemenliği'nin anahtarlarını sana vereceğim. Yeryüzünde bağlayacağın her şey göklerde de bağlanmış olacak; yeryüzünde çözeceğin her şey göklerde de çözülmüş olacak.\""},{"n":"20","t":"Bu sözlerden sonra İsa, kendisinin Mesih olduğunu kimseye söylememeleri için öğrencilerini uyardı. İsa Ölüp Dirileceğini Önceden Bildiriyor (Mar.8:31-9:1; Luk.9:22-27)"},{"n":"21","t":"Bundan sonra İsa, kendisinin Yeruşalim'e gitmesi, ileri gelenler, başkâhinler ve din bilginlerinin elinden çok acı çekmesi, öldürülmesi ve üçüncü gün dirilmesi gerektiğini öğrencilerine anlatmaya başladı."},{"n":"22","t":"Bunun üzerine Petrus O'nu bir kenara çekip azarlamaya başladı. \"Tanrı korusun, ya Rab! Senin başına asla böyle bir şey gelmeyecek!\" dedi."},{"n":"23","t":"Ama İsa Petrus'a dönüp, \"Çekil önümden, Şeytan!\" dedi, \"Bana engel oluyorsun. Düşüncelerin Tanrı'ya değil, insana özgüdür.\""},{"n":"24","t":"Sonra İsa, öğrencilerine şunları söyledi: \"Ardımdan gelmek isteyen kendini inkâr etsin, çarmıhını yüklenip beni izlesin."},{"n":"25","t":"Canını kurtarmak isteyen onu yitirecek, canını benim uğruma yitiren ise onu kurtaracaktır."},{"n":"26","t":"İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur? İnsan kendi canına karşılık ne verebilir?"},{"n":"27","t":"İnsanoğlu*, Babası'nın görkemi içinde melekleriyle gelecek ve herkese, yaptığının karşılığını verecektir."},{"n":"28","t":"Size doğrusunu söyleyeyim, burada bulunanlar arasında, İnsanoğlu'nun kendi egemenliği içinde gelişini görmeden ölümü tatmayacak olanlar var.\""}]},{"ch":17,"verses":[{"n":"1","t":"Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yakup'un kardeşi Yuhanna'yı alarak yüksek bir dağa çıktı."},{"n":"2","t":"Onların gözü önünde İsa'nın görünümü değişti. Yüzü güneş gibi parladı, giysileri ışık gibi bembeyaz oldu."},{"n":"3","t":"O anda Musa'yla İlyas öğrencilere göründü. İsa'yla konuşuyorlardı."},{"n":"4","t":"Petrus İsa'ya, \"Ya Rab\" dedi, \"Burada bulunmamız ne iyi oldu! İstersen burada üç çardak kurayım: Biri sana, biri Musa'ya, biri de İlyas'a.\""},{"n":"5","t":"Petrus daha konuşurken parlak bir bulut onlara gölge saldı. Buluttan gelen bir ses, \"Sevgili Oğlum budur, O'ndan hoşnudum. O'nu dinleyin!\" dedi."},{"n":"6","t":"Öğrenciler bunu işitince, dehşet içinde yüzüstü yere kapandılar."},{"n":"7","t":"İsa gelip onlara dokundu, \"Kalkın, korkmayın!\" dedi."},{"n":"8","t":"Başlarını kaldırınca İsa'dan başka kimseyi göremediler."},{"n":"9","t":"Dağdan inerlerken İsa onlara, \"İnsanoğlu* ölümden dirilmeden, gördüklerinizi kimseye söylemeyin\" diye buyurdu."},{"n":"10","t":"Öğrencileri O'na şunu sordular: \"Peki, din bilginleri* neden önce İlyas'ın gelmesi gerektiğini söylüyorlar?\""},{"n":"11","t":"İsa, \"İlyas gerçekten gelecek ve her şeyi yeniden düzene koyacak\" diye yanıtladı."},{"n":"12","t":"\"Size şunu söyleyeyim, İlyas zaten geldi, ama onu tanımadılar, ona yapmadıklarını bırakmadılar. Aynı şekilde İnsanoğlu da onların elinden acı çekecektir.\""},{"n":"13","t":"O zaman öğrenciler İsa'nın kendilerine Vaftizci Yahya'dan söz ettiğini anladılar. Cinli Çocuk İyileştiriliyor (Mar.9:14-32; Luk.9:37-45)"},{"n":"14","t":"Kalabalığın yanına vardıklarında bir adam İsa'ya yaklaşıp önünde diz çöktü."},{"n":"15","t":"\"Ya Rab\" dedi, \"Oğlumun haline acı! Sarası var, çok acı çekiyor. Sık sık ateşe, suya düşüyor."},{"n":"16","t":"Onu senin öğrencilerine getirdim, ama iyileştiremediler.\""},{"n":"17","t":"İsa, \"Ey imansız ve sapmış kuşak!\" dedi. \"Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Çocuğu buraya, bana getirin.\""},{"n":"18","t":"İsa cini azarlayınca, cin çocuktan çıktı, çocuk o anda iyileşti."},{"n":"19","t":"Sonra öğrenciler tek başlarına İsa'ya gelip, \"Biz cini neden kovamadık?\" diye sordular."},{"n":"20-21","t":"İsa, \"İmanınız kıt olduğu için\" karşılığını verdi. \"Size doğrusunu söyleyeyim, bir hardal tanesi kadar imanınız olsa şu dağa, 'Buradan şuraya göç' derseniz, göçer; sizin için imkânsız bir şey olmayacaktır.\"*fx* İsa Ölüp Dirileceğini Tekrar Bildiriyor (Mar.9:30-32; Luk.9:43-45)"},{"n":"22-23","t":"Celile'de bir araya geldiklerinde İsa onlara, \"İnsanoğlu*, insanların eline teslim edilecek ve öldürülecek, ama üçüncü gün dirilecek\" dedi. Öğrenciler buna çok kederlendiler. Tapınak Vergisi"},{"n":"24","t":"Kefarnahum'a geldiklerinde, iki dirhemlik tapınak vergisini*fx* toplayanlar Petrus'a gelip, \"Öğretmeniniz tapınak vergisini ödemiyor mu?\" diye sordular."},{"n":"25","t":"Petrus, \"Ödüyor\" dedi. Petrus eve gelince, daha kendisi bir şey söylemeden İsa ona, \"Simun, ne dersin?\" dedi. \"Dünya kralları gümrük ya da vergiyi kimlerden alır? Kendi oğullarından mı, yabancılardan mı?\""},{"n":"26","t":"Petrus'un, \"Yabancılardan\" demesi üzerine İsa, \"O halde oğullar muaftır\" dedi."},{"n":"27","t":"\"Ama vergi toplayanları gücendirmeyelim. Göle gidip oltanı at. Tuttuğun ilk balığı çıkar, onun ağzını aç, dört dirhemlik bir akçe*fx* bulacaksın. Parayı al, ikimizin vergisi olarak onlara ver.\""}]},{"ch":18,"verses":[{"n":"1","t":"Bu sırada öğrencileri İsa'ya yaklaşıp, \"Göklerin Egemenliği'nde en büyük kimdir?\" diye sordular."},{"n":"2-3","t":"İsa, yanına küçük bir çocuk çağırdı, onu orta yere dikip şöyle dedi: \"Size doğrusunu söyleyeyim, yolunuzdan dönüp küçük çocuklar gibi olmazsanız, Göklerin Egemenliği'ne asla giremezsiniz."},{"n":"4","t":"Kim bu çocuk gibi alçakgönüllü olursa, Göklerin Egemenliği'nde en büyük odur."},{"n":"5","t":"Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur."},{"n":"6","t":"\"Ama kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocaman bir değirmen taşı asılıp denizin dibine atılması kendisi için daha iyi olur."},{"n":"7","t":"İnsanı günaha düşüren tuzaklardan ötürü vay dünyanın haline! Böyle tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!"},{"n":"8","t":"\"Eğer elin ya da ayağın günah işlemene neden olursa, onu kesip at. Tek el, tek ayakla yaşama kavuşman, iki elle, iki ayakla sönmez ateşe atılmandan iyidir."},{"n":"9","t":"Eğer gözün günah işlemene neden olursa, onu çıkar at. Tek gözle yaşama kavuşman, iki gözle cehennem ateşine atılmandan iyidir."},{"n":"10-11","t":"\"Bu küçüklerden birini bile hor görmekten sakının! Size şunu söyleyeyim, onların göklerdeki melekleri, göklerdeki Babam'ın yüzünü her zaman görürler.\"*fx* Kaybolan Koyun Benzetmesi (Luk.15:3-7)"},{"n":"12","t":"\"Siz ne dersiniz? Bir adamın yüz koyunu olsa ve bunlardan biri yolunu şaşırsa, doksan dokuzunu dağlarda bırakıp yolunu şaşıranı aramaya gitmez mi?"},{"n":"13","t":"Size doğrusunu söyleyeyim, eğer onu bulursa, yolunu şaşırmamış doksan dokuz koyun için sevindiğinden daha çok onun için sevinir."},{"n":"14","t":"Bunun gibi, göklerdeki Babanız da bu küçüklerden hiçbirinin kaybolmasını istemez.\" Bir Kardeş Günah İşlerse"},{"n":"15","t":"\"Eğer kardeşin sana karşı günah işlerse, ona git, suçunu kendisine göster. Her şey yalnız ikinizin arasında kalsın. Kardeşin seni dinlerse, onu kazanmış olursun."},{"n":"16","t":"Ama dinlemezse, yanına bir ya da iki kişi daha al ki, söylenen her şey iki ya da üç tanığın sözüyle doğrulansın."},{"n":"17","t":"Onları da dinlemezse, durumu inanlılar topluluğuna* bildir. Topluluğu da dinlemezse, onu putperest ya da vergi görevlisi* say."},{"n":"18","t":"\"Size doğrusunu söyleyeyim, yeryüzünde bağlayacağınız her şey gökte de bağlanmış olacak. Yeryüzünde çözeceğiniz her şey gökte de çözülmüş olacak."},{"n":"19","t":"Yine size şunu söyleyeyim, yeryüzünde aranızdan iki kişi, dileyecekleri herhangi bir şey için anlaşırlarsa, göklerdeki Babam dileklerini yerine getirir."},{"n":"20","t":"Nerede iki ya da üç kişi benim adımla toplanırsa, ben de orada, aralarındayım.\" Acımasız Köle Benzetmesi"},{"n":"21","t":"Bunun üzerine Petrus İsa'ya gelip, \"Ya Rab\" dedi, \"Kardeşim bana karşı kaç kez günah işlerse onu bağışlamalıyım? Yedi kez mi?\""},{"n":"22","t":"İsa, \"Yedi kez değil\" dedi. \"Yetmiş kere yedi kez derim sana."},{"n":"23","t":"Şöyle ki, Göklerin Egemenliği, köleleriyle hesaplaşmak isteyen bir krala benzer."},{"n":"24","t":"Kral hesap görmeye başladığında kendisine, borcu on bin talantı bulan bir köle getirildi."},{"n":"25","t":"Kölenin ödeme gücü olmadığından efendisi onun, karısının, çocuklarının ve bütün malının satılıp borcun ödenmesini buyurdu."},{"n":"26","t":"Köle yere kapanıp efendisine, 'Ne olur, sabret! Bütün borcumu ödeyeceğim' dedi."},{"n":"27","t":"Efendisi köleye acıdı, borcunu bağışlayıp onu salıverdi."},{"n":"28","t":"\"Ama köle çıkıp gitti, kendisine yüz dinar borcu olan başka bir köleye rastladı. Onu yakalayıp, 'Borcunu öde' diyerek boğazına sarıldı."},{"n":"29","t":"Bu köle yüzüstü yere kapandı, 'Ne olur, sabret! Borcumu ödeyeceğim' diye yalvardı."},{"n":"30","t":"Ama ilk köle bunu reddetti. Gitti, borcunu ödeyinceye dek adamı zindana kapattı."},{"n":"31","t":"Öteki köleler, olanları görünce çok üzüldüler. Efendilerine gidip bütün olup bitenleri anlattılar."},{"n":"32","t":"\"Bunun üzerine efendisi köleyi yanına çağırdı. 'Ey kötü köle!' dedi. 'Bana yalvardığın için bütün borcunu bağışladım."},{"n":"33","t":"Benim sana acıdığım gibi, senin de köle arkadaşına acıman gerekmez miydi?'"},{"n":"34","t":"Bu öfkeyle efendisi, bütün borcunu ödeyinceye dek onu işkencecilere teslim etti."},{"n":"35","t":"\"Eğer her biriniz kardeşini gönülden bağışlamazsa, göksel Babam da size öyle davranacaktır.\""}]},{"ch":19,"verses":[{"n":"1","t":"İsa konuşmasını bitirdikten sonra Celile'den ayrılıp Yahudiye'nin* Şeria Irmağı'nın karşı yakasındaki topraklarına geçti."},{"n":"2","t":"Büyük halk toplulukları da O'nun ardından gitti. Hasta olanları orada iyileştirdi."},{"n":"3","t":"İsa'nın yanına gelen bazı Ferisiler*, O'nu denemek amacıyla şunu sordular: \"Bir adamın, herhangi bir nedenle karısını boşaması Kutsal Yasa'ya uygun mudur?\""},{"n":"4-5","t":"İsa şu karşılığı verdi: \"Kutsal Yazılar'ı okumadınız mı? Yaradan başlangıçtan 'İnsanları erkek ve dişi olarak yarattı' ve şöyle dedi: 'Bu nedenle adam annesini babasını bırakıp karısına bağlanacak, ikisi tek beden olacak.'"},{"n":"6","t":"Şöyle ki, onlar artık iki değil, tek bedendir. O halde Tanrı'nın birleştirdiğini, insan ayırmasın.\""},{"n":"7","t":"Ferisiler İsa'ya, \"Öyleyse\" dediler, \"Musa neden erkeğin boşanma belgesi verip karısını boşayabileceğini söyledi?\""},{"n":"8","t":"İsa onlara, \"İnatçı olduğunuz için Musa karılarınızı boşamanıza izin verdi\" dedi. \"Başlangıçta bu böyle değildi."},{"n":"9","t":"Ben size şunu söyleyeyim, karısını fuhuştan başka bir nedenle boşayıp başkasıyla evlenen, zina etmiş olur. Boşanan kadınla evlenen de zina etmiş olur*fx*.\""},{"n":"10","t":"Öğrenciler İsa'ya, \"Eğer erkekle karısı arasındaki ilişki buysa, hiç evlenmemek daha iyi!\" dediler."},{"n":"11","t":"İsa onlara, \"Herkes bu sözü kabul edemez, ancak Tanrı'nın güç verdiği kişiler kabul edebilir\" dedi."},{"n":"12","t":"\"Çünkü kimisi doğuştan hadımdır, kimisi insanlar tarafından hadım edilir, kimisi de Göklerin Egemenliği uğruna kendini hadım sayar. Bunu kabul edebilen etsin!\" İsa Küçük Çocukları Kutsuyor (Mar.10:13-16; Luk.18:15-17)"},{"n":"13-14","t":"O sırada bazıları küçük çocukları İsa'nın yanına getirdiler; ellerini onların üzerine koyup dua etmesini istediler. Öğrenciler onları azarlayınca İsa, \"Bırakın çocukları\" dedi. \"Bana gelmelerine engel olmayın! Çünkü Göklerin Egemenliği böylelerinindir.\""},{"n":"15","t":"Ellerini onların üzerine koyduktan sonra oradan ayrıldı. Zenginlik ve Sonsuz Yaşam (Mar.10:17-31; Luk.18:18-30)"},{"n":"16","t":"Adamın biri İsa'ya gelip, \"Öğretmenim, sonsuz yaşama kavuşmak için nasıl bir iyilik yapmalıyım?\" diye sordu."},{"n":"17","t":"İsa, \"Bana neden iyilik hakkında soru soruyorsun?\" dedi. \"İyi olan yalnız biri var. Yaşama kavuşmak istiyorsan, O'nun buyruklarını yerine getir.\""},{"n":"18-19","t":"\"Hangi buyrukları?\" diye sordu adam. İsa şu karşılığı verdi: \"'Adam öldürmeyeceksin, zina etmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, annene babana saygı göstereceksin' ve 'Komşunu kendin gibi seveceksin.'\""},{"n":"20","t":"Genç adam, \"Bunların hepsini yerine getirdim\" dedi, \"Daha ne eksiğim var?\""},{"n":"21","t":"İsa ona, \"Eğer eksiksiz olmak istiyorsan, git, varını yoğunu sat, parasını yoksullara ver; böylece göklerde hazinen olur. Sonra gel, beni izle\" dedi."},{"n":"22","t":"Genç adam bu sözleri işitince üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı."},{"n":"23","t":"İsa öğrencilerine, \"Size doğrusunu söyleyeyim\" dedi, \"Zengin kişi Göklerin Egemenliği'ne zor girecek."},{"n":"24","t":"Yine şunu söyleyeyim ki, devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliği'ne girmesinden daha kolaydır.\""},{"n":"25","t":"Bunu işiten öğrenciler büsbütün şaşırdılar, \"Öyleyse kim kurtulabilir?\" diye sordular."},{"n":"26","t":"İsa onlara bakarak, \"İnsanlar için bu imkânsız, ama Tanrı için her şey mümkündür\" dedi."},{"n":"27","t":"Bunun üzerine Petrus O'na, \"Bak\" dedi, \"Biz her şeyi bırakıp senin ardından geldik, kazancımız ne olacak?\""},{"n":"28","t":"İsa onlara, \"Size doğrusunu söyleyeyim\" dedi, \"Her şey yenilendiğinde, İnsanoğlu* görkemli tahtına oturduğunda, siz, evet ardımdan gelen sizler, on iki tahta oturup İsrail'in on iki oymağını yargılayacaksınız."},{"n":"29","t":"Benim adım uğruna evlerini, kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakan herkes, bunların yüz katını elde edecek ve sonsuz yaşamı miras alacak."},{"n":"30","t":"Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak.\""}]},{"ch":20,"verses":[{"n":"1","t":"\"Göklerin Egemenliği, sabah erkenden bağında çalışacak işçi aramaya çıkan toprak sahibine benzer."},{"n":"2","t":"Adam, işçilerle günlüğü bir dinara anlaşıp onları bağına gönderdi."},{"n":"3","t":"\"Saat* dokuza doğru tekrar dışarı çıktı, çarşı meydanında boş duran başka adamlar gördü."},{"n":"4-5","t":"Onlara, 'Siz de bağa gidip çalışın. Hakkınız neyse, veririm' dedi, onlar da bağa gittiler. \"Öğleyin ve saat üçe doğru yine çıkıp aynı şeyi yaptı."},{"n":"6","t":"Saat beşe doğru çıkınca, orada duran başka işçiler gördü. Onlara, 'Neden bütün gün burada boş duruyorsunuz?' diye sordu."},{"n":"7","t":"\"'Kimse bize iş vermedi ki' dediler. \"Onlara, 'Siz de bağa gidin, çalışın' dedi."},{"n":"8","t":"\"Akşam olunca, bağın sahibi kâhyasına, 'İşçileri çağır' dedi. 'Sonuncudan başlayarak ilkine kadar, hepsine ücretlerini ver.'"},{"n":"9","t":"\"Saat beşe doğru işe başlayanlar gelip kâhyadan birer dinar aldılar."},{"n":"10","t":"İlk başlayanlar gelince daha çok alacaklarını sandılar, ama onlara da birer dinar verildi."},{"n":"11","t":"Paralarını alınca bağ sahibine söylenmeye başladılar:"},{"n":"12","t":"'En son çalışanlar yalnız bir saat çalıştı' dediler. 'Ama onları günün yükünü ve sıcağını çeken bizlerle bir tuttun!'"},{"n":"13","t":"\"Bağ sahibi onlardan birine şöyle karşılık verdi: 'Arkadaş, sana haksızlık etmiyorum ki! Seninle bir dinara anlaşmadık mı?"},{"n":"14","t":"Hakkını al, git! Sana verdiğimi sonuncuya da vermek istiyorum."},{"n":"15","t":"Kendi paramla istediğimi yapmaya hakkım yok mu? Yoksa cömertliğimi kıskanıyor musun?'"},{"n":"16","t":"\"İşte böylece sonuncular birinci, birinciler de sonuncu olacak.\" İsa Ölüp Dirileceğini Üçüncü Kez Bildiriyor (Mar.10:32-34; Luk.18:31-34)"},{"n":"17-18","t":"İsa Yeruşalim'e giderken, yolda on iki öğrencisini bir yana çekip onlara özel olarak şunu söyledi: \"Şimdi Yeruşalim'e gidiyoruz. İnsanoğlu*, başkâhinlerin ve din bilginlerinin eline teslim edilecek, onlar da O'nu ölüm cezasına çarptıracaklar."},{"n":"19","t":"O'nunla alay etmeleri, kamçılayıp çarmıha germeleri için O'nu öteki uluslara teslim edecekler. Ne var ki O, üçüncü gün dirilecek.\" Bir Annenin İsteği (Mar.10:35-45)"},{"n":"20","t":"O sırada Zebedi oğullarının annesi oğullarıyla birlikte İsa'ya yaklaştı. Önünde yere kapanarak kendisinden bir dileği olduğunu söyledi."},{"n":"21","t":"İsa kadına, \"Ne istiyorsun?\" diye sordu. Kadın, \"Buyruk ver, senin egemenliğinde bu iki oğlumdan biri sağında, biri solunda otursun\" dedi."},{"n":"22","t":"\"Siz ne dilediğinizi bilmiyorsunuz\" diye karşılık verdi İsa. \"Benim içeceğim kâseden* siz içebilir misiniz?\" \"Evet, içebiliriz\" dediler."},{"n":"23","t":"İsa onlara, \"Elbette benim kâsemden içeceksiniz\" dedi, \"Ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Babam bu yerleri belirli kişiler için hazırlamıştır.\""},{"n":"24","t":"Bunu işiten on öğrenci iki kardeşe kızdılar."},{"n":"25","t":"Ama İsa onları yanına çağırıp şöyle dedi: \"Bilirsiniz ki, ulusların önderleri onlara egemen kesilir, ileri gelenleri de ağırlıklarını hissettirirler."},{"n":"26","t":"Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, ötekilerin hizmetkârı olsun."},{"n":"27","t":"Aranızda birinci olmak isteyen, ötekilerin kulu olsun."},{"n":"28","t":"Nitekim İnsanoğlu*, hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldi.\" İki Körün Gözleri Açılıyor (Mar.10:46-52; Luk.18:35-43)"},{"n":"29","t":"Eriha'dan ayrılırlarken büyük bir kalabalık İsa'nın ardından gitti."},{"n":"30","t":"Yol kenarında oturan iki kör, İsa'nın oradan geçmekte olduğunu duyunca, \"Ya Rab, ey Davut Oğlu*, halimize acı!\" diye bağırdılar."},{"n":"31","t":"Kalabalık onları azarlayarak susturmak istediyse de onlar, \"Ya Rab, ey Davut Oğlu, halimize acı!\" diyerek daha çok bağırdılar."},{"n":"32","t":"İsa durup onları çağırdı. \"Sizin için ne yapmamı istiyorsunuz?\" diye sordu."},{"n":"33","t":"Onlar da, \"Ya Rab, gözlerimiz açılsın\" dediler."},{"n":"34","t":"İsa onlara acıdı, gözlerine dokundu. O anda yeniden görmeye başladılar ve O'nun ardından gittiler."}]},{"ch":21,"verses":[{"n":"1-2","t":"Yeruşalim'e yaklaşıp Zeytin Dağı'nın yamacındaki Beytfaci Köyü'ne geldiklerinde İsa, iki öğrencisini önden gönderdi. Onlara, \"Karşınızdaki köye gidin\" dedi, \"Hemen orada bağlı bir dişi eşek ve yanında bir sıpa bulacaksınız. Onları çözüp bana getirin."},{"n":"3","t":"Size bir şey diyen olursa, 'Rab'bin bunlara ihtiyacı var, hemen geri gönderecek' dersiniz.\""},{"n":"4","t":"Bu olay, peygamber aracılığıyla bildirilen şu söz yerine gelsin diye oldu:"},{"n":"5","t":"\"Siyon* kızına deyin ki, 'İşte, alçakgönüllü Kralın, Eşeğe, evet sıpaya, Eşek yavrusuna binmiş Sana geliyor.'\""},{"n":"6","t":"Öğrenciler gidip İsa'nın kendilerine buyurduğu gibi yaptılar."},{"n":"7","t":"Eşekle sıpayı getirip üzerlerine giysilerini yaydılar, İsa sıpaya bindi."},{"n":"8","t":"Halkın büyük bir bölümü giysilerini yolun üzerine serdi. Bazıları da ağaçlardan dal kesip yola seriyordu."},{"n":"9","t":"Önden giden ve arkadan gelen kalabalıklar şöyle bağırıyorlardı: \"Davut Oğlu'na hozana*! Rab'bin adıyla gelene övgüler olsun, En yücelerde hozana!\""},{"n":"10","t":"İsa Yeruşalim'e girdiği zaman bütün kent, \"Bu kimdir?\" diyerek çalkandı."},{"n":"11","t":"Kalabalıklar, \"Bu, Celile'nin Nasıra Kenti'nden Peygamber İsa'dır\" diyordu. İsa Satıcıları Tapınaktan Kovuyor (Mar.11:15-19; Luk.19:45-48; Yu.2:13-22)"},{"n":"12","t":"İsa, tapınağın avlusuna girerek oradaki bütün alıcı ve satıcıları dışarı kovdu. Para bozanların* masalarını, güvercin satanların sehpalarını devirdi."},{"n":"13","t":"Onlara şöyle dedi: \"'Evime dua evi denecek' diye yazılmıştır. Ama siz onu haydut inine çevirdiniz!\""},{"n":"14","t":"İsa tapınaktayken kendisine gelen kör ve kötürümleri iyileştirdi."},{"n":"15","t":"Ne var ki, başkâhinlerle din bilginleri, O'nun yarattığı harikaları ve tapınakta, \"Davut Oğlu'na hozana!\" diye bağıran çocukları görünce öfkelendiler."},{"n":"16","t":"İsa'ya, \"Bunların ne söylediğini duyuyor musun?\" diye sordular. \"Duyuyorum\" dedi İsa. \"Siz şu sözü hiç okumadınız mı? 'Küçük çocukların ve emziktekilerin dudaklarından kendine övgüler döktürdün.'\""},{"n":"17","t":"İsa onları bırakıp kentten çıktı. Beytanya'ya dönüp geceyi orada geçirdi. Meyvesiz İncir Ağacı (Mar.11:12-14,20-24)"},{"n":"18","t":"İsa sabah erkenden kente dönerken acıkmıştı."},{"n":"19","t":"Yol kenarında gördüğü bir incir ağacına yaklaştı. Ağaçta yapraktan başka bir şey bulamayınca ağaca, \"Artık sonsuza dek sende meyve yetişmesin!\" dedi. İncir ağacı o anda kurudu."},{"n":"20","t":"Öğrenciler bunu görünce şaşkına döndüler. \"İncir ağacı birdenbire nasıl kurudu?\" diye sordular."},{"n":"21","t":"İsa onlara şu karşılığı verdi: \"Size doğrusunu söyleyeyim, eğer imanınız olur da kuşku duymazsanız, yalnız incir ağacına olanı yapmakla kalmazsınız; şu dağa, 'Kalk, denize atıl' derseniz, dediğiniz olacaktır."},{"n":"22","t":"İmanla dua ederseniz, dilediğiniz her şeyi alırsınız.\" İsa'nın Yetkisi (Mar.11:27-33; Luk.20:1-8)"},{"n":"23","t":"İsa tapınağa girmiş öğretiyordu. Bu sırada başkâhinler ve halkın ileri gelenleri O'nun yanına gelerek, \"Bunları hangi yetkiyle yapıyorsun, bu yetkiyi sana kim verdi?\" diye sordular."},{"n":"24","t":"İsa onlara şu karşılığı verdi: \"Ben de size bir soru soracağım. Bana yanıt verirseniz, ben de size bunları hangi yetkiyle yaptığımı söylerim."},{"n":"25","t":"Yahya'nın vaftiz etme yetkisi*fx* nereden geldi, Tanrı'dan mı*fx*, insanlardan mı?\" Bunu aralarında şöyle tartışmaya başladılar: \"'Tanrı'dan' dersek, bize, 'Öyleyse ona niçin inanmadınız?' diyecek."},{"n":"26","t":"Yok eğer 'İnsanlardan' dersek... Halkın tepkisinden korkuyoruz. Çünkü herkes Yahya'yı peygamber sayıyor.\""},{"n":"27","t":"İsa'ya, \"Bilmiyoruz\" diye yanıt verdiler. İsa, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi. İki Oğul Benzetmesi"},{"n":"28","t":"\"Ama şuna ne dersiniz? Bir adamın iki oğlu vardı. Adam birincisine gidip, 'Oğlum, git bugün bağda çalış' dedi."},{"n":"29","t":"\"Oğlu, 'Gitmem!' dedi. Ama sonra pişman olup gitti."},{"n":"30","t":"\"Adam ikinci oğluna gidip aynı şeyi söyledi. O, 'Olur, efendim' dedi, ama gitmedi."},{"n":"31","t":"\"İkisinden hangisi babasının isteğini yerine getirmiş oldu?\" \"Birincisi\" diye karşılık verdiler. İsa da onlara, \"Size doğrusunu söyleyeyim, vergi görevlileriyle fahişeler, Tanrı'nın Egemenliği'ne sizden önce giriyorlar\" dedi."},{"n":"32","t":"\"Yahya size doğruluk yolunu göstermeye geldi, ona inanmadınız. Oysa vergi görevlileriyle fahişeler ona inandılar. Siz bunu gördükten sonra bile pişman olup ona inanmadınız.\" Bağ Kiracıları Benzetmesi (Mar.12:1-12; Luk.20:9-19)"},{"n":"33","t":"\"Bir benzetme daha dinleyin: Toprak sahibi bir adam, bağ dikti, çevresini çitle çevirdi, üzüm sıkma çukuru kazdı, bir de bekçi kulesi yaptı. Sonra bağı bağcılara kiralayıp yolculuğa çıktı."},{"n":"34","t":"Bağbozumu yaklaşınca, üründen kendisine düşeni almaları için kölelerini bağcılara yolladı."},{"n":"35","t":"Bağcılar adamın kölelerini yakaladı, birini dövdü, birini öldürdü, ötekini de taşladı."},{"n":"36","t":"Bağ sahibi bu kez ilkinden daha çok sayıda köle yolladı. Bağcılar bunlara da aynı şeyi yaptılar."},{"n":"37","t":"Sonunda bağ sahibi, 'Oğlumu sayarlar' diyerek bağcılara onu yolladı."},{"n":"38","t":"\"Ama bağcılar adamın oğlunu görünce birbirlerine, 'Mirasçı bu; gelin, onu öldürüp mirasına konalım' dediler."},{"n":"39","t":"Böylece onu yakaladılar, bağdan atıp öldürdüler."},{"n":"40","t":"Bu durumda bağın sahibi geldiği zaman bağcılara ne yapacak?\""},{"n":"41","t":"İsa'ya şu karşılığı verdiler: \"Bu korkunç adamları korkunç bir şekilde yok edecek; bağı da, ürününü kendisine zamanında verecek olan başka bağcılara kiralayacak.\""},{"n":"42","t":"İsa onlara şunu sordu: \"Kutsal Yazılar'da şu sözleri hiç okumadınız mı? 'Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu. Rab'bin işidir bu, Gözümüzde harika bir iş!'"},{"n":"43","t":"\"Bu nedenle size şunu söyleyeyim, Tanrı'nın Egemenliği sizden alınacak ve bunun ürünlerini yetiştiren bir ulusa verilecek."},{"n":"44","t":"\"Bu taşın üzerine düşen, paramparça olacak; taş da kimin üzerine düşerse, onu ezip toz edecek.\""},{"n":"45","t":"Başkâhinler ve Ferisiler, İsa'nın anlattığı benzetmeleri duyunca bunları kendileri için söylediğini anladılar."},{"n":"46","t":"O'nu tutuklamak istedilerse de, halkın tepkisinden korktular. Çünkü halk, O'nu peygamber sayıyordu."}]},{"ch":22,"verses":[{"n":"1-2","t":"İsa söz alıp onlara yine benzetmelerle şöyle seslendi: \"Göklerin Egemenliği, oğlu için düğün şöleni hazırlayan bir krala benzer."},{"n":"3","t":"Kral şölene davet ettiklerini çağırmak üzere kölelerini gönderdi, ama davetliler gelmek istemedi."},{"n":"4","t":"\"Kral yine başka kölelerini gönderirken onlara dedi ki, 'Davetlilere şunu söyleyin: Bakın, ben ziyafetimi hazırladım. Sığırlarım, besili hayvanlarım kesildi. Her şey hazır, buyrun şölene!'"},{"n":"5","t":"\"Ama davetliler aldırmadılar. Biri tarlasına, biri ticaretine gitti."},{"n":"6","t":"Öbürleri de kralın kölelerini yakalayıp hırpaladılar ve öldürdüler."},{"n":"7","t":"Kral öfkelendi. Ordularını gönderip o katilleri yok etti, kentlerini ateşe verdi."},{"n":"8","t":"\"Sonra kölelerine şöyle dedi: 'Düğün şöleni hazır, ama çağırdıklarım buna layık değilmiş."},{"n":"9","t":"Gidin yol kavşaklarına, kimi bulursanız düğüne çağırın.'"},{"n":"10","t":"Böylece köleler yollara döküldü, iyi kötü kimi buldularsa, hepsini topladılar. Düğün yeri konuklarla doldu."},{"n":"11","t":"\"Kral konukları görmeye geldiğinde, orada düğün giysisi giymemiş bir adam gördü."},{"n":"12","t":"Ona, 'Arkadaş, düğün giysisi giymeden buraya nasıl girdin?' diye sorunca, adamın dili tutuldu."},{"n":"13","t":"\"O zaman kral, uşaklarına, 'Şunun ellerini ayaklarını bağlayın, dışarıya, karanlığa atın!' dedi. 'Orada ağlayış ve diş gıcırtısı olacaktır.'"},{"n":"14","t":"\"Çünkü çağrılanlar çok, ama seçilenler azdır.\" Sezar'ın Hakkı Sezar'a (Mar.12:13-17; Luk.20:20-26)"},{"n":"15","t":"Bunun üzerine Ferisiler çıkıp gittiler. İsa'yı, kendi söyleyeceği sözlerle tuzağa düşürmek amacıyla düzen kurdular."},{"n":"16","t":"Hirodes* yanlılarıyla birlikte gönderdikleri kendi öğrencileri İsa'ya gelip, \"Öğretmenimiz\" dediler, \"Senin dürüst biri olduğunu, Tanrı yolunu dürüstçe öğrettiğini, kimseyi kayırmadığını biliyoruz. Çünkü insanlar arasında ayrım yapmazsın."},{"n":"17","t":"Peki, söyle bize, sence Sezar'a* vergi vermek Kutsal Yasa'ya uygun mu değil mi?\""},{"n":"18","t":"İsa onların kötü niyetlerini bildiğinden, \"Ey ikiyüzlüler!\" dedi. \"Beni neden deniyorsunuz?"},{"n":"19","t":"Vergi öderken kullandığınız parayı gösterin bana!\" O'na bir dinar getirdiler."},{"n":"20","t":"İsa, \"Bu resim, bu yazı kimin?\" diye sordu."},{"n":"21","t":"\"Sezar'ın\" dediler.O zaman İsa, \"Öyleyse Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını Tanrı'ya verin\" dedi."},{"n":"22","t":"Bu sözleri duyunca şaştılar, İsa'yı bırakıp gittiler. Dirilişle İlgili Soru (Mar.12:18-27; Luk.20:27-40)"},{"n":"23-24","t":"Ölümden sonra diriliş olmadığını söyleyen Sadukiler*, aynı gün İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa şöyle buyurmuştur: 'Eğer bir adam çocuk sahibi olmadan ölürse, kardeşi onun karısını alsın, soyunu sürdürsün.'"},{"n":"25","t":"Aramızda yedi kardeş vardı. İlki evlendi ve öldü. Çocuğu olmadığından karısını kardeşine bıraktı."},{"n":"26","t":"İkincisi, üçüncüsü, yedincisine kadar hepsine aynı şey oldu."},{"n":"27","t":"Hepsinden sonra kadın da öldü."},{"n":"28","t":"Buna göre diriliş günü kadın bu yedi kardeşten hangisinin karısı olacak? Çünkü hepsi de onunla evlendi.\""},{"n":"29","t":"İsa onlara, \"Siz Kutsal Yazılar'ı ve Tanrı'nın gücünü bilmediğiniz için yanılıyorsunuz\" diye karşılık verdi."},{"n":"30","t":"\"Dirilişten sonra insanlar ne evlenir, ne de evlendirilir, gökteki melekler gibidirler."},{"n":"31","t":"Ölülerin dirilmesi konusuna gelince, Tanrı'nın size bildirdiği şu sözü okumadınız mı?"},{"n":"32","t":"'Ben İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısı'yım' diyor. Tanrı ölülerin değil, dirilerin Tanrısı'dır.\""},{"n":"33","t":"Bunları işiten halk, O'nun öğretişine şaşıp kaldı. En Büyük Buyruk (Mar.12:28-34; Luk.10:25-28)"},{"n":"34","t":"Ferisiler, İsa'nın Sadukiler'i susturduğunu duyunca bir araya toplandılar."},{"n":"35-36","t":"Onlardan biri, bir Kutsal Yasa uzmanı, İsa'yı denemek amacıyla O'na şunu sordu: \"Öğretmenim, Kutsal Yasa'da en önemli buyruk hangisidir?\""},{"n":"37","t":"İsa ona şu karşılığı verdi: \"'Tanrın Rab'bi bütün yüreğinle, bütün canınla ve bütün aklınla seveceksin.'"},{"n":"38","t":"İşte ilk ve en önemli buyruk budur."},{"n":"39","t":"İlkine benzeyen ikinci buyruk da şudur: 'Komşunu kendin gibi seveceksin.'"},{"n":"40","t":"Kutsal Yasa'nın tümü ve peygamberlerin sözleri bu iki buyruğa dayanır.\" Mesih Kimin Oğlu? (Mar.12:35-37; Luk.20:41-44)"},{"n":"41-42","t":"Ferisiler toplu haldeyken İsa onlara şunu sordu: \"Mesih'le* ilgili olarak ne düşünüyorsunuz? O kimin oğludur?\" Onlar da, \"Davut'un Oğlu\" dediler."},{"n":"43","t":"İsa şöyle dedi: \"O halde nasıl oluyor da Davut, Ruh'tan esinlenerek O'ndan 'Rab' diye söz ediyor? Şöyle diyor Davut:"},{"n":"44","t":"'Rab Rabbim'e dedi ki,Ben düşmanlarını Ayaklarının altına serinceye dek Sağımda otur.'"},{"n":"45","t":"Davut O'ndan Rab diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\""},{"n":"46","t":"İsa'ya hiç kimse karşılık veremedi. O günden sonra artık kimse de O'na bir şey sormaya cesaret edemedi."}]},{"ch":23,"verses":[{"n":"1-2","t":"Bundan sonra İsa halka ve öğrencilerine şöyle seslendi: \"Din bilginleri* ve Ferisiler* Musa'nın kürsüsünde otururlar."},{"n":"3","t":"Bu nedenle size söylediklerinin tümünü yapın ve yerine getirin, ama onların yaptıklarını yapmayın. Çünkü söyledikleri şeyleri kendileri yapmazlar."},{"n":"4","t":"Ağır ve taşınması güç yükleri bağlayıp başkalarının sırtına yüklerler, kendileriyse bu yükleri taşımak için parmaklarını bile oynatmak istemezler."},{"n":"5","t":"\"Yaptıklarının tümünü gösteriş için yaparlar. Örneğin, hamaillerini*fx* büyük, giysilerinin püsküllerini*fx* uzun yaparlar."},{"n":"6","t":"Şölenlerde başköşeye, havralarda en seçkin yerlere kurulmaya bayılırlar."},{"n":"7","t":"Meydanlarda selamlanmaktan ve insanların kendilerini 'Rabbî*' diye çağırmalarından zevk duyarlar."},{"n":"8","t":"\"Kimse sizi 'Rabbî' diye çağırmasın. Çünkü sizin tek öğretmeniniz var ve hepiniz kardeşsiniz."},{"n":"9","t":"Yeryüzünde kimseye 'Baba' demeyin. Çünkü tek Babanız var, O da göksel Baba'dır."},{"n":"10","t":"Kimse sizi 'Önder' diye çağırmasın. Çünkü tek önderiniz var, O da Mesih'tir."},{"n":"11","t":"Aranızda en üstün olan, ötekilerin hizmetkârı olsun."},{"n":"12","t":"Kendini yücelten alçaltılacak, kendini alçaltan yüceltilecektir."},{"n":"13-14","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Göklerin Egemenliği'nin kapısını insanların yüzüne kapıyorsunuz; ne kendiniz içeri giriyor, ne de girmek isteyenleri bırakıyorsunuz!*fx*"},{"n":"15","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Tek bir kişiyi dininize döndürmek için denizleri, kıtaları dolaşırsınız. Dininize döneni de kendinizden iki kat cehennemlik yaparsınız."},{"n":"16","t":"\"Vay halinize kör kılavuzlar! Diyorsunuz ki, 'Tapınak üzerine ant içenin andı sayılmaz, ama tapınaktaki altın üzerine ant içen, andını yerine getirmek zorundadır.'"},{"n":"17","t":"Budalalar, körler! Hangisi daha önemli, altın mı, altını kutsal kılan tapınak mı?"},{"n":"18","t":"Yine diyorsunuz ki, 'Sunak üzerine ant içenin andı sayılmaz, ama sunaktaki adağın üzerine ant içen, andını yerine getirmek zorundadır.'"},{"n":"19","t":"Ey körler! Hangisi daha önemli, adak mı, adağı kutsal kılan sunak mı?"},{"n":"20","t":"Öyleyse sunak üzerine ant içen, hem sunağın hem de sunaktaki her şeyin üzerine ant içmiş olur."},{"n":"21","t":"Tapınak üzerine ant içen de hem tapınak, hem de tapınakta yaşayan Tanrı üzerine ant içmiş olur."},{"n":"22","t":"Gök üzerine ant içen, Tanrı'nın tahtı ve tahtta oturanın üzerine ant içmiş olur."},{"n":"23","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz nanenin, dereotunun ve kimyonun ondalığını verirsiniz de, Kutsal Yasa'nın daha önemli konularını -adaleti, merhameti, sadakati- ihmal edersiniz. Ondalık vermeyi ihmal etmeden asıl bunları yerine getirmeniz gerekirdi."},{"n":"24","t":"Ey kör kılavuzlar! Küçük sineği süzer ayırır, ama deveyi yutarsınız!"},{"n":"25","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Bardağın ve çanağın dışını temizlersiniz, oysa bunların içi açgözlülük ve taşkınlıkla doludur."},{"n":"26","t":"Ey kör Ferisi! Sen önce bardağın ve çanağın içini temizle ki, dıştan da temiz olsunlar."},{"n":"27","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Siz dıştan güzel görünen, ama içi ölü kemikleri ve her türlü pislikle dolu badanalı mezarlara benzersiniz."},{"n":"28","t":"Dıştan insanlara doğru görünürsünüz, ama içte ikiyüzlülük ve kötülükle dolusunuz."},{"n":"29","t":"\"Vay halinize ey din bilginleri ve Ferisiler, ikiyüzlüler! Peygamberlerin mezarlarını yapar, doğru kişilerin anıtlarını donatırsınız."},{"n":"30","t":"'Atalarımızın yaşadığı günlerde yaşasaydık, onlarla birlikte peygamberlerin kanına girmezdik' diyorsunuz."},{"n":"31","t":"Böylece, peygamberleri öldürenlerin torunları olduğunuza kendiniz tanıklık ediyorsunuz."},{"n":"32","t":"Haydi, atalarınızın başlattığı işi bitirin!"},{"n":"33","t":"\"Sizi yılanlar, engerekler soyu! Cehennem cezasından nasıl kaçacaksınız?"},{"n":"34","t":"İşte bunun için size peygamberler, bilge kişiler ve din bilginleri gönderiyorum. Bunlardan kimini öldürecek, çarmıha gereceksiniz. Kimini havralarınızda kamçılayacak, kentten kente kovalayacaksınız."},{"n":"35","t":"Böylelikle, doğru kişi olan Habil'in kanından, tapınakla sunak arasında öldürdüğünüz Berekya oğlu Zekeriya'nın kanına kadar, yeryüzünde akıtılan her doğru kişinin kanından sorumlu tutulacaksınız."},{"n":"36","t":"Size doğrusunu söyleyeyim, bunların hepsinden bu kuşak*fx* sorumlu tutulacaktır."},{"n":"37","t":"\"Ey Yeruşalim! Peygamberleri öldüren, kendisine gönderilenleri taşlayan Yeruşalim! Tavuğun civcivlerini kanatları altına topladığı gibi ben de kaç kez senin çocuklarını toplamak istedim, ama siz istemediniz."},{"n":"38","t":"Bakın, eviniz ıssız bırakılacak!"},{"n":"39","t":"Size şunu söyleyeyim: 'Rab'bin adıyla gelene övgüler olsun!' diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.\""}]},{"ch":24,"verses":[{"n":"1","t":"İsa tapınaktan çıkıp giderken, öğrencileri, tapınağın binalarını O'na göstermek için yanına geldiler."},{"n":"2","t":"İsa onlara, \"Bütün bunları görüyor musunuz?\" dedi. \"Size doğrusunu söyleyeyim, burada taş üstünde taş kalmayacak, hepsi yıkılacak!\""},{"n":"3","t":"İsa, Zeytin Dağı'nda otururken öğrencileri yalnız olarak yanına geldiler. \"Söyle bize\" dediler, \"Bu dediklerin ne zaman olacak, senin gelişini ve çağın bitimini gösteren belirti ne olacak?\""},{"n":"4","t":"İsa onlara şu karşılığı verdi: \"Sakın kimse sizi saptırmasın!"},{"n":"5","t":"Birçokları, 'Mesih* benim' diyerek benim adımla gelip birçok kişiyi aldatacaklar."},{"n":"6","t":"Savaş gürültüleri, savaş haberleri duyacaksınız. Sakın korkmayın! Bunların olması gerek, ama bu daha son demek değildir."},{"n":"7","t":"Ulus ulusa, devlet devlete savaş açacak; yer yer kıtlıklar, depremler olacak."},{"n":"8","t":"Bütün bunlar, doğum sancılarının başlangıcıdır."},{"n":"9","t":"\"O zaman sizi sıkıntıya sokacak, öldürecekler. Benim adımdan ötürü bütün uluslar sizden nefret edecek."},{"n":"10","t":"O zaman birçok kişi imandan sapacak, birbirlerini ele verecek ve birbirlerinden nefret edecekler."},{"n":"11","t":"Birçok sahte peygamber türeyecek ve bunlar birçok kişiyi saptıracak."},{"n":"12","t":"Kötülüklerin çoğalmasından ötürü birçoklarının sevgisi soğuyacak."},{"n":"13","t":"Ama sonuna kadar dayanan kurtulacaktır."},{"n":"14","t":"Göksel egemenliğin bu Müjdesi bütün uluslara tanıklık olmak üzere dünyanın her yerinde duyurulacak. İşte o zaman son gelecektir."},{"n":"15-16","t":"\"Peygamber Daniel'in sözünü ettiği yıkıcı iğrenç şeyin* kutsal yerde dikildiğini gördüğünüz zaman -okuyan anlasın- Yahudiye'de bulunanlar dağlara kaçsın."},{"n":"17","t":"Damda olan, evindeki eşyalarını almak için aşağı inmesin."},{"n":"18","t":"Tarlada olan, abasını almak için geri dönmesin."},{"n":"19","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline!"},{"n":"20","t":"Dua edin ki, kaçışınız kışa ya da Şabat Günü'ne* rastlamasın."},{"n":"21","t":"Çünkü o günlerde öyle korkunç bir sıkıntı olacak ki, dünyanın başlangıcından bu yana böylesi olmamış, bundan sonra da olmayacaktır."},{"n":"22","t":"O günler kısaltılmamış olsaydı, hiç kimse kurtulamazdı. Ama seçilmiş olanlar uğruna o günler kısaltılacak."},{"n":"23","t":"Eğer o zaman biri size, 'İşte Mesih burada', ya da 'İşte şurada' derse, inanmayın."},{"n":"24","t":"Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar büyük belirtiler ve harikalar yapacaklar. Öyle ki, ellerinden gelse, seçilmiş olanları bile saptıracaklar."},{"n":"25","t":"İşte size önceden söylüyorum."},{"n":"26","t":"\"Bunun için size, 'İşte Mesih çölde' derlerse gitmeyin. 'Bakın, iç odalarda' derlerse inanmayın."},{"n":"27","t":"Çünkü İnsanoğlu'nun* gelişi, doğuda çakıp batıya kadar her taraftan görülen şimşek gibi olacaktır."},{"n":"28","t":"\"Leş neredeyse, akbabalar oraya üşüşecek."},{"n":"29","t":"\"O günlerin sıkıntısından hemen sonra, 'Güneş kararacak, Ay ışık vermez olacak, Yıldızlar gökten düşecek, Göksel güçler sarsılacak.'"},{"n":"30","t":"\"O zaman İnsanoğlu'nun belirtisi gökte görünecek. Yeryüzündeki bütün halklar ağlayıp dövünecek, İnsanoğlu'nun gökteki bulutlar üzerinde büyük güç ve görkemle geldiğini görecekler."},{"n":"31","t":"Kendisi güçlü bir borazan sesiyle meleklerini gönderecek. Melekler O'nun seçtiklerini göğün bir ucundan öbür ucuna dek, dünyanın dört bucağından toplayacaklar."},{"n":"32","t":"\"İncir ağacından ders alın! Dalları filizlenip yaprakları sürünce, yaz mevsiminin yakın olduğunu anlarsınız."},{"n":"33","t":"Aynı şekilde, bütün bunların gerçekleştiğini gördüğünüzde bilin ki, İnsanoğlu yakındır, kapıdadır."},{"n":"34","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak*fx* ortadan kalkmayacak."},{"n":"35","t":"Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır.\" Bilinmeyen Gün ve Saat (Mar.13:32-37; Luk.12:41-48; 17:26-30,34-36)"},{"n":"36","t":"\"O günü ve saati, ne gökteki melekler, ne de Oğul bilir; Baba'dan başka kimse bilmez."},{"n":"37","t":"Nuh'un günlerinde nasıl olduysa, İnsanoğlu'nun* gelişinde de öyle olacak."},{"n":"38","t":"Nuh'un gemiye bindiği güne dek, tufandan önceki günlerde insanlar yiyip içiyor, evlenip evlendiriliyorlardı."},{"n":"39","t":"Tufan gelinceye, hepsini süpürüp götürünceye dek başlarına geleceklerden habersizdiler. İnsanoğlu'nun gelişi de öyle olacak."},{"n":"40","t":"O gün tarlada bulunan iki kişiden biri alınacak, biri bırakılacak."},{"n":"41","t":"Değirmende buğday öğüten iki kadından biri alınacak, biri bırakılacak."},{"n":"42","t":"\"Bunun için uyanık kalın. Çünkü Rabbiniz'in geleceği günü bilemezsiniz."},{"n":"43","t":"Ama şunu bilin ki, ev sahibi, hırsızın gece hangi saatte geleceğini bilse, uyanık kalır, evinin soyulmasına fırsat vermez."},{"n":"44","t":"Bunun için siz de hazır olun! Çünkü İnsanoğlu beklemediğiniz saatte gelecektir."},{"n":"45","t":"\"Efendinin, hizmetkârlarına vaktinde yiyecek vermek için başlarına atadığı güvenilir ve akıllı köle kimdir?"},{"n":"46","t":"Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!"},{"n":"47","t":"Size doğrusunu söyleyeyim, efendisi onu bütün malının üzerinde yetkili kılacak."},{"n":"48-51","t":"Ama o köle kötü olur da içinden, 'Efendim gecikiyor' der ve öteki köleleri dövmeye başlarsa, sarhoşlarla birlikte yiyip içerse, efendisi, onun beklemediği günde, ummadığı saatte gelecek, onu şiddetle cezalandırıp ikiyüzlülerle bir tutacak. Orada ağlayış ve diş gıcırtısı olacaktır.\""}]},{"ch":25,"verses":[{"n":"1","t":"\"O zaman Göklerin Egemenliği, kandillerini alıp güveyi karşılamaya çıkan on kıza benzeyecek."},{"n":"2","t":"Bunların beşi akıllı, beşi akılsızdı."},{"n":"3","t":"Akılsızlar yanlarına kandillerini aldılar, ama yağ almadılar."},{"n":"4","t":"Akıllılar ise, kandilleriyle birlikte kaplar içinde yağ da aldılar."},{"n":"5","t":"Güvey gecikince hepsini uyku bastı, dalıp uyudular."},{"n":"6","t":"\"Gece yarısı bir ses yankılandı: 'İşte güvey geliyor, onu karşılamaya çıkın!'"},{"n":"7","t":"Bunun üzerine kızların hepsi kalkıp kandillerini tazelediler."},{"n":"8","t":"\"Akılsızlar akıllılara, 'Kandillerimiz sönüyor, bize yağ verin!' dediler."},{"n":"9","t":"\"Akıllılar, 'Olmaz! Hem bize hem size yetmeyebilir. En iyisi satıcılara gidin, kendinize yağ alın' dediler."},{"n":"10","t":"\"Ne var ki, onlar yağ satın almaya giderlerken güvey geldi. Hazırlıklı olan kızlar, onunla birlikte düğün şölenine girdiler ve kapı kapandı."},{"n":"11","t":"\"Daha sonra gelen öbür kızlar, 'Efendimiz, efendimiz, aç kapıyı bize!' dediler."},{"n":"12","t":"\"Güvey ise, 'Size doğrusunu söyleyeyim, sizi tanımıyorum' dedi."},{"n":"13","t":"\"Bu nedenle uyanık kalın. Çünkü o günü ve o saati bilemezsiniz.\" Emanet Para Benzetmesi (Luk.19:11-27)"},{"n":"14","t":"\"Göksel egemenlik, yolculuğa çıkan bir adamın kölelerini çağırıp malını onlara emanet etmesine benzer."},{"n":"15","t":"\"Adam, her birinin yeteneğine göre, birine beş, birine iki, birine de bir talant vererek yola çıktı."},{"n":"16","t":"Beş talant alan, hemen gidip bu parayı işletti ve beş talant daha kazandı."},{"n":"17","t":"İki talant alan da iki talant daha kazandı."},{"n":"18","t":"Bir talant alan ise gidip toprağı kazdı ve efendisinin parasını sakladı."},{"n":"19","t":"\"Uzun zaman sonra bu kölelerin efendisi döndü, onlarla hesaplaşmaya oturdu."},{"n":"20","t":"Beş talant alan gelip beş talant daha getirdi, 'Efendimiz' dedi, 'Bana beş talant emanet etmiştin; bak, beş talant daha kazandım.'"},{"n":"21","t":"\"Efendisi ona, 'Aferin, iyi ve güvenilir köle!' dedi. 'Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!'"},{"n":"22","t":"\"İki talant alan da geldi, 'Efendimiz' dedi, 'Bana iki talant emanet etmiştin; bak, iki talant daha kazandım.'"},{"n":"23","t":"\"Efendisi ona, 'Aferin, iyi ve güvenilir köle!' dedi. 'Sen küçük işlerde güvenilir olduğunu gösterdin, ben de seni büyük işlerin başına geçireceğim. Gel, efendinin şenliğine katıl!'"},{"n":"24","t":"\"Sonra bir talant alan geldi, 'Efendimiz' dedi, 'Senin sert bir adam olduğunu biliyordum. Ekmediğin yerden biçer, harman savurmadığın yerden devşirirsin."},{"n":"25","t":"Bu nedenle korktum, gidip senin verdiğin talantı toprağa gömdüm. İşte, al paranı!'"},{"n":"26-27","t":"\"Efendisi ona şu karşılığı verdi: 'Kötü ve tembel köle! Ekmediğim yerden biçtiğimi, harman savurmadığım yerden devşirdiğimi bildiğine göre paramı faize vermeliydin. Ben de geldiğimde onu faiziyle geri alırdım..."},{"n":"28","t":"Haydi, elindeki talantı alın, on talantı olana verin!"},{"n":"29","t":"Çünkü kimde varsa, ona daha çok verilecek ve o bolluk içinde olacak. Ama kimde yoksa, kendisinde olan da elinden alınacak."},{"n":"30","t":"Şu yararsız köleyi dışarıya, karanlığa atın. Orada ağlayış ve diş gıcırtısı olacaktır.'\" Yargı Günü"},{"n":"31","t":"\"İnsanoğlu* kendi görkemi içinde bütün melekleriyle birlikte gelince, görkemli tahtına oturacak."},{"n":"32","t":"Ulusların hepsi O'nun önünde toplanacak, O da koyunları keçilerden ayıran bir çoban gibi, insanları birbirinden ayıracak."},{"n":"33","t":"Koyunları sağına, keçileri soluna alacak."},{"n":"34","t":"\"O zaman Kral, sağındaki kişilere, 'Sizler, Babam'ın kutsadıkları, gelin!' diyecek. 'Dünya kurulduğundan beri sizin için hazırlanmış olan egemenliği miras alın!"},{"n":"35","t":"Çünkü acıkmıştım, bana yiyecek verdiniz; susamıştım, bana içecek verdiniz; yabancıydım, beni içeri aldınız."},{"n":"36","t":"Çıplaktım, beni giydirdiniz; hastaydım, benimle ilgilendiniz; zindandaydım, yanıma geldiniz.'"},{"n":"37","t":"\"O vakit doğru kişiler O'na şu karşılığı verecek: 'Ya Rab, seni ne zaman aç görüp doyurduk, susuz görüp su verdik?"},{"n":"38","t":"Ne zaman seni yabancı görüp içeri aldık, ya da çıplak görüp giydirdik?"},{"n":"39","t":"Seni ne zaman hasta ya da zindanda görüp yanına geldik?'"},{"n":"40","t":"\"Kral da onları şöyle yanıtlayacak: 'Size doğrusunu söyleyeyim, bu en basit kardeşlerimden biri için yaptığınızı, benim için yapmış oldunuz.'"},{"n":"41","t":"\"Sonra solundakilere şöyle diyecek: 'Ey lanetliler, çekilin önümden! İblis'le melekleri için hazırlanmış sönmez ateşe gidin!"},{"n":"42-43","t":"Çünkü acıkmıştım, bana yiyecek vermediniz; susamıştım, bana içecek vermediniz; yabancıydım, beni içeri almadınız; çıplaktım, beni giydirmediniz; hastaydım, zindandaydım, benimle ilgilenmediniz.'"},{"n":"44","t":"\"O vakit onlar da şöyle karşılık verecekler: 'Ya Rab, seni ne zaman aç, susuz, yabancı, çıplak, hasta ya da zindanda gördük de yardım etmedik?'"},{"n":"45","t":"\"Kral da onlara şu yanıtı verecek: 'Size doğrusunu söyleyeyim, mademki bu en basit kardeşlerimden biri için bunu yapmadınız, benim için de yapmamış oldunuz.'"},{"n":"46","t":"\"Bunlar sonsuz azaba, doğrular ise sonsuz yaşama gidecekler.\""}]},{"ch":26,"verses":[{"n":"1-2","t":"İsa bütün bunları anlattıktan sonra öğrencilerine, \"İki gün sonra Fısıh Bayramı* olduğunu biliyorsunuz\" dedi, \"İnsanoğlu* çarmıha gerilmek üzere ele verilecek.\""},{"n":"3","t":"Bu sırada başkâhinlerle halkın ileri gelenleri, Kayafa adındaki başkâhinin sarayında toplandılar."},{"n":"4","t":"İsa'yı hileyle tutuklayıp öldürmek için düzen kurdular."},{"n":"5","t":"Ama, \"Bayramda olmasın ki, halk arasında kargaşalık çıkmasın\" diyorlardı. İsa Beytanya'da (Mar.14:3-9; Yu.12:1-8)"},{"n":"6-7","t":"İsa Beytanya'da cüzamlı* Simun'un evindeyken, yanına bir kadın geldi. Kadın kaymaktaşından bir kap içinde çok değerli, güzel kokulu yağ getirmişti. İsa sofrada otururken, kadın yağı O'nun başına döktü."},{"n":"8","t":"Öğrenciler bunu görünce kızdılar. \"Nedir bu savurganlık?\" dediler."},{"n":"9","t":"\"Bu yağ pahalıya satılabilir, parası yoksullara verilebilirdi.\""},{"n":"10","t":"Söylenenleri farkeden İsa, öğrencilerine, \"Kadını neden üzüyorsunuz?\" dedi. \"Benim için güzel bir şey yaptı."},{"n":"11","t":"Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım."},{"n":"12","t":"Kadın bu güzel kokulu yağı, beni gömülmeye hazırlamak için bedenimin üzerine boşalttı."},{"n":"13","t":"Size doğrusunu söyleyeyim, bu Müjde dünyanın neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.\" Yahuda'nın İhaneti (Mar.14:10-11; Luk.22:3-6)"},{"n":"14-15","t":"O sırada Onikiler'den* biri -adı Yahuda İskariot olanı başkâhinlere giderek, \"O'nu ele verirsem bana ne verirsiniz?\" dedi. Otuz gümüş tartıp ona verdiler."},{"n":"16","t":"Yahuda o andan itibaren İsa'yı ele vermek için fırsat kollamaya başladı. Fısıh Yemeği (Mar.14:12-26; Luk.22:7-23; Yu.13:21-30; 1Ko.11:23-25)"},{"n":"17","t":"Mayasız Ekmek Bayramı'nın* ilk günü öğrenciler İsa'nın yanına gelerek, \"Fısıh* yemeğini yemen için nerede hazırlık yapmamızı istersin?\" diye sordular."},{"n":"18","t":"İsa onlara, \"Kente varıp o adamın evine gidin\" dedi. \"Ona şöyle deyin: 'Öğretmen diyor ki, zamanım yaklaştı. Fısıh Bayramı'nı, öğrencilerimle birlikte senin evinde kutlayacağım.'\""},{"n":"19","t":"Öğrenciler, İsa'nın buyruğunu yerine getirerek Fısıh yemeği için hazırlık yaptılar."},{"n":"20","t":"Akşam olunca İsa on iki öğrencisiyle yemeğe oturdu."},{"n":"21","t":"Yemek yerlerken, \"Size doğrusunu söyleyeyim, sizden biri bana ihanet edecek\" dedi."},{"n":"22","t":"Bu söz onları kedere boğdu. Teker teker, \"Ya Rab, beni demek istemedin ya?\" diye sormaya başladılar."},{"n":"23","t":"O da, \"Bana ihanet edecek olan\" dedi, \"Elindeki ekmeği benimle birlikte sahana batırandır."},{"n":"24","t":"İnsanoğlu*, kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğlu'na ihanet edenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.\""},{"n":"25","t":"O'na ihanet edecek olan Yahuda, \"Rabbî*, yoksa beni mi demek istedin?\" diye sordu. İsa ona, \"Söylediğin gibidir\" karşılığını verdi."},{"n":"26","t":"Yemek sırasında İsa eline ekmek aldı, şükredip ekmeği böldü ve öğrencilerine verdi. \"Alın, yiyin\" dedi, \"Bu benim bedenimdir.\""},{"n":"27","t":"Sonra bir kâse alıp şükretti ve bunu öğrencilerine vererek, \"Hepiniz bundan için\" dedi."},{"n":"28","t":"\"Çünkü bu benim kanımdır, günahların bağışlanması için birçokları uğruna akıtılan antlaşma kanıdır."},{"n":"29","t":"Size şunu söyleyeyim, Babam'ın egemenliğinde sizinle birlikte tazesini içeceğim o güne dek, asmanın bu ürününden bir daha içmeyeceğim.\""},{"n":"30","t":"İlahi söyledikten sonra dışarı çıkıp Zeytin Dağı'na doğru gittiler. Petrus'un İnkârı Önceden Bildiriliyor (Mar.14:27-31; Luk.22:31-34; Yu.13:36-38)"},{"n":"31","t":"Bu arada İsa öğrencilerine, \"Bu gece hepiniz benden ötürü sendeleyip düşeceksiniz\" dedi. \"Çünkü şöyle yazılmıştır: 'Çobanı vuracağım, Sürüdeki koyunlar darmadağın olacak.'"},{"n":"32","t":"Ama ben dirildikten sonra sizden önce Celile'ye gideceğim.\""},{"n":"33","t":"Petrus O'na, \"Herkes senden ötürü sendeleyip düşse de ben asla düşmem\" dedi."},{"n":"34","t":"\"Sana doğrusunu söyleyeyim\" dedi İsa, \"Bu gece horoz ötmeden beni üç kez inkâr edeceksin.\""},{"n":"35","t":"Petrus, \"Seninle birlikte ölmem gerekse bile seni asla inkâr etmem\" dedi. Öğrencilerin hepsi de aynı şeyi söyledi. Getsemani Bahçesinde (Mar.14:32-42; Luk.22:39-46)"},{"n":"36","t":"Sonra İsa öğrencileriyle birlikte Getsemani denen yere geldi. Öğrencilerine, \"Ben şuraya gidip dua edeceğim, siz burada oturun\" dedi."},{"n":"37","t":"Petrus ile Zebedi'nin iki oğlunu yanına aldı. Kederlenmeye, ağır bir sıkıntı duymaya başlamıştı."},{"n":"38","t":"Onlara, \"Ölesiye kederliyim\" dedi. \"Burada kalın, benimle birlikte uyanık durun.\""},{"n":"39","t":"Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. \"Baba\" dedi, \"Mümkünse bu kâse* benden uzaklaştırılsın. Yine de benim değil, senin istediğin olsun.\""},{"n":"40","t":"Öğrencilerin yanına döndüğünde onları uyumuş buldu. Petrus'a, \"Demek ki benimle birlikte bir saat uyanık kalamadınız!\" dedi."},{"n":"41","t":"\"Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.\""},{"n":"42","t":"İsa ikinci kez uzaklaşıp dua etti. \"Baba\" dedi, \"Eğer ben içmeden bu kâsenin uzaklaştırılması mümkün değilse, senin istediğin olsun.\""},{"n":"43","t":"Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına ağırlık çökmüştü."},{"n":"44","t":"Onları bırakıp tekrar uzaklaştı, yine aynı sözlerle üçüncü kez dua etti."},{"n":"45","t":"Sonra öğrencilerin yanına dönerek, \"Hâlâ uyuyor, dinleniyor musunuz?\" dedi. \"İşte saat yaklaştı, İnsanoğlu* günahkârların eline veriliyor."},{"n":"46","t":"Kalkın, gidelim. İşte bana ihanet eden geldi!\" İsa Tutuklanıyor (Mar.14:43-50; Luk.22:47-53; Yu.18:3-12)"},{"n":"47","t":"İsa daha konuşurken, Onikiler'den* biri olan Yahuda geldi. Yanında, başkâhinlerle halkın ileri gelenleri tarafından gönderilmiş kılıçlı sopalı büyük bir kalabalık vardı."},{"n":"48","t":"İsa'ya ihanet eden Yahuda, \"Kimi öpersem, İsa O'dur, O'nu tutuklayın\" diye onlarla sözleşmişti."},{"n":"49","t":"Dosdoğru İsa'ya gidip, \"Selam, Rabbî*!\" diyerek O'nu öptü."},{"n":"50","t":"İsa, \"Arkadaş, ne yapacaksan yap*fx*!\" dedi. Bunun üzerine adamlar yaklaştı, İsa'yı yakalayıp tutukladılar."},{"n":"51","t":"İsa'yla birlikte olanlardan biri, ani bir hareketle kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu."},{"n":"52","t":"O zaman İsa ona, \"Kılıcını yerine koy!\" dedi. \"Kılıç çekenlerin hepsi kılıçla ölecek."},{"n":"53","t":"Yoksa Babam'dan yardım isteyemez miyim sanıyorsun? İstesem, hemen şu an bana on iki tümenden* fazla melek gönderir."},{"n":"54","t":"Ama böyle olması gerektiğini bildiren Kutsal Yazılar o zaman nasıl yerine gelir?\""},{"n":"55","t":"Bundan sonra İsa kalabalığa dönüp şöyle seslendi: \"Niçin bir haydutmuşum gibi beni kılıç ve sopalarla yakalamaya geldiniz? Her gün tapınakta oturup öğretiyordum, beni tutuklamadınız."},{"n":"56","t":"Ama bütün bunlar, peygamberlerin yazdıkları yerine gelsin diye oldu.\" O zaman öğrencilerin hepsi O'nu bırakıp kaçtı. İsa Yüksek Kurul'un Önünde (Mar.14:53-65; Luk.22:54-55,63-71; Yu.18:13-14,19-24)"},{"n":"57","t":"İsa'yı tutuklayanlar, O'nu başkâhin Kayafa'ya götürdüler. Din bilginleriyle ileri gelenler de orada toplanmışlardı."},{"n":"58","t":"Petrus, İsa'yı uzaktan, ta başkâhinin avlusuna kadar izledi. Sonucu görmek için içeri girip nöbetçilerin yanına oturdu."},{"n":"59","t":"Başkâhinlerle Yüksek Kurul'un* öteki üyeleri, İsa'yı ölüm cezasına çarptırmak için kendisine karşı yalancı tanıklar arıyorlardı."},{"n":"60-61","t":"Ortaya birçok yalancı tanık çıktığı halde, aradıklarını bulamadılar. Sonunda ortaya çıkan iki kişi şöyle dedi: \"Bu adam, 'Ben Tanrı'nın Tapınağı'nı yıkıp üç günde yeniden kurabilirim' dedi.\""},{"n":"62","t":"Başkâhin ayağa kalkıp İsa'ya, \"Hiç yanıt vermeyecek misin?\" dedi. \"Nedir bunların sana karşı ettiği bu tanıklıklar?\""},{"n":"63","t":"İsa susmaya devam etti. Başkâhin ise O'na, \"Yaşayan Tanrı adına ant içmeni buyuruyorum, söyle bize, Tanrı'nın Oğlu Mesih* sen misin?\" dedi."},{"n":"64","t":"İsa, \"Söylediğin gibidir\" karşılığını verdi. \"Üstelik size şunu söyleyeyim, bundan sonra İnsanoğlu'nun*, Kudretli Olan'ın*fx* sağında oturduğunu ve göğün bulutları üzerinde geldiğini göreceksiniz.\""},{"n":"65","t":"Bunun üzerine başkâhin giysilerini yırtarak, \"Tanrı'ya küfretti!\" dedi. \"Artık tanıklara ne ihtiyacımız var? İşte küfürü işittiniz."},{"n":"66","t":"Buna ne diyorsunuz?\" \"Ölümü hak etti!\" diye karşılık verdiler."},{"n":"67-68","t":"Bunun üzerine İsa'nın yüzüne tükürüp O'nu yumrukladılar. Bazıları da O'nu tokatlayıp, \"Ey Mesih, peygamberliğini göster bakalım, sana vuran kim?\" dediler. Petrus İsa'yı İnkâr Ediyor (Mar.14:66-72; Luk.22:56-62; Yu.18:15-18,25-27)"},{"n":"69","t":"Petrus ise dışarıda, avluda oturuyordu. Bir hizmetçi kız yanına gelip, \"Sen de Celileli İsa'yla birlikteydin\" dedi."},{"n":"70","t":"Ama Petrus bunu herkesin önünde inkâr ederek, \"Neden söz ettiğini anlamıyorum\" dedi."},{"n":"71","t":"Sonra avlu kapısının önüne çıktı. Onu gören başka bir hizmetçi kız orada bulunanlara, \"Bu adam Nasıralı İsa'yla birlikteydi\" dedi."},{"n":"72","t":"Petrus ant içerek, \"Ben o adamı tanımıyorum\" diye yine inkâr etti."},{"n":"73","t":"Orada duranlar az sonra Petrus'a yaklaşıp, \"Gerçekten sen de onlardansın. Konuşman seni ele veriyor\" dediler."},{"n":"74","t":"Petrus kendine lanet okuyup ant içerek, \"O adamı tanımıyorum!\" dedi. Tam o anda horoz öttü."},{"n":"75","t":"Petrus, İsa'nın, \"Horoz ötmeden beni üç kez inkâr edeceksin\" dediğini hatırladı ve dışarı çıkıp acı acı ağladı."}]},{"ch":27,"verses":[{"n":"1","t":"Sabah olunca bütün başkâhinlerle halkın ileri gelenleri, İsa'yı ölüm cezasına çarptırmak konusunda anlaştılar."},{"n":"2","t":"O'nu bağladılar ve götürüp Vali Pilatus'a teslim ettiler."},{"n":"3","t":"İsa'ya ihanet eden Yahuda, O'nun mahkûm edildiğini görünce yaptığına pişman oldu. Otuz gümüşü başkâhinlere ve ileri gelenlere geri götürdü."},{"n":"4","t":"\"Ben suçsuz birini*fx* ele vermekle günah işledim\" dedi. Onlar ise, \"Bundan bize ne? Onu sen düşün\" dediler."},{"n":"5","t":"Yahuda paraları tapınağın içine fırlatarak oradan ayrıldı, gidip kendini astı."},{"n":"6","t":"Paraları toplayan başkâhinler, \"Kan bedeli olan bu paraları tapınağın hazinesine koymak doğru olmaz\" dediler."},{"n":"7","t":"Kendi aralarında anlaşarak bu parayla yabancılar için mezarlık yapmak üzere Çömlekçi Tarlası'nı satın aldılar."},{"n":"8","t":"Bunun için bu tarlaya bugüne dek \"Kan Tarlası\" denilmiştir."},{"n":"9-10","t":"Böylece Peygamber Yeremya aracılığıyla bildirilen şu söz yerine gelmiş oldu: \"İsrailoğulları'ndan kimilerinin O'na biçtikleri değerin karşılığı olan Otuz gümüşü aldılar; Rab'bin bana buyurduğu gibi, Çömlekçi Tarlası'nı satın almak için harcadılar.\" İsa Vali Pilatus'un Önünde (Mar.15:2-15; Luk.23:3-5,13-25; Yu.18:33-19:16)"},{"n":"11","t":"İsa valinin önüne çıkarıldı. Vali O'na, \"Sen Yahudiler'in Kralı mısın?\" diye sordu. İsa, \"Söylediğin gibidir\" dedi."},{"n":"12","t":"Başkâhinlerle ileri gelenler O'nu suçlayınca hiç karşılık vermedi."},{"n":"13","t":"Pilatus O'na, \"Senin aleyhinde yaptıkları bunca tanıklığı duymuyor musun?\" dedi."},{"n":"14","t":"İsa tek konuda bile ona yanıt vermedi. Vali buna çok şaştı."},{"n":"15","t":"Her Fısıh Bayramı'nda* vali, halkın istediği bir tutukluyu salıvermeyi adet edinmişti."},{"n":"16","t":"O günlerde Barabba adında ünlü bir tutuklu vardı."},{"n":"17","t":"Halk bir araya toplandığında, Pilatus onlara, \"Sizin için kimi salıvermemi istersiniz, Barabba'yı mı, Mesih* denen İsa'yı mı?\" diye sordu."},{"n":"18","t":"İsa'yı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu."},{"n":"19","t":"Pilatus yargı kürsüsünde otururken karısı ona, \"O doğru adama dokunma. Dün gece rüyamda O'nun yüzünden çok sıkıntı çektim\" diye haber gönderdi."},{"n":"20","t":"Başkâhinler ve ileri gelenler ise, Barabba'nın salıverilmesini ve İsa'nın öldürülmesini istesinler diye halkı kışkırttılar."},{"n":"21","t":"Vali onlara şunu sordu: \"Sizin için hangisini salıvermemi istersiniz?\" \"Barabba'yı\" dediler."},{"n":"22","t":"Pilatus, \"Öyleyse Mesih denen İsa'yı ne yapayım?\" diye sordu. Hep bir ağızdan, \"Çarmıha gerilsin!\" dediler."},{"n":"23","t":"Pilatus, \"O ne kötülük yaptı ki?\" diye sordu. Onlar ise daha yüksek sesle, \"Çarmıha gerilsin!\" diye bağrışıp durdular."},{"n":"24","t":"Pilatus, elinden bir şey gelmediğini, tersine, bir kargaşalığın başladığını görünce su aldı, kalabalığın önünde ellerini yıkayıp şöyle dedi: \"Bu adamın kanından ben sorumlu değilim. Bu işe siz bakın!\""},{"n":"25","t":"Bütün halk şu karşılığı verdi: \"O'nun kanının sorumluluğu bizim ve çocuklarımızın üzerinde olsun!\""},{"n":"26","t":"Bunun üzerine Pilatus onlar için Barabba'yı salıverdi. İsa'yı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti. Askerlerin İsa'yı Aşağılaması (Mar.15:16-20; Yu.19:2-3)"},{"n":"27","t":"Sonra valinin askerleri İsa'yı vali konağına götürüp bütün taburu başına topladılar."},{"n":"28","t":"O'nu soyup üzerine kırmızı bir kaftan geçirdiler."},{"n":"29","t":"Dikenlerden bir taç örüp başına koydular, sağ eline de bir kamış tutturdular. Önünde diz çöküp, \"Selam, ey Yahudiler'in Kralı!\" diyerek O'nunla alay ettiler."},{"n":"30","t":"Üzerine tükürdüler, kamışı alıp başına vurdular."},{"n":"31","t":"O'nunla böyle alay ettikten sonra kaftanı üzerinden çıkarıp kendi giysilerini giydirdiler ve çarmıha germeye götürdüler. İsa Çarmıha Geriliyor (Mar.15:21-32; Luk.23:26-43; Yu.19:17-27)"},{"n":"32","t":"Dışarı çıktıklarında Simun adında Kireneli bir adama rastladılar. İsa'nın çarmıhını ona zorla taşıttılar."},{"n":"33-34","t":"Golgota, yani Kafatası denilen yere vardıklarında içmesi için İsa'ya ödle karışık şarap verdiler. İsa bunu tadınca içmek istemedi."},{"n":"35","t":"Askerler O'nu çarmıha gerdikten sonra kura çekerek giysilerini aralarında paylaştılar."},{"n":"36","t":"Sonra oturup yanında nöbet tuttular."},{"n":"37","t":"Başının üzerine, BU, YAHUDİLER'İN KRALI İSA'DIR diye yazan bir suç yaftası astılar."},{"n":"38","t":"İsa'yla birlikte, biri sağında öbürü solunda olmak üzere iki haydut da çarmıha gerildi."},{"n":"39-40","t":"Oradan geçenler başlarını sallayıp İsa'ya sövüyor, \"Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Haydi, kurtar kendini! Tanrı'nın Oğlu'ysan çarmıhtan in!\" diyorlardı."},{"n":"41-42","t":"Başkâhinler, din bilginleri ve ileri gelenler de aynı şekilde O'nunla alay ederek, \"Başkalarını kurtardı, kendini kurtaramıyor\" diyorlardı. \"İsrail'in Kralı imiş! Şimdi çarmıhtan aşağı insin de O'na iman edelim."},{"n":"43","t":"Tanrı'ya güveniyordu; Tanrı O'nu seviyorsa, kurtarsın bakalım! Çünkü, 'Ben Tanrı'nın Oğlu'yum' demişti.\""},{"n":"44","t":"İsa'yla birlikte çarmıha gerilen haydutlar da O'na aynı şekilde hakaret ettiler. İsa'nın Ölümü (Mar.15:33-41; Luk.23:44-49; Yu.19:28-30)"},{"n":"45","t":"Öğleyin on ikiden üçe kadar bütün ülkenin üzerine karanlık çöktü."},{"n":"46","t":"Saat* üçe doğru İsa yüksek sesle, \"Eli, Eli, lema şevaktani?\" yani, \"Tanrım, Tanrım, beni neden terk ettin?\" diye bağırdı."},{"n":"47","t":"Orada duranlardan bazıları bunu işitince, \"Bu adam İlyas'ı çağırıyor\" dediler."},{"n":"48","t":"İçlerinden biri hemen koşup bir sünger getirdi, ekşi şaraba batırıp bir kamışın ucuna takarak İsa'ya içirdi."},{"n":"49","t":"Öbürleri ise, \"Dur bakalım, İlyas gelip O'nu kurtaracak mı?\" dediler."},{"n":"50","t":"İsa, yüksek sesle bir kez daha bağırdı ve ruhunu teslim etti."},{"n":"51","t":"O anda tapınaktaki perde* yukarıdan aşağıya yırtılarak ikiye bölündü. Yer sarsıldı, kayalar yarıldı."},{"n":"52","t":"Mezarlar* açıldı, ölmüş olan birçok kutsal kişinin cesetleri dirildi."},{"n":"53","t":"Bunlar mezarlarından çıkıp İsa'nın dirilişinden sonra kutsal kente* girdiler ve birçok kimseye göründüler."},{"n":"54","t":"İsa'yı bekleyen yüzbaşı ve beraberindeki askerler, depremi ve öbür olayları görünce dehşete kapıldılar, \"Bu gerçekten Tanrı'nın Oğlu'ydu!\" dediler."},{"n":"55","t":"Orada, olup bitenleri uzaktan izleyen birçok kadın vardı. Bunlar, Celile'den İsa'nın ardından gelip O'na hizmet etmişlerdi."},{"n":"56","t":"Aralarında Mecdelli Meryem, Yakup ile Yusuf'un annesi Meryem ve Zebedi oğullarının annesi de vardı. İsa'nın Gömülmesi (Mar.15:42-47; Luk.23:50-56; Yu.19:38-42)"},{"n":"57","t":"Akşama doğru Yusuf adında zengin bir Aramatyalı geldi. O da İsa'nın bir öğrencisiydi."},{"n":"58","t":"Pilatus'a gidip İsa'nın cesedini istedi. Pilatus da cesedin ona verilmesini buyurdu."},{"n":"59-60","t":"Yusuf cesedi aldı, temiz keten beze sardı, kayaya oydurduğu kendi yeni mezarına yatırdı. Mezarın girişine büyük bir taş yuvarlayıp oradan ayrıldı."},{"n":"61","t":"Mecdelli Meryem ile öteki Meryem ise orada, mezarın karşısında oturuyorlardı."},{"n":"62-63","t":"Ertesi gün, yani Hazırlık Günü'nden* sonraki gün, başkâhinlerle Ferisiler Pilatus'un önünde toplanarak, \"Efendimiz\" dediler, \"O aldatıcının, daha yaşarken, 'Ben öldükten üç gün sonra dirileceğim' dediğini hatırlıyoruz."},{"n":"64","t":"Onun için buyruk ver de üçüncü güne dek mezarı güvenlik altına alsınlar. Yoksa öğrencileri gelir, cesedini çalar ve halka, 'Ölümden dirildi' derler. Son aldatmaca ilkinden beter olur.\""},{"n":"65","t":"Pilatus onlara, \"Yanınıza asker alın, gidip mezarı dilediğiniz gibi güvenlik altına alın\" dedi."},{"n":"66","t":"Onlar da askerlerle birlikte gittiler, taşı mühürleyip mezarı güvenlik altına aldılar."}]},{"ch":28,"verses":[{"n":"1","t":"Şabat Günü'nü* izleyen haftanın ilk günü*, tan yeri ağarırken, Mecdelli Meryem ile öbür Meryem mezarı* görmeye gittiler."},{"n":"2","t":"Ansızın büyük bir deprem oldu. Rab'bin bir meleği gökten indi ve mezara gidip taşı bir yana yuvarlayarak üzerine oturdu."},{"n":"3","t":"Görünüşü şimşek gibi, giysileri ise kar gibi bembeyazdı."},{"n":"4","t":"Nöbetçiler korkudan titremeye başladılar, sonra ölü gibi yere yıkıldılar."},{"n":"5","t":"Melek kadınlara şöyle seslendi: \"Korkmayın! Çarmıha gerilen İsa'yı aradığınızı biliyorum."},{"n":"6","t":"O burada yok; söylemiş olduğu gibi dirildi. Gelin, O'nun yattığı yeri görün."},{"n":"7","t":"Çabuk gidin, öğrencilerine şöyle deyin: 'İsa ölümden dirildi. Sizden önce Celile'ye gidiyor, kendisini orada göreceksiniz.' İşte ben size söylemiş bulunuyorum.\""},{"n":"8","t":"Kadınlar korku ve büyük sevinç içinde hemen mezardan uzaklaştılar; koşarak İsa'nın öğrencilerine haber vermeye gittiler."},{"n":"9","t":"İsa ansızın karşılarına çıktı, \"Selam!\" dedi. Yaklaşıp İsa'nın ayaklarına sarılarak O'na tapındılar."},{"n":"10","t":"O zaman İsa, \"Korkmayın!\" dedi. \"Gidip kardeşlerime haber verin, Celile'ye gitsinler, beni orada görecekler.\" Nöbetçilerin Getirdiği Haber"},{"n":"11","t":"Kadınlar daha yoldayken nöbetçi askerlerden bazıları kente giderek olup bitenleri başkâhinlere bildirdiler."},{"n":"12-13","t":"Başkâhinler ileri gelenlerle birlikte toplanıp birbirlerine danıştıktan sonra askerlere yüklü para vererek dediler ki, \"Siz şöyle diyeceksiniz: 'Öğrencileri geceleyin geldi, biz uyurken O'nun cesedini çalıp götürdüler.'"},{"n":"14","t":"Eğer bu haber valinin kulağına gidecek olursa biz onu yatıştırır, size bir zarar gelmesini önleriz.\""},{"n":"15","t":"Böylece askerler parayı aldılar ve kendilerine söylendiği gibi yaptılar. Bu söylenti Yahudiler arasında bugün de yaygındır. Son Buyruk (Mar.16:14-18; Luk.24:36-49; Yu.20:19-23; Elç.1:6-8)"},{"n":"16","t":"On bir öğrenci Celile'ye, İsa'nın kendilerine bildirdiği dağa gittiler."},{"n":"17","t":"İsa'yı gördükleri zaman O'na tapındılar. Ama bazıları kuşku içindeydi."},{"n":"18","t":"İsa yanlarına gelip kendilerine şunları söyledi: \"Gökte ve yeryüzünde bütün yetki bana verildi."},{"n":"19","t":"Bu nedenle gidin, bütün ulusları öğrencilerim olarak yetiştirin; onları Baba, Oğul ve Kutsal Ruh'un adıyla*fx* vaftiz edin;"},{"n":"20","t":"size buyurduğum her şeye uymayı onlara öğretin. İşte ben, dünyanın sonuna dek her an sizinle birlikteyim.\""}]},{"ch":29,"verses":[{"n":"1-2","t":"\"Doğuda O'nun yıldızını gördük\" ya da \"O'nun yıldızının doğuşunu gördük\". 2:9 \"Doğuda\" ya da \"Doğuşunu\". 4:3 \"Ayartıcı\":"},{"n":"22","t":"\"Aşağılayıcı bir söz\": Grekçe \"Raka\", yani \"Boş kafalı\". 5:26 \"Kuruş\": Grekçe \"Kodrantis\" (bkz. Birimler Cetveli). 5:37 \"Şeytan\": Grekçe \"Kötü olan\". 6:13 \"Çünkü egemenlik, güç ve yücelik sonsuzlara dek senindir! Amin\" sözleri bazı Grekçe elyazmalarında"},{"n":"22","t":"\"Gözünüz sağlamsa\" diye çevrilen Grekçe deyim \"Cömertseniz\" anlamına"},{"n":"23","t":"\"Gözünüz bozuksa\" diye çevrilen Grekçe deyim \"Açgözlüyseniz\" anlamına"},{"n":"24","t":"\"Para\": Grekçe \"Mamon\". Aramice'de* zenginlik anlamına gelen mamon sözcüğü, para ya da para kazanma hırsı anlamında"},{"n":"27","t":"\"Ömrünü bir anlık\" ya da \"Boyunu bir arşın\". 11:12 \"Göklerin Egemenliği zorlanıyor, zorlu kişiler onu ele geçirmeye çalışıyor\" ya da \"Göklerin Egemenliği zorlu biçimde gelişiyor, zorlu kişiler ona sahip çıkıyor\". 13:33 \"Ölçek\": Grekçe \"Saton\" (bkz. Birimler Cetveli). 14:24 \"Bir hayli uzakta\": Grekçe \"Birçok stadion uzakta\" (bkz. Birimler Cetveli). 14:25 \"Sabaha karşı\": Grekçe \"Gecenin dördüncü nöbetinde\" (bkz. Sözlük, \"Saat\"). 15:25 \"O'nun önünde yere kapandı\" ya da \"O'na tapındı\". 16:17 \"İnsan\": Grekçe \"Et ve kan\". 16:18 \"Petrus\": Grekçe \"Petros\", yani \"Kaya parçası, taş\". 16:18 \"Kaya\": Grekçe \"Petra\", yani \"Büyük taş kütlesi, kaya\". 17:20-21 Birçok Grekçe elyazması, \"Ama bu tür cinler ancak dua ve oruçla kovulabilir\" sözlerini de"},{"n":"24","t":"\"İki dirhemlik tapınak vergisi\": Grekçe \"Didrahma\" (bkz. Birimler Cetveli). 17:27 \"Dört dirhemlik bir akçe\": Grekçe \"Bir statir\" (bkz. Birimler Cetveli). 18:10-11 Birçok Grekçe elyazması, \"İnsanoğlu, kaybolanı kurtarmak için geldi\" sözlerini de"},{"n":"64","t":"\"Kudretli Olan\":"},{"n":"4","t":"\"Birini\": Grekçe \"Kanı\". 28:19 \"Adıyla\": Grekçe \"Adı içine\"._ 19:9 \"Boşanan kadınla evlenen de zina etmiş olur\" sözleri birçok Grekçe elyazmasında"},{"n":"25","t":"\"Yahya'nın vaftiz etme yetkisi\": Grekçe \"Yahya'nın vaftizi\". 21:25 \"Tanrı'dan mı\": Grekçe \"Gökten mi\". 23:5 \"Hamail\": Eski Antlaşma'dan alınan bazı ayetlerin içine konduğu, alna ya da sol kola takılan küçük kutu anlamındadır (bkz. Çık.13:9; Yas.6:8,9). 23:5 \"Püskül\": Dindar Yahudiler, Kutsal Yasa'yı hatırlamak için giysilerinin eteğine dört püskül dikerler (bkz. Say.15:38,39; Yas.22:12). 23:13-14 Birçok Grekçe elyazması, \"Vay halinize, ey din bilginleri ve Ferisiler, ikiyüzlüler! Bir yandan gösteriş için uzun uzun dua edersiniz, öte yandan dul kadınların malını mülkünü sömürürsünüz. Bundan ötürü cezanız daha ağır olacaktır\" sözlerini de içerir (bkz. Mar.12:40; Luk.20:47). 23:36 \"Kuşak\" ya da \"Soy\". 24:34 \"Kuşak\" ya da \"Soy\". 26:50 \"Ne yapacaksan yap\" ya da \"Bunun için mi geldin?\""}]}]},{"id":"markos","name":"Markos","chapters":[{"ch":1,"verses":[{"n":"1","t":"Tanrı'nın Oğlu İsa Mesih'le* ilgili Müjde'nin başlangıcı."},{"n":"2","t":"Peygamber Yeşaya'nın Kitabı'nda şöyle yazılmıştır: \"İşte, habercimi senin önünden gönderiyorum; O senin yolunu hazırlayacak.\""},{"n":"3","t":"\"Çölde haykıran, `Rab'bin yolunu hazırlayın, Geçeceği patikaları düzleyin' diye sesleniyor.\""},{"n":"4","t":"Böylece Vaftizci Yahya çölde ortaya çıktı. İnsanları, günahlarının bağışlanması için tövbe edip vaftiz* olmaya çağırıyordu."},{"n":"5","t":"Bütün Yahudiye halkı ve Yeruşalimliler'in hepsi ona geliyor, günahlarını itiraf ediyor, onun tarafından Şeria Irmağı'nda vaftiz ediliyordu."},{"n":"6","t":"Yahya'nın deve tüyünden giysisi, belinde deri kuşağı vardı. Çekirge ve yaban balı yerdi."},{"n":"7","t":"Şu haberi yayıyordu: \"Benden sonra benden daha güçlü olan geliyor. Eğilip O'nun çarıklarının bağını çözmeye bile layık değilim."},{"n":"8","t":"Ben sizi suyla vaftiz ettim, ama O sizi Kutsal Ruh'la vaftiz edecektir.\" İsa Görevine Başlıyor (Mat.3:13-4:22; Luk.3:21-22; 4:1-15; 5:1-11)"},{"n":"9","t":"O günlerde Celile'nin Nasıra Kenti'nden çıkıp gelen İsa, Yahya tarafından Şeria Irmağı'nda vaftiz edildi."},{"n":"10","t":"Tam sudan çıkarken, göklerin yarıldığını ve Ruh'un güvercin gibi üzerine indiğini gördü."},{"n":"11","t":"Göklerden, \"Sen benim sevgili Oğlum'sun, senden hoşnudum\" diyen bir ses duyuldu."},{"n":"12","t":"O an Ruh, İsa'yı çöle gönderdi."},{"n":"13","t":"İsa çölde kaldığı kırk gün boyunca Şeytan tarafından denendi. Yabanıl hayvanlar arasındaydı, melekler O'na hizmet ediyordu."},{"n":"14","t":"Yahya'nın tutuklanmasından sonra İsa, Tanrı'nın Müjdesi'ni duyura duyura Celile'ye gitti."},{"n":"15","t":"\"Zaman doldu\" diyordu, \"Tanrı'nın Egemenliği yaklaştı. Tövbe edin, Müjde'ye inanın!\""},{"n":"16","t":"İsa, Celile Gölü'nün kıyısından geçerken, göle ağ atmakta olan Simun ile kardeşi Andreas'ı gördü. Bu adamlar balıkçıydı."},{"n":"17","t":"İsa onlara, \"Ardımdan gelin\" dedi, \"Sizleri insan tutan balıkçılar yapacağım.\""},{"n":"18","t":"Onlar da hemen ağlarını bırakıp O'nun ardından gittiler."},{"n":"19","t":"İsa biraz ileri gidince Zebedi'nin oğulları Yakup'la Yuhanna'yı gördü. Teknede ağlarını onarıyorlardı."},{"n":"20","t":"Hemen onları çağırdı. Onlar da babaları Zebedi'yi işçilerle birlikte teknede bırakıp İsa'nın ardından gittiler. İsa Kötü Ruhları Kovuyor, Hastaları İyileştiriyor (Mat.8:14-17; Luk.4:31-44)"},{"n":"21","t":"Kefarnahum'a girdiler. Şabat Günü* İsa havraya gidip öğretmeye başladı."},{"n":"22","t":"Halk O'nun öğretişine şaşıp kaldı. Çünkü onlara din bilginleri* gibi değil, yetkili biri gibi öğretiyordu."},{"n":"23-24","t":"Tam o sırada havrada bulunan ve kötü ruha tutulmuş bir adam, \"Ey Nasıralı İsa, bizden ne istiyorsun?\" diye bağırdı. \"Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrı'nın Kutsalı'sın sen!\""},{"n":"25","t":"İsa, \"Sus, çık adamdan!\" diyerek kötü ruhu azarladı."},{"n":"26","t":"Kötü ruh adamı sarstı ve büyük bir çığlık atarak içinden çıktı."},{"n":"27","t":"Herkes şaşıp kaldı. Birbirlerine, \"Bu nasıl şey?\" diye sormaya başladılar. \"Yepyeni bir öğreti! Kötü ruhlara bile yetkiyle buyruk veriyor, onlar da sözünü dinliyor.\""},{"n":"28","t":"Böylece İsa'yla ilgili haber, Celile bölgesinin her yerine hızla yayıldı."},{"n":"29","t":"İsa havradan çıkar çıkmaz, Yakup ve Yuhanna ile birlikte Simun ve Andreas'ın evine gitti."},{"n":"30","t":"Simun'un kaynanası ateşler içinde yatıyordu. Durumu hemen İsa'ya bildirdiler."},{"n":"31","t":"O da hastaya yaklaştı, elinden tutup kaldırdı. Kadının ateşi düştü, onlara hizmet etmeye başladı."},{"n":"32","t":"Akşam olup güneş batınca, bütün hastaları ve cinlileri İsa'ya getirdiler."},{"n":"33","t":"Bütün kent halkı kapıya toplanmıştı."},{"n":"34","t":"İsa, çeşitli hastalıklara yakalanmış birçok kişiyi iyileştirdi, birçok cini kovdu. Cinlerin konuşmasına izin vermiyordu. Çünkü onlar kendisinin kim olduğunu biliyorlardı."},{"n":"35","t":"Sabah çok erkenden, ortalık henüz ağarmadan İsa kalktı, evden çıkıp ıssız bir yere gitti, orada dua etmeye başladı."},{"n":"36","t":"Simun ile yanındakiler İsa'yı aramaya çıktılar."},{"n":"37","t":"O'nu bulunca, \"Herkes seni arıyor!\" dediler."},{"n":"38","t":"İsa onlara, \"Başka yerlere, yakın kasabalara gidelim\" dedi. \"Oralarda da Tanrı sözünü duyurayım. Bunun için çıkıp geldim.\""},{"n":"39","t":"Böylece havralarında Tanrı sözünü duyurarak ve cinleri kovarak bütün Celile bölgesini dolaştı. İsa Bir Cüzamlıyı İyileştiriyor (Mat.8:1-4; Luk.5:12-16)"},{"n":"40","t":"İsa'ya cüzamlı* biri geldi, diz çökerek, \"İstersen beni temiz kılabilirsin\" diye yalvardı."},{"n":"41","t":"İsa'nın yüreği sızladı, elini uzatıp adama dokundu, \"İsterim, temiz ol!\" dedi."},{"n":"42","t":"Adam anında cüzamdan kurtulup tertemiz oldu."},{"n":"43","t":"İsa onu sıkıca uyararak hemen yanından uzaklaştırdı."},{"n":"44","t":"\"Sakın kimseye bir şey söyleme!\" dedi. \"Git, kâhine* görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu sunuları sun.\""},{"n":"45","t":"Ne var ki, adam çıkıp gitti, olayla ilgili haberi her tarafa yayıp duyurmaya başladı. Öyle ki, İsa artık hiçbir kente açıkça giremez oldu. Ancak dışarıda, ıssız yerlerde kalıyordu. Ve halk her yerden O'na akın ediyordu."}]},{"ch":2,"verses":[{"n":"1","t":"Birkaç gün sonra İsa tekrar Kefarnahum'a geldiğinde, evde olduğu duyuldu."},{"n":"2","t":"O kadar çok insan toplandı ki, artık kapının önünde bile duracak yer kalmamıştı. İsa onlara Tanrı sözünü anlatıyordu."},{"n":"3","t":"Bu arada O'na dört kişinin taşıdığı felçli bir adamı getirdiler."},{"n":"4","t":"Kalabalıktan O'na yaklaşamadıkları için, bulunduğu yerin üzerindeki damı delip açarak felçliyi üstünde yattığı şilteyle birlikte aşağı indirdiler."},{"n":"5","t":"İsa onların imanını görünce felçliye, \"Oğlum, günahların bağışlandı\" dedi."},{"n":"6-7","t":"Orada oturan bazı din bilginleri ise içlerinden şöyle düşündüler: \"Bu adam neden böyle konuşuyor? Tanrı'ya küfrediyor! Tanrı'dan başka kim günahları bağışlayabilir?\""},{"n":"8","t":"Akıllarından geçeni hemen ruhunda sezen İsa onlara, \"Aklınızdan neden böyle şeyler geçiriyorsunuz?\" dedi."},{"n":"9","t":"\"Hangisi daha kolay, felçliye, `Günahların bağışlandı' demek mi, yoksa, 'Kalk, şilteni topla, yürü' demek mi?"},{"n":"10-11","t":"Ne var ki, İnsanoğlu'nun* yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye...\" Sonra felçliye, \"Sana söylüyorum, kalk, şilteni topla, evine git!\" dedi."},{"n":"12","t":"Adam kalktı, hemen şiltesini topladı, hepsinin gözü önünde çıkıp gitti. Herkes şaşakalmıştı. Tanrı'yı övüyorlar, \"Böylesini hiç görmemiştik\" diyorlardı. Levi'nin Öğrencilere Katılması (Mat.9:9-13; Luk.5:27-32)"},{"n":"13","t":"İsa yine çıkıp göl kıyısına gitti. Bütün halk yanına geldi, O da onlara öğretmeye başladı."},{"n":"14","t":"Yoldan geçerken, vergi toplama yerinde oturan Alfay oğlu Levi'yi gördü. Ona, \"Ardımdan gel\" dedi. Levi de kalkıp İsa'nın ardından gitti."},{"n":"15","t":"Sonra İsa, Levi'nin evinde yemek yerken, birçok vergi görevlisiyle* günahkâr O'nunla ve öğrencileriyle birlikte sofraya oturmuştu. O'nu izleyen böyle birçok kişi vardı."},{"n":"16","t":"Ferisiler'den* bazı din bilginleri, O'nu günahkârlar ve vergi görevlileriyle birlikte yemekte görünce öğrencilerine, \"Niçin vergi görevlileri ve günahkârlarla birlikte yemek yiyor?\" diye sordular."},{"n":"17","t":"Bunu duyan İsa onlara, \"Sağlamların değil, hastaların hekime ihtiyacı var\" dedi. \"Ben doğru kişileri değil, günahkârları çağırmaya geldim.\" Oruçla İlgili Soru (Mat.9:14-17; Luk.5:33-39)"},{"n":"18","t":"Yahya'nın öğrencileriyle Ferisiler oruç tutarken, bazı kişiler İsa'ya gelip, \"Yahya'nın ve Ferisiler'in öğrencileri oruç tutuyor da senin öğrencilerin neden tutmuyor?\" diye sordular."},{"n":"19","t":"İsa şöyle karşılık verdi: \"Güvey aralarında olduğu sürece davetliler oruç tutar mı? Güvey aralarında oldukça oruç tutmazlar!"},{"n":"20","t":"Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o gün oruç tutacaklar."},{"n":"21","t":"Hiç kimse eski giysiyi yeni kumaş parçasıyla yamamaz. Yoksa yeni yama çeker, eski giysiden kopar, yırtık daha beter olur."},{"n":"22","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa şarap tulumları patlatır, şarap da tulumlar da mahvolur. Yeni şarap yeni tulumlara doldurulur.\" Şabat Günü Sorunu (Mat.12:1-8; Luk.6:1-5)"},{"n":"23","t":"Bir Şabat Günü* İsa ekinler arasından geçiyordu. Öğrencileri yolda giderken başakları koparmaya başladılar."},{"n":"24","t":"Ferisiler İsa'ya, \"Bak, Şabat Günü yasak olanı neden yapıyorlar?\" dediler."},{"n":"25","t":"İsa onlara, \"Davut'la yanındakiler aç ve muhtaç kalınca Davut'un ne yaptığını hiç okumadınız mı?\" diye sordu."},{"n":"26","t":"\"Başkâhin Aviyatar'ın zamanında Davut, Tanrı'nın evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini* yedi ve yanındakilere de verdi.\""},{"n":"27","t":"Sonra onlara, \"İnsan Şabat Günü için değil, Şabat Günü insan için yaratıldı\" dedi."},{"n":"28","t":"\"Bu nedenle İnsanoğlu* Şabat Günü'nün de Rabbi'dir.\""}]},{"ch":3,"verses":[{"n":"1","t":"İsa yine havraya girdi. Orada eli sakat bir adam vardı."},{"n":"2","t":"Bazıları İsa'yı suçlamak amacıyla, Şabat Günü* hastayı iyileştirecek mi diye O'nu gözlüyorlardı."},{"n":"3","t":"İsa, eli sakat adama, \"Kalk, öne çık!\" dedi."},{"n":"4","t":"Sonra havradakilere, \"Kutsal Yasa'ya göre Şabat Günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, can almak mı?\" diye sordu. Onlardan ses çıkmadı."},{"n":"5","t":"İsa, çevresindekilere öfkeyle baktı. Yüreklerinin duygusuzluğu O'nu kederlendirmişti. Adama, \"Elini uzat!\" dedi. Adam elini uzattı, eli yine sapasağlam oluverdi."},{"n":"6","t":"Bunun üzerine Ferisiler dışarı çıktılar, İsa'yı yok etmek için Hirodes yanlılarıyla hemen görüşmeye başladılar. İsa, Celile Gölü'nün Kıyısında"},{"n":"7-8","t":"İsa, öğrencileriyle birlikte göl kıyısına çekildi. Celile'den büyük bir kalabalık O'nun ardından geldi. Ayrıca, bütün yaptıklarını duyan büyük kalabalıklar Yahudiye'den, Yeruşalim'den, İdumeya'dan, Şeria Irmağı'nın karşı yakasından, Sur ve Sayda bölgelerinden kendisine akın etti."},{"n":"9","t":"İsa, kalabalığın arasında sıkışıp kalmamak için öğrencilerine bir kayık hazır bulundurmalarını söyledi."},{"n":"10","t":"Birçoklarını iyileştirmiş olduğundan, çeşitli hastalıklara yakalananlar O'na dokunmak için üzerine üşüşüyordu."},{"n":"11","t":"Kötü ruhlar O'nu görünce ayaklarına kapanıyor, \"Sen Tanrı'nın Oğlu'sun!\" diye bağırıyorlardı."},{"n":"12","t":"Ama İsa, kim olduğunu açıklamamaları için onları sıkı sıkıya uyardı. İsa On İki Elçisini Seçiyor (Mat.10:1-4; Luk.6:12-16)"},{"n":"13","t":"İsa, dağa çıkarak istediği kişileri yanına çağırdı. Onlar da yanına gittiler."},{"n":"14-19","t":"İsa bunlardan on iki kişiyi yanında bulundurmak, Tanrı sözünü duyurmaya göndermek ve cinleri kovmaya yetkili kılmak üzere seçti. Seçtiği bu on iki kişi şunlardır: Petrus adını verdiği Simun, Beni-Regeş, yani Gökgürültüsü Oğulları adını verdiği Zebedi'nin oğulları Yakup ve Yuhanna, Andreas, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Taday, Yurtsever* Simun ve İsa'ya ihanet eden Yahuda İskariot. İsa ve Baalzevul (Mat.12:22-32; Luk.11:14-23; 12:10)"},{"n":"20","t":"İsa bundan sonra eve gitti. Yine öyle büyük bir kalabalık toplandı ki, İsa'yla öğrencileri yemek bile yiyemediler."},{"n":"21","t":"Yakınları bunu duyunca, \"Aklını kaçırmış\" diyerek O'nu almaya geldiler."},{"n":"22","t":"Yeruşalim'den gelen din bilginleri ise, \"Baalzevul* O'nun içine girmiş\" ve \"Cinleri, cinlerin önderinin gücüyle kovuyor\" diyorlardı."},{"n":"23","t":"Bunun üzerine İsa din bilginlerini yanına çağırıp onlara benzetmelerle seslendi. \"Şeytan, Şeytan'ı nasıl kovabilir?\" dedi."},{"n":"24","t":"\"Bir ülke kendi içinde bölünmüşse, ayakta kalamaz."},{"n":"25","t":"Bir ev kendi içinde bölünmüşse, ayakta kalamaz."},{"n":"26","t":"Şeytan da kendine karşı gelip kendi içinde bölünmüşse, artık ayakta kalamaz; sonu gelmiş demektir."},{"n":"27","t":"Hiç kimse güçlü adamın evine girip malını çalamaz. Ancak onu bağladıktan sonra evini soyabilir."},{"n":"28-29","t":"Size doğrusunu söyleyeyim, insanların işlediği her günah, ettiği her küfür bağışlanacak, ama Kutsal Ruh'a küfreden asla bağışlanmayacak. Bunu yapan, asla silinmeyecek bir günah işlemiş olur.\""},{"n":"30","t":"İsa bu sözleri, \"O'nda kötü ruh var\" dedikleri için söyledi. İsa'nın Annesiyle Kardeşleri (Mat.12:46-50; Luk.8:19-21)"},{"n":"31","t":"Daha sonra İsa'nın annesiyle kardeşleri geldi. Dışarıda durdular, haber gönderip O'nu çağırdılar."},{"n":"32","t":"İsa'nın çevresinde oturan kalabalıktan bazıları, \"Bak\" dediler, \"Annenle kardeşlerin dışarıda, seni istiyorlar.\""},{"n":"33","t":"İsa buna karşılık onlara, \"Kimdir annem ve kardeşlerim?\" dedi."},{"n":"34","t":"Sonra çevresinde oturanlara bakıp şöyle dedi: \"İşte annem, işte kardeşlerim!"},{"n":"35","t":"Tanrı'nın isteğini kim yerine getirirse, kardeşim, kızkardeşim ve annem odur.\""}]},{"ch":4,"verses":[{"n":"1","t":"İsa göl kıyısında halka yine öğretmeye başladı. Çevresinde çok büyük bir kalabalık toplandı. Bu yüzden İsa göldeki bir tekneye binip oturdu. Bütün kalabalık göl kıyısında duruyordu."},{"n":"2-3","t":"İsa onlara benzetmelerle birçok şey öğretiyordu. Öğretirken, \"Şunu dinleyin\" dedi. \"Ekincinin biri tohum ekmeye çıktı."},{"n":"4","t":"Ektiği tohumlardan kimi yol kenarına düştü. Kuşlar gelip bunları yedi."},{"n":"5","t":"Kimi, toprağı az kayalık yerlere düştü. Toprak derin olmadığından hemen filizlendi."},{"n":"6","t":"Ne var ki, güneş doğunca kavruldular, kök salamadıkları için kuruyup gittiler."},{"n":"7","t":"Kimi, dikenler arasına düştü. Dikenler büyüdü, filizleri boğdu ve filizler ürün vermedi."},{"n":"8","t":"Kimi ise iyi toprağa düştü, büyüyüp çoğaldı, ürün verdi. Bazısı otuz, bazısı altmış, bazısı da yüz kat ürün verdi.\""},{"n":"9","t":"Sonra İsa şunu ekledi: \"İşitecek kulağı olan işitsin!\" Benzetmelerin Amacı (Mat.13:10-17; Luk.8:9-10)"},{"n":"10","t":"Onikiler'le* öbür izleyicileri İsa'yla yalnız kalınca, kendisinden benzetmelerin anlamını sordular."},{"n":"11","t":"O da onlara şöyle dedi: \"Tanrı'nın Egemenliği'nin sırrı sizlere açıklandı, ama dışarıda olanlara her şey benzetmelerle anlatılır."},{"n":"12","t":"Öyle ki, 'Bakıp bakıp görmesinler, Duyup duyup anlamasınlar da, Dönüp bağışlanmasınlar.'\" Tohum Benzetmesi Açıklanıyor (Mat.13:18-23; Luk.8:11-15)"},{"n":"13","t":"İsa sonra onlara, \"Siz bu benzetmeyi anlamıyor musunuz?\" dedi. \"Öyleyse bütün benzetmeleri nasıl anlayacaksınız?"},{"n":"14","t":"Ekincinin ektiği, Tanrı sözüdür."},{"n":"15","t":"Bazı insanlar sözün ekildiği yerde yol kenarına düşen tohumlara benzer. Bunlar sözü işitir işitmez, Şeytan gelir, yüreklerine ekilen sözü alır götürür."},{"n":"16-17","t":"Kayalık yerlere ekilenler ise, işittikleri sözü hemen sevinçle kabul eden, ama kök salamadıkları için ancak bir süre dayanan kişilerdir. Böyleleri Tanrı sözünden ötürü sıkıntı ya da zulme uğrayınca hemen sendeleyip düşerler."},{"n":"18-19","t":"Yine bazıları dikenler arasında ekilen tohumlara benzerler. Bunlar sözü işitirler, ama dünyasal kaygılar, zenginliğin aldatıcılığı ve daha başka hevesler araya girip sözü boğar ve ürün vermesini engeller."},{"n":"20","t":"İyi toprağa ekilenler ise, sözü işiten, onu benimseyen, kimi otuz, kimi altmış, kimi de yüz kat ürün veren kişilerdir.\" Kandil Kandilliğe Konur (Luk.8:16-18)"},{"n":"21","t":"Onlara, \"Kandili, tahıl ölçeğinin ya da yatağın altına koymak için mi getirirler?\" dedi. \"Kandilliğe koymak için değil mi?"},{"n":"22","t":"Gizli olan ne varsa, açığa çıkarılmak üzere gizlenmiştir; saklı olan ne varsa, aydınlığa çıkmak üzere saklanmıştır."},{"n":"23","t":"İşitecek kulağı olan işitsin!\""},{"n":"24","t":"İsa şöyle devam etti: \"İşittiklerinize dikkat edin! Hangi ölçekle verirseniz, aynı ölçekle alacaksınız. Hatta size daha fazlası verilecek."},{"n":"25","t":"Çünkü kimde varsa, ona daha çok verilecek. Ama kimde yoksa, elindeki de alınacak.\" Filizlenen Tohum Benzetmesi"},{"n":"26","t":"Sonra İsa şöyle dedi: \"Tanrı'nın Egemenliği, toprağa tohum saçan adama benzer."},{"n":"27","t":"Gece olur, uyur; gündüz olur, kalkar. Kendisi nasıl olduğunu bilmez ama, tohum filizlenir, gelişir."},{"n":"28","t":"Toprak kendiliğinden ürün verir. Önce filizi, sonra başağı, sonunda da başağı dolduran taneleri verir."},{"n":"29","t":"Ürün olgunlaşınca, adam hemen orağı vurur. Çünkü biçim vakti gelmiştir.\" Hardal Tanesi Benzetmesi (Mat.13:31-32,34; Luk.13:18-19)"},{"n":"30","t":"İsa sonra şöyle dedi: \"Tanrı'nın Egemenliği'ni neye benzetelim, nasıl bir benzetmeyle anlatalım?"},{"n":"31-32","t":"Tanrı'nın Egemenliği, hardal tanesine benzer. Hardal, yeryüzünde toprağa ekilen tohumların en küçüğü olmakla birlikte, ekildikten sonra gelişir, bütün bahçe bitkilerinin boyunu aşar. Öylesine dal budak salar ki, kuşlar gölgesinde barınabilir.\""},{"n":"33","t":"İsa, Tanrı sözünü, buna benzer birçok benzetmeyle halkın anlayabildiği ölçüde anlatırdı."},{"n":"34","t":"Benzetme kullanmadan onlara hiçbir şey anlatmazdı. Ama kendi öğrencileriyle yalnız kaldığında, onlara her şeyi açıklardı. İsa Fırtınayı Yatıştırıyor (Mat.8:23-27; Luk.8:22-25)"},{"n":"35","t":"O gün akşam olunca öğrencilerine, \"Karşı yakaya geçelim\" dedi."},{"n":"36","t":"Öğrenciler kalabalığı geride bırakarak İsa'yı, içinde bulunduğu tekneyle götürdüler. Yanında başka tekneler de vardı."},{"n":"37","t":"Bu sırada büyük bir fırtına koptu. Dalgalar tekneye öyle bindirdi ki, tekne neredeyse suyla dolmuştu."},{"n":"38","t":"İsa, teknenin kıç tarafında bir yastığa yaslanmış uyuyordu. Öğrenciler O'nu uyandırıp, \"Öğretmenimiz, öleceğiz! Hiç aldırmıyor musun?\" dediler."},{"n":"39","t":"İsa kalkıp rüzgarı azarladı, göle, \"Sus, sakin ol!\" dedi. Rüzgar dindi, ortalık sütliman oldu."},{"n":"40","t":"İsa öğrencilerine, \"Neden korkuyorsunuz? Hâlâ imanınız yok mu?\" dedi."},{"n":"41","t":"Onlar ise büyük korku içinde birbirlerine, \"Bu adam kim ki, rüzgar da göl de O'nun sözünü dinliyor?\" dediler."}]},{"ch":5,"verses":[{"n":"1","t":"Gölün karşı yakasına, Gerasalılar'ın memleketine vardılar."},{"n":"2","t":"İsa tekneden iner inmez, kötü ruha tutulmuş bir adam mezarlık mağaralardan çıkıp O'nu karşıladı."},{"n":"3","t":"Mezarların içinde yaşayan bu adamı artık kimse zincirle bile bağlı tutamıyordu."},{"n":"4","t":"Birçok kez zincir ve kösteklerle bağlandığı halde, zincirleri koparmış, köstekleri parçalamıştı. Hiç kimse onunla başa çıkamıyordu."},{"n":"5","t":"Gece gündüz mezarlarda, dağlarda bağırıp duruyor, kendini taşlarla yaralıyordu."},{"n":"6","t":"Uzaktan İsa'yı görünce koşup geldi, O'nun önünde yere kapandı."},{"n":"7","t":"Yüksek sesle haykırarak, \"Ey İsa, yüce Tanrı'nın Oğlu, benden ne istiyorsun? Tanrı hakkı için sana yalvarırım, bana işkence etme!\" dedi."},{"n":"8","t":"Çünkü İsa, \"Ey kötü ruh, adamın içinden çık!\" demişti."},{"n":"9","t":"Sonra İsa adama, \"Adın ne?\" diye sordu. \"Adım Tümen*. Çünkü sayımız çok\" dedi."},{"n":"10","t":"Ruhları o bölgeden çıkarmaması için İsa'ya yalvarıp yakardı."},{"n":"11","t":"Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı."},{"n":"12","t":"Kötü ruhlar İsa'ya, \"Bizi şu domuzlara gönder, onlara girelim\" diye yalvardılar."},{"n":"13","t":"İsa'nın izin vermesi üzerine kötü ruhlar adamdan çıkıp domuzların içine girdiler. Yaklaşık iki bin domuzdan oluşan sürü, dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"14","t":"Domuzları güdenler kaçıp kentte ve köylerde olayın haberini yaydılar. Halk olup biteni görmeye çıktı."},{"n":"15","t":"İsa'nın yanına geldiklerinde, önceleri bir tümen cine tutulan adamı giyinmiş, aklı başına gelmiş, oturmuş görünce korktular."},{"n":"16","t":"Olayı görenler, cinli adama olanları ve domuzların başına gelenleri halka anlattılar."},{"n":"17","t":"Bunun üzerine halk, bölgelerinden ayrılması için İsa'ya yalvarmaya başladı."},{"n":"18","t":"İsa tekneye binerken, önceleri cinli olan adam O'na, \"Seninle geleyim\" diye yalvardı."},{"n":"19","t":"Ama İsa adama izin vermedi. Ona, \"Evine, yakınlarının yanına dön\" dedi. \"Rab'bin senin için neler yaptığını, sana nasıl merhamet ettiğini onlara anlat.\""},{"n":"20","t":"Adam da gitti, İsa'nın kendisi için neler yaptığını Dekapolis'te duyurmaya başladı. Anlattıklarına herkes şaşıp kalıyordu. Dirilen Kız, İyileşen Kadın (Mat.9:18-26; Luk.8:40-56)"},{"n":"21","t":"İsa tekneyle karşı yakaya dönünce, çevresinde büyük bir kalabalık toplandı. Kendisi gölün kıyısında duruyordu."},{"n":"22-23","t":"Bu sırada havra yöneticilerinden Yair adında biri geldi. İsa'yı görünce ayaklarına kapandı, \"Küçük kızım can çekişiyor. Gelip ellerini onun üzerine koy da kurtulsun, yaşasın!\" diye yalvardı."},{"n":"24","t":"İsa adamla birlikte gitti. Büyük bir kalabalık da ardından gidiyor, O'nu sıkıştırıyordu."},{"n":"25","t":"Orada, on iki yıldır kanaması olan bir kadın vardı."},{"n":"26","t":"Birçok hekimin elinden çok çekmiş, varını yoğunu harcamış, ama iyileşeceğine daha da kötüleşmişti."},{"n":"27","t":"Kadın, İsa hakkında anlatılanları duymuştu. Bu nedenle, kalabalıkta O'nun arkasından gelip giysisine dokundu."},{"n":"28","t":"İçinden, \"Giysilerine bile dokunsam kurtulurum\" diyordu."},{"n":"29","t":"O anda kanaması kesiliverdi. Kadın, bedeninin derinliğinde acıdan kurtulduğunu hissetti."},{"n":"30","t":"İsa ise, kendisinden bir gücün akıp gittiğini hemen anladı. Kalabalığın ortasında dönüp, \"Giysilerime kim dokundu?\" diye sordu."},{"n":"31","t":"Öğrencileri O'na, \"Seni sıkıştıran kalabalığı görüyorsun! Nasıl oluyor da, 'Bana kim dokundu' diye soruyorsun?\" dediler."},{"n":"32","t":"İsa kendisine dokunanı görmek için çevresine bakındı."},{"n":"33","t":"Kadın da kendisindeki değişikliği biliyordu. Korkuyla titreyerek geldi, İsa'nın ayaklarına kapandı ve O'na bütün gerçeği anlattı."},{"n":"34","t":"İsa ona, \"Kızım\" dedi, \"İmanın seni kurtardı. Esenlikle git. Acıların son bulsun.\""},{"n":"35","t":"İsa daha konuşurken, havra yöneticisinin evinden adamlar geldi. Yöneticiye, \"Kızın öldü\" dediler. \"Öğretmeni neden hâlâ rahatsız ediyorsun?\""},{"n":"36","t":"İsa bu sözlere aldırmadan havra yöneticisine, \"Korkma, yalnız iman et!\" dedi."},{"n":"37","t":"İsa, Petrus, Yakup ve Yakup'un kardeşi Yuhanna'dan başka hiç kimsenin kendisiyle birlikte gitmesine izin vermedi."},{"n":"38","t":"Havra yöneticisinin evine vardıklarında İsa, acı acı ağlayıp feryat eden gürültülü bir kalabalıkla karşılaştı."},{"n":"39","t":"İçeri girerek onlara, \"Niye gürültü edip ağlıyorsunuz?\" dedi. \"Çocuk ölmedi, uyuyor.\""},{"n":"40","t":"Onlar ise kendisiyle alay ettiler. Ama İsa hepsini dışarı çıkardıktan sonra çocuğun annesini babasını ve kendisiyle birlikte olanları alıp çocuğun bulunduğu odaya girdi."},{"n":"41","t":"Çocuğun elini tutarak ona, \"Talita kumi!\" dedi. Bu söz, \"Kızım, sana söylüyorum, kalk\" demektir."},{"n":"42","t":"On iki yaşında olan kız hemen ayağa kalktı, yürümeye başladı. Oradakileri derin bir şaşkınlık aldı."},{"n":"43","t":"İsa, \"Bunu kimse bilmesin\" diyerek onları sıkı sıkıya uyardı ve kıza yemek verilmesini buyurdu."}]},{"ch":6,"verses":[{"n":"1","t":"İsa oradan ayrılarak kendi memleketine gitti. Öğrencileri de ardından gittiler."},{"n":"2","t":"Şabat Günü* olunca İsa havrada öğretmeye başladı. Söylediklerini işiten birçok kişi şaşıp kaldı. \"Bu adam bunları nereden öğrendi?\" diye soruyorlardı. \"Kendisine verilen bu bilgelik nedir? Nasıl böyle mucizeler yapabiliyor?"},{"n":"3","t":"Meryem'in oğlu, Yakup, Yose, Yahuda ve Simun'un kardeşi olan marangoz değilmi bu? Kızkardeşleri burada, aramızda yaşamıyor mu?\" Ve gücenip O'nu reddettiler."},{"n":"4","t":"İsa da onlara, \"Bir peygamber, kendi memleketinden, akraba çevresinden ve kendi evinden başka yerde hor görülmez\" dedi."},{"n":"5","t":"Orada birkaç hastayı, üzerlerine ellerini koyarak iyileştirmekten başka hiçbir mucize yapamadı."},{"n":"6","t":"Halkın imansızlığına şaşıyordu. İsa On İki Elçisini Görevlendiriyor (Mat.10:5-15; Luk.9:1-6) İsa çevredeki köyleri dolaşıp öğretiyordu."},{"n":"7","t":"On iki öğrencisini yanına çağırdı ve onları ikişer ikişer halk arasına göndermeye başladı. Onlara kötü ruhlar üzerinde yetki verdi."},{"n":"8","t":"Yolculuk için yanlarına değnekten başka bir şey almamalarını söyledi. Ne ekmek, ne torba, ne de kuşaklarında para götüreceklerdi."},{"n":"9","t":"Onlara çarık giymelerini söyledi. Ama, \"İki mintan giymeyin\" dedi."},{"n":"10","t":"\"Bir yere gittiğiniz zaman, oradan ayrılıncaya dek hep aynı evde kalın\" diye devam etti."},{"n":"11","t":"\"İnsanların sizi kabul etmedikleri, sizi dinlemedikleri bir yerden ayrılırken, onlara uyarı olsun diye ayağınızın altındaki tozu silkin!\""},{"n":"12","t":"Böylece öğrenciler yola çıkıp insanları tövbeye çağırmaya başladılar."},{"n":"13","t":"Birçok cin kovdular; birçok hastayı, üzerlerine yağ sürerek iyileştirdiler. Yahya'nın Öldürülmesi (Mat.14:1-12; Luk.9:7-9)"},{"n":"14","t":"Kral Hirodes* de olup bitenleri duydu. Çünkü İsa'nın ünü her tarafa yayılmıştı. Bazıları, \"Bu adam, ölümden dirilen Vaftizci Yahya'dır. Olağanüstü güçlerin onda etkin olmasının nedeni budur\" diyordu."},{"n":"15","t":"Başkaları, \"O İlyas'tır\" diyor, yine başkaları, \"Eski peygamberlerden biri gibi bir peygamberdir\" diyordu."},{"n":"16","t":"Hirodes bunları duyunca, \"Başını kestirdiğim Yahya dirildi!\" dedi."},{"n":"17-18","t":"Hirodes'in kendisi, kardeşi Filipus'un karısı Hirodiya'nın yüzünden adam gönderip Yahya'yı tutuklatmış, zindana attırıp zincire vurdurmuştu. Çünkü Hirodes bu kadınla evlenince Yahya ona, \"Kardeşinin karısıyla evlenmen Kutsal Yasa'ya aykırıdır\" demişti."},{"n":"19","t":"Hirodiya bu yüzden Yahya'ya kin bağlamıştı; onu öldürtmek istiyor, ama başaramıyordu."},{"n":"20","t":"Çünkü Yahya'nın doğru ve kutsal bir adam olduğunu bilen Hirodes ondan korkuyor ve onu koruyordu. Yahya'yı dinlediği zaman büyük bir şaşkınlık içinde kalıyor, yine de onu dinlemekten zevk alıyordu."},{"n":"21","t":"Ne var ki, Hirodes'in kendi doğum gününde saray büyükleri, komutanlar ve Celile'nin ileri gelenleri için verdiği şölende beklenen fırsat doğdu."},{"n":"22","t":"Hirodiya'nın kızı içeri girip dans etti. Bu, Hirodes'le konuklarının hoşuna gitti. Kral genç kıza, \"Dile benden, ne dilersen veririm\" dedi."},{"n":"23","t":"Ant içerek, \"Benden ne dilersen, krallığımın yarısı da olsa, veririm\" dedi."},{"n":"24","t":"Kız dışarı çıkıp annesine, \"Ne isteyeyim?\" diye sordu. \"Vaftizci Yahya'nın başını iste\" dedi annesi."},{"n":"25","t":"Kız hemen koşup kralın yanına girdi, \"Vaftizci Yahya'nın başını bir tepsi üzerinde hemen bana vermeni istiyorum\" diyerek dileğini açıkladı."},{"n":"26","t":"Kral buna çok üzüldüyse de, konuklarının önünde içtiği anttan ötürü kızı reddetmek istemedi."},{"n":"27","t":"Hemen bir cellat gönderip Yahya'nın başını getirmesini buyurdu. Cellat zindana giderek Yahya'nın başını kesti."},{"n":"28","t":"Kesik başı bir tepsi üzerinde getirip genç kıza verdi, kız da annesine götürdü."},{"n":"29","t":"Yahya'nın öğrencileri bunu duyunca gelip cesedi aldılar ve mezara koydular. İsa Beş Bin Kişiyi Doyuruyor (Mat.14:13-21; Luk.9:10-17; Yu.6:1-14)"},{"n":"30","t":"Elçiler, İsa'nın yanına dönerek yaptıkları ve öğrettikleri her şeyi O'na anlattılar."},{"n":"31","t":"İsa onlara, \"Gelin, tek başımıza tenha bir yere gidelim de biraz dinlenin\" dedi. Gelen giden öyle çoktu ki, yemek yemeye bile vakit bulamıyorlardı."},{"n":"32","t":"Tekneye binip tek başlarına tenha bir yere doğru yol aldılar."},{"n":"33","t":"Gittiklerini gören birçok kişi onları tanıdı. Halk civardaki bütün kentlerden yaya olarak yola dökülüp onlardan önce oraya vardı."},{"n":"34","t":"İsa tekneden inince büyük bir kalabalıkla karşılaştı. Çobansız koyunlara benzeyen bu insanlara acıdı ve onlara birçok konuda öğretmeye başladı."},{"n":"35-36","t":"Vakit ilerlemişti. Öğrencileri İsa'ya gelip, \"Burası ıssız bir yer\" dediler, \"Vakit de ilerledi. Halkı salıver de çevredeki çiftlik ve köylere gidip kendilerine yiyecek alsınlar.\""},{"n":"37","t":"İsa ise, \"Onlara siz yiyecek verin\" diye karşılık verdi. Öğrenciler İsa'ya, \"Gidip iki yüz dinarlık ekmek alıp onlara yedirelim mi yani?\" diye sordular."},{"n":"38","t":"İsa onlara, \"Kaç ekmeğiniz var, gidin bakın\" dedi. Öğrenip geldiler, \"Beş ekmekle iki balığımız var\" dediler."},{"n":"39","t":"İsa herkesi küme küme yeşil çayıra oturtmalarını buyurdu."},{"n":"40","t":"Halk yüzer ellişer kişilik bölükler halinde oturdu."},{"n":"41","t":"İsa beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra ekmekleri böldü ve halka dağıtmaları için öğrencilerine verdi. İki balığı da hepsinin arasında paylaştırdı."},{"n":"42-43","t":"Herkes yiyip doydu. Artakalan ekmek ve balıktan on iki sepet dolusu topladılar."},{"n":"44","t":"Yemek yiyen erkeklerin sayısı beş bin kadardı. İsa Su Üstünde Yürüyor (Mat.14:22-33; Yu.6:15-21)"},{"n":"45","t":"Bundan hemen sonra İsa öğrencilerine, tekneye binip kendisinden önce karşı yakada bulunan Beytsayda'ya geçmelerini buyurdu. Bu arada kendisi halkı evlerine gönderecekti."},{"n":"46","t":"Onları uğurladıktan sonra, dua etmek için dağa çıktı."},{"n":"47-48","t":"Akşam olduğunda, tekne gölün ortasına varmıştı. Yalnız başına karada kalan İsa, öğrencilerinin kürek çekmekte çok zorlandıklarını gördü. Çünkü rüzgar onlara karşı esiyordu. Sabaha karşı*fx* İsa, gölün üstünde yürüyerek onlara yaklaştı. Yanlarından geçip gidecekti."},{"n":"49","t":"Onlar ise, gölün üstünde yürüdüğünü görünce O'nu hayalet sanarak bağrıştılar."},{"n":"50","t":"Hepsi O'nu görmüş ve dehşete kapılmıştı. İsa hemen onlara seslenerek, \"Cesur olun, benim, korkmayın!\" dedi."},{"n":"51","t":"Tekneye binip onlara katılınca rüzgar dindi. Onlarsa büyük bir şaşkınlık içindeydi."},{"n":"52","t":"Ekmekle ilgili mucizeyi bile anlamamışlardı; zihinleri körelmişti. İsa Ginnesar'da Hastaları İyileştiriyor (Mat.14:34-36)"},{"n":"53","t":"İsa'yla öğrencileri gölü aştılar, Ginnesar'da karaya çıkıp tekneyi bağladılar."},{"n":"54","t":"Onlar tekneden inince, halk İsa'yı hemen tanıdı."},{"n":"55","t":"Bazıları koşarak bütün yöreyi dolaştı. İsa'nın bulunduğu yeri öğrenenler, hastaları şilteleriyle oraya götürmeye başladılar."},{"n":"56","t":"Köy olsun, kent ya da çiftlik olsun, İsa'nın gittiği her yerde, hastaları meydanlara yatırıyor, sadece giysisinin eteğine dokunmalarına izin vermesi için yalvarıyorlardı. Dokunanların hepsi de iyileşti."}]},{"ch":7,"verses":[{"n":"1","t":"Yeruşalim'den gelen Ferisiler ve bazı din bilginleri, İsa'nın çevresinde toplandılar."},{"n":"2","t":"O'nun öğrencilerinden bazılarının murdar*, yani yıkanmamış ellerle yemek yediklerini gördüler."},{"n":"3","t":"Ferisiler, hatta bütün Yahudiler, atalarının töresi uyarınca ellerini iyice yıkamadan yemek yemezler."},{"n":"4","t":"Çarşıdan dönünce de, yıkanmadan yemek yemezler. Ayrıca kâse, testi ve bakır kapların yıkanmasıyla ilgili başka birçok töreye de uyarlar."},{"n":"5","t":"Ferisiler ve din bilginleri İsa'ya, \"Öğrencilerin neden atalarımızın töresine uymuyorlar, niçin murdar ellerle yemek yiyorlar?\" diye sordular."},{"n":"6","t":"İsa onları şöyle yanıtladı: \"Yeşaya'nın siz ikiyüzlülerle ilgili peygamberlik sözü ne kadar yerindedir! Yazmış olduğu gibi, 'Bu halk, dudaklarıyla beni*fx* sayar, Ama yürekleri benden uzak."},{"n":"7","t":"Bana boşuna taparlar. Çünkü öğrettikleri, sadece insan buyruklarıdır.'"},{"n":"8","t":"Siz Tanrı buyruğunu bir yana bırakmış, insan töresine uyuyorsunuz.\""},{"n":"9","t":"İsa onlara ayrıca şunu söyledi: \"Kendi törenizi sürdürmek için Tanrı buyruğunu bir kenara itmeyi ne de güzel beceriyorsunuz!"},{"n":"10","t":"Musa, 'Annene babana saygı göstereceksin' ve, 'Annesine ya da babasına söven kesinlikle öldürülecektir' diye buyurmuştu."},{"n":"11-12","t":"Ama siz, 'Eğer bir adam annesine ya da babasına, benden alacağın bütün yardım kurbandır, yani Tanrı'ya adanmıştır derse, artık annesi ya da babası için bir şey yapmasına izin yok' diyorsunuz."},{"n":"13","t":"Böylece kuşaktan kuşağa aktardığınız törelerle Tanrı'nın sözünü geçersiz kılıyorsunuz. Buna benzer daha birçok şey yapıyorsunuz.\""},{"n":"14","t":"İsa, halkı yine yanına çağırıp onlara, \"Hepiniz beni dinleyin ve şunu belleyin\" dedi."},{"n":"15-16","t":"\"İnsanın dışında olup içine giren hiçbir şey onu kirletemez. İnsanı kirleten, insanın içinden çıkandır.\"*fx*"},{"n":"17","t":"İsa kalabalığı bırakıp eve girince, öğrencileri O'na bu benzetmenin anlamını sordular."},{"n":"18","t":"O da onlara, \"Demek siz de anlamıyorsunuz, öyle mi?\" dedi. \"Dışarıdan insanın içine giren hiçbir şeyin onu kirletemeyeceğini bilmiyor musunuz?"},{"n":"19","t":"Dıştan giren, insanın yüreğine değil, midesine gider, oradan da helaya atılır.\" İsa bu sözlerle, bütün yiyeceklerin temiz olduğunu bildirmiş oluyordu."},{"n":"20","t":"İsa şöyle devam etti: \"İnsanı kirleten, insanın içinden çıkandır."},{"n":"21-22","t":"Çünkü kötü düşünceler, fuhuş, hırsızlık, cinayet, zina, açgözlülük, kötülük, hile, sefahat, kıskançlık, iftira, kibir ve akılsızlık içten, insanın yüreğinden kaynaklanır."},{"n":"23","t":"Bu kötülüklerin hepsi içten kaynaklanır ve insanı kirletir.\" Fenikeli Kadının İmanı (Mat.15:21-28)"},{"n":"24","t":"İsa oradan ayrılarak Sur*fx* bölgesine gitti. Burada bir eve girdi. Kimsenin bunu bilmesini istemiyordu, ama gizlenemedi."},{"n":"25","t":"Küçük kızı kötü ruha tutulmuş bir kadın, İsa'yla ilgili haberi duyar duymaz geldi, ayaklarına kapandı."},{"n":"26","t":"Yahudi olmayan bu kadın Suriye-Fenike ırkındandı. Kızından cini kovması için İsa'ya rica etti."},{"n":"27","t":"İsa ona, \"Bırak, önce çocuklar doysunlar\" dedi. \"Çocukların ekmeğini alıp köpeklere atmak doğru değildir.\""},{"n":"28","t":"Kadın buna karşılık, \"Haklısın, Rab\" dedi. \"Ama köpekler de sofranın altında çocukların ekmek kırıntılarını yer.\""},{"n":"29","t":"İsa ona, \"Bu sözden ötürü cin kızından çıktı, gidebilirsin\" dedi."},{"n":"30","t":"Kadın evine gittiğinde çocuğunu cinden kurtulmuş, yatakta yatar buldu. Sağır Bir Adam İyileştiriliyor"},{"n":"31","t":"Sur bölgesinden ayrılan İsa, Sayda yoluyla Dekapolis bölgesinin ortasından geçerek tekrar Celile Gölü'ne geldi."},{"n":"32","t":"Ona sağır ve dili tutuk bir adam getirdiler, elini üzerine koyması için yalvardılar."},{"n":"33","t":"İsa adamı kalabalıktan ayırıp bir yana çekti. Parmaklarını adamın kulaklarına soktu, tükürüp onun diline dokundu."},{"n":"34","t":"Sonra göğe bakarak içini çekti ve adama, \"Effata\", yani \"Açıl!\" dedi."},{"n":"35","t":"Adamın kulakları hemen açıldı, dili çözüldü ve düzgün bir şekilde konuşmaya başladı."},{"n":"36","t":"İsa orada bulunanları, bunu kimseye söylememeleri için uyardı. Ama onları ne kadar uyardıysa, onlar da haberi o kadar yaydılar."},{"n":"37","t":"Halk büyük bir hayret içinde kalmıştı. \"Yaptığı her şey iyi. Sağırların kulaklarını açıyor, dilsizleri konuşturuyor!\" diyorlardı."}]},{"ch":8,"verses":[{"n":"1-2","t":"O günlerde yine büyük bir kalabalık toplanmıştı. Yiyecek bir şeyleri olmadığı için İsa öğrencilerini yanına çağırıp, \"Halka acıyorum\" dedi. \"Üç gündür yanımdalar, yiyecek hiçbir şeyleri yok."},{"n":"3","t":"Onları aç aç evlerine gönderirsem, yolda bayılırlar. Hem bazıları uzak yoldan geliyor.\""},{"n":"4","t":"Öğrencileri buna karşılık, \"Böyle ıssız bir yerde bu kadar kişiyi doyuracak ekmeği insan nereden bulabilir?\" dediler."},{"n":"5","t":"İsa, \"Kaç ekmeğiniz var?\" diye sordu. \"Yedi tane\" dediler."},{"n":"6","t":"Bunun üzerine İsa, halka yere oturmalarını buyurdu. Sonra yedi ekmeği aldı, şükredip bunları böldü, dağıtmaları için öğrencilerine verdi. Onlar da halka dağıttılar."},{"n":"7","t":"Birkaç küçük balıkları da vardı. İsa şükredip bunları da dağıtmalarını söyledi."},{"n":"8","t":"Herkes yiyip doydu. Artakalan parçalardan yedi küfe dolusu topladılar."},{"n":"9-10","t":"Orada yaklaşık dört bin kişi vardı. İsa onları evlerine gönderdikten sonra öğrencileriyle birlikte hemen tekneye binip Dalmanuta bölgesine geçti. Ferisiler'in ve Hirodes'in Mayası (Mat.16:1-12)"},{"n":"11","t":"Ferisiler* gelip İsa'yla tartışmaya başladılar. O'nu denemek amacıyla gökten bir belirti göstermesini istediler."},{"n":"12","t":"İsa içten bir ah çekerek, \"Bu kuşak neden bir belirti istiyor?\" dedi. \"Size doğrusunu söyleyeyim, bu kuşağa hiçbir belirti gösterilmeyecek.\""},{"n":"13","t":"Sonra onları orada bırakıp yine tekneye bindi ve karşı yakaya yöneldi."},{"n":"14","t":"Öğrenciler ekmek almayı unutmuşlardı. Teknede, yanlarında yalnız bir ekmek vardı."},{"n":"15","t":"İsa onlara şu uyarıda bulundu: \"Dikkatli olun, Ferisiler'in mayasından ve Hirodes'in* mayasından sakının!\""},{"n":"16","t":"Onlar ise kendi aralarında, \"Ekmeğimiz olmadığı için böyle diyor\" şeklinde tartıştılar."},{"n":"17","t":"Bunun farkında olan İsa, \"Ekmeğiniz yok diye niçin tartışıyorsunuz?\" dedi. \"Hâlâ akıl erdiremiyor, anlamıyor musunuz? Zihniniz köreldi mi?"},{"n":"18-19","t":"Gözleriniz olduğu halde görmüyor musunuz? Kulaklarınız olduğu halde işitmiyor musunuz? Hatırlamıyor musunuz, beş ekmeği beş bin kişiye bölüştürdüğümde kaç sepet dolusu yemek fazlası topladınız?\" \"On iki\" dediler."},{"n":"20","t":"\"Yedi ekmeği dört bin kişiye bölüştürdüğümde kaç küfe dolusu yemek fazlası topladınız?\" \"Yedi\" dediler."},{"n":"21","t":"İsa onlara, \"Hâlâ anlamıyor musunuz?\" dedi. Beytsayda'da Kör Bir Adam İyileştiriliyor"},{"n":"22","t":"İsa ile öğrencileri Beytsayda'ya geldiler. Orada bazı kişiler İsa'ya kör bir adam getirip ona dokunması için yalvardılar."},{"n":"23","t":"İsa körün elinden tutarak onu köyün dışına çıkardı. Gözlerine tükürüp ellerini üzerine koydu ve, \"Bir şey görüyor musun?\" diye sordu."},{"n":"24","t":"Adam başını kaldırıp, \"İnsanlar görüyorum\" dedi, \"Ağaçlara benziyorlar, ama yürüyorlar.\""},{"n":"25","t":"Sonra İsa ellerini yeniden adamın gözleri üzerine koydu. Adam gözlerini açtı, baktı; iyileşmiş ve her şeyi açık seçik görmeye başlamıştı."},{"n":"26","t":"İsa, \"Köye bile girme!\" diyerek onu evine gönderdi. Petrus'un Mesih'i Tanıması (Mat.16:13-20; Luk.9:18-21)"},{"n":"27","t":"İsa, öğrencileriyle birlikte Filipus Sezariyesi'ne bağlı köylere gitti. Yolda öğrencilerine, \"Halk benim kim olduğumu söylüyor?\" diye sordu."},{"n":"28","t":"Öğrencileri O'na şu karşılığı verdiler: \"Vaftizci Yahya diyorlar. Ama kimi İlyas, kimi de peygamberlerden biri olduğunu söylüyor.\""},{"n":"29","t":"O da onlara, \"Siz ne dersiniz, sizce ben kimim?\" diye sordu. Petrus, \"Sen Mesih'sin*\" yanıtını verdi."},{"n":"30","t":"Bunun üzerine İsa bu konuda kimseye bir şey söylememeleri için onları uyardı. İsa Ölüp Dirileceğini Önceden Bildiriyor (Mat.16:21-28; Luk.9:22-27)"},{"n":"31","t":"İsa, İnsanoğlu'nun* çok acı çekmesi, ileri gelenler, başkâhinler ve din bilginlerince* reddedilmesi, öldürülmesi ve üç gün sonra dirilmesi gerektiğini onlara anlatmaya başladı."},{"n":"32","t":"Bunları açıkça söylüyordu. Bunun üzerine Petrus O'nu bir kenara çekip azarlamaya başladı."},{"n":"33","t":"İsa dönüp öteki öğrencilerine baktı; Petrus'u azarlayarak, \"Çekil önümden, Şeytan!\" dedi. \"Düşüncelerin Tanrı'ya değil, insana özgüdür.\""},{"n":"34","t":"Öğrencileriyle birlikte halkı da yanına çağırıp şöyle konuştu: \"Ardımdan gelmek isteyen kendini inkâr etsin, çarmıhını yüklenip beni izlesin."},{"n":"35","t":"Canını kurtarmak isteyen onu yitirecek, canını benim ve Müjde'nin uğruna yitiren ise onu kurtaracaktır."},{"n":"36","t":"İnsan bütün dünyayı kazanıp da canından olursa, bunun kendisine ne yararı olur?"},{"n":"37","t":"İnsan kendi canına karşılık ne verebilir?"},{"n":"38","t":"Bu vefasız ve günahkâr kuşağın ortasında, kim benden ve benim sözlerimden utanırsa, İnsanoğlu da, Babası'nın görkemi içinde kutsal meleklerle birlikte geldiğinde o kişiden utanacaktır.\""}]},{"ch":9,"verses":[{"n":"1","t":"İsa, \"Size doğrusunu söyleyeyim\" diye devam etti, \"Burada bulunanlar arasında, Tanrı Egemenliği'nin güçlü biçimde gerçekleştiğini görmeden ölümü tatmayacak olanlar var.\" İsa'nın Görünümü Değişiyor (Mat.17:1-13; Luk.9:28-36)"},{"n":"2","t":"Altı gün sonra İsa, yanına yalnız Petrus, Yakup ve Yuhanna'yı alarak yüksek bir dağa çıktı. Onların gözü önünde İsa'nın görünümü değişti."},{"n":"3","t":"Giysileri göz kamaştırıcı bir beyazlığa büründü; yeryüzünde hiçbir çamaşırcının erişemeyeceği bir beyazlıktı bu."},{"n":"4","t":"O anda Musa'yla İlyas öğrencilere göründü. İsa'yla konuşuyorlardı."},{"n":"5","t":"Petrus İsa'ya, \"Rabbî*, burada bulunmamız ne iyi oldu! Üç çardak kuralım: Biri sana, biri Musa'ya, biri de İlyas'a\" dedi."},{"n":"6","t":"Ne söyleyeceğini bilmiyordu. Çünkü çok korkmuşlardı."},{"n":"7","t":"Bu sırada bir bulut gelip onlara gölge saldı. Buluttan gelen bir ses, \"Sevgili Oğlum budur, O'nu dinleyin!\" dedi."},{"n":"8","t":"Öğrenciler birden çevrelerine baktılar, ama bu kez yanlarında İsa'dan başka kimseyi göremediler."},{"n":"9","t":"Dağdan inerlerken İsa, İnsanoğlu* ölümden dirilmeden orada gördüklerini hiç kimseye söylememeleri için onları uyardı."},{"n":"10","t":"Bu uyarıya uymakla birlikte kendi aralarında, \"Ölümden dirilmek ne demek?\"diye tartışıp durdular."},{"n":"11","t":"İsa'ya, \"Din bilginleri* neden önce İlyas'ın gelmesi gerektiğini söylüyorlar?\" diye sordular."},{"n":"12","t":"O da onlara şöyle dedi: \"Gerçekten de önce İlyas gelir ve her şeyi yeniden düzene koyar. Ama nasıl oluyor da İnsanoğlu'nun çok acı çekeceği ve hiçe sayılacağı yazılmıştır?"},{"n":"13","t":"Size şunu söyleyeyim, İlyas geldi bile, onun hakkında yazılmış olduğu gibi, ona yapmadıklarını bırakmadılar.\" Cinli Bir Çocuğun İyileştirilmesi (Mat.17:14-23; Luk.9:37-45)"},{"n":"14","t":"Öteki öğrencilerin yanına döndüklerinde, onların çevresinde büyük bir kalabalığın toplandığını, birtakım din bilginlerinin onlarla tartıştığını gördüler."},{"n":"15","t":"Kalabalık İsa'yı görünce büyük bir şaşkınlığa kapıldı ve koşup O'nu selamladı."},{"n":"16","t":"İsa öğrencilerine, \"Onlarla ne tartışıyorsunuz?\" diye sordu."},{"n":"17","t":"Halktan biri O'na, \"Öğretmenim\" diye karşılık verdi, \"Dilsiz bir ruha tutulan oğlumu sana getirdim."},{"n":"18","t":"Ruh onu nerede yakalarsa yere çarpıyor. Çocuk ağzından köpükler saçıyor, dişlerini gıcırdatıyor ve kaskatı kesiliyor. Ruhu kovmaları için öğrencilerine başvurdum, ama başaramadılar.\""},{"n":"19","t":"İsa onlara, \"Ey imansız kuşak!\" dedi. \"Sizinle daha ne kadar kalacağım? Size daha ne kadar katlanacağım? Çocuğu bana getirin!\""},{"n":"20","t":"Çocuğu kendisine getirdiler. Ruh, İsa'yı görür görmez çocuğu şiddetle sarstı; çocuk yere düştü, ağzından köpükler saçarak yuvarlanmaya başladı."},{"n":"21","t":"İsa çocuğun babasına, \"Bu hal çocuğun başına geleli ne kadar oldu?\" diye sordu. \"Küçüklüğünden beri böyle\" dedi babası."},{"n":"22","t":"\"Üstelik ruh onu öldürmek için sık sık ateşe, suya attı. Elinden bir şey gelirse, bize yardım et, halimize acı!\""},{"n":"23","t":"İsa ona, \"Elimden gelirse mi? İman eden biri için her şey mümkün!\" dedi."},{"n":"24","t":"Çocuğun babası hemen, \"İman ediyorum, imansızlığımı yenmeme yardım et!\"diye feryat etti."},{"n":"25","t":"İsa, halkın koşuşup geldiğini görünce kötü ruhu azarlayarak, \"Sana buyuruyorum, dilsiz ve sağır ruh, çocuğun içinden çık ve ona bir daha girme!\" dedi."},{"n":"26","t":"Bunun üzerine ruh bir çığlık attı ve çocuğu şiddetle sarsarak çıktı. Çocuk ölü gibi hareketsiz kaldı, öyle ki oradakilerin birçoğu, \"Öldü!\" diyordu."},{"n":"27","t":"Ama İsa elinden tutup kaldırınca, çocuk ayağa kalktı."},{"n":"28","t":"İsa eve girdikten sonra öğrencileri özel olarak O'na, \"Biz kötü ruhu neden kovamadık?\" diye sordular."},{"n":"29","t":"İsa onlara, \"Bu tür ruhlar ancak duayla*fx* kovulabilir\" yanıtını verdi. İsa Ölüp Dirileceğini Tekrar Bildiriyor (Mat.17:22-23; Luk.9:43-45)"},{"n":"30","t":"Oradan ayrılmış, Celile bölgesinden geçiyorlardı. İsa hiç kimsenin bunu bilmesini istemiyordu."},{"n":"31","t":"Öğrencilerine öğretirken şöyle diyordu: \"İnsanoğlu*, insanların eline teslim edilecek ve öldürülecek, ama öldürüldükten üç gün sonra dirilecek.\""},{"n":"32","t":"Onlar bu sözleri anlamıyor, İsa'ya soru sormaktan da korkuyorlardı. En Büyük Kim? (Mat.18:1-5; Luk.9:46-48)"},{"n":"33","t":"Kefarnahum'a vardılar. Eve girdikten sonra İsa onlara, \"Yolda neyi tartışıyordunuz?\" diye sordu."},{"n":"34","t":"Hiç birinden ses çıkmadı. Çünkü yolda aralarında kimin en büyük olduğunu tartışmışlardı."},{"n":"35","t":"İsa oturup Onikiler'i* yanına çağırdı. Onlara şöyle dedi: \"Birinci olmak isteyen en sonuncu olsun, herkesin hizmetkârı olsun.\""},{"n":"36-37","t":"Küçük bir çocuğu alıp orta yere dikti, sonra onu kucağına alarak onlara şöyle dedi: \"Böyle bir çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni değil, beni göndereni kabul etmiş olur.\" Bize Karşı Olmayan Bizden Yanadır (Luk.9:49-50)"},{"n":"38","t":"Yuhanna O'na, \"Öğretmenim\" dedi, \"Senin adınla cin kovan birini gördük, ama bizi izleyenlerden olmadığı için ona engel olmaya çalıştık.\""},{"n":"39","t":"\"Ona engel olmayın!\" dedi İsa. \"Çünkü benim adımla mucize yapıp da ardından beni kötüleyecek kimse yoktur."},{"n":"40","t":"Bize karşı olmayan, bizden yanadır."},{"n":"41","t":"Size doğrusunu söyleyeyim, Mesih'e ait olduğunuz için sizlere bir bardak su veren ödülsüz kalmayacaktır.\" Birini Günaha Sokmanın Cezası (Mat.18:6-9; Luk.17:1-2)"},{"n":"42","t":"\"Kim bana iman eden bu küçüklerden birini günaha düşürürse, boynuna kocamanbir değirmen taşı geçirilip denize atılması kendisi için daha iyi olur."},{"n":"43-44","t":"Eğer elin günah işlemene neden olursa, onu kes. Tek elle yaşama kavuşman, iki elle sönmez ateşe, cehenneme gitmenden iyidir."},{"n":"45-46","t":"Eğer ayağın günah işlemene neden olursa, onu kes. Tek ayakla yaşama kavuşman, iki ayakla cehenneme atılmandan iyidir."},{"n":"47","t":"Eğer gözün günah işlemene neden olursa, onu çıkar at. Tanrı'nın Egemenliği'ne tek gözle girmen, iki gözle cehenneme atılmandan iyidir."},{"n":"48","t":"'Oradakileri kemiren kurt ölmez, Yakan ateş sönmez.'*fx*"},{"n":"49","t":"Çünkü herkes ateşle tuzlanacaktır."},{"n":"50","t":"Tuz yararlıdır. Ama tuz tuzluluğunu yitirirse, bir daha ona nasıl tat verebilirsiniz? İçinizde tuz olsun ve birbirinizle barış içinde yaşayın!\""}]},{"ch":10,"verses":[{"n":"1","t":"İsa oradan ayrılıp Yahudiye'nin* Şeria Irmağı'nın karşı yakasındaki topraklarına geçti. Çevresinde yine kalabalıklar toplanmıştı; her zamanki gibi onlara öğretiyordu."},{"n":"2","t":"Yanına gelen bazı Ferisiler O'nu denemek amacıyla, \"Bir erkeğin, karısını boşaması Kutsal Yasa'ya uygun mudur?\" diye sordular."},{"n":"3","t":"İsa karşılık olarak, \"Musa size ne buyurdu?\" dedi."},{"n":"4","t":"Onlar, \"Musa, erkeğin bir boşanma belgesi yazarak karısını boşamasına izin vermiştir\" dediler."},{"n":"5","t":"İsa onlara, \"İnatçı olduğunuz için Musa bu buyruğu yazdı\" dedi."},{"n":"6","t":"\"Tanrı, yaratılışın başlangıcından 'İnsanları erkek ve dişi olarak yarattı.'"},{"n":"7-8","t":"'Bu nedenle adam annesini babasını bırakıp karısına bağlanacak, ikisi tek beden olacak.' Şöyle ki, onlar artık iki değil, tek bedendir."},{"n":"9","t":"O halde Tanrı'nın birleştirdiğini insan ayırmasın.\""},{"n":"10","t":"Öğrencileri evde O'na yine bu konuyla ilgili bazı sorular sordular."},{"n":"11","t":"İsa onlara, \"Karısını boşayıp başkasıyla evlenen, karısına karşı zina etmiş olur\" dedi."},{"n":"12","t":"\"Kocasını boşayıp başkasıyla evlenen kadın da zina etmiş olur.\" İsa Küçük Çocukları Kutsuyor (Mat.19:13-15; Luk.18:15-17)"},{"n":"13","t":"Bu arada bazıları küçük çocukları İsa'nın yanına getiriyor, onlara dokunmasını istiyorlardı. Ne var ki, öğrenciler onları azarladılar."},{"n":"14","t":"İsa bunu görünce kızdı. Öğrencilerine, \"Bırakın, çocuklar bana gelsin\" dedi. \"Onlara engel olmayın! Çünkü Tanrı'nın Egemenliği böylelerinindir."},{"n":"15","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliği'ni bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.\""},{"n":"16","t":"Çocukları kucağına aldı, ellerini üzerlerine koyup onları kutsadı. Zenginlik ve Sonsuz Yaşam (Mat.19:16-30; Luk.18:18-30)"},{"n":"17","t":"İsa yola çıkarken, biri koşarak yanına geldi. Önünde diz çöküp O'na, \"İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?\" diye sordu."},{"n":"18","t":"İsa, \"Bana neden iyi diyorsun?\" dedi. \"İyi olan yalnız biri var, O da Tanrı'dır."},{"n":"19","t":"O'nun buyruklarını biliyorsun: 'Adam öldürmeyeceksin, zina etmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, kimsenin hakkını yemeyeceksin, annene babana saygı göstereceksin.'\""},{"n":"20","t":"Adam, \"Öğretmenim, bunların hepsini gençliğimden beri yerine getiriyorum dedi."},{"n":"21","t":"Ona sevgiyle bakan İsa, \"Bir eksiğin var\" dedi. \"Git neyin varsa sat, parasını yoksullara ver; böylece gökte hazinen olur. Sonra gel, beni izle.\""},{"n":"22","t":"Bu sözler üzerine adamın yüzü asıldı, üzüntü içinde oradan uzaklaştı. Çünkü çok malı vardı."},{"n":"23","t":"İsa çevresine göz gezdirdikten sonra öğrencilerine, \"Varlıklı kişilerin Tanrı Egemenliği'ne girmesi ne güç olacak!\" dedi."},{"n":"24","t":"Öğrenciler O'nun sözlerine şaştılar. Ama İsa onlara yine, \"Çocuklar\" dedi, \"Tanrı'nın Egemenliği'ne girmek ne güçtür!"},{"n":"25","t":"Devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliği'ne girmesinden daha kolaydır.\""},{"n":"26","t":"Öğrenciler büsbütün şaşırmışlardı. Birbirlerine, \"Öyleyse kim kurtulabilir?\" diyorlardı."},{"n":"27","t":"İsa onlara bakarak, \"İnsanlar için bu imkânsız, ama Tanrı için değil. Tanrı için her şey mümkündür\" dedi."},{"n":"28","t":"Petrus O'na, \"Bak, biz her şeyi bırakıp senin ardından geldik\" demeye başladı."},{"n":"29-30","t":"\"Size doğrusunu söyleyeyim\" dedi İsa, \"Benim ve Müjde'nin uğruna evini,kardeşlerini, anne ya da babasını, çocuklarını ya da topraklarını bırakıp da şimdi, bu çağda çekeceği zulümlerle birlikte yüz kat daha fazla eve, kardeşe, anneye, çocuğa, toprağa ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur."},{"n":"31","t":"Ne var ki, birincilerin birçoğu sonuncu, sonuncuların birçoğu da birinci olacak.\" İsa Ölüp Dirileceğini Üçüncü Kez Bildiriyor (Mat.20:17-19; Luk.18:31-34)"},{"n":"32-33","t":"Yola çıkmış Yeruşalim'e gidiyorlardı. İsa önlerinde yürüyordu. Öğrencileri şaşkınlık içindeydi, ardından gelenler ise korkuyorlardı. İsa Onikiler'i* yine bir yana çekip kendi başına gelecekleri anlatmaya başladı: \"Şimdi Yeruşalim'e gidiyoruz\" dedi. \"İnsanoğlu*, başkâhinlerin ve din bilginlerinin eline teslim edilecek. Onlar da O'nu ölüm cezasına çarptıracak ve öteki uluslara teslim edecekler."},{"n":"34","t":"O'nunla alay edecek, üzerine tükürecek ve O'nu kamçılayıp öldürecekler. Ne var ki O, üç gün sonra dirilecek.\" Yakup'la Yuhanna'nın Dileği (Mat.20:20-28)"},{"n":"35","t":"Zebedi'nin oğulları Yakup ile Yuhanna İsa'ya yaklaşıp, \"Öğretmenimiz, bir dileğimiz var, bunu yapmanı istiyoruz\" dediler."},{"n":"36","t":"İsa onlara, \"Sizin için ne yapmamı istiyorsunuz?\" diye sordu."},{"n":"37","t":"\"Sen yüceliğine kavuşunca birimize sağında, ötekimize de solunda oturma ayrıcalığını ver\" dediler."},{"n":"38","t":"\"Siz ne dilediğinizi bilmiyorsunuz\" dedi İsa. \"Benim içeceğim kâseden siz içebilir misiniz? Benim vaftiz olacağım gibi siz de vaftiz olabilir misiniz?\"*fx*"},{"n":"39-40","t":"\"Evet, olabiliriz\" dediler. İsa onlara, \"Benim içeceğim kâseden siz de içeceksiniz, benim vaftiz olacağım gibi siz de vaftiz olacaksınız\" dedi. \"Ama sağımda ya da solumda oturmanıza izin vermek benim elimde değil. Bu yerler belirli kişiler için hazırlanmıştır.\""},{"n":"41","t":"Bunu işiten on öğrenci Yakup'la Yuhanna'ya kızmaya başladılar."},{"n":"42","t":"İsa onları yanına çağırıp şöyle dedi: \"Bilirsiniz ki, ulusların önderleri sayılanlar, onlara egemen kesilir, ileri gelenleri de onlara ağırlıklarını hissettirirler."},{"n":"43","t":"Sizin aranızda böyle olmayacak. Aranızda büyük olmak isteyen, ötekilerin hizmetkârı olsun."},{"n":"44","t":"Aranızda birinci olmak isteyen, hepinizin kulu olsun."},{"n":"45","t":"Çünkü İnsanoğlu bile hizmet edilmeye değil, hizmet etmeye ve canını birçokları için fidye olarak vermeye geldi.\" Kör Bartimay'ın Gözleri Açılıyor (Mat.20:29-34; Luk.18:35-43)"},{"n":"46","t":"Sonra Eriha'ya geldiler. İsa, öğrencileri ve büyük bir kalabalıkla birlikte Eriha'dan ayrılırken, Timay oğlu Bartimay adında kör bir dilenci yol kenarında oturuyordu ."},{"n":"47","t":"Nasıralı İsa'nın orada olduğunu duyunca, \"Ey Davut Oğlu İsa, halime acı!\" diye bağırmaya başladı."},{"n":"48","t":"Birçok kimse onu azarlayarak susturmak istediyse de o, \"Ey Davut Oğlu, halime acı!\" diyerek daha çok bağırdı."},{"n":"49","t":"İsa durdu, \"Çağırın onu\" dedi. Kör adama seslenerek, \"Ne mutlu sana! Kalk, seni çağırıyor!\" dediler."},{"n":"50","t":"Adam abasını üstünden atarak ayağa fırladı ve İsa'nın yanına geldi."},{"n":"51","t":"İsa, \"Senin için ne yapmamı istiyorsun?\" diye sordu. Kör adam, \"Rabbuni*fx*, gözlerim görsün\" dedi."},{"n":"52","t":"İsa, \"Gidebilirsin, imanın seni kurtardı\" dedi. Adam o anda yeniden görmeyebaşladı ve yol boyunca İsa'nın ardından gitti."}]},{"ch":11,"verses":[{"n":"1-2","t":"Yeruşalim'e yaklaşıp Zeytin Dağı'nın yamacındaki Beytfaci ile Beytanya'ya geldiklerinde İsa iki öğrencisini önden gönderdi. Onlara, \"Karşınızdaki köye gidin\" dedi, \"Köye girer girmez, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin."},{"n":"3","t":"Biri size, 'Bunu niye yapıyorsunuz?' derse, 'Rab'bin ona ihtiyacı var, hemen geri gönderecek' dersiniz.\""},{"n":"4","t":"Gittiler ve yol üzerinde, bir evin sokak kapısının yanında bağlı buldukları sıpayı çözdüler."},{"n":"5","t":"Orada duranlardan bazıları, \"Sıpayı ne diye çözüyorsunuz?\" dediler."},{"n":"6","t":"Öğrenciler İsa'nın kendilerine söylediklerini tekrarlayınca, adamlar onları rahat bıraktı."},{"n":"7","t":"Sıpayı İsa'ya getirip üzerine kendi giysilerini yaydılar. İsa sıpaya bindi."},{"n":"8","t":"Birçokları giysilerini, bazıları da çevredeki ağaçlardan kestikleri dalları yola serdiler."},{"n":"9","t":"Önden gidenler ve arkadan gelenler şöyle bağırıyorlardı: \"Hozana*! Rab'bin adıyla gelene övgüler olsun!"},{"n":"10","t":"Atamız Davut'un yaklaşan egemenliği kutlu olsun! En yücelerde hozana!\""},{"n":"11","t":"İsa Yeruşalim'e varınca tapınağa gitti, her tarafı gözden geçirdi. Sonra vakit ilerlemiş olduğundan Onikiler'le* birlikte Beytanya'ya döndü. Meyvesiz İncir Ağacı (Mat.21:18-19)"},{"n":"12","t":"Ertesi gün Beytanya'dan çıktıklarında İsa acıkmıştı."},{"n":"13","t":"Uzakta, yapraklanmış bir incir ağacı görünce belki incir bulurum diye yaklaştı. Ağacın yanına vardığında yapraktan başka bir şey bulamadı. Çünkü incir mevsimi değildi."},{"n":"14","t":"İsa ağaca, \"Artık sonsuza dek senden kimse meyve yiyemesin!\" dedi. Öğrencileri de bunu duydular. İsa Satıcıları Tapınaktan Kovuyor (Mat.21:12-17; Luk.19:45-48; Yu.2:13-22)"},{"n":"15","t":"Oradan Yeruşalim'e geldiler. İsa tapınağın avlusuna girerek oradaki alıcı ve satıcıları dışarı kovdu. Para bozanların* masalarını, güvercin satanların sehpalarını devirdi."},{"n":"16","t":"Yük taşıyan hiç kimsenin tapınağın avlusundan geçmesine izin vermedi."},{"n":"17","t":"Halka öğretirken şunları söyledi: \"'Evime, bütün ulusların dua evi denecek' diye yazılmamış mı? Ama siz onu haydut inine çevirdiniz.\""},{"n":"18","t":"Başkâhinler ve din bilginleri bunu duyunca İsa'yı yok etmek için bir yol aramaya başladılar. O'ndan korkuyorlardı. Çünkü bütün halk O'nun öğretisine hayrandı."},{"n":"19","t":"Akşam olunca İsa'yla öğrencileri kentten ayrıldı. İncir Ağacından Alınacak Ders (Mat.21:20-22)"},{"n":"20","t":"Sabah erkenden incir ağacının yanından geçerlerken, ağacın kökten kurumuş olduğunu gördüler."},{"n":"21","t":"Olayı hatırlayan Petrus, \"Rabbî*, bak! Lanetlediğin incir ağacı kurumuş!\" dedi."},{"n":"22","t":"İsa onlara şöyle karşılık verdi: \"Tanrı'ya iman edin."},{"n":"23","t":"Size doğrusunu söyleyeyim, kim şu dağa, 'Kalk, denize atıl!' der ve yüreğinde kuşku duymadan dediğinin olacağına inanırsa, dileği yerine gelecektir."},{"n":"24","t":"Bunun için size diyorum ki, duayla dilediğiniz her şeyi daha şimdiden almış olduğunuza inanın, dileğiniz yerine gelecektir."},{"n":"25-26","t":"Kalkıp dua ettiğiniz zaman, birine karşı bir şikâyetiniz varsa onu bağışlayın ki, göklerdeki Babanız da sizin suçlarınızı bağışlasın.\"*fx* İsa'nın Yetkisi (Mat.21:23-27; Luk.20:1-8)"},{"n":"27-28","t":"Yine Yeruşalim'e geldiler. İsa tapınakta gezinirken başkâhinler, din bilginleri* ve ileri gelenler O'nun yanına gelip, \"Bunları hangi yetkiyle yapıyorsun, bunları yapma yetkisini sana kim verdi?\" diye sordular."},{"n":"29","t":"İsa da onlara, \"Size bir soru soracağım\" dedi. \"Bana yanıt verin, ben de size bunları hangi yetkiyle yaptığımı söylerim."},{"n":"30","t":"Yahya'nın vaftiz etme yetkisi Tanrı'dan*fx* mıydı, insanlardan mı? Yanıt verin bana.\""},{"n":"31","t":"Bunu aralarında şöyle tartışmaya başladılar: \"'Tanrı'dan' dersek, 'Öyleyse ona niçin inanmadınız?' diyecek."},{"n":"32","t":"Yok eğer 'İnsanlardan' dersek...\" Halkın tepkisinden korkuyorlardı. Çünkü herkes Yahya'yı gerçekten peygamber sayıyordu."},{"n":"33","t":"İsa'ya, \"Bilmiyoruz\" diye yanıt verdiler. İsa da onlara, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi."}]},{"ch":12,"verses":[{"n":"1","t":"İsa onlara benzetmelerle konuşmaya başladı. \"Adamın biri bağ dikti, çevresini çitle çevirdi, üzüm sıkmak için bir çukur kazdı, bir de bekçi kulesi yaptı. Sonra bağı bağcılara kiralayıp yolculuğa çıktı."},{"n":"2","t":"Mevsimi gelince bağın ürününden payına düşeni almak üzere bağcılara bir köle yolladı."},{"n":"3","t":"Bağcılar köleyi yakalayıp dövdü ve eli boş gönderdi."},{"n":"4","t":"Bağ sahibi bu kez onlara başka bir köle yolladı. Onu da başından yaralayıp aşağıladılar."},{"n":"5","t":"Birini daha yolladı, onu öldürdüler. Daha birçok köle yolladı. Kimini dövüp kimini öldürdüler."},{"n":"6","t":"\"Bağ sahibinin yanında tek kişi kaldı, o da sevgili oğluydu. 'Oğlumu sayarlar' diyerek bağcılara en son onu yolladı."},{"n":"7","t":"\"Ama bağcılar birbirlerine, 'Mirasçı budur, gelin onu öldürelim, miras bizim olur' dediler."},{"n":"8","t":"Böylece onu yakaladılar, öldürüp bağdan dışarı attılar."},{"n":"9","t":"\"Bu durumda bağın sahibi ne yapacak? Gelip bağcıları yok edecek, bağı da başkalarına verecek."},{"n":"10-11","t":"Şu Kutsal Yazı'yı okumadınız mı?'Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu. Rab'bin işidir bu, Gözümüzde harika bir iş!'\""},{"n":"12","t":"İsa'nın bu benzetmede kendilerinden söz ettiğini anlayan Yahudi önderler O'nu tutuklamak istediler; ama halkın tepkisinden korktukları için O'nu bırakıp gittiler. Sezar'ın Hakkı Sezar'a (Mat.22:15-22; Luk.20:20-26)"},{"n":"13","t":"Daha sonra İsa'yı söyleyeceği sözlerle tuzağa düşürmek amacıyla Ferisiler'den ve Hirodes yanlılarından bazılarını O'na gönderdiler."},{"n":"14","t":"Bunlar gelip İsa'ya, \"Öğretmenimiz\" dediler, \"Senin dürüst biri olduğunu, kimseyi kayırmadan, insanlar arasında ayrım yapmadan Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezar'a* vergi vermek Kutsal Yasa'ya uygun mu, değil mi? Verelim mi, vermeyelim mi?\""},{"n":"15","t":"Onların ikiyüzlülüğünü bilen İsa şöyle dedi: \"Beni neden deniyorsunuz? Bana bir dinar getirin bakayım.\""},{"n":"16","t":"Parayı getirdiler. İsa, \"Bu resim, bu yazı kimin?\" diye sordu. \"Sezar'ın\" dediler."},{"n":"17","t":"İsa da, \"Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını Tanrı'ya verin\" dedi. İsa'nın sözlerine şaşakaldılar. Dirilişle İlgili Soru (Mat.22:23-33; Luk.20:27-40)"},{"n":"18-19","t":"Ölümden sonra diriliş olmadığını söyleyen Sadukiler İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: 'Eğer bir adam ölür, geride bir dul bırakır, ama çocuk bırakmazsa, kardeşi onun karısını alıp soyunu sürdürsün.'"},{"n":"20","t":"Yedi kardeş vardı. Birincisi evlendi ve çocuk bırakmadan öldü."},{"n":"21","t":"İkincisi aynı kadını aldı, o da çocuk sahibi olmadan öldü. Üçüncüsüne de öyle oldu."},{"n":"22","t":"Yedisi de çocuksuz öldü. Hepsinden sonra kadın da öldü."},{"n":"23","t":"Diriliş günü, ölümden dirildiklerinde kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.\""},{"n":"24","t":"İsa onlara şöyle karşılık verdi: \"Ne Kutsal Yazılar'ı ne de Tanrı'nın gücünü biliyorsunuz. Yanılmanızın nedeni de bu değil mi?"},{"n":"25","t":"İnsanlar ölümden dirilince ne evlenir ne evlendirilir, göklerdeki melekler gibidirler."},{"n":"26","t":"Ölülerin dirilmesi konusuna gelince, Musa'nın Kitabı'nda, alevlenen çalıyla ilgili bölümde Tanrı'nın Musa'ya söylediklerini okumadınız mı? 'Ben İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısı'yım' diyor."},{"n":"27","t":"Tanrı ölülerin değil, dirilerin Tanrısı'dır. Siz büyük bir yanılgı içindesiniz.\" En Büyük Buyruk (Mat.22:34-40; Luk.10:25-28)"},{"n":"28","t":"Onların tartışmalarını dinleyen ve İsa'nın onlara güzel yanıt verdiğini gören bir din bilgini* yaklaşıp O'na, \"Buyrukların en önemlisi hangisidir?\" diye sordu."},{"n":"29","t":"İsa şöyle karşılık verdi: \"En önemlisi şudur: 'Dinle, ey İsrail! Tanrımız Rab tek Rab'dir."},{"n":"30","t":"Tanrın Rab'bi bütün yüreğinle, bütün canınla, bütün aklınla ve bütün gücünle seveceksin.'"},{"n":"31","t":"İkincisi de şudur: 'Komşunu kendin gibi seveceksin.' Bunlardan daha büyük buyruk yoktur.\""},{"n":"32","t":"Din bilgini İsa'ya, \"İyi söyledin, öğretmenim\" dedi. \"'Tanrı tektir ve O'ndan başkası yoktur' demekle doğruyu söyledin."},{"n":"33","t":"İnsanın Tanrı'yı bütün yüreğiyle, bütün anlayışıyla ve bütün gücüyle sevmesi, komşusunu da kendi gibi sevmesi, bütün yakmalık sunulardan* ve kurbanlardan daha önemlidir.\""},{"n":"34","t":"İsa onun akıllıca yanıt verdiğini görünce, \"Sen Tanrı'nın Egemenliği'nden uzak değilsin\" dedi. Bundan sonra kimse O'na soru sormaya cesaret edemedi. Mesih Kimin Oğlu? (Mat.22:41-46; Luk.20:41-44)"},{"n":"35","t":"İsa tapınakta öğretirken şunu sordu: \"Nasıl oluyor da din bilginleri, 'Mesih*, Davut'un Oğlu'dur' diyorlar?"},{"n":"36","t":"Davut'un kendisi, Kutsal Ruh'tan esinlenerek şöyle demişti: Rab Rabbim'e dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek Sağımda otur.'"},{"n":"37","t":"Davut'un kendisi O'ndan Rab diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\" Oradaki büyük kalabalık O'nu zevkle dinliyordu. İsa İkiyüzlü Din Bilginlerini Kınıyor (Mat.23:1-36; Luk.20:45-47)"},{"n":"38-39","t":"İsa öğretirken şöyle dedi: \"Uzun kaftanlar içinde dolaşmaktan, meydanlarda selamlanmaktan, havralarda en seçkin yerlere ve şölenlerde başköşelere kurulmaktan hoşlanan din bilginlerinden sakının."},{"n":"40","t":"Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha ağır olacaktır.\" Dul Kadının Bağışı (Luk.21:1-4)"},{"n":"41","t":"İsa tapınakta bağış toplanan yerin karşısında oturmuş, kutulara para atan halkı seyrediyordu. Birçok zengin kişi kutuya bol para attı."},{"n":"42","t":"Yoksul bir dul kadın da geldi, birkaç kuruş değerinde iki bakır para*fx* attı."},{"n":"43","t":"İsa öğrencilerini yanına çağırarak, \"Size doğrusunu söyleyeyim\" dedi, \"Bu yoksul dul kadın kutuya herkesten daha çok para attı."},{"n":"44","t":"Çünkü ötekilerin hepsi, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna karşın, varını yoğunu, geçinmek için elinde ne varsa, tümünü verdi.\""}]},{"ch":13,"verses":[{"n":"1","t":"İsa tapınaktan çıkarken öğrencilerinden biri O'na, \"Öğretmenim\" dedi, \"Şu güzel taşlara, şu görkemli yapılara bak!\""},{"n":"2","t":"İsa ona, \"Bu büyük yapıları görüyor musun? Burada taş üstünde taş kalmayacak, hepsi yıkılacak!\" dedi."},{"n":"3-4","t":"İsa, Zeytin Dağı'nda, tapınağın karşısında otururken Petrus, Yakup, Yuhanna ve Andreas özel olarak kendisine şunu sordular: \"Söyle bize, bu dediklerin ne zaman olacak, bütün bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?\""},{"n":"5","t":"İsa onlara anlatmaya başladı: \"Sakın kimse sizi saptırmasın\" dedi."},{"n":"6","t":"\"Birçokları, 'Ben O'yum' diyerek benim adımla gelip birçok kişiyi saptıracaklar."},{"n":"7","t":"Savaş gürültüleri, savaş haberleri duyunca korkmayın. Bunların olması gerek,ama bu daha son demek değildir."},{"n":"8","t":"Ulus ulusa, devlet devlete savaş açacak; yer yer depremler, kıtlıklar olacak. Bunlar, doğum sancılarının başlangıcıdır."},{"n":"9","t":"\"Ama siz kendinize dikkat edin! İnsanlar sizi mahkemelere verecek, havralarda dövecekler. Benden ötürü valilerin, kralların önüne çıkarılacak, böylece onlara tanıklık edeceksiniz."},{"n":"10","t":"Ne var ki, önce Müjde'nin bütün uluslara duyurulması gerekir."},{"n":"11","t":"Sizi tutuklayıp mahkemeye verdiklerinde, 'Ne söyleyeceğiz?' diye önceden kaygılanmayın. O anda size ne esinlenirse onu söyleyin. Çünkü konuşan siz değil, Kutsal Ruh olacak."},{"n":"12","t":"Kardeş kardeşi, baba çocuğunu ölüme teslim edecek. Çocuklar anne babalarına başkaldırıp onları öldürtecek."},{"n":"13","t":"Benim adımdan ötürü herkes sizden nefret edecek. Ama sonuna kadar dayanan kurtulacaktır."},{"n":"14","t":"\"Yıkıcı iğrenç şeyin*, bulunmaması gereken yerde dikildiğini gördüğünüz zaman -okuyan anlasın- Yahudiye'de bulunanlar dağlara kaçsın."},{"n":"15","t":"Damda olan, evinden bir şey almak için aşağı inmesin, içeri girmesin."},{"n":"16","t":"Tarlada olan, abasını almak için geri dönmesin."},{"n":"17","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline!"},{"n":"18","t":"Dua edin ki, kaçışınız kışa rastlamasın."},{"n":"19","t":"Çünkü o günlerde öyle bir sıkıntı olacak ki, Tanrı'nın var ettiği yaratılışın başlangıcından bu yana böylesi olmamış, bundan sonra da olmayacaktır."},{"n":"20","t":"Rab o günleri kısaltmamış olsaydı, hiç kimse kurtulamazdı. Ama Rab, seçilmiş olanlar, kendi seçtiği kişiler uğruna o günleri kısaltmıştır."},{"n":"21","t":"Eğer o zaman biri size, 'İşte Mesih* burada', ya da, 'İşte şurada' derse, inanmayın."},{"n":"22","t":"Çünkü sahte mesihler, sahte peygamberler türeyecek; bunlar, belirtiler ve harikalar yapacaklar. Öyle ki, ellerinden gelse seçilmiş olanları saptıracaklar."},{"n":"23","t":"Ama siz dikkatli olun. İşte size her şeyi önceden söylüyorum.\" Mesih'in Tekrar Gelişi (Mat.24:29-35; Luk.21:25-33)"},{"n":"24-25","t":"\"Ama o günlerde, o sıkıntıdan sonra, 'Güneş kararacak, Ay ışık vermez olacak, Yıldızlar gökten düşecek, Göksel güçler sarsılacak.'"},{"n":"26","t":"\"O zaman İnsanoğlu'nun* bulutlar içinde büyük güç ve görkemle geldiğini görecekler."},{"n":"27","t":"İnsanoğlu o zaman meleklerini gönderecek, seçtiklerini yeryüzünün bir ucundan göğün öbür ucuna dek, dünyanın dört bucağından toplayacak."},{"n":"28","t":"\"İncir ağacından ders alın. Dalları filizlenip yaprakları sürünce, yaz mevsiminin yakın olduğunu anlarsınız."},{"n":"29","t":"Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki İnsanoğlu yakındır, kapıdadır."},{"n":"30","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan bu kuşak*fx* ortadan kalkmayacak."},{"n":"31","t":"Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır.\" Bilinmeyen Gün ve Saat (Mat.24:36-44)"},{"n":"32","t":"\"O günü ve o saati, ne gökteki melekler, ne de Oğul bilir; Baba'dan başka kimse bilmez."},{"n":"33","t":"Dikkat edin, uyanık kalın, dua edin. Çünkü o anın ne zaman geleceğini bilemezsiniz."},{"n":"34","t":"Bu, yolculuğa çıkan bir adamın durumuna benzer. Evinden ayrılırken kölelerine yetki ve görev verir, kapıdaki nöbetçiye de uyanık kalmasını buyurur."},{"n":"35","t":"Siz de uyanık kalın. Çünkü ev sahibi ne zaman gelecek, akşam mı, gece yarısı mı, horoz öttüğünde mi, sabaha doğru mu, bilemezsiniz."},{"n":"36","t":"Ansızın gelip sizi uykuda bulmasın!"},{"n":"37","t":"Size söylediklerimi herkese söylüyorum; uyanık kalın!\""}]},{"ch":14,"verses":[{"n":"1","t":"Fısıh ve Mayasız Ekmek Bayramı'na* iki gün kalmıştı. Başkâhinlerle din bilginleri İsa'yı hileyle tutuklayıp öldürmenin bir yolunu arıyorlardı."},{"n":"2","t":"\"Bayramda olmasın, yoksa halk arasında kargaşalık çıkar\" diyorlardı."},{"n":"3","t":"İsa Beytanya'da cüzamlı* Simun'un evinde sofrada otururken yanına bir kadın geldi. Kadın kaymaktaşından bir kap içinde çok değerli, saf hintsümbülü yağı getirmişti. Kabı kırarak yağı O'nun başına döktü."},{"n":"4-5","t":"Bazıları buna kızdılar; birbirlerine, \"Bu yağ niçin böyle boş yere harcandı? Üç yüz dinardan fazlaya satılabilir, parası yoksullara verilebilirdi\" diyerek kadını azarlamaya başladılar."},{"n":"6","t":"\"Kadını rahat bırakın\" dedi İsa. \"Neden üzüyorsunuz onu? Benim için güzel bir şey yaptı."},{"n":"7","t":"Yoksullar her zaman aranızdadır, dilediğiniz anda onlara yardım edebilirsiniz; ama ben her zaman aranızda olmayacağım."},{"n":"8","t":"Kadın elinden geleni yaptı, beni gömülmeye hazırlamak üzere daha şimdiden bedenimi yağladı."},{"n":"9","t":"Size doğrusunu söyleyeyim, Müjde dünyanın neresinde duyurulursa, bu kadının yaptığı da onun anılması için anlatılacak.\""},{"n":"10","t":"Bu arada Onikiler'den* biri olan Yahuda İskariot, İsa'yı ele vermek amacıyla başkâhinlerin yanına gitti."},{"n":"11","t":"Onlar bunu işitince sevindiler, Yahuda'ya para vermeyi vaat ettiler. O da İsa'yı ele vermek için fırsat kollamaya başladı. Fısıh Yemeği (Mat.26:17-30; Luk.22:7-23; Yu.13:21-30)"},{"n":"12","t":"Fısıh* kurbanının kesildiği Mayasız Ekmek Bayramı'nın* ilk günü öğrencileri İsa'ya, \"Fısıh yemeğini yemen için nereye gidip hazırlık yapmamızı istersin?\" diye sordular."},{"n":"13","t":"O da öğrencilerinden ikisini şu sözlerle önden gönderdi: \"Kente gidin, orada su testisi taşıyan bir adam çıkacak karşınıza. Onu izleyin."},{"n":"14","t":"Adamın gideceği evin sahibine şöyle deyin: 'Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.'"},{"n":"15","t":"Ev sahibi size üst katta döşenmiş, hazır büyük bir oda gösterecek. Orada bizim için hazırlık yapın.\""},{"n":"16","t":"Öğrenciler yola çıkıp kente gittiler. Her şeyi, İsa'nın kendilerine söylediği gibi buldular ve Fısıh yemeği için hazırlık yaptılar."},{"n":"17","t":"Akşam olunca İsa Onikiler'le* birlikte geldi."},{"n":"18","t":"Sofraya oturmuş yemek yerlerken İsa, \"Size doğrusunu söyleyeyim\" dedi, \"Sizden biri, benimle yemek yiyen biri bana ihanet edecek.\""},{"n":"19","t":"Onlar da kederlenerek birer birer kendisine, \"Beni demek istemedin ya?\" diye sormaya başladılar."},{"n":"20","t":"İsa onlara, \"Onikiler'den biridir, ekmeğini benimle birlikte sahana batırandır\" dedi."},{"n":"21","t":"\"Evet, İnsanoğlu* kendisi için yazılmış olduğu gibi gidiyor, ama İnsanoğlu'na ihanet edenin vay haline! O adam hiç doğmamış olsaydı, kendisi için daha iyi olurdu.\""},{"n":"22","t":"İsa yemek sırasında eline ekmek aldı, şükredip ekmeği böldü ve, \"Alın, bu benim bedenimdir\" diyerek öğrencilerine verdi."},{"n":"23","t":"Sonra bir kâse alıp şükretti ve bunu öğrencilerine verdi. Hepsi bundan içti."},{"n":"24","t":"\"Bu benim kanım\" dedi İsa, \"Birçokları uğruna akıtılan antlaşma kanıdır."},{"n":"25","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliği'nde tazesini içeceğim o güne dek, asmanın ürününden bir daha içmeyeceğim.\""},{"n":"26","t":"İlahi söyledikten sonra dışarı çıkıp Zeytin Dağı'na doğru gittiler. Petrus'un İnkârı Önceden Bildiriliyor (Mat.26:31-35; Luk.22:31-34; Yu.13:36-38)"},{"n":"27","t":"Bu arada İsa öğrencilerine, \"Hepiniz sendeleyip düşeceksiniz\" dedi. \"Çünkü şöyle yazılmıştır: 'Çobanı vuracağım, Koyunlar darmadağın olacak.'"},{"n":"28","t":"Ama ben dirildikten sonra sizden önce Celile'ye gideceğim.\""},{"n":"29","t":"Petrus O'na, \"Herkes sendeleyip düşse bile ben düşmem\" dedi."},{"n":"30","t":"\"Sana doğrusunu söyleyeyim\" dedi İsa, \"Bugün, bu gece, horoz iki kez ötmeden sen beni üç kez inkâr edeceksin.\""},{"n":"31","t":"Ama Petrus üsteleyerek, \"Seninle birlikte ölmem gerekse bile seni asla inkâr etmem\" dedi. Öğrencilerin hepsi de aynı şeyi söyledi. Getsemani Bahçesinde (Mat.26:36-46; Luk.22:39-46)"},{"n":"32","t":"Sonra Getsemani denilen yere geldiler. İsa öğrencilerine, \"Ben dua ederken siz burada oturun\" dedi."},{"n":"33","t":"Petrus'u, Yakup'u ve Yuhanna'yı yanına aldı. Hüzünlenmeye ve ağır bir sıkıntı duymaya başlamıştı."},{"n":"34","t":"Onlara, \"Ölesiye kederliyim\" dedi. \"Burada kalın, uyanık durun.\""},{"n":"35","t":"Biraz ilerledi, yüzüstü yere kapanıp dua etmeye başladı. \"Mümkünse o saati yaşamayayım\" dedi."},{"n":"36","t":"\"Abba*fx*, Baba, senin için her şey mümkün, bu kâseyi* benden uzaklaştır.*fx* Ama benim değil, senin istediğin olsun.\""},{"n":"37","t":"Öğrencilerinin yanına döndüğünde onları uyumuş buldu. Petrus'a, \"Simun\" dedi, \"Uyuyor musun? Bir saat uyanık kalamadın mı?"},{"n":"38","t":"Uyanık durup dua edin ki, ayartılmayasınız. Ruh isteklidir, ama beden güçsüzdür.\""},{"n":"39","t":"Yine uzaklaştı, aynı sözleri tekrarlayarak dua etti."},{"n":"40","t":"Geri geldiğinde öğrencilerini yine uyumuş buldu. Onların göz kapaklarına ağırlık çökmüştü. İsa'ya ne diyeceklerini bilemiyorlardı."},{"n":"41","t":"İsa üçüncü kez yanlarına döndü, \"Hâlâ uyuyor, dinleniyor musunuz?\" dedi. \"Yeter! Saat geldi. İşte İnsanoğlu* günahkârların eline veriliyor."},{"n":"42","t":"Kalkın, gidelim. İşte bana ihanet eden geldi!\" İsa Tutuklanıyor (Mat.26:47-56; Luk.22:47-53; Yu.18:3-12)"},{"n":"43","t":"Tam o anda, İsa daha konuşurken, Onikiler'den* biri olan Yahuda çıkageldi. Yanında başkâhinler, din bilginleri ve ileri gelenler tarafından gönderilmiş kılıçlı sopalı bir kalabalık vardı."},{"n":"44","t":"İsa'ya ihanet eden Yahuda, \"Kimi öpersem, İsa O'dur. O'nu tutuklayın, güvenlik altına alıp götürün\" diye onlarla sözleşmişti."},{"n":"45","t":"Gelir gelmez İsa'ya yaklaştı, \"Rabbî*\" diyerek O'nu öptü."},{"n":"46","t":"Onlar da İsa'yı yakalayıp tutukladılar."},{"n":"47","t":"İsa'nın yanında bulunanlardan biri kılıcını çekti, başkâhinin kölesine vurup kulağını uçurdu."},{"n":"48","t":"İsa onlara, \"Niçin bir haydutmuşum gibi beni kılıç ve sopalarla yakalamaya geldiniz?\" dedi."},{"n":"49","t":"\"Her gün tapınakta, yanıbaşınızda öğretiyordum, beni tutuklamadınız. Ama bu, Kutsal Yazılar yerine gelsin diye oldu.\""},{"n":"50","t":"O zaman öğrencilerinin hepsi O'nu bırakıp kaçtı."},{"n":"51","t":"İsa'nın ardından sadece keten beze sarınmış bir genç gidiyordu. Bu genç de yakalandı."},{"n":"52","t":"Ama keten bezden sıyrılıp çıplak olarak kaçtı. İsa Yüksek Kurul'un Önünde (Mat.26:57-68; Luk.22:54-55,63-71; Yu.18:13-14,19-24)"},{"n":"53","t":"İsa'yı görevli başkâhine götürdüler. Bütün başkâhinler, ileri gelenler ve din bilginleri* de orada toplandı."},{"n":"54","t":"Petrus, İsa'yı başkâhinin avlusunun içine kadar uzaktan izledi. Avluda nöbetçilerle birlikte ateşin başında oturup ısınmaya başladı."},{"n":"55","t":"Başkâhinler ve Yüksek Kurul'un* öteki üyeleri, İsa'yı ölüm cezasına çarptırmak için kendisine karşı tanık arıyor, ama bulamıyorlardı."},{"n":"56","t":"Birçok kişi O'na karşı yalan yere tanıklık ettiyse de, tanıklıkları birbirini tutmadı."},{"n":"57-58","t":"Bazıları kalkıp O'na karşı yalan yere şöyle tanıklık ettiler: \"Biz O'nun, 'Elle yapılmış bu tapınağı yıkacağım ve üç günde, elle yapılmamış başka bir tapınak kuracağım' dediğini işittik.\""},{"n":"59","t":"Ama bu noktada bile tanıklıkları birbirini tutmadı."},{"n":"60","t":"Sonra başkâhin topluluğun ortasında ayağa kalkarak İsa'ya, \"Hiç yanıt vermeyecek misin? Nedir bunların sana karşı ettiği bu tanıklıklar?\" diye sordu."},{"n":"61","t":"Ne var ki, İsa susmaya devam etti, hiç yanıt vermedi. Başkâhin O'na yeniden, \"Yüce Olan'ın*fx* Oğlu Mesih* sen misin?\" diye sordu."},{"n":"62","t":"İsa, \"Benim\" dedi. \"Ve sizler, İnsanoğlu'nun* Kudretli Olan'ın*fx* sağında oturduğunu ve göğün bulutlarıyla geldiğini göreceksiniz.\""},{"n":"63-64","t":"Başkâhin giysilerini yırtarak, \"Artık tanıklara ne ihtiyacımız var?\" dedi. \"Küfürü işittiniz. Buna ne diyorsunuz?\" Hepsi İsa'nın ölüm cezasını hak ettiğine karar verdiler."},{"n":"65","t":"Bazıları O'nun üzerine tükürmeye, gözlerini bağlayarak O'nu yumruklamaya başladılar. \"Haydi, peygamberliğini göster!\" diyorlardı. Nöbetçiler de O'nu aralarına alıp tokatladılar. Petrus İsa'yı İnkâr Ediyor (Mat.26:69-75; Luk.22:56-62; Yu.18:15-18,25-27)"},{"n":"66-67","t":"Petrus aşağıda, avludayken, başkâhinin hizmetçi kızlarından biri geldi. Isınmakta olan Petrus'u görünce onu dikkatle süzüp, \"Sen de Nasıralı İsa'yla birlikteydin\" dedi."},{"n":"68","t":"Petrus ise bunu inkâr ederek, \"Senin neden söz ettiğini bilmiyorum, anlamıyorum\" dedi ve dışarıya, dış kapının önüne çıktı. Bu arada horoz öttü."},{"n":"69","t":"Hizmetçi kız Petrus'u görünce çevrede duranlara yine, \"Bu adam onlardan biri\" demeye başladı."},{"n":"70","t":"Petrus tekrar inkâr etti. Çevrede duranlar az sonra Petrus'a yine, \"Gerçekten onlardansın; sen de Celileli'sin\" dediler."},{"n":"71","t":"Petrus kendine lanet okuyup ant içerek, \"Sözünü ettiğiniz o adamı tanımıyorum\" dedi."},{"n":"72","t":"Tam o anda horoz ikinci kez öttü. Petrus, İsa'nın kendisine, \"Horoz iki kez ötmeden beni üç kez inkâr edeceksin\" dediğini hatırladı ve hüngür hüngür ağlamaya başladı."}]},{"ch":15,"verses":[{"n":"1","t":"Sabah olunca başkâhinler, ileri gelenler, din bilginleri ve Yüksek Kurul'un* öteki üyeleri bir danışma toplantısı yaptıktan sonra İsa'yı bağladılar, götürüp Pilatus'a teslim ettiler."},{"n":"2","t":"Pilatus O'na, \"Sen Yahudiler'in Kralı mısın?\" diye sordu. İsa, \"Söylediğin gibidir\" yanıtını verdi."},{"n":"3","t":"Başkâhinler O'na karşı birçok suçlamada bulundular."},{"n":"4","t":"Pilatus O'na yeniden, \"Hiç yanıt vermeyecek misin?\" diye sordu. \"Bak, seni ne çok şeyle suçluyorlar!\""},{"n":"5","t":"Ama İsa artık yanıt vermiyordu. Pilatus buna şaştı. İsa Ölüm Cezasına Çarptırılıyor (Mat.27:15-26; Luk.23:13-25; Yu.18:39-19:16)"},{"n":"6","t":"Pilatus, her Fısıh Bayramı'nda* halkın istediği bir tutukluyu salıverirdi."},{"n":"7","t":"Ayaklanma sırasında adam öldüren isyancılarla birlikte Barabba adında bir tutuklu da vardı."},{"n":"8","t":"Halk, Pilatus'a gelip her zamanki gibi kendileri için birini salıvermesini istedi."},{"n":"9","t":"Pilatus onlara, \"Sizin için Yahudiler'in Kralı'nı salıvermemi ister misiniz?\" dedi."},{"n":"10","t":"Başkâhinlerin İsa'yı kıskançlıktan ötürü kendisine teslim ettiklerini biliyordu."},{"n":"11","t":"Ne var ki başkâhinler, İsa'nın değil, Barabba'nın salıverilmesini istemeleri için halkı kışkırttılar."},{"n":"12","t":"Pilatus onlara tekrar seslenerek, \"Öyleyse Yahudiler'in Kralı dediğiniz adamı ne yapayım?\" diye sordu."},{"n":"13","t":"\"O'nu çarmıha ger!\" diye bağırdılar yine."},{"n":"14","t":"Pilatus onlara, \"O ne kötülük yaptı ki?\" dedi. Onlar ise daha yüksek sesle, \"O'nu çarmıha ger!\" diye bağrıştılar."},{"n":"15","t":"Halkı memnun etmek isteyen Pilatus, onlar için Barabba'yı salıverdi. İsa'yı ise kamçılattıktan sonra çarmıha gerilmek üzere askerlere teslim etti. Askerlerin İsa'yı Aşağılaması (Mat.27:27-31; Yu.19:2-3)"},{"n":"16","t":"Askerler İsa'yı, Pretorium denilen vali konağına götürüp bütün taburu topladılar."},{"n":"17","t":"O'na mor bir giysi giydirdiler, dikenlerden bir taç örüp başına geçirdiler."},{"n":"18","t":"\"Selam, ey Yahudiler'in Kralı!\" diyerek O'nu selamlamaya başladılar."},{"n":"19","t":"Başına bir kamışla vuruyor, üzerine tükürüyor, diz çöküp önünde yere kapanıyorlardı."},{"n":"20","t":"O'nunla böyle alay ettikten sonra mor giysiyi üzerinden çıkarıp kendi giysilerini giydirdiler ve çarmıha germek üzere O'nu dışarı götürdüler. İsa Çarmıha Geriliyor (Mat.27:32-44; Luk.23:26-43; Yu.19:17-27)"},{"n":"21","t":"Kırdan gelmekte olan Simun adında Kireneli bir adam oradan geçiyordu. İskender ve Rufus'un babası olan bu adama İsa'nın çarmıhını zorla taşıttılar."},{"n":"22","t":"İsa'yı Golgota, yani Kafatası denilen yere götürdüler."},{"n":"23","t":"O'na mürle* karışık şarap vermek istediler, ama içmedi."},{"n":"24","t":"Sonra O'nu çarmıha gerdiler. Kim ne alacak diye kura çekerek giysilerini aralarında paylaştılar."},{"n":"25","t":"İsa'yı çarmıha gerdiklerinde saat dokuzdu."},{"n":"26","t":"Üzerindeki suç yaftasında, YAHUDİLER'İN KRALI diye yazılıydı."},{"n":"27-28","t":"İsa'yla birlikte, biri sağında öbürü solunda olmak üzere iki haydudu da çarmıha gerdiler.*fx*"},{"n":"29-30","t":"Oradan geçenler başlarını sallayıp İsa'ya sövüyor, \"Hani sen tapınağı yıkıp üç günde yeniden kuracaktın? Çarmıhtan in de kurtar kendini!\" diyorlardı."},{"n":"31","t":"Aynı şekilde başkâhinler ve din bilginleri de O'nunla alay ederek aralarında, \"Başkalarını kurtardı, kendini kurtaramıyor\" diye konuşuyorlardı."},{"n":"32","t":"\"İsrail'in Kralı Mesih şimdi çarmıhtan insin de görüp iman edelim.\" İsa'yla birlikte çarmıha gerilenler de O'na hakaret ettiler. İsa'nın Ölümü (Mat.27:45-56; Luk.23:44-49; Yu.19:28-30)"},{"n":"33","t":"Öğleyin on ikiden üçe kadar bütün ülkenin üzerine karanlık çöktü."},{"n":"34","t":"Saat üçte İsa yüksek sesle, \"Elohi, Elohi, lema şevaktani\" yani, \"Tanrım, Tanrım, beni neden terk ettin?\" diye bağırdı."},{"n":"35","t":"Orada duranlardan bazıları bunu işitince, \"Bakın, İlyas'ı çağırıyor\" dediler."},{"n":"36","t":"Aralarından biri koşup bir süngeri ekşi şaraba batırdı, bir kamışın ucuna takarak İsa'ya içirdi. \"Dur bakalım, İlyas gelip O'nu indirecek mi?\" dedi."},{"n":"37","t":"Ama İsa yüksek sesle bağırarak son nefesini verdi."},{"n":"38","t":"O anda tapınaktaki perde* yukarıdan aşağıya yırtılarak ikiye bölündü."},{"n":"39","t":"İsa'nın karşısında duran yüzbaşı, O'nun bu şekilde son nefesini verdiğini görünce, \"Bu adam gerçekten Tanrı'nın Oğlu'ydu\" dedi."},{"n":"40","t":"Olup bitenleri uzaktan izleyen bazı kadınlar da vardı. Aralarında Mecdelli Meryem, küçük Yakup ile Yose'nin annesi Meryem ve Salome bulunuyordu."},{"n":"41","t":"İsa daha Celile'deyken bu kadınlar O'nun ardından gitmiş, O'na hizmet etmişlerdi. O'nunla birlikte Yeruşalim'e gelmiş olan daha birçok kadın da olup bitenleri izliyordu. İsa'nın Gömülmesi (Mat.27:57-61; Luk.23:50-56; Yu.19:38-42)"},{"n":"42-43","t":"O gün Hazırlık Günü, yani Şabat Günü'nden* önceki gündü. Artık akşam oluyordu. Bu nedenle, Yüksek Kurul'un* saygın bir üyesi olup Tanrı'nın Egemenliği'ni umutla bekleyen Aramatyalı Yusuf geldi, cesaretini toplayarak Pilatus'un huzuruna çıktı, İsa'nın cesedini istedi."},{"n":"44","t":"Pilatus, İsa'nın bu kadar çabuk ölmüş olmasına şaştı. Yüzbaşıyı çağırıp, \"Öleli çok oldu mu?\" diye sordu."},{"n":"45","t":"Yüzbaşıdan durumu öğrenince Yusuf'a, cesedi alması için izin verdi."},{"n":"46","t":"Yusuf keten bez satın aldı, cesedi çarmıhtan indirip beze sardı, kayaya oyulmuş bir mezara yatırarak mezarın girişine bir taş yuvarladı."},{"n":"47","t":"Mecdelli Meryem ile Yose'nin annesi Meryem, İsa'nın nereye konulduğunu gördüler."}]},{"ch":16,"verses":[{"n":"1","t":"Şabat Günü* geçince, Mecdelli Meryem, Yakup'un annesi Meryem ve Salome gidip İsa'nın cesedine sürmek üzere baharat satın aldılar."},{"n":"2","t":"Haftanın ilk günü* sabah çok erkenden, güneşin doğuşuyla birlikte mezara gittiler."},{"n":"3","t":"Aralarında, \"Mezarın girişindeki taşı bizim için kim yana yuvarlayacak?\" diye konuşuyorlardı."},{"n":"4","t":"Başlarını kaldırıp bakınca, o kocaman taşın yana yuvarlanmış olduğunu gördüler."},{"n":"5","t":"Mezara girip sağ tarafta, beyaz kaftan giyinmiş genç bir adamın oturduğunu görünce çok şaşırdılar."},{"n":"6","t":"Adam onlara, \"Şaşırmayın!\" dedi. \"Çarmıha gerilen Nasıralı İsa'yı arıyorsunuz. O dirildi, burada yok. İşte O'nu yatırdıkları yer."},{"n":"7","t":"Şimdi öğrencilerine ve Petrus'a gidip şöyle deyin: 'İsa sizden önce Celile'ye gidiyor. Size bildirdiği gibi, kendisini orada göreceksiniz.'\""},{"n":"8","t":"Kadınlar mezardan çıkıp kaçtılar. Onları bir titreme, bir şaşkınlık almıştı. Korkularından kimseye bir şey söylemediler. İsa Öğrencilerine Görünüyor (Mat.28:9-10; Luk.24:13-35; Yu.20:11-18)"},{"n":"9","t":"İsa, haftanın ilk günü* sabah erkenden dirildiği zaman önce Mecdelli Meryem'e göründü. Ondan yedi cin kovmuştu."},{"n":"10","t":"Meryem gitti, İsa'yla bulunmuş olan, şimdiyse yas tutup gözyaşı döken öğrencilerine haberi verdi."},{"n":"11","t":"Ne var ki onlar, İsa'nın yaşadığını, Meryem'e göründüğünü duyunca inanmadılar."},{"n":"12","t":"Bundan sonra İsa kırlara doğru yürümekte olan öğrencilerinden ikisine değişik bir biçimde göründü."},{"n":"13","t":"Bunlar geri dönüp öbürlerine haber verdiler, ama öbürleri bunlara da inanmadılar."},{"n":"14","t":"İsa daha sonra, sofrada otururlarken Onbirler'e* göründü. Onları imansızlıklarından ve yüreklerinin duygusuzluğundan ötürü azarladı. Çünkü kendisini diri görenlere inanmamışlardı. İsa Öğrencilerini Bütün Dünyaya Gönderiyor (Mat.28:16-20; Luk.24:36-53; Yu.20:19-23; Elç.1:6-11)"},{"n":"15","t":"İsa onlara şöyle buyurdu: \"Dünyanın her yanına gidin, Müjde'yi bütün yaratılışa duyurun."},{"n":"16","t":"İman edip vaftiz olan kurtulacak, iman etmeyen ise hüküm giyecek."},{"n":"17-18","t":"İman edenlerle birlikte görülecek belirtiler şunlardır: Benim adımla cinleri kovacaklar, yeni dillerle konuşacaklar, yılanları elleriyle tutacaklar. Öldürücü bir zehir içseler bile, zarar görmeyecekler. Ellerini hastaların üzerine koyacaklar ve hastalar iyileşecek.\""},{"n":"19","t":"Rab İsa, onlara bu sözleri söyledikten sonra göğe alındı ve Tanrı'nın sağında oturdu."},{"n":"20","t":"Öğrencileri de gidip Tanrı sözünü her yere yaydılar. Rab onlarla birlikte çalışıyor, görülen belirtilerle sözünü doğruluyordu.*fx*"}]},{"ch":17,"verses":[{"n":"15-16","t":"Birçok Grekçe elyazması, \"İşitecek kulağı olan işitsin!\" sözlerini de içerir (bkz. Mar.4: 9,23). 7:24 \"Sur\": Bazı Grekçe elyazmalarında, \"Sur ve Sayda\" diye"},{"n":"29","t":"\"Duayla\": Birçok Grekçe elyazmasında, \"Dua ve oruçla\" diye"},{"n":"48","t":"Bu ayet bazı Grekçe elyazmalarında ayrıca 45. ve 47. ayetlerden önce"},{"n":"38","t":"Bu ayette İsa, çekeceği acılardan ve çarmıhtaki ölümünden söz"},{"n":"51","t":"\"Rabbuni\": Aramice'de* öğretmenim anlamına"},{"n":"25-26","t":"Birçok Grekçe elyazması, \"Ama siz bağışlamazsanız, göklerdeki Babanız da sizin suçlarınızı bağışlamaz\" sözlerini de içerir (bkz. Mat.6:15; 18:35). 11:30 \"Yahya'nın vaftiz etme yetkisi Tanrı'dan\": Grekçe \"Yahya'nın vaftizi gökten\". 31. ayette de \"Tanrı'dan\" diye çevrilen sözcük Grekçe \"Gökten\" diye"},{"n":"42","t":"\"Birkaç kuruş değerinde iki bakır para\": Grekçe \"Bir kodrantis olan iki lepton\" (bkz. Birimler Cetveli). 13:30 \"Kuşak\" ya da \"Soy\". 14:35-36 Grekçe, \"Biraz ilerledi, yüzüstü yere kapanıp mümkünse o saatin kendisinden geçmesi için dua etti. Dedi ki, 'Abba, Baba, senin için her şey mümkün, bu kâseyi benden uzaklaştır.'\" 14:36 \"Abba\": Aramice'de* baba anlamına"},{"n":"61","t":"\"Yüce Olan'ın\": Grekçe \"Mübarek'in\", yani \"Tanrı'nın\". 14:62 \"Kudretli Olan\":"},{"n":"27-28","t":"Birçok Grekçe elyazması, \"Böylece 'O, suçlularla bir sayıldı' diyen Kutsal Yazı yerine geldi\" sözlerini de içerir (bkz. Luk.22:37). 16:20 9-20 ayetleri bazı Grekçe elyazmalarında yoktur._"}]}]},{"id":"luka","name":"Luka","chapters":[{"ch":1,"verses":[{"n":"1-3","t":"Sayın Teofilos, Birçok kişi aramızda olup bitenlerin tarihçesini yazmaya girişti. Nitekim başlangıçtan beri bu olayların görgü tanığı ve Tanrı sözünün hizmetkârı olanlar bunları bize ilettiler. Ben de bütün bu olayları ta başından özenle araştırmış biri olarak bunları sana sırasıyla yazmayı uygun gördüm."},{"n":"4","t":"Öyle ki, sana verilen bilgilerin doğruluğunu bilesin. Yahya'nın Doğumu Önceden Bildiriliyor"},{"n":"5","t":"Yahudiye Kralı Hirodes* zamanında, Aviya bölüğünden Zekeriya adında bir kâhin* vardı. Harun soyundan gelen karısının adı ise Elizabet'ti."},{"n":"6","t":"Her ikisi de Tanrı'nın gözünde doğru kişilerdi, Rab'bin bütün buyruk ve kurallarına eksiksizce uyarlardı."},{"n":"7","t":"Elizabet kısır olduğu için çocukları olmuyordu. İkisinin de yaşı ilerlemişti."},{"n":"8","t":"Zekeriya, hizmet sırasının kendi bölüğünde olduğu bir gün, Tanrı'nın önünde kâhinlik görevini yerine getiriyordu."},{"n":"9","t":"Kâhinlik geleneği uyarınca Rab'bin Tapınağı'na girip buhur yakma görevi kurayla ona verilmişti."},{"n":"10","t":"Buhur yakma saatinde bütün halk topluluğu dışarıda dua ediyordu."},{"n":"11","t":"Bu sırada, Rab'bin bir meleği buhur sunağının sağında durup Zekeriya'ya göründü."},{"n":"12","t":"Zekeriya onu görünce şaşırdı, korkuya kapıldı."},{"n":"13","t":"Melek, \"Korkma, Zekeriya\" dedi, \"Duan kabul edildi. Karın Elizabet sana bir oğul doğuracak, adını Yahya koyacaksın."},{"n":"14","t":"Sevinip coşacaksın. Birçokları da onun doğumuna sevinecek."},{"n":"15","t":"O, Rab'bin gözünde büyük olacak. Hiç şarap ve içki içmeyecek; daha annesinin rahmindeyken Kutsal Ruh'la dolacak."},{"n":"16","t":"İsrailoğulları'ndan birçoğunu, Tanrıları Rab'be döndürecek."},{"n":"17","t":"Babaların yüreklerini çocuklarına döndürmek, söz dinlemeyenleri doğru kişilerin anlayışına yöneltmek ve Rab için hazırlanmış bir halk yetiştirmek üzere, İlyas'ın ruhu ve gücüyle Rab'bin önünden gidecektir.\""},{"n":"18","t":"Zekeriya meleğe, \"Bundan nasıl emin olabilirim?\" dedi. \"Çünkü ben yaşlandım, karımın da yaşı ilerledi.\""},{"n":"19","t":"Melek ona şöyle karşılık verdi: \"Ben Tanrı'nın huzurunda duran Cebrail'im. Seninle konuşmak ve bu müjdeyi sana bildirmek için gönderildim."},{"n":"20","t":"İşte, belirlenen zamanda yerine gelecek olan sözlerime inanmadığın için dilin tutulacak, bunların gerçekleşeceği güne dek konuşamayacaksın.\""},{"n":"21","t":"Zekeriya'yı bekleyen halk, onun tapınakta bu kadar uzun süre kalmasına şaştı."},{"n":"22","t":"Zekeriya ise dışarı çıktığında onlarla konuşamadı. O zaman tapınakta bir görüm gördüğünü anladılar. Kendisi onlara işaretler yapıyor, ama konuşamıyordu."},{"n":"23","t":"Görev süresi bitince Zekeriya evine döndü."},{"n":"24","t":"Bir süre sonra karısı Elizabet gebe kaldı ve beş ay evine kapandı."},{"n":"25","t":"\"Bunu benim için yapan Rab'dir\" dedi. \"Bu günlerde benimle ilgilenerek insanlar arasında utancımı giderdi.\" İsa'nın Doğumu Önceden Bildiriliyor"},{"n":"26-27","t":"Elizabet'in hamileliğinin altıncı ayında Tanrı, Melek Cebrail'i Celile'de bulunan Nasıra adlı kente, Davut'un soyundan Yusuf adındaki adamla nişanlı kıza gönderdi. Kızın adı Meryem'di."},{"n":"28","t":"Onun yanına giren melek, \"Selam, ey Tanrı'nın lütfuna erişen kız! Rab seninledir\" dedi."},{"n":"29","t":"Söylenenlere çok şaşıran Meryem, bu selamın ne anlama gelebileceğini düşünmeye başladı."},{"n":"30","t":"Ama melek ona, \"Korkma Meryem\" dedi, \"Sen Tanrı'nın lütfuna eriştin."},{"n":"31","t":"Bak, gebe kalıp bir oğul doğuracak, adını İsa koyacaksın."},{"n":"32","t":"O büyük olacak, kendisine 'Yüceler Yücesi'nin Oğlu' denecek. Rab Tanrı O'na, atası Davut'un tahtını verecek."},{"n":"33","t":"O da sonsuza dek Yakup'un soyu üzerinde egemenlik sürecek, egemenliğinin sonu gelmeyecektir.\""},{"n":"34","t":"Meryem meleğe, \"Bu nasıl olur? Ben erkeğe varmadım ki\" dedi."},{"n":"35","t":"Melek ona şöyle yanıt verdi: \"Kutsal Ruh senin üzerine gelecek, Yüceler Yücesi'nin gücü sana gölge salacak. Bunun için doğacak olana kutsal, Tanrı Oğlu denecek."},{"n":"36","t":"Bak, senin akrabalarından Elizabet de yaşlılığında bir oğula gebe kaldı. Kısır bilinen bu kadın şimdi altıncı ayındadır."},{"n":"37","t":"Tanrı'nın yapamayacağı hiçbir şey yoktur.\""},{"n":"38","t":"\"Ben Rab'bin kuluyum\" dedi Meryem, \"Bana dediğin gibi olsun.\" Bundan sonar melek onun yanından ayrıldı. Meryem, Elizabet'i Ziyaret Ediyor"},{"n":"39","t":"O günlerde Meryem kalkıp aceleyle Yahuda'nın dağlık bölgesindeki bir kente gitti."},{"n":"40","t":"Zekeriya'nın evine girip Elizabet'i selamladı."},{"n":"41-42","t":"Elizabet Meryem'in selamını duyunca rahmindeki çocuk hopladı. Kutsal Ruh'la dolan Elizabet yüksek sesle şöyle dedi: \"Kadınlar arasında kutsanmış bulunuyorsun, rahminin ürünü de kutsanmıştır!"},{"n":"43","t":"Nasıl oldu da Rabbim'in annesi yanıma geldi?"},{"n":"44","t":"Bak, selamın kulaklarıma eriştiği an, çocuk rahmimde sevinçle hopladı."},{"n":"45","t":"İman eden kadına ne mutlu! Çünkü Rab'bin ona söylediği sözler gerçekleşecektir.\""},{"n":"46-47","t":"Meryem de şöyle dedi: \"Canım Rab'bi yüceltir; Ruhum, Kurtarıcım Tanrı sayesinde sevinçle coşar."},{"n":"48","t":"Çünkü O, sıradan biri olan kuluyla ilgilendi. İşte, bundan böyle bütün kuşaklar beni mutlu sayacak."},{"n":"49","t":"Çünkü Güçlü Olan, benim için büyük işler yaptı. O'nun adı kutsaldır."},{"n":"50","t":"Kuşaklar boyunca kendisinden korkanlara merhamet eder."},{"n":"51","t":"Bileğiyle büyük işler yaptı; Gururluları yüreklerindeki kuruntularla darmadağın etti."},{"n":"52","t":"Hükümdarları tahtlarından indirdi, Sıradan insanları yükseltti."},{"n":"53","t":"Aç olanları iyiliklerle doyurdu, Zenginleri ise elleri boş çevirdi."},{"n":"54-55","t":"Atalarımıza söz verdiği gibi, İbrahim'e ve onun soyuna sonsuza dek Merhamet etmeyi unutmayarak Kulu İsrail'in yardımına yetişti.\""},{"n":"56","t":"Meryem, üç ay kadar Elizabet'in yanında kaldı, sonra kendi evine döndü. Yahya'nın Doğumu"},{"n":"57","t":"Elizabet'in doğurma vakti geldi ve bir oğul doğurdu."},{"n":"58","t":"Komşularıyla akrabaları, Rab'bin ona ne büyük merhamet gösterdiğini duyunca, onun sevincine katıldılar."},{"n":"59","t":"Sekizinci gün çocuğun sünnetine geldiler. Ona babası Zekeriya'nın adını vereceklerdi."},{"n":"60","t":"Ama annesi, \"Hayır, adı Yahya olacak\" dedi."},{"n":"61","t":"Ona, \"Akrabaların arasında bu adı taşıyan kimse yok ki\" dediler."},{"n":"62","t":"Bunun üzerine babasına işaretle çocuğun adını ne koymak istediğini sordular."},{"n":"63","t":"Zekeriya bir yazı levhası istedi ve, \"Adı Yahya'dır\" diye yazdı. Herkes şaşakaldı."},{"n":"64","t":"O anda Zekeriya'nın ağzı açıldı, dili çözüldü. Tanrı'yı överek konuşmaya başladı."},{"n":"65","t":"Çevrede oturanların hepsi korkuya kapıldı. Bütün bu olaylar, Yahudiye'nin dağlık bölgesinin her yanında konuşulur oldu."},{"n":"66","t":"Duyan herkes derin derin düşünüyor, \"Acaba bu çocuk ne olacak?\" diyordu. Çünkü Rab*fx* onunla birlikteydi. Zekeriya'nın Şükran İlahisi"},{"n":"67","t":"Çocuğun babası Zekeriya, Kutsal Ruh'la dolarak şu peygamberlikte bulundu:"},{"n":"68","t":"\"İsrail'in Tanrısı Rab'be övgüler olsun! Çünkü halkının yardımına gelip onları fidyeyle kurtardı."},{"n":"69-71","t":"Eski çağlardan beri Kutsal peygamberlerinin ağzından bildirdiği gibi, Kulu Davut'un soyundan Bizim için güçlü bir kurtarıcı*fx* çıkardı; Düşmanlarımızdan, Bizden nefret edenlerin hepsinin elinden Kurtuluşumuzu sağladı."},{"n":"72","t":"Böylece atalarımıza merhamet ederek Kutsal antlaşmasını anmış oldu."},{"n":"73-75","t":"Nitekim bizi düşmanlarımızın elinden kurtaracağına Ve ömrümüz boyunca Kendi önünde kutsallık ve doğruluk içinde, Korkusuzca kendisine tapınmamızı sağlayacağına dair Atamız İbrahim'e ant içerek söz vermişti."},{"n":"76-77","t":"Sen de, ey çocuk, Yüceler Yücesi'nin peygamberi diye anılacaksın. Rab'bin yollarını hazırlamak üzere önünden gidecek Ve O'nun halkına, Günahlarının bağışlanmasıyla kurtulacaklarını bildireceksin."},{"n":"78-79","t":"Çünkü Tanrımız'ın yüreği merhamet doludur. O'nun merhameti sayesinde, Yücelerden doğan Güneş*fx*, Karanlıkta ve ölümün gölgesinde yaşayanlara ışık saçmak Ve ayaklarımızı esenlik yoluna yöneltmek üzere Yardımımıza gelecektir.\""},{"n":"80","t":"Çocuk büyüyor, ruhsal yönden güçleniyordu. İsrail halkına görüneceği güne dek ıssız yerlerde yaşadı."}]},{"ch":2,"verses":[{"n":"1","t":"O günlerde Sezar* Avgustus bütün Roma dünyasında bir nüfus sayımının yapılması için buyruk çıkardı."},{"n":"2","t":"Bu ilk sayım, Kirinius'un Suriye valiliği zamanında yapıldı."},{"n":"3","t":"Herkes yazılmak için kendi kentine gitti."},{"n":"4","t":"Böylece Yusuf da, Davut'un soyundan ve torunlarından olduğu için Celile'nin Nasıra Kenti'nden Yahudiye bölgesine, Davut'un kenti Beytlehem'e gitti."},{"n":"5","t":"Orada, hamile olan nişanlısı Meryem'le birlikte yazılacaktı."},{"n":"6-7","t":"Onlar oradayken, Meryem'in doğurma vakti geldi ve ilk oğlunu doğurdu. Onu kundağa sarıp bir yemliğe yatırdı. Çünkü handa*fx* yer yoktu. Çobanlar ve Melekler"},{"n":"8","t":"Aynı yörede, sürülerinin yanında nöbet tutarak geceyi kırlarda geçiren çobanlar vardı."},{"n":"9","t":"Rab'bin bir meleği onlara göründü ve Rab'bin görkemi çevrelerini aydınlattı. Büyük bir korkuya kapıldılar."},{"n":"10-11","t":"Melek onlara, \"Korkmayın!\" dedi. \"Size, bütün halkı çok sevindirecek bir haber müjdeliyorum: Bugün size, Davut'un kentinde bir Kurtarıcı doğdu. Bu, Rab olan Mesih'tir*."},{"n":"12","t":"İşte size bir işaret: Kundağa sarılmış ve yemlikte yatan bir bebek bulacaksınız.\""},{"n":"13-14","t":"Birdenbire meleğin yanında, göksel ordulardan oluşan büyük bir topluluk belirdi. Tanrı'yı överek, \"En yücelerde Tanrı'ya yücelik olsun, Yeryüzünde O'nun hoşnut kaldığı insanlara Esenlik olsun!\" dediler."},{"n":"15","t":"Melekler yanlarından ayrılıp göğe çekildikten sonra çobanlar birbirlerine, \"Haydi, Beytlehem'e gidelim, Rab'bin bize bildirdiği bu olayı görelim\" dediler."},{"n":"16","t":"Aceleyle gidip Meryem'le Yusuf'u ve yemlikte yatan bebeği buldular."},{"n":"17","t":"Onları görünce, çocukla ilgili kendilerine anlatılanları bildirdiler."},{"n":"18","t":"Bunu duyanların hepsi, çobanların söylediklerine şaşıp kaldılar."},{"n":"19","t":"Meryem ise bütün bu sözleri derin derin düşünerek yüreğinde saklıyordu."},{"n":"20","t":"Çobanlar, işitip gördüklerinin tümü için Tanrı'yı yüceltip överek geri döndüler. Her şeyi, kendilerine anlatıldığı gibi bulmuşlardı. İsa'nın Tapınakta Tanrı'ya Adanması"},{"n":"21","t":"Sekizinci gün, çocuğu sünnet etme zamanı gelince, O'na İsa adı verildi. Bu, O'nun anne rahmine düşmesinden önce meleğin kendisine verdiği isimdi."},{"n":"22","t":"Musa'nın Yasası'na göre arınma günlerinin*fx* bitiminde Yusuf'la Meryem çocuğu Rab'be adamak için Yeruşalim'e* götürdüler."},{"n":"23","t":"Nitekim Rab'bin Yasası'nda, \"İlk doğan her erkek çocuk Rab'be adanmış sayılacak\" diye yazılmıştır."},{"n":"24","t":"Ayrıca Rab'bin Yasası'nda buyrulduğu gibi, kurban olarak \"bir çift kumru ya da iki güvercin yavrusu\" sunacaklardı."},{"n":"25","t":"O sırada Yeruşalim'de Şimon adında bir adam vardı. Doğru ve dindar biriydi. İsrail'in avutulmasını özlemle bekliyordu. Kutsal Ruh onun üzerindeydi."},{"n":"26","t":"Rab'bin Mesihi'ni görmeden ölmeyeceği Kutsal Ruh aracılığıyla kendisine bildirilmişti."},{"n":"27-28","t":"Böylece Şimon, Ruh'un yönlendirmesiyle tapınağa geldi. Küçük İsa'nın annesi babası, Kutsal Yasa'nın ilgili kuralını yerine getirmek üzere O'nu içeri getirdiklerinde, Şimon O'nu kucağına aldı, Tanrı'yı överek şöyle dedi:"},{"n":"29","t":"\"Ey Rabbim, verdiğin sözü tuttun; Artık ben, kulun huzur içinde ölebilirim*fx*."},{"n":"30-32","t":"Çünkü senin sağladığın, Bütün halkların gözü önünde hazırladığın kurtuluşu, Ulusları aydınlatıp Halkın İsrail'e yücelik kazandıracak ışığı Gözlerimle gördüm.\""},{"n":"33","t":"İsa'nın annesiyle babası, O'nun hakkında söylenenlere şaştılar."},{"n":"34","t":"Şimon onları kutsayıp çocuğun annesi Meryem'e şöyle dedi: \"Bu çocuk, İsrail'de birçok kişinin düşmesine ya da yükselmesine yol açmak ve aleyhinde konuşulacak bir belirti olmak üzere belirlenmiştir."},{"n":"35","t":"Senin kalbine de adeta bir kılıç saplanacak. Bütün bunlar, birçoklarının yüreğindeki düşüncelerin açığa çıkması için olacak.\""},{"n":"36-37","t":"Anna adında çok yaşlı bir kadın peygamber vardı. Aşer oymağından Fanuel'in kızıydı. Genç kız olarak evlenip kocasıyla yedi yıl yaşadıktan sonra dul kalmıştı. Şimdi seksen dört yaşındaydı. Tapınaktan ayrılmaz, oruç tutup dua ederek gece gündüz Tanrı'ya tapınırdı."},{"n":"38","t":"Tam o sırada ortaya çıkan Anna, Tanrı'ya şükrederek Yeruşalim'in kurtuluşunu bekleyen herkese İsa'dan söz etmeye başladı."},{"n":"39","t":"Yusuf'la Meryem, Rab'bin Yasası'nda öngörülen her şeyi yerine getirdikten sonra Celile'ye, kendi kentleri Nasıra'ya döndüler."},{"n":"40","t":"Çocuk büyüyor, güçleniyor ve bilgelikte yetkinleşiyordu. Tanrı'nın lütfu O'nun üzerindeydi. İsa Tapınakta"},{"n":"41","t":"İsa'nın annesi babası her yıl Fısıh Bayramı'nda* Yeruşalim'e giderlerdi."},{"n":"42","t":"İsa on iki yaşına gelince, bayram geleneğine uyarak yine gittiler."},{"n":"43-44","t":"Bayramdan sonra eve dönerlerken küçük İsa Yeruşalim'de kaldı. Bunu farketmeyen annesiyle babası, çocuğun yol arkadaşlarıyla birlikte olduğunu sanarak bir günlük yol gittiler. Sonra O'nu akrabalar ve dostlar arasında aramaya başladılar."},{"n":"45","t":"Bulamayınca O'nu araya araya Yeruşalim'e döndüler."},{"n":"46","t":"Üç gün sonra O'nu tapınakta buldular. Din öğretmenleri arasında oturmuş, onları dinliyor, sorular soruyordu."},{"n":"47","t":"O'nu dinleyen herkes, zekâsına ve verdiği yanıtlara hayran kalıyordu."},{"n":"48","t":"Annesiyle babası O'nu görünce şaşırdılar. Annesi, \"Çocuğum, bize bunu niçin yaptın? Bak, babanla ben büyük kaygı içinde seni arayıp durduk\" dedi."},{"n":"49","t":"O da onlara, \"Beni niçin arayıp durdunuz?\" dedi. \"Babam'ın evinde bulunmam gerektiğini bilmiyor muydunuz?\""},{"n":"50","t":"Ne var ki onlar ne demek istediğini anlamadılar."},{"n":"51","t":"İsa onlarla birlikte yola çıkıp Nasıra'ya döndü. Onların sözünü dinlerdi. Annesi bütün bu olup bitenleri yüreğinde sakladı."},{"n":"52","t":"İsa bilgelikte ve boyda gelişiyor, Tanrı'nın ve insanların beğenisini kazanıyordu."}]},{"ch":3,"verses":[{"n":"1","t":"Sezar* Tiberius'un egemenliğinin on beşinci yılıydı. Yahudiye'de Pontius Pilatus valilik yapıyordu. Celile'yi Hirodes*, İtureya ve Trahonitis bölgesini Hirodes'in kardeşi Filipus, Avilini'yi Lisanias yönetiyordu."},{"n":"2","t":"Hanan ile Kayafa başkâhinlik ediyorlardı. Bu sırada Tanrı çölde bulunan Zekeriya oğlu Yahya'ya seslendi."},{"n":"3","t":"O da Şeria Irmağı'nın çevresindeki bütün bölgeyi dolaşarak insanları, günahlarının bağışlanması için tövbe edip vaftiz* olmaya çağırdı."},{"n":"4","t":"Nitekim Peygamber Yeşaya'nın sözlerini içeren kitapta şöyle yazılmıştır: \"Çölde haykıran, 'Rab'bin yolunu hazırlayın, Geçeceği patikaları düzleyin' diye sesleniyor."},{"n":"5","t":"'Her vadi doldurulacak, Her dağ ve her tepe alçaltılacak. Dolambaçlı yollar doğrultulacak, Engebeli yollar düzleştirilecek."},{"n":"6","t":"Ve bütün insanlar Tanrı'nın sağladığı kurtuluşu görecektir.'\""},{"n":"7","t":"Yahya, vaftiz olmak için kendisine gelen kalabalıklara şöyle seslendi: \"Ey engerekler soyu! Gelecek gazaptan kaçmak için sizi kim uyardı?"},{"n":"8","t":"Bundan böyle tövbeye yaraşır meyveler verin! Kendi kendinize, 'Biz İbrahim'in soyundanız' demeye kalkmayın. Ben size şunu söyleyeyim: Tanrı, İbrahim'e şu taşlardan da çocuk yaratabilir."},{"n":"9","t":"Balta ağaçların köküne dayanmış bile. İyi meyve vermeyen her ağaç kesilip ateşe atılır.\""},{"n":"10","t":"Halk ona, \"Öyleyse biz ne yapalım?\" diye sordu."},{"n":"11","t":"Yahya onlara, \"İki mintanı olan birini mintanı olmayana versin; yiyeceği olan yiyeceği olmayanla paylaşsın\" yanıtını verdi."},{"n":"12","t":"Bazı vergi görevlileri* de vaftiz olmaya gelerek, \"Öğretmenimiz, biz ne yapalım?\" dediler."},{"n":"13","t":"Yahya, \"Size buyrulandan çok vergi almayın\" dedi."},{"n":"14","t":"Bazı askerler de, \"Ya biz ne yapalım?\" diye sordular. O da, \"Kaba kuvvetle ya da yalan suçlamalarla kimseden para koparmayın\" dedi, \"Ücretinizle yetinin.\""},{"n":"15","t":"Halk umut içinde bekliyordu. Yahya'yla ilgili olarak herkesin aklında, \"Acaba Mesih* bu mu?\" sorusu vardı."},{"n":"16","t":"Yahya ise hepsine şöyle yanıt verdi: \"Ben sizi suyla vaftiz ediyorum, ama benden daha güçlü Olan geliyor. Ben O'nun çarıklarının bağını çözmeye bile layık değilim. O sizi Kutsal Ruh'la ve ateşle vaftiz edecek."},{"n":"17","t":"Harman yerini temizlemek ve buğdayı toplayıp ambarına yığmak için yabası elinde hazır duruyor. Samanı ise sönmeyen ateşte yakacak.\""},{"n":"18","t":"Yahya başka birçok konuda halka çağrıda bulunuyor, Müjde'yi duyuruyordu."},{"n":"19-20","t":"Ne var ki bölgenin kralı* Hirodes, kardeşinin karısı Hirodiya'yla ilgili olayı ve kendi yapmış olduğu bütün kötülükleri yüzüne vuran Yahya'yı hapse attırarak kötülüklerine bir yenisini ekledi. İsa'nın Vaftiz Olması (Mat.3:13-17; Mar.1:9-11)"},{"n":"21-22","t":"Bütün halk vaftiz olduktan sonra İsa da vaftiz oldu. Dua ederken gök açıldı ve Kutsal Ruh, bedensel görünümde, güvercin gibi O'nun üzerine indi. Gökten, \"Sen benim sevgili Oğlum'sun, senden hoşnudum\" diyen bir ses duyuldu. İsa'nın Soyu (Mat.1:1-17)"},{"n":"23","t":"İsa görevine başladığı zaman otuz yaşlarındaydı. Yusuf'un oğlu olduğu sanılıyordu. Yusuf da Eli oğlu,"},{"n":"24","t":"Mattat oğlu, Levi oğlu, Malki oğlu, Yannay oğlu, Yusuf oğlu,"},{"n":"25","t":"Mattitya oğlu, Amos oğlu, Nahum oğlu, Hesli oğlu, Nagay oğlu,"},{"n":"26","t":"Mahat oğlu, Mattitya oğlu, Şimi oğlu, Yosek oğlu, Yoda oğlu,"},{"n":"27","t":"Yohanan oğlu, Reşa oğlu, Zerubbabil oğlu, Şealtiel oğlu, Neri oğlu,"},{"n":"28","t":"Malki oğlu, Addi oğlu, Kosam oğlu, Elmadam oğlu, Er oğlu,"},{"n":"29","t":"Yeşu oğlu, Eliezer oğlu, Yorim oğlu, Mattat oğlu, Levi oğlu,"},{"n":"30","t":"Şimon oğlu, Yahuda oğlu, Yusuf oğlu, Yonam oğlu, Elyakim oğlu,"},{"n":"31","t":"Mala oğlu, Menna oğlu, Mattata oğlu, Natan oğlu, Davut oğlu,"},{"n":"32","t":"İşay oğlu, Ovet oğlu, Boaz oğlu, Salmon*fx* oğlu, Nahşon oğlu,"},{"n":"33","t":"Amminadav oğlu, Ram oğlu*fx*, Hesron oğlu, Peres oğlu, Yahuda oğlu,"},{"n":"34","t":"Yakup oğlu, İshak oğlu, İbrahim oğlu, Terah oğlu, Nahor oğlu,"},{"n":"35","t":"Seruk oğlu, Reu oğlu, Pelek oğlu, Ever oğlu, Şelah oğlu,"},{"n":"36","t":"Kenan oğlu, Arpakşat oğlu, Sam oğlu, Nuh oğlu, Lemek oğlu,"},{"n":"37","t":"Metuşelah oğlu, Hanok oğlu, Yeret oğlu, Mahalalel oğlu, Kenan oğlu,"},{"n":"38","t":"Enoş oğlu, Şit oğlu, Adem oğlu, Tanrı Oğlu'ydu."}]},{"ch":4,"verses":[{"n":"1-2","t":"Kutsal Ruh'la dolu olarak Şeria Irmağı'ndan dönen İsa, Ruh'un yönlendirmesiyle çölde dolaştırılarak kırk gün İblis tarafından denendi. O günlerde hiçbir şey yemedi. Dolayısıyla bu süre sonunda acıktı."},{"n":"3","t":"Bunun üzerine İblis O'na, \"Tanrı'nın Oğlu'ysan, şu taşa söyle ekmek olsun\" dedi."},{"n":"4","t":"İsa, \"'İnsan yalnız ekmekle yaşamaz' diye yazılmıştır\" karşılığını verdi."},{"n":"5","t":"Sonra İblis İsa'yı yükseklere çıkararak bir anda O'na dünyanın bütün ülkelerini gösterdi."},{"n":"6","t":"O'na, \"Bütün bunların yönetimini ve zenginliğini sana vereceğim\" dedi. \"Bunlar bana teslim edildi, ben de dilediğim kişiye veririm."},{"n":"7","t":"Bana taparsan, hepsi senin olacak.\""},{"n":"8","t":"İsa ona şu karşılığı verdi: \"'Tanrın Rab'be tapacak, yalnız O'na kulluk edeceksin' diye yazılmıştır.\""},{"n":"9","t":"İblis O'nu Yeruşalim'e götürüp tapınağın tepesine çıkardı. \"Tanrı'nın Oğlu'ysan, kendini buradan aşağı at\" dedi."},{"n":"10","t":"\"Çünkü şöyle yazılmıştır: 'Tanrı, seni korumaları için Meleklerine buyruk verecek.'"},{"n":"11","t":"'Ayağın bir taşa çarpmasın diye Seni elleri üzerinde taşıyacaklar.'\""},{"n":"12","t":"İsa ona şöyle karşılık verdi: \"'Tanrın Rab'bi denemeyeceksin!' diye buyrulmuştur.\""},{"n":"13","t":"İblis, İsa'yı her bakımdan denedikten sonra bir süre için O'nun yanından ayrıldı. İsa Celile'de (Mat.4:12-17; Mar.1:14-15)"},{"n":"14","t":"İsa, Ruh'un gücüyle donanmış olarak Celile'ye döndü. Haber bütün bölgeye yayıldı."},{"n":"15","t":"Oranın havralarında öğretiyor, herkes tarafından övülüyordu."},{"n":"16-17","t":"İsa, büyüdüğü Nasıra Kenti'ne geldiğinde her zamanki gibi Şabat Günü* havraya gitti. Kutsal Yazılar'ı okumak üzere ayağa kalkınca O'na Peygamber Yeşaya'nın Kitabı verildi. Kitabı açarak şu sözlerin yazılı olduğu yeri buldu:"},{"n":"18-19","t":"\"Rab'bin Ruhu üzerimdedir. Çünkü O beni yoksullara Müjde'yi iletmek için meshetti*. Tutsaklara serbest bırakılacaklarını, Körlere gözlerinin açılacağını duyurmak için, Ezilenleri özgürlüğe kavuşturmak Ve Rab'bin lütuf yılını ilan etmek için Beni gönderdi.\""},{"n":"20","t":"Sonra kitabı kapattı, görevliye geri verip oturdu. Havradakilerin hepsi dikkatle O'na bakıyordu."},{"n":"21","t":"İsa, \"Dinlediğiniz bu Yazı bugün yerine gelmiştir\" diye konuşmaya başladı."},{"n":"22","t":"Herkes İsa'yı övüyor, ağzından çıkan lütufkâr sözlere hayran kalıyordu. \"Yusuf'un oğlu değil mi bu?\" diyorlardı."},{"n":"23","t":"İsa onlara şöyle dedi: \"Kuşkusuz bana şu deyimi hatırlatacaksınız: 'Ey hekim, önce kendini iyileştir! Kefarnahum'da yaptıklarını duyduk. Aynısını burada, kendi memleketinde de yap.'\""},{"n":"24","t":"\"Size doğrusunu söyleyeyim\" diye devam etti İsa, \"Hiçbir peygamber kendi memleketinde kabul görmez."},{"n":"25","t":"Yine size gerçeği söyleyeyim, gökyüzünün üç yıl altı ay kapalı kaldığı, bütün ülkede korkunç bir kıtlığın baş gösterdiği İlyas zamanında İsrail'de çok sayıda dul kadın vardı."},{"n":"26","t":"İlyas bunlardan hiçbirine gönderilmedi; yalnız Sayda bölgesinin Sarefat Kenti'nde bulunan dul bir kadına gönderildi."},{"n":"27","t":"Peygamber Elişa'nın zamanında İsrail'de çok sayıda cüzamlı* vardı. Bunlardan hiçbiri iyileştirilmedi; yalnız Suriyeli Naaman iyileştirildi.\""},{"n":"28","t":"Havradakiler bu sözleri duyunca öfkeden kudurdular."},{"n":"29","t":"Ayağa kalkıp İsa'yı kentin dışına kovdular. O'nu uçurumdan aşağı atmak için kentin kurulduğu tepenin yamacına götürdüler."},{"n":"30","t":"Ama İsa onların arasından geçerek oradan uzaklaştı. İsa Kötü Bir Ruhu Kovuyor (Mar.1:21-28)"},{"n":"31","t":"Sonra İsa Celile'nin Kefarnahum Kenti'ne gitti. Şabat Günü* halka öğretiyordu."},{"n":"32","t":"Yetkiyle konuştuğu için O'nun öğretişine şaşıp kaldılar."},{"n":"33-34","t":"Havrada cinli, içinde kötü ruh olan bir adam vardı. Adam yüksek sesle, \"Ey Nasıralı İsa, bırak bizi! Bizden ne istiyorsun?\" diye bağırdı. \"Bizi mahvetmeye mi geldin? Senin kim olduğunu biliyorum, Tanrı'nın Kutsalı'sın sen!\""},{"n":"35","t":"İsa, \"Sus, çık adamdan!\" diyerek cini azarladı. Cin adamı herkesin önünde yere vurduktan sonra, ona hiç zarar vermeden içinden çıktı."},{"n":"36","t":"Herkes şaşkına dönmüştü. Birbirlerine, \"Bu nasıl söz? Güç ve yetkiyle kötü ruhlara çıkmalarını buyuruyor, onlar da çıkıyor!\" diyorlardı."},{"n":"37","t":"İsa'yla ilgili haber o bölgenin her yanında yankılandı. İsa Birçok Hastayı İyileştiriyor (Mat.8:14-17; Mar.1:29-34)"},{"n":"38","t":"İsa havradan ayrılarak Simun'un evine gitti. Simun'un kaynanası hastaydı, ateşler içindeydi. Onun için İsa'dan yardım istediler."},{"n":"39","t":"İsa kadının başucunda durup ateşi azarladı, kadının ateşi düştü. Kadın hemen ayağa kalkıp onlara hizmet etmeye başladı."},{"n":"40","t":"Güneş batarken herkes çeşitli hastalıklara yakalanmış akrabalarını İsa'ya getirdi. İsa her birinin üzerine ellerini koyarak onları iyileştirdi."},{"n":"41","t":"Birçoğunun içinden cinler de, \"Sen Tanrı'nın Oğlu'sun!\" diye bağırarak çıkıyordu. Ne var ki, İsa onları azarladı, konuşmalarına izin vermedi. Çünkü kendisinin Mesih* olduğunu biliyorlardı."},{"n":"42","t":"Sabah olunca İsa dışarı çıkıp ıssız bir yere gitti. Halk ise O'nu arıyordu. Bulunduğu yere geldiklerinde O'nu yanlarında alıkoymaya çalıştılar."},{"n":"43","t":"Ama İsa, \"Öbür kentlerde de Tanrı'nın Egemenliği'yle ilgili Müjde'yi yaymam gerek\" dedi. \"Çünkü bunun için gönderildim.\""},{"n":"44","t":"Böylece Yahudiye'deki*fx* havralarda Tanrı sözünü duyurmaya devam etti."}]},{"ch":5,"verses":[{"n":"1","t":"Halk, Ginnesar Gölü'nün kıyısında duran İsa'nın çevresini sarmış, Tanrı'nın sözünü dinliyordu."},{"n":"2","t":"İsa, gölün kıyısında iki tekne gördü. Balıkçılar teknelerinden inmiş ağlarını yıkıyorlardı."},{"n":"3","t":"İki tekneden Simun'a ait olanına binen İsa, ona kıyıdan biraz açılmasını rica etti. Sonra oturdu, teknenin içinden halka öğretmeye devam etti."},{"n":"4","t":"Konuşmasını bitirince Simun'a, \"Derin sulara açılın, balık tutmak için ağlarınızı atın\" dedi."},{"n":"5","t":"Simun şu karşılığı verdi: \"Efendimiz, bütün gece çabaladık, hiçbir şey tutamadık. Yine de senin sözün üzerine ağları atacağım.\""},{"n":"6","t":"Bunu yapınca öyle çok balık yakaladılar ki, ağları yırtılmaya başladı."},{"n":"7","t":"Öbür teknedeki ortaklarına işaret ederek gelip yardım etmelerini istediler. Onlar da geldiler ve her iki tekneyi balıkla doldurdular; tekneler neredeyse batıyordu."},{"n":"8","t":"Simun Petrus bunu görünce, \"Ya Rab, benden uzak dur, ben günahlı bir adamım\" diyerek İsa'nın dizlerine kapandı."},{"n":"9","t":"Kendisi ve yanındakiler, tutmuş oldukları balıkların çokluğuna şaşıp kalmışlardı."},{"n":"10","t":"Simun'un ortakları olan Zebedi oğulları Yakup'la Yuhanna'yı da aynı şaşkınlık almıştı. İsa Simun'a, \"Korkma\" dedi, \"Bundan böyle balık yerine insan tutacaksın.\""},{"n":"11","t":"Sonra onlar tekneleri karaya çektiler ve her şeyi bırakıp İsa'nın ardından gittiler. İsa Bir Cüzamlıyı İyileştiriyor (Mat.8:1-4; Mar.1:40-45)"},{"n":"12","t":"İsa kentlerden birindeyken, her yanını cüzam* kaplamış bir adamla karşılaştı. Adam İsa'yı görünce yüzüstü yere kapanıp yalvardı: \"Ya Rab, istersen beni temiz kılabilirsin\" dedi."},{"n":"13","t":"İsa elini uzatıp adama dokundu, \"İsterim, temiz ol!\" dedi. Adam anında cüzamdan kurtuldu."},{"n":"14","t":"İsa ona, bundan kimseye söz etmemesini buyurdu. \"Git, kâhine* görün ve cüzamdan temizlendiğini herkese kanıtlamak için Musa'nın buyurduğu sunuları sun\" dedi."},{"n":"15","t":"Ne var ki, İsa'yla ilgili haber daha da çok yayıldı. Kalabalık halk toplulukları İsa'yı dinlemek ve hastalıklarından kurtulmak amacıyla akın akın geliyordu."},{"n":"16","t":"Kendisi ise ıssız yerlere çekilip dua ediyordu. Bir Felçlinin İyileştirilmesi (Mat.9:1-8; Mar.2:1-12)"},{"n":"17","t":"Bir gün İsa öğretiyordu. Celile'nin ve Yahudiye'nin bütün köylerinden ve Yeruşalim'den gelen Ferisiler'le* Kutsal Yasa öğretmenleri O'nun çevresinde oturuyorlardı. İsa, Rab'bin gücü sayesinde hastaları iyileştiriyordu."},{"n":"18","t":"O sırada birkaç kişi, yatak üzerinde taşıdıkları felçli bir adamı evden içeri sokup İsa'nın önüne koymaya çalışıyordu."},{"n":"19","t":"Kalabalıktan ötürü onu içeri sokacak yol bulamayınca dama çıktılar, kiremitleri kaldırıp adamı yatakla birlikte orta yere, İsa'nın önüne indirdiler."},{"n":"20","t":"İsa onların imanını görünce, \"Dostum, günahların bağışlandı\" dedi."},{"n":"21","t":"Din bilginleriyle* Ferisiler, \"Tanrı'ya küfreden bu adam kim? Tanrı'dan başka kim günahları bağışlayabilir?\" diye düşünmeye başladılar."},{"n":"22","t":"Akıllarından geçenleri bilen İsa onlara şöyle seslendi: \"Aklınızdan neden böyle şeyler geçiriyorsunuz?"},{"n":"23","t":"Hangisi daha kolay, 'Günahların bağışlandı' demek mi, yoksa 'Kalk, yürü' demek mi?"},{"n":"24","t":"Ne var ki, İnsanoğlu'nun* yeryüzünde günahları bağışlama yetkisine sahip olduğunu bilesiniz diye...\" Sonra felçli adama, \"Sana söylüyorum, kalk, yatağını toplayıp evine git!\" dedi."},{"n":"25","t":"Adam onların gözü önünde hemen ayağa kalktı, üzerinde yattığı yatağı topladı ve Tanrı'yı yücelterek evine gitti."},{"n":"26","t":"Herkesi bir şaşkınlık almıştı. Tanrı'yı yüceltiyor, büyük korku içinde, \"Bugün şaşılacak işler gördük!\" diyorlardı. Levi'nin Öğrencilere Katılması (Mat.9:9-13; Mar.2:13-17)"},{"n":"27","t":"Bu olaydan sonra İsa dışarı çıktı, vergi toplama yerinde oturan Levi adında bir vergi görevlisini* gördü. Adama, \"Ardımdan gel\" dedi."},{"n":"28","t":"O da kalktı, her şeyi bırakıp İsa'nın ardından gitti."},{"n":"29","t":"Sonra Levi, evinde İsa'nın onuruna büyük bir şölen verdi. Vergi görevlileriyle başka kişilerden oluşan büyük bir kalabalık onlarla birlikte yemeğe oturmuştu."},{"n":"30","t":"Ferisiler'le onların din bilginleri söylenmeye başladılar. İsa'nın öğrencilerine, \"Siz neden vergi görevlileri ve günahkârlarla birlikte yiyip içiyorsunuz?\" dediler."},{"n":"31","t":"İsa onlara şu karşılığı verdi: \"Sağlıklı olanların değil, hastaların hekime ihtiyacı var."},{"n":"32","t":"Ben doğru kişileri değil, günahkârları tövbeye çağırmaya geldim.\" Oruçla İlgili Soru (Mat.9:14-17; Mar.2:18-22)"},{"n":"33","t":"Onlar İsa'ya, \"Yahya'nın öğrencileri sık sık oruç tutup dua ediyorlar, Ferisiler'in öğrencileri de öyle. Seninkiler ise yiyip içiyor\" dediler."},{"n":"34","t":"İsa şöyle karşılık verdi: \"Güvey aralarında olduğu sürece davetlilere oruç tutturabilir misiniz?"},{"n":"35","t":"Ama güveyin aralarından alınacağı günler gelecek, onlar işte o zaman, o günler oruç tutacaklar.\""},{"n":"36","t":"İsa onlara şu benzetmeyi de anlattı: \"Hiç kimse yeni giysiden bir parça yırtıp eski giysiyi yamamaz. Yoksa hem yeni giysi yırtılır, hem de o giysiden koparılan yama eskisine uymaz."},{"n":"37","t":"Hiç kimse yeni şarabı eski tulumlara doldurmaz. Yoksa yeni şarap tulumları patlatır; hem şarap dökülür, hem de tulumlar mahvolur."},{"n":"38","t":"Yeni şarabı yeni tulumlara doldurmak gerek."},{"n":"39","t":"Üstelik hiç kimse eski şarabı içtikten sonra yenisini istemez. 'Eskisi güzel' der.\""}]},{"ch":6,"verses":[{"n":"1","t":"Bir Şabat Günü* İsa ekinler arasından geçiyordu. Öğrencileri başakları koparıyor, avuçlarında ufalayıp yiyorlardı."},{"n":"2","t":"Ferisiler'den bazıları, \"Şabat Günü yasak olanı neden yapıyorsunuz?\" dediler."},{"n":"3","t":"İsa onlara şöyle karşılık verdi: \"Davut'la yanındakiler acıkınca Davut'un ne yaptığını okumadınız mı?"},{"n":"4","t":"Tanrı'nın evine girdi, kâhinlerden başkasının yemesi yasak olan adak ekmeklerini* alıp yedi ve yanındakilere de verdi.\""},{"n":"5","t":"Sonra İsa onlara, \"İnsanoğlu* Şabat Günü'nün de Rabbi'dir\" dedi."},{"n":"6","t":"Bir başka Şabat Günü İsa havraya girmiş öğretiyordu. Orada sağ eli sakat bir adam vardı."},{"n":"7","t":"İsa'yı suçlamak için fırsat kollayan din bilginleriyle Ferisiler, Şabat Günü hastaları iyileştirecek mi diye O'nu gözlüyorlardı."},{"n":"8","t":"İsa, onların ne düşündüklerini biliyordu. Eli sakat olan adama, \"Ayağa kalk, öne çık\" dedi. O da kalktı, orta yerde durdu."},{"n":"9","t":"İsa onlara, \"Size sorayım\" dedi, \"Kutsal Yasa'ya göre Şabat Günü iyilik yapmak mı doğru, kötülük yapmak mı? Can kurtarmak mı doğru, öldürmek mi?\""},{"n":"10","t":"Gözlerini hepsinin üzerinde gezdirdikten sonra adama, \"Elini uzat\" dedi. Adam elini uzattı, eli yine sapasağlam oluverdi."},{"n":"11","t":"Onlar ise öfkeden deliye döndüler ve aralarında İsa'ya ne yapabileceklerini tartışmaya başladılar. İsa On İki Elçisini Seçiyor (Mat.10:1-4; Mar.3:13-19)"},{"n":"12","t":"O günlerde İsa, dua etmek için dağa çıktı ve bütün geceyi Tanrı'ya dua ederek geçirdi."},{"n":"13-16","t":"Gün doğunca öğrencilerini yanına çağırdı ve onların arasından, elçi diye adlandırdığı şu on iki kişiyi seçti: Petrus adını verdiği Simun, onun kardeşi Andreas, Yakup, Yuhanna, Filipus, Bartalmay, Matta, Tomas, Alfay oğlu Yakup, Yurtsever* diye tanınan Simun, Yakup oğlu Yahuda ve İsa'ya ihanet eden Yahuda İskariot."},{"n":"17","t":"İsa bunlarla birlikte aşağı inip düzlük bir yerde durdu. Öğrencilerinden büyük bir kalabalık ve bütün Yahudiye'den, Yeruşalim'den, Sur'la Sayda yakınlarındaki kıyı bölgesinden gelen büyük bir halk topluluğu da oradaydı."},{"n":"18","t":"İsa'yı dinlemek ve hastalıklarına şifa bulmak için gelmişlerdi. Kötü ruhlar yüzünden sıkıntı çekenler de iyileştiriliyordu."},{"n":"19","t":"Kalabalıkta herkes İsa'ya dokunmak için çabalıyordu. Çünkü O'nun içinden akan bir güç herkese şifa veriyordu. Mutlular ve Mutsuzlar (Mat.5:1-12)"},{"n":"20","t":"İsa, gözlerini öğrencilerine çevirerek şöyle dedi: \"Ne mutlu size, ey yoksullar! Çünkü Tanrı'nın Egemenliği sizindir."},{"n":"21","t":"Ne mutlu size, şimdi açlık çekenler! Çünkü doyurulacaksınız. Ne mutlu size, şimdi ağlayanlar! Çünkü güleceksiniz."},{"n":"22","t":"İnsanoğlu'na* bağlılığınız yüzünden İnsanlar sizden nefret ettikleri, Sizi toplum dışı edip aşağıladıkları Ve adınızı kötüleyip sizi reddettikleri zaman Ne mutlu size!"},{"n":"23","t":"O gün sevinin, coşkuyla zıplayın! Çünkü gökteki ödülünüz büyüktür. Nitekim onların ataları da Peygamberlere böyle davrandılar."},{"n":"24","t":"Ama vay halinize, ey zenginler, Çünkü tesellinizi almış bulunuyorsunuz!"},{"n":"25","t":"Vay halinize, şimdi karnı tok olan sizler, Çünkü açlık çekeceksiniz! Vay halinize, ey şimdi gülenler, Çünkü yas tutup ağlayacaksınız!"},{"n":"26","t":"Bütün insanlar sizin için iyi sözler söyledikleri zaman, Vay halinize! Çünkü onların ataları da Sahte peygamberlere böyle davrandılar.\" Düşmanlarınızı Sevin (Mat.5:38-48; 7:12)"},{"n":"27-28","t":"\"Ama beni dinleyen sizlere şunu söylüyorum: Düşmanlarınızı sevin, sizden nefret edenlere iyilik yapın, size lanet edenler için iyilik dileyin, size hakaret edenler için dua edin."},{"n":"29","t":"Bir yanağınıza vurana öbür yanağınızı da çevirin. Abanızı alandan mintanınızı da esirgemeyin."},{"n":"30","t":"Sizden bir şey dileyen herkese verin, malınızı alandan onu geri istemeyin."},{"n":"31","t":"İnsanların size nasıl davranmasını istiyorsanız, siz de onlara öyle davranın."},{"n":"32","t":"\"Eğer yalnız sizi sevenleri severseniz, bu size ne övgü kazandırır? Günahkârlar bile kendilerini sevenleri sever."},{"n":"33","t":"Size iyilik yapanlara iyilik yaparsanız, bu size ne övgü kazandırır? Günahkârlar bile böyle yapar."},{"n":"34","t":"Geri alacağınızı umduğunuz kişilere ödünç verirseniz, bu size ne övgü kazandırır? Günahkârlar bile verdiklerini geri almak koşuluyla günahkârlara ödünç verirler."},{"n":"35","t":"Ama siz düşmanlarınızı sevin, iyilik yapın, hiçbir karşılık beklemeden ödünç verin. Alacağınız ödül büyük olacak, Yüceler Yücesi'nin oğulları olacaksınız. Çünkü O, nankör ve kötü kişilere karşı iyi yüreklidir."},{"n":"36","t":"Babanız merhametli olduğu gibi, siz de merhametli olun.\" Başkasını Yargılamayın (Mat.7:1-5)"},{"n":"37","t":"\"Başkasını yargılamayın, siz de yargılanmazsınız. Suçlu çıkarmayın, siz de suçlu çıkarılmazsınız. Başkasını bağışlayın, siz de bağışlanırsınız."},{"n":"38","t":"Verin, size verilecektir. İyice bastırılmış, silkelenmiş ve taşmış, dolu bir ölçekle kucağınıza boşaltılacak. Hangi ölçekle verirseniz, aynı ölçekle alacaksınız.\""},{"n":"39","t":"İsa onlara şu benzetmeyi de anlattı: \"Kör köre kılavuzluk edebilir mi? İkisi de çukura düşmez mi?"},{"n":"40","t":"Öğrenci öğretmeninden üstün değildir, ama eğitimini tamamlayan her öğrenci öğretmeni gibi olacaktır."},{"n":"41","t":"\"Sen neden kardeşinin gözündeki çöpü görürsün de kendi gözündeki merteği farketmezsin?"},{"n":"42","t":"Kendi gözündeki merteği görmezken, kardeşine nasıl, 'Kardeş, izin ver, gözündeki çöpü çıkarayım' dersin? Seni ikiyüzlü! Önce kendi gözündeki merteği çıkar, o zaman kardeşinin gözündeki çöpü çıkarmak için daha iyi görürsün.\" Ağaç ve Meyvesi (Mat.7:16-20; 12:33-35)"},{"n":"43","t":"\"İyi ağaç kötü meyve, kötü ağaç da iyi meyve vermez."},{"n":"44","t":"Her ağaç meyvesinden tanınır. Dikenli bitkilerden incir toplanmaz, çalılardan üzüm devşirilmez."},{"n":"45","t":"İyi insan yüreğindeki iyilik hazinesinden iyilik, kötü insan içindeki kötülük hazinesinden kötülük çıkarır. İnsanın ağzı, yüreğinden taşanı söyler."},{"n":"46","t":"\"Niçin beni 'Ya Rab, ya Rab' diye çağırıyorsunuz da söylediklerimi yapmıyorsunuz?"},{"n":"47","t":"Bana gelen ve sözlerimi duyup uygulayan kişinin kime benzediğini size anlatayım."},{"n":"48","t":"Böyle bir kişi, evini yaparken toprağı kazan, derinlere inip temeli kaya üzerine atan adama benzer. Sel sularıyla kabaran ırmak o eve saldırsa da, onu sarsamaz. Çünkü ev sağlam yapılmıştır."},{"n":"49","t":"Ama sözlerimi duyup da uygulamayan kişi, evini temel koymaksızın toprağın üzerine kuran adama benzer. Kabaran ırmak saldırınca ev hemen çöker. Evin yıkılışı da korkunç olur.\""}]},{"ch":7,"verses":[{"n":"1","t":"İsa, kendisini dinleyen halka bütün bu sözleri söyledikten sonra Kefarnahum'a gitti."},{"n":"2","t":"Orada bir yüzbaşının çok değer verdiği kölesi ölüm döşeğinde hasta yatıyordu."},{"n":"3","t":"İsa'yla ilgili haberleri duyan yüzbaşı, gelip kölesini iyileştirmesini rica etmek üzere O'na Yahudiler'in bazı ileri gelenlerini gönderdi."},{"n":"4","t":"Bunlar İsa'nın yanına gelince içten bir yalvarışla O'na şöyle dediler: \"Bu adam senin yardımına layıktır."},{"n":"5","t":"Çünkü ulusumuzu seviyor. Havramızı yaptıran da kendisidir.\""},{"n":"6","t":"İsa onlarla birlikte yola çıktı. Eve yaklaştığı sırada, yüzbaşı bazı dostlarını yollayıp O'na şu haberi gönderdi: \"Ya Rab, zahmet etme; evime girmene layık değilim."},{"n":"7","t":"Bu yüzden yanına gelmeye de kendimi layık görmedim. Sen yeter ki bir söz söyle, uşağım iyileşir."},{"n":"8","t":"Ben de buyruk altında bir görevliyim, benim de buyruğumda askerlerim var. Birine, 'Git' derim, gider; ötekine, 'Gel' derim, gelir; köleme, 'Şunu yap' derim, yapar.\""},{"n":"9","t":"Bu sözleri duyan İsa yüzbaşıya hayran kaldı. Ardından gelen kalabalığa dönerek, \"Size şunu söyleyeyim\" dedi, \"İsrail'de bile böyle iman görmedim.\""},{"n":"10","t":"Gönderilenler eve döndüklerinde köleyi iyileşmiş buldular. İsa Bir Dulun Oğlunu Diriltiyor"},{"n":"11","t":"Bundan kısa bir süre sonra İsa, Nain denilen bir kente gitti. Öğrencileriyle büyük bir kalabalık O'na eşlik ediyordu."},{"n":"12","t":"İsa kentin kapısına tam yaklaştığı sırada, dul annesinin tek oğlu olan bir adamın cenazesi kaldırılıyordu. Kent halkından büyük bir kalabalık da kadınla birlikteydi."},{"n":"13","t":"Rab kadını görünce ona acıdı. Kadına, \"Ağlama\" dedi."},{"n":"14","t":"Yaklaşıp cenaze sedyesine dokununca sedyeyi taşıyanlar durdu. İsa, \"Delikanlı\" dedi, \"Sana söylüyorum, kalk!\""},{"n":"15","t":"Ölü doğrulup oturdu ve konuşmaya başladı. İsa onu annesine geri verdi."},{"n":"16","t":"Herkesi bir korku almıştı. \"Aramızda büyük bir peygamber ortaya çıktı!\" ve \"Tanrı, halkının yardımına geldi!\" diyerek Tanrı'yı yüceltmeye başladılar."},{"n":"17","t":"İsa'yla ilgili bu haber bütün Yahudiye'ye ve çevre bölgelere yayıldı. İsa ve Vaftizci Yahya (Mat.11:2-19)"},{"n":"18-19","t":"Yahya'nın öğrencileri bütün bu olup bitenleri kendisine bildirdiler. Öğrencilerinden ikisini yanına çağıran Yahya, \"Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?\" diye sormaları için onları Rab'be gönderdi."},{"n":"20","t":"Adamlar İsa'nın yanına gelince şöyle dediler: \"Bizi sana Vaftizci Yahya gönderdi. 'Gelecek Olan sen misin, yoksa başkasını mı bekleyelim?' diye soruyor.\""},{"n":"21","t":"Tam o sırada İsa, çeşitli hastalıklara, illetlere ve kötü ruhlara tutulmuş birçok kişiyi iyileştirdi, birçok körün gözünü açtı."},{"n":"22","t":"Sonra Yahya'nın öğrencilerine şöyle karşılık verdi: \"Gidin, görüp işittiklerinizi Yahya'ya bildirin. Körlerin gözleri açılıyor, kötürümler yürüyor, cüzamlılar temiz kılınıyor, sağırlar işitiyor, ölüler diriliyor ve Müjde yoksullara duyuruluyor."},{"n":"23","t":"Benden ötürü sendeleyip düşmeyene ne mutlu!\""},{"n":"24","t":"Yahya'nın gönderdiği haberciler gittikten sonra İsa, halka Yahya'dan söz etmeye başladı. \"Çöle ne görmeye gittiniz?\" dedi. \"Rüzgarda sallanan bir kamış mı?"},{"n":"25","t":"Söyleyin, ne görmeye gittiniz? Pahalı giysiler giymiş bir adam mı? Oysa şahane giysiler giyip bolluk içinde yaşayanlar kral saraylarında bulunur."},{"n":"26","t":"Öyleyse ne görmeye gittiniz? Bir peygamber mi? Evet! Size şunu söyleyeyim, gördüğünüz kişi peygamberden de üstündür."},{"n":"27","t":"'İşte, habercimi senin önünden gönderiyorum; O önden gidip senin yolunu hazırlayacak' diye yazılmış olan sözler onunla ilgilidir."},{"n":"28","t":"Size şunu söyleyeyim, kadından doğanlar arasında Yahya'dan daha üstün olanı yoktur. Bununla birlikte, Tanrı'nın Egemenliği'nde en küçük olan ondan üstündür.\""},{"n":"29","t":"Yahya tarafından vaftiz edilen halk, hatta vergi görevlileri* bile bunu duyunca Tanrı'nın adil olduğunu doğruladılar."},{"n":"30","t":"Oysa Yahya tarafından vaftiz edilmeye yanaşmayan Ferisiler'le Kutsal Yasa uzmanları, Tanrı'nın kendileriyle ilgili tasarısını reddettiler."},{"n":"31","t":"İsa, \"Bu kuşağın insanlarını neye benzeteyim? Bunlar neye benziyorlar?\" dedi."},{"n":"32","t":"\"Çarşı meydanında oturup birbirlerine, 'Size kaval çaldık, oynamadınız; Ağıt yaktık, ağlamadınız' \\m diye seslenen çocuklara benziyorlar."},{"n":"33","t":"Vaftizci Yahya geldiği zaman oruç tutup şaraptan kaçındı, ona 'cinli' diyorsunuz."},{"n":"34","t":"İnsanoğlu* geldiği zaman yiyip içti. Bu kez de diyorsunuz ki, 'Şu obur ve ayyaş adama bakın! Vergi görevlileri* ve günahkârlarla dost oldu!'"},{"n":"35","t":"Ne var ki bilgelik, onu benimseyen herkes tarafından doğrulanır.\" İsa ve Günahkâr Kadın"},{"n":"36","t":"Ferisiler'den biri İsa'yı yemeğe çağırdı. O da Ferisi'nin evine gidip sofraya oturdu."},{"n":"37-38","t":"O sırada, kentte günahkâr olarak tanınan bir kadın, İsa'nın, Ferisi'nin evinde yemek yediğini öğrenince kaymaktaşından bir kap içinde güzel kokulu yağ getirdi. İsa'nın arkasında, ayaklarının dibinde durup ağlayarak, gözyaşlarıyla O'nun ayaklarını ıslatmaya başladı. Saçlarıyla ayaklarını sildi, öptü ve yağı üzerlerine sürdü."},{"n":"39","t":"İsa'yı evine çağırmış olan Ferisi bunu görünce kendi kendine, \"Bu adam peygamber olsaydı, kendisine dokunan bu kadının kim ve ne tür bir kadın olduğunu, günahkâr biri olduğunu anlardı\" dedi."},{"n":"40","t":"Bunun üzerine İsa Ferisi'ye, \"Simun\" dedi, \"Sana bir söyleyeceğim var.\" O da, \"Buyur, öğretmenim\" dedi."},{"n":"41","t":"\"Tefeciye borçlu iki kişi vardı. Biri beş yüz, öbürü de elli dinar borçluydu."},{"n":"42","t":"Borçlarını ödeyecek güçte olmadıklarından, tefeci her ikisinin de borcunu bağışladı. Buna göre, hangisi onu çok sever?\""},{"n":"43","t":"Simun, \"Sanırım, kendisine daha çok bağışlanan\" diye yanıtladı. İsa ona, \"Doğru söyledin\" dedi."},{"n":"44","t":"Sonra kadına bakarak Simun'a şunları söyledi: \"Bu kadını görüyor musun? Ben senin evine geldim, ayaklarım için bana su vermedin. Bu kadın ise ayaklarımı gözyaşlarıyla ıslatıp saçlarıyla sildi."},{"n":"45","t":"Sen beni öpmedin, ama bu kadın eve girdiğimden beri ayaklarımı öpüp duruyor."},{"n":"46","t":"Sen başıma zeytinyağı sürmedin, ama bu kadın ayaklarıma güzel kokulu yağ sürdü."},{"n":"47","t":"Bu nedenle sana şunu söyleyeyim, kendisinin çok olan günahları bağışlanmıştır. Çok sevgi göstermesinin nedeni budur. Oysa kendisine az bağışlanan, az sever.\""},{"n":"48","t":"Sonra kadına, \"Günahların bağışlandı\" dedi."},{"n":"49","t":"İsa'yla birlikte sofrada oturanlar kendi aralarında, \"Kim bu adam? Günahları bile bağışlıyor!\" şeklinde konuşmaya başladılar."},{"n":"50","t":"İsa ise kadına, \"İmanın seni kurtardı, esenlikle git\" dedi."}]},{"ch":8,"verses":[{"n":"1","t":"Bundan kısa bir süre sonra İsa on iki öğrencisiyle birlikte köy kent dolaşmaya başladı. Tanrı'nın Egemenliği'ni duyurup müjdeliyordu."},{"n":"2-3","t":"Kötü ruhlardan ve hastalıklardan kurtulan bazı kadınlar, içinden yedi cin çıkmış olan Mecdelli denilen Meryem, Hirodes'in* kâhyası Kuza'nın karısı Yohanna, Suzanna ve daha birçokları İsa'yla birlikte dolaşıyordu. Bunlar, kendi olanaklarıyla İsa'ya ve öğrencilerine yardım ediyorlardı. Tohum Benzetmesi (Mat.13:1-23; Mar.4:1-20)"},{"n":"4-5","t":"Büyük bir kalabalığın toplandığı, insanların her kentten kendisine akın akın geldiği bir sırada İsa şu benzetmeyi anlattı: \"Ekincinin biri tohum ekmeye çıktı. Ektiği tohumlardan kimi yol kenarına düştü, ayak altında çiğnenip gökteki kuşlara yem oldu."},{"n":"6","t":"Kimi kayalık yere düştü, filizlenince susuzluktan kuruyup gitti."},{"n":"7","t":"Kimi, dikenler arasına düştü. Filizlerle birlikte büyüyen dikenler filizleri boğdu."},{"n":"8","t":"Kimi ise iyi toprağa düştü, büyüyünce yüz kat ürün verdi.\" Bunları söyledikten sonra, \"İşitecek kulağı olan işitsin!\" diye seslendi."},{"n":"9-10","t":"İsa, bu benzetmenin anlamını kendisinden soran öğrencilerine, \"Tanrı Egemenliği'nin sırlarını bilme ayrıcalığı size verildi\" dedi. \"Ama başkalarına benzetmelerle sesleniyorum. Öyle ki, 'Gördükleri halde görmesinler, Duydukları halde anlamasınlar.'"},{"n":"11","t":"\"Benzetmenin anlamı şudur: Tohum Tanrı'nın sözüdür."},{"n":"12","t":"Yol kenarındakiler sözü işiten kişilerdir. Ama sonra İblis gelir, inanıp kurtulmasınlar diye sözü yüreklerinden alır götürür."},{"n":"13","t":"Kayalık yere düşenler, işittikleri sözü sevinçle kabul eden, ama kök salamadıkları için ancak bir süre inanan kişilerdir. Böyleleri denendikleri zaman imandan dönerler."},{"n":"14","t":"Dikenler arasına düşenler, sözü işiten ama zamanla yaşamın kaygıları, zenginlikleri ve zevkleri içinde boğulan, dolayısıyla olgun ürün vermeyenlerdir."},{"n":"15","t":"İyi toprağa düşenler ise, sözü işitince onu iyi ve sağlam bir yürekte saklayanlardır. Bunlar sabırla dayanarak ürün verirler.\" Her Şey Işığa Çıkacak (Mar.4:21-25)"},{"n":"16","t":"\"Hiç kimse kandil yakıp bunu bir kapla örtmez, ya da yatağın altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar."},{"n":"17","t":"Çünkü açığa çıkarılmayacak gizli hiçbir şey yok; bilinmeyecek, aydınlığa çıkmayacak saklı hiçbir şey yoktur."},{"n":"18","t":"Bunun için, nasıl dinlediğinize dikkat edin. Kimde varsa, ona daha çok verilecek. Ama kimde yoksa, kendisinde var sandığı bile elinden alınacak.\" İsa'nın Yakınları (Mat.12:46-50; Mar.3:31-35)"},{"n":"19","t":"İsa'nın annesiyle kardeşleri O'na geldiler, ama kalabalıktan ötürü kendisine yaklaşamadılar."},{"n":"20","t":"İsa'ya, \"Annenle kardeşlerin dışarıda duruyor, seni görmek istiyorlar\" diye haber verildi."},{"n":"21","t":"İsa haberi getirenlere şöyle karşılık verdi: \"Annemle kardeşlerim, Tanrı'nın sözünü duyup yerine getirenlerdir.\" İsa Fırtınayı Dindiriyor (Mat.8:23-27; Mar.4:35-41)"},{"n":"22","t":"Bir gün İsa öğrencileriyle birlikte bir tekneye binerek onlara, \"Gölün karşı yakasına geçelim\" dedi. Böylece kıyıdan açıldılar."},{"n":"23","t":"Teknede giderlerken İsa uykuya daldı. O sırada gölde fırtına koptu. Tekne su almaya başlayınca tehlikeli bir duruma düştüler."},{"n":"24","t":"Gidip İsa'yı uyandırarak, \"Efendimiz, Efendimiz, öleceğiz!\" dediler. İsa kalkıp rüzgarı ve kabaran dalgaları azarladı. Fırtına dindi ve ortalık sütliman oldu."},{"n":"25","t":"İsa öğrencilerine, \"Nerede imanınız?\" dedi. Onlar korku ve şaşkınlık içindeydiler. Birbirlerine, \"Bu adam kim ki, rüzgara, suya bile buyruk veriyor, onlar da sözünü dinliyor!\" dediler. Cinli Bir Adamın İyileştirilmesi (Mat.8:28-34; Mar.5:1-20)"},{"n":"26","t":"Celile'nin karşısında bulunan Gerasalılar'ın memleketine vardılar."},{"n":"27","t":"İsa karaya çıkınca kentten bir adam O'nu karşıladı. Cinli ve uzun zamandan beri giysi giymeyen bu adam evde değil, mezarlık mağaralarda yaşıyordu."},{"n":"28","t":"Adam İsa'yı görünce çığlık atıp önünde yere kapandı. Yüksek sesle, \"Ey İsa, yüce Tanrı'nın Oğlu, benden ne istiyorsun?\" dedi. \"Sana yalvarırım, bana işkence etme!\""},{"n":"29","t":"Çünkü İsa, kötü ruha adamın içinden çıkmasını buyurmuştu. Kötü ruh adamı sık sık etkisi altına alıyordu. Adam zincir ve kösteklerle bağlanıp başına nöbetçi konulduğu halde bağlarını paralıyor ve cin tarafından ıssız yerlere sürülüyordu."},{"n":"30","t":"İsa ona, \"Adın ne?\" diye sordu. O da, \"Tümen*\" diye yanıtladı. Çünkü onun içine bir sürü cin girmişti."},{"n":"31","t":"Cinler, dipsiz derinliklere gitmelerini buyurmasın diye İsa'ya yalvarıp durdular."},{"n":"32","t":"Orada, dağın yamacında otlayan büyük bir domuz sürüsü vardı. Cinler, domuzların içine girmelerine izin vermesi için İsa'ya yalvardılar. O da onlara izin verdi."},{"n":"33","t":"Adamdan çıkan cinler domuzların içine girdiler. Sürü dik yamaçtan aşağı koşuşarak göle atlayıp boğuldu."},{"n":"34","t":"Domuzları güdenler olup biteni görünce kaçtılar, kentte ve köylerde olayın haberini yaydılar."},{"n":"35","t":"Bunun üzerine halk olup biteni görmeye çıktı. İsa'nın yanına geldikleri zaman, cinlerden kurtulan adamı giyinmiş ve aklı başına gelmiş olarak İsa'nın ayakları dibinde oturmuş buldular ve korktular."},{"n":"36","t":"Olayı görenler, cinli adamın nasıl kurtulduğunu halka anlattılar."},{"n":"37","t":"O zaman Gerasa yöresinden gelen bütün kalabalık büyük bir korkuya kapılarak İsa'nın yanlarından ayrılmasını rica ettiler. O da geri dönmek üzere tekneye bindi."},{"n":"38-39","t":"Cinlerden kurtulan adam İsa'nın yanında kalmak için O'na yalvardı. Ama İsa, \"Evine dön, Tanrı'nın senin için neler yaptığını anlat\" diyerek onu salıverdi. Adam da gitti, İsa'nın kendisi için neler yaptığını bütün kentte duyurdu. Dirilen Kız, İyileşen Kadın (Mat.9:18-26; Mar.5:21-43)"},{"n":"40","t":"Karşı yakaya dönen İsa'yı halk karşıladı. Çünkü herkes O'nu bekliyordu."},{"n":"41","t":"O sırada, havra yöneticisi olan Yair adında bir adam gelip İsa'nın ayaklarına kapandı, evine gelmesi için yalvardı."},{"n":"42","t":"Çünkü on iki yaşlarındaki biricik kızı ölmek üzereydi. İsa oraya giderken kalabalık O'nu her yandan sıkıştırıyordu."},{"n":"43","t":"On iki yıldır kanaması olan bir kadın da oradaydı. Varını yoğunu hekimlere harcamıştı; ama hiçbiri onu iyileştirememişti."},{"n":"44","t":"İsa'nın arkasından yetişip giysisinin eteğine dokundu ve o anda kanaması kesildi."},{"n":"45","t":"İsa, \"Bana kim dokundu?\" dedi. Herkes inkâr ederken Petrus*fx*, \"Efendimiz, kalabalık seni çepeçevre sarmış sıkıştırıyor\" dedi."},{"n":"46","t":"Ama İsa, \"Birisi bana dokundu\" dedi. \"İçimden bir gücün akıp gittiğini hissettim.\""},{"n":"47","t":"Yaptığını gizleyemeyeceğini anlayan kadın titreyerek geldi, İsa'nın ayaklarına kapandı. Bütün halkın önünde, O'na neden dokunduğunu ve o anda nasıl iyileştiğini anlattı."},{"n":"48","t":"İsa ona, \"Kızım\" dedi, \"İmanın seni kurtardı. Esenlikle git.\""},{"n":"49","t":"İsa daha konuşurken havra yöneticisinin evinden biri geldi. Yöneticiye, \"Kızın öldü\" dedi, \"Artık öğretmeni rahatsız etme.\""},{"n":"50","t":"İsa bunu duyunca havra yöneticisine şöyle dedi: \"Korkma, yalnız iman et, kızın kurtulacak.\""},{"n":"51","t":"İsa adamın evine gelince Petrus, Yuhanna, Yakup ve kızın annesi babası dışında hiç kimsenin kendisiyle birlikte içeri girmesine izin vermedi."},{"n":"52","t":"Herkes kız için ağlıyor, dövünüyordu. İsa, \"Ağlamayın\" dedi, \"Kız ölmedi, uyuyor.\""},{"n":"53","t":"Kızın öldüğünü bildikleri için İsa'yla alay ettiler."},{"n":"54","t":"O ise kızın elini tutarak, \"Kızım, kalk!\" diye seslendi."},{"n":"55","t":"Ruhu yeniden bedenine dönen kız hemen ayağa kalktı. İsa, kıza yemek verilmesini buyurdu."},{"n":"56","t":"Kızın annesiyle babası şaşkınlık içindeydi. İsa, olanları hiç kimseye anlatmamaları için onları uyardı."}]},{"ch":9,"verses":[{"n":"1","t":"İsa, Onikiler'i* yanına çağırıp onlara bütün cinler üzerinde ve hastalıkları iyileştirmek için güç ve yetki verdi."},{"n":"2","t":"Sonra onları Tanrı'nın Egemenliği'ni duyurmaya ve hastalara şifa vermeye gönderdi."},{"n":"3","t":"Onlara şöyle dedi: \"Yolculuk için yanınıza hiçbir şey almayın: Ne değnek, ne torba, ne ekmek, ne para, ne de yedek mintan."},{"n":"4","t":"Hangi eve girerseniz, kentten ayrılıncaya dek orada kalın."},{"n":"5","t":"Sizi kabul etmeyenlere gelince, kentten ayrılırken onlara uyarı olsun diye ayaklarınızın tozunu silkin.\""},{"n":"6","t":"Onlar da yola çıktılar, her yerde Müjde'yi yayarak ve hastaları iyileştirerek köy köy dolaştılar."},{"n":"7-8","t":"Bölgenin kralı* Hirodes bütün bu olanları duyunca şaşkına döndü. Çünkü bazıları Yahya'nın ölümden dirildiğini, bazıları İlyas'ın göründüğünü, başkaları ise eski peygamberlerden birinin dirildiğini söylüyordu."},{"n":"9","t":"Hirodes, \"Yahya'nın başını ben kestirdim. Şimdi hakkında böyle haberler duyduğum bu adam kim?\" diyor ve İsa'yı görmenin bir yolunu arıyordu. İsa Beş Bin Kişiyi Doyuruyor (Mat.14:13-21; Mar.6:30-44; Yu.6:1-44)"},{"n":"10","t":"Elçiler geri dönünce, yaptıkları her şeyi İsa'ya anlattılar. Sonra İsa yalnızca onları yanına alıp Beytsayda denilen bir kente çekildi."},{"n":"11","t":"Bunu öğrenen halk O'nun ardından gitti. İsa onları ilgiyle karşıladı, kendilerine Tanrı'nın Egemenliği'nden söz etti ve şifaya ihtiyacı olanları iyileştirdi."},{"n":"12","t":"Günbatımına doğru Onikiler gelip O'na, \"Halkı salıver de çevredeki köylere ve çiftliklere gidip kendilerine barınak ve yiyecek bulsunlar. Çünkü ıssız bir yerdeyiz\" dediler."},{"n":"13","t":"İsa, \"Onlara siz yiyecek verin\" dedi. \"Beş ekmekle iki balıktan başka bir şeyimiz yok\" dediler. \"Yoksa bunca halk için yiyecek almaya biz mi gidelim?\""},{"n":"14","t":"Orada yaklaşık beş bin erkek vardı. İsa öğrencilerine, \"Halkı yaklaşık ellişer kişilik kümeler halinde yere oturtun\" dedi."},{"n":"15","t":"Öğrenciler öyle yapıp herkesi yere oturttular."},{"n":"16","t":"İsa, beş ekmekle iki balığı aldı, gözlerini göğe kaldırarak şükretti; sonra bunları böldü ve halka dağıtmaları için öğrencilerine verdi."},{"n":"17","t":"Herkes yiyip doydu. Artakalan parçalardan on iki sepet dolusu toplandı. Petrus'un Mesih'i Tanıması (Mat.16:13-28; Mar.8:27-9:1)"},{"n":"18","t":"Bir gün İsa tek başına dua ediyordu, öğrencileri de yanındaydı. İsa onlara, \"Halk benim kim olduğumu söylüyor?\" diye sordu."},{"n":"19","t":"Şöyle yanıtladılar: \"Vaftizci Yahya diyorlar. Ama kimi İlyas, kimi de eski peygamberlerden biri dirilmiş, diyor.\""},{"n":"20","t":"İsa onlara, \"Siz ne dersiniz\" dedi, \"Sizce ben kimim?\" Petrus, \"Sen Tanrı'nın Mesihi'sin*\" yanıtını verdi."},{"n":"21","t":"İsa, onları uyararak bunu hiç kimseye söylememelerini buyurdu."},{"n":"22","t":"İnsanoğlu'nun* çok acı çekmesi, ileri gelenler, başkâhinler ve din bilginlerince reddedilmesi, öldürülmesi ve üçüncü gün dirilmesi gerektiğini söyledi."},{"n":"23","t":"Sonra hepsine, \"Ardımdan gelmek isteyen kendini inkâr etsin, her gün çarmıhını yüklenip beni izlesin\" dedi,"},{"n":"24","t":"\"Canını kurtarmak isteyen onu yitirecek, canını benim uğruma yitiren ise onu kurtaracaktır."},{"n":"25","t":"İnsan bütün dünyayı kazanıp da canını yitirirse, canından olursa, bunun kendisine ne yararı olur?"},{"n":"26","t":"Kim benden ve benim sözlerimden utanırsa, İnsanoğlu da kendisinin, Babası'nın ve kutsal meleklerin görkemi içinde geldiğinde o kişiden utanacaktır."},{"n":"27","t":"Size gerçeği söyleyeyim, burada bulunanlar arasında, Tanrı'nın Egemenliği'ni görmeden ölümü tatmayacak olanlar var.\" İsa'nın Görünümü Değişiyor (Mat.17:1-8; Mar.9:2-8)"},{"n":"28","t":"Bu sözleri söyledikten yaklaşık sekiz gün sonra İsa, yanına Petrus, Yuhanna ve Yakup'u alarak dua etmek üzere dağa çıktı."},{"n":"29","t":"İsa dua ederken yüzünün görünümü değişti, giysileri şimşek gibi parıldayan bir beyazlığa büründü."},{"n":"30-31","t":"O anda görkem içinde beliren iki kişi İsa'yla konuşmaya başladılar. Bunlar Musa ile İlyas'tı. İsa'nın yakında Yeruşalim'de gerçekleşecek olan ayrılışını*fx* konuşuyorlardı."},{"n":"32","t":"Petrus ile yanındakilerin üzerine uyku çökmüştü. Ama uykuları iyice dağılınca İsa'nın görkemini ve yanında duran iki kişiyi gördüler."},{"n":"33","t":"Bunlar İsa'nın yanından ayrılırken Petrus İsa'ya, \"Efendimiz\" dedi, \"Burada bulunmamız ne iyi oldu! Üç çardak kuralım: Biri sana, biri Musa'ya, biri de İlyas'a.\" Aslında ne söylediğinin farkında değildi."},{"n":"34","t":"Petrus daha bunları söylerken bir bulut gelip onlara gölge saldı. Bulut onları sarınca korktular."},{"n":"35","t":"Buluttan gelen bir ses, \"Bu benim Oğlum'dur, seçilmiş Olan'dır. O'nu dinleyin!\" dedi."},{"n":"36","t":"Ses kesilince İsa'nın tek başına olduğu görüldü. Öğrenciler bunu gizli tuttular ve o günlerde hiç kimseye gördüklerinden söz etmediler. Cinli Bir Çocuğun İyileştirilmesi (Mat.17:14-23; Mar.9:14-32)"},{"n":"37","t":"Ertesi gün dağdan indikleri zaman, İsa'yı büyük bir kalabalık karşıladı."},{"n":"38","t":"Kalabalığın içinden bir adam, \"Öğretmenim\" diye seslendi, \"Yalvarırım, oğlumu bir gör, o tek çocuğumdur."},{"n":"39","t":"Bir ruh onu yakalıyor, o da birdenbire çığlık atıyor. Ruh onu, ağzından köpükler gelene dek şiddetle sarsıyor. Bedenini yara bere içinde bırakarak güçbela ayrılıyor."},{"n":"40","t":"Ruhu kovmaları için öğrencilerine yalvardım, ama başaramadılar.\""},{"n":"41","t":"İsa şöyle karşılık verdi: \"Ey imansız ve sapmış kuşak! Sizinle daha ne kadar kalıp size katlanacağım? Oğlunu buraya getir.\""},{"n":"42","t":"Çocuk daha İsa'ya yaklaşırken cin onu yere vurup şiddetle sarstı. Ama İsa kötü ruhu azarladı, çocuğu iyileştirerek babasına geri verdi."},{"n":"43-44","t":"Herkes Tanrı'nın büyük gücüne şaşıp kaldı. İsa Ölüp Dirileceğini Tekrar Bildiriyor (Mat.17:22-23; Mar.9:30-32) Herkes İsa'nın bütün yaptıkları karşısında hayret içindeyken, İsa öğrencilerine, \"Şu sözlerime iyice kulak verin\" dedi. \"İnsanoğlu*, insanların eline teslim edilecek.\""},{"n":"45","t":"Onlar bu sözü anlamadılar. Sözü kavramasınlar diye anlamı kendilerinden gizlenmişti. Üstelik İsa'ya bu sözle ilgili soru sormaktan korkuyorlardı. En Büyük Kim? (Mat.18:1-5; Mar.9:33-40)"},{"n":"46","t":"Öğrenciler, aralarında kimin en büyük olduğunu tartışmaya başladılar."},{"n":"47-48","t":"Akıllarından geçeni bilen İsa, küçük bir çocuğu tutup yanına çekti ve onlara şöyle dedi: \"Bu çocuğu benim adım uğruna kabul eden, beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur. Aranızda en küçük kim ise, işte en büyük odur.\""},{"n":"49","t":"Yuhanna buna karşılık, \"Efendimiz\" dedi, \"Senin adınla cin kovan birini gördük, ama bizimle birlikte seni izlemediği için ona engel olmaya çalıştık.\""},{"n":"50","t":"İsa, \"Ona engel olmayın!\" dedi. \"Size karşı olmayan, sizden yanadır.\" Samiriyeliler İsa'yı İstemiyor"},{"n":"51","t":"Göğe alınacağı gün yaklaşınca İsa, kararlı adımlarla Yeruşalim'e doğru yola çıktı."},{"n":"52","t":"Kendi önünden haberciler gönderdi. Bunlar, kendisi için hazırlık yapmak üzere gidip Samiriyeliler'e* ait bir köye girdiler."},{"n":"53","t":"Ama Samiriyeliler İsa'yı kabul etmediler. Çünkü Yeruşalim'e doğru gidiyordu."},{"n":"54","t":"Öğrencilerden Yakup'la Yuhanna bunu görünce, \"Rab, bunları yok etmek için bir buyrukla gökten ateş yağdırmamızı ister misin?\" dediler."},{"n":"55","t":"Ama İsa dönüp onları azarladı."},{"n":"56","t":"Sonra*fx* başka bir köye gittiler. İsa'yı İzlemenin Bedeli (Mat.8:19-22)"},{"n":"57","t":"Yolda giderlerken bir adam İsa'ya, \"Nereye gidersen, senin ardından geleceğim\" dedi."},{"n":"58","t":"İsa ona, \"Tilkilerin ini, kuşların yuvası var, ama İnsanoğlu'nun başını yaslayacak bir yeri yok\" dedi."},{"n":"59","t":"Bir başkasına, \"Ardımdan gel\" dedi. Adam ise, \"İzin ver, önce gidip babamı gömeyim\" dedi."},{"n":"60","t":"İsa ona şöyle dedi: \"Bırak ölüleri, kendi ölülerini kendileri gömsün. Sen gidip Tanrı'nın Egemenliği'ni duyur.\""},{"n":"61","t":"Bir başkası, \"Ya Rab\" dedi, \"Senin ardından geleceğim ama, izin ver, önce evimdekilerle vedalaşayım.\""},{"n":"62","t":"İsa ona, \"Sabanı tutup da geriye bakan, Tanrı'nın Egemenliği'ne layık değildir\" dedi."}]},{"ch":10,"verses":[{"n":"1","t":"Bu olaylardan sonra Rab yetmiş kişi daha görevlendirdi. Bunları ikişer ikişer, kendisinin gideceği her kente, her yere kendi önünden gönderdi."},{"n":"2","t":"Onlara, \"Ürün bol, ama işçi az\" dedi, \"Bu nedenle ürünün sahibi Rab'be yalvarın, ürününü kaldıracak işçiler göndersin."},{"n":"3","t":"Haydi gidin! İşte, sizi kuzular gibi kurtların arasına gönderiyorum."},{"n":"4","t":"Yanınıza ne kese, ne torba, ne de çarık alın. Yolda hiç kimseyle selamlaşmayın."},{"n":"5","t":"Hangi eve girerseniz, önce, 'Bu eve esenlik olsun!' deyin."},{"n":"6","t":"Orada esenliksever biri varsa, dilediğiniz esenlik onun üzerinde kalacak; yoksa, size dönecektir."},{"n":"7","t":"Girdiğiniz evde kalın, size ne verirlerse onu yiyip için. Çünkü işçi ücretini hak eder. Evden eve taşınmayın."},{"n":"8","t":"\"Bir kente girdiğinizde sizi kabul ederlerse, önünüze konulanı yiyin."},{"n":"9","t":"Orada bulunan hastaları iyileştirin ve kendilerine, 'Tanrı'nın Egemenliği size yaklaştı' deyin."},{"n":"10-11","t":"Ama bir kente girdiğinizde sizi kabul etmezlerse, o kentin caddelerine çıkıp şöyle deyin: 'Kentinizden ayaklarımızda kalan tozu bile size karşı silkiyoruz. Yine de şunu bilin ki, Tanrı'nın Egemenliği yaklaştı.'"},{"n":"12","t":"Size şunu söyleyeyim, yargı günü o kentin hali Sodom Kenti'nin halinden beter olacaktır."},{"n":"13","t":"\"Vay haline, ey Horazin! Vay haline, ey Beytsayda! Sizlerde yapılan mucizeler Sur ve Sayda'da yapılmış olsaydı, çoktan çul* kuşanıp kül içinde oturarak tövbe etmiş olurlardı."},{"n":"14","t":"Ama yargı günü sizin haliniz Sur ve Sayda'nın halinden beter olacaktır."},{"n":"15","t":"Ya sen, ey Kefarnahum, göğe mi çıkarılacaksın? Hayır, ölüler diyarına indirileceksin!"},{"n":"16","t":"\"Sizi dinleyen beni dinlemiş olur, sizi reddeden beni reddetmiş olur. Beni reddeden de beni göndereni reddetmiş olur.\""},{"n":"17","t":"Yetmişler sevinç içinde döndüler. \"Ya Rab\" dediler, \"Senin adını andığımızda cinler bile bize boyun eğiyor.\""},{"n":"18","t":"İsa onlara şöyle dedi: \"Şeytan'ın gökten yıldırım gibi düştüğünü gördüm."},{"n":"19","t":"Ben size, yılanları ve akrepleri ayak altında ezmek ve düşmanın bütün gücünü alt etmek için yetki verdim. Hiçbir şey size zarar vermeyecektir."},{"n":"20","t":"Bununla birlikte, ruhların size boyun eğmesine sevinmeyin, adlarınızın gökte yazılmış olmasına sevinin.\""},{"n":"21","t":"O anda İsa Kutsal Ruh'un etkisiyle coşarak şöyle dedi: \"Baba, yerin ve göğün Rabbi! Bu gerçekleri bilge ve akıllı kişilerden gizleyip küçük çocuklara açtığın için sana şükrederim. Evet Baba, senin isteğin buydu."},{"n":"22","t":"\"Babam her şeyi bana teslim etti. Oğul'un kim olduğunu Baba'dan başka kimse bilmez. Baba'nın kim olduğunu da Oğul'dan ve Oğul'un O'nu tanıtmak istediği kişilerden başkası bilmez.\""},{"n":"23","t":"Sonra öğrencilerine dönüp özel olarak şöyle dedi: \"Sizin gördüklerinizi gören gözlere ne mutlu!"},{"n":"24","t":"Size şunu söyleyeyim, nice peygamberler, nice krallar sizin ördüklerinizi görmek istediler, ama göremediler. Sizin işittiklerinizi işitmek istediler, ama işitemediler.\" İyi Samiriyeli"},{"n":"25","t":"Bir Kutsal Yasa uzmanı İsa'yı denemek amacıyla gelip şöyle dedi: \"Öğretmenim, sonsuz yaşamı miras almak için ne yapmalıyım?\""},{"n":"26","t":"İsa ona, \"Kutsal Yasa'da ne yazılmıştır?\" diye sordu. \"Orada ne okuyorsun?\""},{"n":"27","t":"Adam şöyle karşılık verdi: \"Tanrın Rab'bi bütün yüreğinle, bütün canınla, bütün gücünle ve bütün aklınla seveceksin. Komşunu da kendin gibi seveceksin.\""},{"n":"28","t":"İsa ona, \"Doğru yanıt verdin\" dedi. \"Bunu yap ve yaşayacaksın.\""},{"n":"29","t":"Oysa adam kendini haklı çıkarmak isteyerek İsa'ya, \"Peki, komşum kim?\"dedi."},{"n":"30","t":"İsa şöyle yanıt verdi: \"Adamın biri Yeruşalim'den Eriha'ya inerken haydutların eline düştü. Onu soyup dövdüler, yarı ölü bırakıp gittiler."},{"n":"31","t":"Bir rastlantı olarak o yoldan bir kâhin geçiyordu. Adamı görünce yolun öbür yanından geçip gitti."},{"n":"32","t":"Bir Levili* de oraya varıp adamı görünce aynı şekilde geçip gitti."},{"n":"33","t":"O yoldan geçen bir Samiriyeli* ise adamın bulunduğu yere gelip onu görünce, yüreği sızladı."},{"n":"34","t":"Adamın yanına gitti, yaralarının üzerine yağla şarap dökerek sardı. Sonra adamı kendi hayvanına bindirip hana götürdü, onunla ilgilendi."},{"n":"35","t":"Ertesi gün iki dinar çıkararak hancıya verdi. 'Ona iyi bak' dedi, 'Bundan fazla ne harcarsan, dönüşümde sana öderim.'"},{"n":"36","t":"\"Sence bu üç kişiden hangisi haydutlar arasına düşen adama komşu gibi davrandı?\""},{"n":"37","t":"Yasa uzmanı, \"Ona acıyıp yardım eden\" dedi. İsa, \"Git, sen de öyle yap\" dedi. İsa, Marta ve Meryem'in Evinde"},{"n":"38","t":"İsa, öğrencileriyle birlikte yola devam edip bir köye girdi. Marta adında bir kadın İsa'yı evinde konuk etti."},{"n":"39","t":"Marta'nın Meryem adındaki kızkardeşi, Rab'bin ayakları dibine oturmuş O'nun konuşmasını dinliyordu."},{"n":"40","t":"Marta ise işlerinin çokluğundan ötürü telaş içindeydi. İsa'nın yanına gelerek, \"Ya Rab\" dedi, \"Kardeşimin beni hizmet işlerinde yalnız bırakmasına aldırmıyor musun? Ona söyle de bana yardım etsin.\""},{"n":"41","t":"Rab ona şu karşılığı verdi: \"Marta, Marta, sen çok şey için kaygılanıp telaşlanıyorsun."},{"n":"42","t":"Oysa gerekli olan tek bir şey vardır. Meryem iyi olanı seçti ve bu kendisinden alınmayacak.\""}]},{"ch":11,"verses":[{"n":"1","t":"İsa bir yerde dua ediyordu. Duasını bitirince öğrencilerinden biri, \"Ya Rab\"dedi, \"Yahya'nın kendi öğrencilerine öğrettiği gibi sen de bize dua etmesini öğret.\""},{"n":"2","t":"İsa onlara, \"Dua ederken şöyle söyleyin\" dedi: \"Baba, adın kutsal kılınsın. Egemenliğin gelsin."},{"n":"3","t":"Her gün bize gündelik ekmeğimizi ver."},{"n":"4","t":"Günahlarımızı bağışla. Çünkü biz de bize karşı suç işleyen herkesi bağışlıyoruz. Ayartılmamıza izin verme.\""},{"n":"5-7","t":"Sonra şöyle dedi: \"Sizlerden birinin bir arkadaşı olur da gece yarısı ona gidip, 'Arkadaş, bana üç ekmek ödünç ver. Bir arkadaşım yoldan geldi, önüne koyacak bir şeyim yok' derse, öbürü içerden, 'Beni rahatsız etme! Kapı kilitli, çocuklarım da yanımda yatıyor. Kalkıp sana bir şey veremem' der mi hiç?"},{"n":"8","t":"Size şunu söyleyeyim, arkadaşlık gereği kalkıp ona istediğini vermese bile, adamın yüzsüzlüğünden ötürü kalkar, ihtiyacı neyse ona verir."},{"n":"9","t":"\"Ben size şunu söyleyeyim: Dileyin, size verilecek; arayın, bulacaksınız; kapıyı çalın, size açılacaktır."},{"n":"10","t":"Çünkü her dileyen alır, arayan bulur, kapı çalana açılır."},{"n":"11","t":"\"Aranızda hangi baba, ekmek isteyen oğluna taş verir? Ya da balık isterse balık yerine yılan verir?"},{"n":"12","t":"Ya da yumurta isterse ona akrep verir?"},{"n":"13","t":"Sizler kötü yürekli olduğunuz halde çocuklarınıza güzel armağanlar vermeyi biliyorsanız, gökteki Baba'nın, kendisinden dileyenlere Kutsal Ruh'u vereceği çok daha kesin değil mi?\" İsa ve Baalzevul (Mat.12:22-30; Mar.3:20-27)"},{"n":"14","t":"İsa adamın birinden dilsiz bir cini kovuyordu. Cin çıkınca adamın dili çözüldü. Halk hayret içinde kaldı."},{"n":"15","t":"Ama içlerinden bazıları, \"Cinleri, cinlerin önderi Baalzevul'un* gücüyle kovuyor\" dediler."},{"n":"16","t":"Bazıları ise O'nu denemek amacıyla gökten bir belirti göstermesini istediler."},{"n":"17","t":"Onların ne düşündüğünü bilen İsa şöyle dedi: \"Kendi içinde bölünen ülke yıkılır, kendi içinde bölünen ev çöker."},{"n":"18","t":"Şeytan da kendi içinde bölünmüşse, onun egemenliği nasıl ayakta kalabilir? Siz, benim Baalzevul'un gücüyle cinleri kovduğumu söylüyorsunuz."},{"n":"19","t":"Eğer ben cinleri Baalzevul'un gücüyle kovuyorsam, sizin adamlarınız kimin gücüyle kovuyor? Sizi bu durumda kendi adamlarınız yargılayacak."},{"n":"20","t":"Ama ben cinleri Tanrı'nın eliyle kovuyorsam, Tanrı'nın Egemenliği üzerinize gelmiş demektir."},{"n":"21","t":"\"Tepeden tırnağa silahlanmış güçlü bir adam kendi evini koruduğu sürece, malları güvenlik içinde olur."},{"n":"22","t":"Ne var ki, ondan daha güçlü biri saldırıp onu alt ettiğinde güvendiği bütün silahları elinden alır ve mallarını yağmalayarak bölüştürür."},{"n":"23","t":"Benden yana olmayan bana karşıdır, benimle birlikte toplamayan dağıtıyor demektir."},{"n":"24","t":"\"Kötü ruh insandan çıkınca kurak yerlerde dolanıp huzur arar. Bulamayınca da, 'Çıktığım eve, kendi evime döneyim' der."},{"n":"25","t":"Eve gelince orayı süpürülmüş, düzeltilmiş bulur."},{"n":"26","t":"Bunun üzerine gider, kendisinden kötü yedi ruh daha alır ve eve girip yerleşirler. Böylece o kişinin son durumu ilkinden beter olur.\""},{"n":"27","t":"İsa bu sözleri söylerken kalabalığın içinden bir kadın O'na, \"Ne mutlu seni taşımış olan rahme, emzirmiş olan memelere!\" diye seslendi."},{"n":"28","t":"İsa, \"Daha doğrusu, ne mutlu Tanrı'nın sözünü dinleyip uygulayanlara!\" dedi. Yunus'un Belirtisi (Mat.12:38-42)"},{"n":"29","t":"Çevredeki kalabalık büyürken İsa konuşmaya başladı. \"Şimdiki kuşak kötü bir kuşaktır\" dedi. \"Doğaüstü bir belirti istiyor, ama ona Yunus'un belirtisinden başka bir belirti gösterilmeyecek."},{"n":"30","t":"Yunus nasıl Ninova halkına bir belirti olduysa, İnsanoğlu* da bu kuşak için öyle olacaktır."},{"n":"31","t":"Güney Kraliçesi, yargı günü bu kuşağın adamlarıyla birlikte kalkıp onları yargılayacak. Çünkü kraliçe, Süleyman'ın bilgece sözlerini dinlemek için dünyanın ta öbür ucundan gelmişti. Bakın, Süleyman'dan daha üstün olan buradadır."},{"n":"32","t":"Ninova halkı, yargı günü bu kuşakla birlikte kalkıp bu kuşağı yargılayacak. Çünkü Ninovalılar, Yunus'un çağrısı üzerine tövbe ettiler. Bakın, Yunus'tan daha üstün olan buradadır.\" Bedenin Işığı (Mat.5:15; 6:22-23)"},{"n":"33","t":"\"Hiç kimse kandil yakıp onu gizli yere ya da tahıl ölçeğinin altına koymaz. Tersine, içeri girenler ışığı görsünler diye onu kandilliğe koyar."},{"n":"34","t":"Bedenin ışığı gözdür. Gözün sağlamsa, bütün bedenin de aydınlık olur. Gözün bozuksa, bedenin de karanlık olur."},{"n":"35","t":"Öyleyse dikkat et, sendeki 'ışık' karanlık olmasın."},{"n":"36","t":"Eğer bütün bedenin aydınlık olur ve hiçbir yanı karanlık kalmazsa, kandilin seni ışınlarıyla aydınlattığı zamanki gibi, bedenin tümden aydınlık olur.\" Vay Halinize, Ferisiler! (Mat.23:1-36; 12:38-40)"},{"n":"37","t":"İsa konuşmasını bitirince bir Ferisi* O'nu evine yemeğe çağırdı. O da içeri girerek sofraya oturdu."},{"n":"38","t":"İsa'nın yemekten önce yıkanmadığını gören Ferisi şaştı."},{"n":"39","t":"Rab ona şöyle dedi: \"Siz Ferisiler, bardağın ve tabağın dışını temizlersiniz, ama içiniz açgözlülük ve kötülükle doludur."},{"n":"40","t":"Ey akılsızlar! Dışı yapanla içi yapan aynı değil mi?"},{"n":"41","t":"Siz kaplarınızın içindekini*fx* sadaka olarak verin, o zaman sizin için her şey temiz olur."},{"n":"42","t":"\"Ama vay halinize, ey Ferisiler! Siz nanenin, sedefotunun ve her tür sebzenin ondalığını verirsiniz de, adaleti ve Tanrı sevgisini ihmal edersiniz. Ondalık vermeyi ihmal etmeden esas bunları yerine getirmeniz gerekirdi."},{"n":"43","t":"Vay halinize, ey Ferisiler! Havralarda en seçkin yerlere kurulmaya, meydanlarda selamlanmaya bayılırsınız."},{"n":"44","t":"Vay halinize! İnsanların, farkında olmadan üzerlerinde gezindiği belirsiz mezarlara benziyorsunuz.\""},{"n":"45","t":"Kutsal Yasa uzmanlarından biri söz alıp İsa'ya, \"Öğretmenim, bunları söylemekle bize de hakaret etmiş oluyorsun\" dedi."},{"n":"46","t":"İsa, \"Sizin de vay halinize, ey Yasa uzmanları!\" dedi. \"İnsanlara taşınması güç yükler yüklersiniz, kendiniz ise bu yükleri kaldırmak için parmağınızı bile kıpırdatmazsınız."},{"n":"47","t":"Vay halinize! Peygamberlerin anıtlarını yaparsınız, oysa onları sizin atalarınız öldürmüştür."},{"n":"48","t":"Böylelikle atalarınızın yaptıklarına tanıklık ederek bunları onaylamış oluyorsunuz. Çünkü onlar peygamberleri öldürdüler, siz de anıtlarını yapıyorsunuz."},{"n":"49","t":"İşte bunun için Tanrı'nın Bilgeliği şöyle demiştir: 'Ben onlara peygamberler ve elçiler göndereceğim, bunlardan kimini öldürecek, kimine zulmedecekler.'"},{"n":"50-51","t":"Böylece bu kuşak, Habil'in kanından tutun da, sunakla tapınak arasında öldürülen Zekeriya'nın kanına değin, dünyanın kuruluşundan beri akıtılan bütün peygamberlerin kanından sorumlu tutulacaktır. Evet, size söylüyorum, bu kuşak sorumlu tutulacaktır."},{"n":"52","t":"Vay halinize, ey Yasa uzmanları! Bilgi kapısının anahtarını alıp götürdünüz. Kendiniz bu kapıdan girmediniz, girmek isteyenlere de engel oldunuz.\""},{"n":"53","t":"İsa oradan ayrılınca, din bilginleriyle Ferisiler O'nu şiddetle sıkıştırarak birçok konuda ağzını aramaya başladılar."},{"n":"54","t":"Ağzından çıkacak bir sözle O'nu tuzağa düşürmek için fırsat kolluyorlardı."}]},{"ch":12,"verses":[{"n":"1","t":"O sırada halktan binlerce kişi birbirlerini ezercesine toplanmıştı. İsa önce kendi öğrencilerine şunları söylemeye başladı: \"Ferisiler'in mayasından -yani, ikiyüzlülükten- kaçının."},{"n":"2","t":"Örtülü olup da açığa çıkarılmayacak, gizli olup da bilinmeyecek hiçbir şey yoktur."},{"n":"3","t":"Bunun için karanlıkta söylediğiniz her söz gün ışığında duyulacak, kapalı kapılar ardında kulağa fısıldadıklarınız damlardan duyurulacaktır."},{"n":"4","t":"\"Siz dostlarıma söylüyorum, bedeni öldüren, ama ondan sonra başka bir şey yapamayanlardan korkmayın."},{"n":"5","t":"Kimden korkmanız gerektiğini size açıklayayım: Kişiyi öldürdükten sonra cehenneme atma yetkisine sahip olan Tanrı'dan korkun. Evet, size söylüyorum, O'ndan korkun."},{"n":"6","t":"Beş serçe iki meteliğe satılmıyor mu? Ama bunlardan bir teki bile Tanrı katında unutulmuş değildir."},{"n":"7","t":"Nitekim başınızdaki bütün saçlar bile sayılıdır. Korkmayın, siz birçok serçeden daha değerlisiniz."},{"n":"8","t":"\"Size şunu söyleyeyim, insanların önünde beni açıkça kabul eden herkesi, İnsanoğlu* da Tanrı'nın melekleri önünde açıkça kabul edecek."},{"n":"9","t":"Ama kim beni insanlar önünde inkâr ederse, kendisi de Tanrı'nın melekleri önünde inkâr edilecek."},{"n":"10","t":"İnsanoğlu'na karşı bir söz söyleyen herkes bağışlanacak. Oysa Kutsal Ruh'a küfreden bağışlanmayacaktır."},{"n":"11","t":"\"Sizi havra topluluklarının, yöneticilerin ve yetkililerin önüne çıkardıklarında, 'Kendimizi neyle, nasıl savunacağız?' ya da, 'Ne söyleyeceğiz?' diye kaygılanmayın."},{"n":"12","t":"Kutsal Ruh o anda size ne söylemeniz gerektiğini öğretecektir.\" Zengin Budala"},{"n":"13","t":"Kalabalığın içinden biri İsa'ya, \"Öğretmenim, kardeşime söyle de mirası benimle paylaşsın\" dedi."},{"n":"14","t":"İsa ona şöyle dedi: \"Ey adam! Kim beni üzerinizde yargıç ya da hakem yaptı?\""},{"n":"15","t":"Sonra onlara, \"Dikkatli olun!\" dedi. \"Her türlü açgözlülükten sakının. Çünkü insanın yaşamı, malının çokluğuna bağlı değildir.\""},{"n":"16","t":"İsa onlara şu benzetmeyi anlattı: \"Zengin bir adamın toprakları bol ürün verdi."},{"n":"17","t":"Adam kendi kendine, 'Ne yapacağım? Ürünlerimi koyacak yerim yok' diye düşündü."},{"n":"18","t":"Sonra, 'Şöyle yapacağım' dedi. 'Ambarlarımı yıkıp daha büyüklerini yapacağım, bütün tahıllarımı ve mallarımı oraya yığacağım."},{"n":"19","t":"Kendime, ey canım, yıllarca yetecek kadar bol malın var. Rahatına bak, ye, iç, yaşamın tadını çıkar diyeceğim.'"},{"n":"20","t":"\"Ama Tanrı ona, 'Ey akılsız!' dedi. 'Bu gece canın senden istenecek. Biriktirdiğin bu şeyler kime kalacak?'"},{"n":"21","t":"\"Kendisi için servet biriktiren, ama Tanrı katında zengin olmayan kişinin sonu böyle olur.\" Kaygılanmayın (Mat.6:25-34)"},{"n":"22","t":"İsa öğrencilerine şöyle dedi: \"Bu nedenle size şunu söylüyorum: 'Ne yiyeceğiz?' diye canınız için, 'Ne giyeceğiz?' diye bedeniniz için kaygılanmayın."},{"n":"23","t":"Can yiyecekten, beden de giyecekten daha önemlidir."},{"n":"24","t":"Kargalara bakın! Ne eker, ne biçerler; ne kilerleri, ne ambarları vardır. Tanrı yine de onları doyurur. Siz kuşlardan çok daha değerlisiniz!"},{"n":"25","t":"Hangi biriniz kaygılanmakla ömrünü bir anlık*fx* uzatabilir?"},{"n":"26","t":"Bu küçücük işe bile gücünüz yetmediğine göre, öbür konularda neden kaygılanıyorsunuz?"},{"n":"27","t":"\"Zambakların nasıl büyüdüğüne bakın! Ne çalışırlar, ne de iplik eğirirler. Ama size şunu söyleyeyim, bütün görkemine karşın Süleyman bile bunlardan biri gibi giyinmiş değildi."},{"n":"28","t":"Ey kıt imanlılar, bugün var olup yarın ocağa atılacak olan kır otunu böyle giydiren Tanrı'nın sizi de giydireceği çok daha kesindir."},{"n":"29","t":"'Ne yiyeceğiz, ne içeceğiz?' diye düşünüp tasalanmayın."},{"n":"30","t":"Dünya ulusları hep bu şeylerin peşinden giderler. Oysa Babanız, bunlara gereksinmeniz olduğunu bilir."},{"n":"31","t":"Siz O'nun egemenliğinin ardından gidin, o zaman size bunlar da verilecektir."},{"n":"32","t":"\"Korkma, ey küçük sürü! Çünkü Babanız, egemenliği size vermeyi uygun gördü."},{"n":"33","t":"Mallarınızı satın, sadaka olarak verin. Kendinize eskimeyen keseler, göklerde tükenmeyen bir hazine edinin. Orada ne hırsız ona yaklaşır, ne de güve onu yer."},{"n":"34","t":"Hazineniz neredeyse, yüreğiniz de orada olacaktır.\" Uyanık ve Hazırlıklı Olun (Mat.10:34-36; 24:42-51; Mar.10:38; 13:34-36)"},{"n":"35","t":"\"Kuşaklarınız belinizde bağlı ve kandilleriniz yanar durumda hazır olun."},{"n":"36","t":"Düğün şenliğinden dönecek olan efendilerinin gelip kapıyı çaldığı an kapıyı açmak için hazır bekleyen köleler gibi olun."},{"n":"37","t":"Efendileri geldiğinde uyanık bulunan kölelere ne mutlu! Size doğrusunu söyleyeyim, efendileri beline kuşağını bağlayacak, kölelerini sofraya oturtacak ve gelip onlara hizmet edecek."},{"n":"38","t":"Efendi gecenin ister ikinci, ister üçüncü nöbetinde*fx* gelsin, uyanık bulacağı kölelere ne mutlu!"},{"n":"39","t":"Ama şunu bilin ki, ev sahibi, hırsızın hangi saatte geleceğini bilse, evinin soyulmasına fırsat vermez."},{"n":"40","t":"Siz de hazır olun. Çünkü İnsanoğlu* beklemediğiniz saatte gelecektir.\""},{"n":"41","t":"Petrus, \"Ya Rab\" dedi, \"Bu benzetmeyi bizim için mi anlatıyorsun, yoksa herkes için mi?\""},{"n":"42","t":"Rab de şöyle dedi: \"Efendinin, uşaklarına vaktinde azık vermek için başlarına atadığı güvenilir ve akıllı kâhya kimdir?"},{"n":"43","t":"Efendisi eve döndüğünde işinin başında bulacağı o köleye ne mutlu!"},{"n":"44","t":"Size gerçeği söyleyeyim, efendisi onu bütün malının üzerinde yetkili kılacak."},{"n":"45-46","t":"Ama o köle içinden, 'Efendim gecikiyor' der, kadın ve erkek hizmetkârları dövmeye, yiyip içip sarhoş olmaya başlarsa, efendisi, onun beklemediği günde, ummadığı saatte gelecek, onu şiddetle cezalandırıp imansızlarla bir tutacaktır."},{"n":"47","t":"\"Efendisinin isteğini bilip de hazırlık yapmayan, onun isteğini yerine getirmeyen köle çok dayak yiyecek."},{"n":"48","t":"Oysa bilmeden dayağı hak eden davranışlarda bulunan, az dayak yiyecek. Kime çok verilmişse, ondan çok istenecek. Kime çok şey emanet edilmişse, kendisinden daha fazlası istenecektir."},{"n":"49","t":"\"Ben dünyaya ateş yağdırmaya geldim. Keşke bu ateş daha şimdiden alevlenmiş olsaydı!"},{"n":"50","t":"Katlanmam gereken bir vaftiz var. Bu vaftiz gerçekleşinceye dek nasıl da sıkıntı çekiyorum!*fx*"},{"n":"51","t":"Yeryüzüne barış getirmeye mi geldiğimi sanıyorsunuz? Size hayır diyorum, ayrılık getirmeye geldim."},{"n":"52","t":"Bundan böyle bir evde beş kişi, ikiye karşı üç, üçe karşı iki bölünmüş olacak."},{"n":"53","t":"Baba oğluna karşı, oğul babasına karşı, anne kızına karşı, kız annesine karşı, kaynana gelinine karşı, gelin kaynanasına karşı olacaktır.\" Belirtileri Anlamak (Mat.5:25-26; 16:2-3)"},{"n":"54","t":"İsa halka şunları da söyledi: \"Batıda bir bulutun yükseldiğini görünce siz hemen, 'Sağanak geliyor' diyorsunuz, ve öyle oluyor."},{"n":"55","t":"Rüzgarın güneyden estiğini görünce, 'Çok sıcak olacak' diyorsunuz, ve öyle oluyor."},{"n":"56","t":"Sizi ikiyüzlüler! Yeryüzünün ve gökyüzünün görünümünden bir anlam çıkarabiliyorsunuz da, şimdiki zamanın anlamını nasıl oluyor da çıkaramıyorsunuz?"},{"n":"57","t":"\"Doğru olana neden kendiniz karar vermiyorsunuz?"},{"n":"58","t":"Sizden davacı olanla birlikte yargıca giderken, yolda onunla anlaşmak için elinizden geleni yapın. Yoksa o sizi yargıcın önüne sürükler, yargıç gardiyanın eline verir, gardiyan da sizi hapse atar."},{"n":"59","t":"Size şunu söyleyeyim, borcunuzun son kuruşunu*fx* ödemedikçe oradan asla çıkamazsınız.\""}]},{"ch":13,"verses":[{"n":"1","t":"O sırada bazı kişiler gelip İsa'ya bir haber getirdiler. Pilatus'un nasıl bazı Celileliler'i öldürüp kanlarını kendi kestikleri kurbanların kanına kattığını anlattılar."},{"n":"2","t":"İsa onlara şöyle karşılık verdi: \"Böyle acı çeken bu Celileliler'in, bütün öbür Celileliler'den daha günahlı olduğunu mu sanıyorsunuz?"},{"n":"3","t":"Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız."},{"n":"4","t":"Ya da, Şiloah'taki kule üzerlerine yıkılınca ölen o on sekiz kişinin, Yeruşalim'de yaşayan öbür insanların hepsinden daha suçlu olduğunu mu sanıyorsunuz?"},{"n":"5","t":"Size hayır diyorum. Ama tövbe etmezseniz, hepiniz böyle mahvolacaksınız.\" Meyve Vermeyen Ağaç"},{"n":"6","t":"İsa şu benzetmeyi anlattı: \"Adamın birinin bağında dikili bir incir ağacı vardı. Adam gelip ağaçta meyve aradı, ama bulamadı."},{"n":"7","t":"Bağcıya, 'Bak' dedi, 'Ben üç yıldır gelip bu incir ağacında meyve arıyorum, bulamıyorum. Onu kes. Toprağın besinini neden boş yere tüketsin?'"},{"n":"8","t":"\"Bağcı, 'Efendim' diye karşılık verdi, 'Ağacı bir yıl daha bırak, bu arada ben çevresini kazıp gübreleyeyim."},{"n":"9","t":"Gelecek yıl meyve verirse, ne iyi; vermezse, onu kesersin.'\" Beli Bükük Bir Kadının İyileştirilmesi"},{"n":"10","t":"Bir Şabat Günü* İsa, havralardan birinde öğretiyordu."},{"n":"11","t":"On sekiz yıldır içinde hastalık ruhu bulunan bir kadın da oradaydı. İki büklüm olmuş, belini hiç doğrultamıyordu."},{"n":"12","t":"İsa onu görünce yanına çağırdı. \"Kadın\" dedi, \"Hastalığından kurtuldun.\""},{"n":"13","t":"Ellerini kadının üzerine koydu. Kadın hemen doğruldu ve Tanrı'yı yüceltmeye başladı."},{"n":"14","t":"İsa'nın hastayı Şabat Günü iyileştirmesine kızan havra yöneticisi kalabalığa seslenerek, \"Çalışmak için altı gün vardır\" dedi. \"O günler gelip iyileşin, Şabat Günü değil.\""},{"n":"15","t":"Rab ona şu karşılığı verdi: \"Sizi ikiyüzlüler! Her biriniz Şabat Günü kendi öküzünü ya da eşeğini yemlikten çözüp suya götürmez mi?"},{"n":"16","t":"Buna göre, Şeytan'ın on sekiz yıldır bağlı tuttuğu, İbrahim'in bir kızı olan bu kadının da Şabat Günü bu bağdan çözülmesi gerekmez miydi?\""},{"n":"17","t":"İsa'nın bu sözleri, kendisine karşı gelenlerin hepsini utandırdı. Bütün kalabalık ise O'nun yaptığı görkemli işlerin tümünü sevinçle karşıladı. Hardal Tanesi ve Maya (Mat.13:31-33; Mar.4:30-32)"},{"n":"18","t":"Sonra İsa şunları söyledi: \"Tanrı'nın Egemenliği neye benzer, onu neye benzeteyim?"},{"n":"19","t":"Tanrı'nın Egemenliği, bir adamın bahçesine ektiği hardal tanesine benzer. Tane gelişip ağaç olur, kuşlar dallarında barınır.\""},{"n":"20","t":"İsa yine, \"Tanrı'nın Egemenliği'ni neye benzeteyim?\" dedi."},{"n":"21","t":"\"O, bir kadının üç ölçek*fx* una karıştırdığı mayaya benzer. Sonunda bütün hamur kabarır.\" Dar Kapı (Mat.7:13-14,21-23)"},{"n":"22","t":"İsa köy kent dolaşarak öğretiyor, Yeruşalim'e doğru ilerliyordu."},{"n":"23-24","t":"Biri O'na, \"Ya Rab\" dedi, \"Kurtulanların sayısı az mı olacak?\" İsa oradakilere şöyle dedi: \"Dar kapıdan girmeye gayret edin. Size şunu söyleyeyim, çok kişi içeri girmek isteyecek, ama giremeyecek."},{"n":"25","t":"Ev sahibi kalkıp kapıyı kapattıktan sonra dışarıda durup, 'Ya Rab, kapıyı aç bize!' diyerek kapıyı vurmaya başlayacaksınız. \"O da size, 'Kim olduğunuzu, nereden geldiğinizi bilmiyorum' diye karşılık verecek."},{"n":"26","t":"\"O zaman, 'Biz senin önünde yiyip içtik, sen de bizim sokaklarımızda öğrettin' demeye başlayacaksınız."},{"n":"27","t":"\"O da size şöyle diyecek: 'Kim olduğunuzu, nereden geldiğinizi bilmiyorum. Çekilin önümden, ey kötülük yapanlar!'"},{"n":"28","t":"\"İbrahim'i, İshak'ı, Yakup'u ve bütün peygamberleri Tanrı'nın Egemenliği'nde, kendinizi ise dışarı atılmış gördüğünüz zaman, aranızda ağlayış ve diş gıcırtısı olacaktır."},{"n":"29","t":"İnsanlar doğudan batıdan, kuzeyden güneyden gelecek ve Tanrı'nın Egemeniği'nde sofraya oturacaklar."},{"n":"30","t":"Ve işte, sonuncu olan bazıları birinci, birinci olan bazıları da sonuncu olacak.\" Ey Yeruşalim! (Mat.23:37-39)"},{"n":"31","t":"Tam o sırada bazı Ferisiler gelip İsa'ya, \"Buradan ayrılıp başka yere git. Hirodes* seni öldürmek istiyor\" dediler."},{"n":"32","t":"İsa onlara şöyle dedi: \"Gidin, o tilkiye söyleyin, 'Bugün ve yarın cinleri kovup hastaları iyileştireceğim ve üçüncü gün hedefime ulaşacağım.'"},{"n":"33","t":"Yine de bugün, yarın ve öbür gün yoluma devam etmeliyim. Çünkü bir peygamberin Yeruşalim'in dışında ölmesi düşünülemez!"},{"n":"34","t":"\"Ey Yeruşalim! Peygamberleri öldüren, kendisine gönderilenleri taşlayan Yeruşalim! Tavuğun civcivlerini kanatları altına topladığı gibi ben de kaç kez senin çocuklarını toplamak istedim, ama siz istemediniz."},{"n":"35","t":"Bakın, eviniz ıssız bırakılacak! Size şunu söyleyeyim: 'Rab'bin adıyla gelene övgüler olsun!' diyeceğiniz zamana dek beni bir daha görmeyeceksiniz.\""}]},{"ch":14,"verses":[{"n":"1","t":"Bir Şabat Günü* İsa Ferisiler'in ileri gelenlerinden birinin evine yemek yemeye gitti. Herkes O'nu dikkatle gözlüyordu."},{"n":"2","t":"Önünde, vücudu su toplamış bir adam vardı."},{"n":"3","t":"İsa, Kutsal Yasa uzmanlarına ve Ferisiler'e, \"Şabat Günü bir hastayı iyileştirmek Kutsal Yasa'ya uygun mudur, değil midir?\" diye sordu."},{"n":"4","t":"Onlar ses çıkarmadılar. İsa adamı tutup iyileştirdi, sonra eve gönderdi."},{"n":"5","t":"İsa onlara şöyle dedi: \"Hanginiz oğlu ya da öküzü Şabat Günü kuyuya düşer de hemen çıkarmaz?\""},{"n":"6","t":"Onlar buna hiçbir karşılık veremediler."},{"n":"7-9","t":"Yemeğe çağrılanların başköşeleri seçtiğini farkeden İsa, onlara şu benzetmeyi anlattı: \"Biri seni düğüne çağırdığı zaman başköşeye kurulma. Belki senden daha saygın birini de çağırmıştır. İkinizi de çağıran gelip, 'Yerini bu adama ver' diyebilir. O zaman utançla kalkıp en arkaya geçersin."},{"n":"10","t":"Bir yere çağrıldığın zaman git, en arkada otur. Öyle ki, seni çağıran gelince, 'Arkadaşım, daha öne buyurmaz mısın?' desin. O zaman seninle birlikte sofrada oturan herkesin önünde onurlandırılmış olursun."},{"n":"11","t":"Kendini yücelten herkes alçaltılacak, kendini alçaltan yüceltilecektir.\" Şölen Benzetmesi (Mat.22:1-10)"},{"n":"12","t":"İsa kendisini yemeğe çağırmış olana da şöyle dedi: \"Bir öğlen ya da akşam yemeği verdiğin zaman dostlarını, kardeşlerini, akrabalarını ve zengin komşularını çağırma. Yoksa onlar da seni çağırarak karşılık verirler."},{"n":"13","t":"Ama ziyafet verdiğin zaman yoksulları, kötürümleri, sakatları, körleri çağır."},{"n":"14","t":"Böylece mutlu olursun. Çünkü bunlar sana karşılık verecek durumda değildirler. Karşılığı sana, doğru kişiler dirildiği zaman verilecektir.\""},{"n":"15","t":"Sofrada oturanlardan biri bunu duyunca İsa'ya, \"Tanrı'nın Egemenliği'nde yemek yiyecek olana ne mutlu!\" dedi."},{"n":"16","t":"İsa ona şöyle dedi: \"Adamın biri büyük bir şölen hazırlayıp birçok konuk çağırdı."},{"n":"17","t":"Şölen saati gelince davetlilere, 'Buyurun, her şey hazır' diye haber vermek üzere kölesini gönderdi."},{"n":"18","t":"\"Ne var ki, hepsi anlaşmışçasına özür dilemeye başladılar. Birincisi, 'Bir tarla satın aldım, gidip görmek zorundayım. Rica ederim, beni hoş gör' dedi."},{"n":"19","t":"\"Bir başkası, 'Beş çift öküz aldım, onları denemeye gidiyorum. Rica ederim, beni hoş gör' dedi."},{"n":"20","t":"\"Yine bir başkası, 'Yeni evlendim, bu nedenle gelemiyorum' dedi."},{"n":"21","t":"\"Köle geri dönüp durumu efendisine bildirdi. Bunun üzerine ev sahibi öfkelenerek kölesine, 'Koş' dedi, 'Kentin caddelerine, sokaklarına çık; yoksulları, kötürümleri, körleri, sakatları buraya getir.'"},{"n":"22","t":"\"Köle, 'Efendim, buyruğun yerine getirilmiştir, ama daha yer var' dedi."},{"n":"23","t":"\"Efendisi köleye, 'Çıkıp yolları ve çit boylarını dolaş, bulduklarını gelmeye zorla da evim dolsun' dedi."},{"n":"24","t":"'Size şunu söyleyeyim, ilk çağrılan o adamlardan hiçbiri benim yemeğimden tatmayacaktır.'\" İsa'nın Öğrencileri (Mat.10:37-38)"},{"n":"25-26","t":"Kalabalık halk toplulukları İsa'yla birlikte yol alıyordu. İsa dönüp onlara şöyle dedi: \"Biri bana gelip de babasını, annesini, karısını, çocuklarını, kardeşlerini, hatta kendi canını bile gözden çıkarmazsa*fx*, öğrencim olamaz."},{"n":"27","t":"Çarmıhını yüklenip ardımdan gelmeyen, öğrencim olamaz."},{"n":"28","t":"\"Aranızdan biri bir kule yapmak isterse, bunu tamamlayacak kadar parası var mı yok mu diye önce oturup yapacağı masrafı hesap etmez mi?"},{"n":"29-30","t":"Çünkü temel atıp da işi bitiremezse, durumu gören herkes, 'Bu adam inşaata başladı, ama bitiremedi' diyerek onunla eğlenmeye başlar."},{"n":"31","t":"\"Ya da hangi kral başka bir kralla savaşa gittiğinde, üzerine yirmi bin askerle yürüyen düşmana on bin askerle karşı koyabilir miyim diye önce oturup bir değerlendirme yapmaz?"},{"n":"32","t":"Eğer karşı koyamayacaksa, öbürü henüz uzaktayken elçiler gönderip barış koşullarını ister."},{"n":"33","t":"Aynı şekilde sizden kim varını yoğunu gözden çıkarmazsa, öğrencim olamaz."},{"n":"34","t":"\"Tuz yararlıdır. Ama tuz tadını yitirirse, bir daha nasıl o tadı kazanabilir?"},{"n":"35","t":"Ne toprağa, ne de gübreye yarar; onu çöpe atarlar. İşitecek kulağı olan işitsin.\""}]},{"ch":15,"verses":[{"n":"1","t":"Bütün vergi görevlileriyle* günahkârlar İsa'yı dinlemek için O'na akın ediyordu."},{"n":"2","t":"Ferisiler'le din bilginleri ise, \"Bu adam günahkârları kabul ediyor, onlarla birlikte yemek yiyor\" diye söyleniyorlardı."},{"n":"3-4","t":"Bunun üzerine İsa onlara şu benzetmeyi anlattı: \"Sizlerden birinin yüz koyunu olsa ve bunlardan bir tanesini kaybetse, doksan dokuzu bozkırda bırakarak kaybolanı bulana dek onun ardına düşmez mi?"},{"n":"5-6","t":"Onu bulunca da sevinç içinde omuzlarına alır, evine döner; arkadaşlarını, komşularını çağırıp onlara, 'Benimle birlikte sevinin, kaybolan koyunumu buldum!' der."},{"n":"7","t":"Size şunu söyleyeyim, aynı şekilde gökte, tövbe eden tek bir günahkâr için, tövbeyi gereksinmeyen doksan dokuz doğru kişi için duyulandan daha büyük sevinç duyulacaktır.\" Kaybolan Para Benzetmesi"},{"n":"8","t":"\"Ya da on gümüş parası olan bir kadın bunlardan bir tanesini kaybetse, kandil yakıp evi süpürerek parayı bulana dek her tarafı dikkatle aramaz mı?"},{"n":"9","t":"Parayı bulunca da arkadaşlarını, komşularını çağırıp, 'Benimle birlikte sevinin, kaybettiğim parayı buldum!' der."},{"n":"10","t":"Size şunu söyleyeyim, aynı şekilde Tanrı'nın melekleri de tövbe eden bir tek günahkâr için sevinç duyacaklar.\" Kaybolan Oğul Benzetmesi"},{"n":"11","t":"İsa, \"Bir adamın iki oğlu vardı\" dedi."},{"n":"12","t":"\"Bunlardan küçüğü babasına, 'Baba' dedi, 'Malından payıma düşeni ver bana.' Baba da servetini iki oğlu arasında paylaştırdı."},{"n":"13","t":"\"Bundan birkaç gün sonra küçük oğul her şeyini toplayıp uzak bir ülkeye gitti. Orada sefahat içinde bir yaşam sürerek varını yoğunu çarçur etti."},{"n":"14","t":"Delikanlı her şeyini harcadıktan sonra, o ülkede şiddetli bir kıtlık baş gösterdi, o da yokluk çekmeye başladı."},{"n":"15","t":"Bunun üzerine gidip o ülkenin vatandaşlarından birinin hizmetine girdi. Adam onu, domuz gütmek üzere otlaklarına yolladı."},{"n":"16","t":"Delikanlı, domuzların yediği keçiboynuzlarıyla karnını doyurmaya can atıyordu. Ama hiç kimse ona bir şey vermedi."},{"n":"17","t":"\"Aklı başına gelince şöyle dedi: 'Babamın nice işçisinin fazlasıyla yiyeceği var, bense burada açlıktan ölüyorum."},{"n":"18","t":"Kalkıp babamın yanına döneceğim, ona, Baba diyeceğim, Tanrı'ya*fx* ve sana karşı günah işledim."},{"n":"19","t":"Ben artık senin oğlun olarak anılmaya layık değilim. Beni işçilerinden biri gibi kabul et.'"},{"n":"20","t":"\"Böylece kalkıp babasının yanına döndü. Kendisi daha uzaktayken babası onu gördü, ona acıdı, koşup boynuna sarıldı ve onu öptü."},{"n":"21","t":"Oğlu ona, 'Baba' dedi, 'Tanrı'ya*fx* ve sana karşı günah işledim. Ben artık senin oğlun olarak anılmaya layık değilim.'"},{"n":"22","t":"\"Babası ise kölelerine, 'Çabuk, en iyi kaftanı getirip ona giydirin!' dedi. 'Parmağına yüzük takın, ayaklarına çarık giydirin!"},{"n":"23","t":"Besili danayı getirip kesin, yiyelim, eğlenelim."},{"n":"24","t":"Çünkü benim bu oğlum ölmüştü, yaşama döndü; kaybolmuştu, bulundu.' Böylece eğlenmeye başladılar."},{"n":"25","t":"\"Babanın büyük oğlu ise tarladaydı. Gelip eve yaklaştığında çalgı ve oyun seslerini duydu."},{"n":"26","t":"Uşaklardan birini yanına çağırıp, 'Ne oluyor?' diye sordu."},{"n":"27","t":"\"O da, 'Kardeşin geldi, baban da ona sağ salim kavuştuğu için besili danayı kesti' dedi."},{"n":"28-29","t":"\"Büyük oğul öfkelendi, içeri girmek istemedi. Babası dışarı çıkıp ona yalvardı. Ama o, babasına şöyle yanıt verdi: 'Bak, bunca yıl senin için köle gibi çalıştım, hiçbir zaman buyruğundan çıkmadım. Ne var ki sen bana, arkadaşlarımla eğlenmem için hiçbir zaman bir oğlak bile vermedin."},{"n":"30","t":"Oysa senin malını fahişelerle yiyen şu oğlun eve dönünce, onun için besili danayı kestin.'"},{"n":"31","t":"\"Babası ona, 'Oğlum, sen her zaman yanımdasın, neyim varsa senindir' dedi."},{"n":"32","t":"'Ama sevinip eğlenmek gerekiyordu. Çünkü bu kardeşin ölmüştü, yaşama döndü; kaybolmuştu, bulundu!'\""}]},{"ch":16,"verses":[{"n":"1","t":"İsa öğrencilerine şunları da anlattı: \"Zengin bir adamın bir kâhyası vardı. Kâhya, efendisinin mallarını çarçur ediyor diye efendisine ihbar edildi."},{"n":"2","t":"Efendisi kâhyayı çağırıp ona, 'Nedir bu senin hakkında duyduklarım? Kâhyalığının hesabını ver. Çünkü sen artık kâhyalık edemezsin' dedi."},{"n":"3","t":"\"Kâhya kendi kendine, 'Ne yapacağım ben?' dedi. 'Efendim kâhyalığı elimden alıyor. Toprak kazmaya gücüm yetmez, dilenmekten utanırım."},{"n":"4","t":"Kâhyalıktan kovulduğum zaman başkaları beni evlerine kabul etsinler diye ne yapacağımı biliyorum.'"},{"n":"5","t":"\"Böylelikle efendisine borcu olanların hepsini tek tek yanına çağırdı. Birincisine, 'Efendime ne kadar borcun var?' dedi."},{"n":"6","t":"\"Adam, 'Yüz ölçek*fx* zeytinyağı' karşılığını verdi. \"Kâhya ona, 'Borç senedini al ve hemen otur, elli ölçek diye yaz' dedi."},{"n":"7","t":"\"Sonra bir başkasına, 'Senin borcun ne kadar?' dedi. \"'Yüz ölçek*fx* buğday' dedi öteki. \"Ona da, 'Borç senedini al, seksen ölçek diye yaz' dedi."},{"n":"8","t":"\"Efendisi, dürüst olmayan kâhyayı, akıllıca davrandığı için övdü. Gerçekten bu çağın insanları, kendilerine benzer kişilerle ilişkilerinde, ışıkta yürüyenlerden*fx* daha akıllı oluyorlar."},{"n":"9","t":"Size şunu söyleyeyim, dünyanın aldatıcı servetini*fx* kendinize dost edinmek için kullanın ki, bu servet yok olunca sizi sonsuza dek kalacak konutlara Kabul etsinler.\" Servet ve Güvenilirlik"},{"n":"10","t":"\"En küçük işte güvenilir olan kişi, büyük işte de güvenilir olur. En küçük işte dürüst olmayan kişi, büyük işte de dürüst olmaz."},{"n":"11","t":"Dünyanın aldatıcı serveti konusunda güvenilir değilseniz, gerçek serveti size kim emanet eder?"},{"n":"12","t":"Başkasının malı konusunda güvenilir değilseniz, kendi malınız olmak üzere size kim bir şey verir?"},{"n":"13","t":"\"Hiçbir uşak iki efendiye kulluk edemez. Ya birinden nefret edip öbürünü sever, ya da birine bağlanıp öbürünü hor görür. Siz hem Tanrı'ya, hem paraya*fx* kulluk edemezsiniz.\""},{"n":"14","t":"Parayı seven Ferisiler bütün bu sözleri duyunca İsa'yla alay etmeye başladılar."},{"n":"15","t":"O da onlara şöyle dedi: \"Siz insanlar önünde kendinizi temize çıkarıyorsunuz, ama Tanrı yüreğinizi biliyor. İnsanların gururlandıkları ne varsa, Tanrı'ya iğrenç gelir."},{"n":"16","t":"\"Kutsal Yasa ve peygamberlerin devri Yahya'nın zamanına dek sürdü. O zamandan bu yana Tanrı'nın Egemenliği müjdeleniyor ve herkes oraya zorla girmeye çalışıyor."},{"n":"17","t":"Yerin ve göğün ortadan kalkması, Kutsal Yasa'nın ufacık bir noktasının yok olmasından daha kolaydır."},{"n":"18","t":"\"Karısını boşayıp başkasıyla evlenen zina etmiş olur. Kocasından boşanmış bir kadınla evlenen de zina etmiş olur.\" Dilenci ile Zengin Adam"},{"n":"19","t":"\"Zengin bir adam vardı. Mor, ince keten giysiler giyer, bolluk içinde her gün eğlenirdi."},{"n":"20-21","t":"Her tarafı yara içinde olan Lazar adında yoksul bir adam bu zenginin kapısının önüne bırakılırdı; zenginin sofrasından düşen kırıntılarla karnını doyurmaya can atardı. Bir yandan da köpekler gelip onun yaralarını yalardı."},{"n":"22","t":"\"Bir gün yoksul adam öldü, melekler onu alıp İbrahim'in yanına götürdüler. Sonra zengin adam da öldü ve gömüldü."},{"n":"23","t":"Ölüler diyarında ıstırap çeken zengin adam başını kaldırıp uzakta İbrahim'i ve onun yanında Lazar'ı gördü."},{"n":"24","t":"'Ey babamız İbrahim, acı bana!' diye seslendi. 'Lazar'ı gönder de parmağının ucunu suya batırıp dilimi serinletsin. Bu alevlerin içinde azap çekiyorum.'"},{"n":"25","t":"\"İbrahim, 'Oğlum' dedi, 'Yaşamın boyunca senin iyilik payını, Lazar'ın da kötülük payını aldığını unutma. Şimdiyse o burada teselli ediliyor, sen de azap çekiyorsun."},{"n":"26","t":"Üstelik, aramıza öyle bir uçurum kondu ki, ne buradan size gelmek isteyenler gelebilir, ne de oradan kimse bize gelebilir.'"},{"n":"27","t":"\"Zengin adam şöyle dedi: 'Öyleyse baba, sana rica ederim, Lazar'ı babamın evine gönder."},{"n":"28","t":"Çünkü beş kardeşim var. Lazar onları uyarsın ki, onlar da bu ıstırap yerine düşmesinler.'"},{"n":"29","t":"\"İbrahim, 'Onlarda Musa'nın ve peygamberlerin sözleri var, onları dinlesinler' dedi."},{"n":"30","t":"\"Zengin adam, 'Hayır, İbrahim baba, dinlemezler!' dedi. 'Ancak ölüler arasından biri onlara giderse, tövbe ederler.'"},{"n":"31","t":"\"İbrahim ona, 'Eğer Musa ile peygamberleri dinlemezlerse, ölüler arasından biri dirilse bile ikna olmazlar' dedi.\""}]},{"ch":17,"verses":[{"n":"1","t":"İsa öğrencilerine şöyle dedi: \"İnsanı günaha düşüren tuzakların olması kaçınılmazdır. Ama bu tuzaklara aracılık eden kişinin vay haline!"},{"n":"2","t":"Böyle bir kişi bu küçüklerden birini günaha düşüreceğine, boynuna bir değirmen taşı geçirilip denize atılsa, kendisi için daha iyi olur."},{"n":"3","t":"Yaşantınıza dikkat edin! Kardeşiniz günah işlerse, onu azarlayın; tövbe ederse, bağışlayın."},{"n":"4","t":"Günde yedi kez size karşı günah işler ve yedi kez size gelip, 'Tövbe ediyorum' derse, onu bağışlayın.\""},{"n":"5","t":"Elçiler Rab'be, \"İmanımızı artır!\" dediler."},{"n":"6","t":"Rab şöyle dedi: \"Bir hardal tanesi kadar imanınız olsa, şu dut ağacına, 'Kökünden sökül ve denizin içine dikil' dersiniz, o da sözünüzü dinler."},{"n":"7","t":"\"Hanginizin çift süren ya da çobanlık eden bir kölesi olur da, tarladan dönüşünde ona, 'Çabuk gel, sofraya otur' der?"},{"n":"8","t":"Tersine ona, 'Yemeğimi hazırla, kuşağını bağla, ben yiyip içerken bana hizmet et. Sonra sen yiyip içersin' demez mi?"},{"n":"9","t":"Verdiği buyrukları yerine getirdi diye köleye teşekkür eder mi?"},{"n":"10","t":"Siz de böylece, size verilen buyrukların hepsini yerine getirdikten sonra, 'Biz değersiz kullarız; sadece yapmamız gerekeni yaptık' deyin.\" On Cüzamlı"},{"n":"11","t":"Yeruşalim'e doğru yoluna devam eden İsa, Samiriye ile Celile arasındaki sınır bölgesinden geçiyordu."},{"n":"12-13","t":"Köyün birine girerken O'nu cüzamlı* on adam karşıladı. Bunlar uzakta durarak, \"İsa, Efendimiz, halimize acı!\" diye seslendiler."},{"n":"14","t":"İsa onları görünce, \"Gidin, kâhinlere* görünün\" dedi. Adamlar yolda giderken cüzamdan temizlendiler."},{"n":"15-16","t":"Onlardan biri, iyileştiğini görünce yüksek sesle Tanrı'yı yücelterek geri döndü, yüzüstü İsa'nın ayaklarına kapanıp O'na teşekkür etti. Bu adam Samiriyeli'ydi*."},{"n":"17","t":"İsa, \"İyileşenler on kişi değil miydi?\" diye sordu. \"Öbür dokuzu nerede?"},{"n":"18","t":"Tanrı'yı yüceltmek için bu yabancıdan başka geri dönen olmadı mı?\""},{"n":"19","t":"Sonra adama, \"Ayağa kalk, git\" dedi. \"İmanın seni kurtardı.\" Tanrı'nın Egemenliği Ne Zaman Gelecek? (Mat.24:23-28,37-41)"},{"n":"20","t":"Ferisiler İsa'ya, \"Tanrı'nın Egemenliği ne zaman gelecek?\" diye sordular. İsa onlara şöyle yanıt verdi: \"Tanrı'nın Egemenliği göze görünür bir şekilde gelmez."},{"n":"21","t":"İnsanlar da, 'İşte burada' ya da, 'İşte şurada' demeyecekler. Çünkü Tanrı'nın Egemenliği içinizdedir.\""},{"n":"22","t":"İsa öğrencilerine şöyle dedi: \"Öyle günler gelecek ki, İnsanoğlu'nun* günlerinden birini görmeyi özleyeceksiniz, ama görmeyeceksiniz."},{"n":"23","t":"İnsanlar size, 'İşte orada', 'İşte burada' diyecekler. Gitmeyin, onların arkasından koşmayın."},{"n":"24","t":"Şimşek çakıp göğü bir ucundan öbür ucuna dek nasıl aydınlatırsa, İnsanoğlu kendi gününde öyle olacaktır."},{"n":"25","t":"Ama önce O'nun çok acı çekmesi ve bu kuşak tarafından reddedilmesi gerekir."},{"n":"26","t":"\"Nuh'un günlerinde nasıl olduysa, İnsanoğlu'nun günlerinde de öyle olacak."},{"n":"27","t":"Nuh'un gemiye bindiği güne dek insanlar yiyip içiyor, evlenip evlendiriliyorlardı. Sonra tufan gelip hepsini yok etti."},{"n":"28","t":"Lut'un günlerinde de durum aynıydı. İnsanlar yiyip içiyor, alıp satıyor, tohum ekiyor, ev yapıyorlardı."},{"n":"29","t":"Ama Lut'un Sodom'dan ayrıldığı gün gökten ateşle kükürt yağdı ve hepsini yok etti."},{"n":"30","t":"\"İnsanoğlu'nun ortaya çıkacağı gün durum aynı olacaktır."},{"n":"31","t":"O gün damda olan, evdeki eşyalarını almak için aşağı inmesin. Tarlada olan da geri dönmesin."},{"n":"32","t":"Lut'un karısını hatırlayın!"},{"n":"33","t":"Canını esirgemek isteyen onu yitirecek. Canını yitiren ise onu yaşatacaktır."},{"n":"34","t":"Size şunu söyleyeyim, o gece aynı yatakta olan iki kişiden biri alınacak, öbürü bırakılacak."},{"n":"35-36","t":"Birlikte buğday öğüten iki kadından biri alınacak, öbürü bırakılacak.\"*fx*"},{"n":"37","t":"Onlar İsa'ya, \"Bu olaylar nerede olacak, Rab?\" diye sordular. O da onlara, \"Leş neredeyse, akbabalar da oraya üşüşecek\" dedi."}]},{"ch":18,"verses":[{"n":"1-2","t":"İsa öğrencilerine, hiç usanmadan, her zaman dua etmeleri gerektiğini belirten şu benzetmeyi anlattı: \"Kentin birinde Tanrı'dan korkmayan, insana saygı duymayan bir yargıç vardı."},{"n":"3","t":"Yine o kentte bir dul kadın vardı. Yargıca sürekli gidip, 'Davacı olduğum kişiden hakkımı al' diyordu."},{"n":"4-5","t":"\"Yargıç bir süre ilgisiz kaldı. Ama sonunda kendi kendine, 'Ben her ne kadar Tanrı'dan korkmaz, insana saygı duymazsam da, bu dul kadın beni rahatsız ettiği için hakkını alacağım. Yoksa sürekli gelip beni canımdan bezdirecek' dedi.\""},{"n":"6","t":"Rab şöyle devam etti: \"Adaletsiz yargıcın ne söylediğini duydunuz."},{"n":"7","t":"Tanrı da, gece gündüz kendisine yakaran seçilmişlerinin hakkını almayacak mı? Onları çok bekletecek mi?"},{"n":"8","t":"Size şunu söyleyeyim, onların hakkını tez alacaktır. Ama İnsanoğlu* geldiği zaman acaba yeryüzünde iman bulacak mı?\" Ferisi ve Vergi Görevlisi"},{"n":"9-10","t":"Kendi doğruluklarına güvenip başkalarına tepeden bakan bazı kişilere İsa şu benzetmeyi anlattı: \"Biri Ferisi*, öbürü vergi görevlisi* iki kişi dua etmek üzere tapınağa çıktı."},{"n":"11","t":"Ferisi ayakta kendi kendine şöyle dua etti: 'Tanrım, öbür insanlara -soygunculara, hak yiyenlere, zina edenlere- ya da şu vergi görevlisine benzemediğim için sana şükrederim."},{"n":"12","t":"Haftada iki gün oruç tutuyor, bütün kazancımın ondalığını veriyorum.'"},{"n":"13","t":"\"Vergi görevlisi ise uzakta durdu, gözlerini göğe kaldırmak bile istemiyordu, ancak göğsünü döverek, 'Tanrım, ben günahkâra merhamet et' diyordu."},{"n":"14","t":"\"Size şunu söyleyeyim, Ferisi değil, bu adam aklanmış olarak evine döndü. Çünkü kendini yücelten herkes alçaltılacak, kendini alçaltan ise yüceltilecektir.\" İsa Küçük Çocukları Kutsuyor (Mat.19:13-15; Mar.10:13-16)"},{"n":"15","t":"Bazıları bebekleri bile İsa'ya getiriyor, onlara dokunmasını istiyorlardı. Bunu gören öğrenciler onları azarladılar."},{"n":"16","t":"Ama İsa çocukları yanına çağırarak, \"Bırakın, çocuklar bana gelsin, onlara engel olmayın!\" dedi. \"Çünkü Tanrı'nın Egemenliği böylelerinindir."},{"n":"17","t":"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliği'ni bir çocuk gibi kabul etmeyen, bu egemenliğe asla giremez.\" Zenginlik ve Sonsuz Yaşam (Mat.19:16-30; Mar.10:17-31)"},{"n":"18","t":"İleri gelenlerden biri İsa'ya, \"İyi öğretmenim, sonsuz yaşama kavuşmak için ne yapmalıyım?\" diye sordu."},{"n":"19","t":"İsa, \"Bana neden iyi diyorsun?\" dedi. \"İyi olan yalnız biri var, O da Tanrı'dır."},{"n":"20","t":"O'nun buyruklarını biliyorsun: 'Zina etmeyeceksin, adam öldürmeyeceksin, çalmayacaksın, yalan yere tanıklık etmeyeceksin, annene babana saygı göstereceksin.'\""},{"n":"21","t":"\"Bunların hepsini gençliğimden beri yerine getiriyorum\" dedi adam."},{"n":"22","t":"İsa bunu duyunca ona, \"Hâlâ bir eksiğin var\" dedi. \"Neyin varsa hepsini sat, parasını yoksullara dağıt; böylece göklerde hazinen olur. Sonra gel, beni izle.\""},{"n":"23","t":"Adam bu sözleri duyunca çok üzüldü. Çünkü son derece zengindi."},{"n":"24","t":"Onun üzüntüsünü gören İsa, \"Varlıklı kişilerin Tanrı Egemenliği'ne girmesi ne kadar güç!\" dedi."},{"n":"25","t":"\"Nitekim devenin iğne deliğinden geçmesi, zenginin Tanrı Egemenliği'ne girmesinden daha kolaydır.\""},{"n":"26","t":"Bunu işitenler, \"Öyleyse kim kurtulabilir?\" dediler."},{"n":"27","t":"İsa, \"İnsanlar için imkânsız olan, Tanrı için mümkündür\" dedi."},{"n":"28","t":"Petrus, \"Bak, biz her şeyimizi bırakıp senin ardından geldik\" dedi."},{"n":"29-30","t":"İsa onlara şöyle dedi: \"Size doğrusunu söyleyeyim, Tanrı'nın Egemenliği uğruna evini, karısını, kardeşlerini, annesiyle babasını ya da çocuklarını bırakıp da bu çağda bunların kat kat fazlasına ve gelecek çağda sonsuz yaşama kavuşmayacak hiç kimse yoktur.\" İsa Ölüp Dirileceğini Üçüncü Kez Bildiriyor (Mat.20:17-19; Mar.10:32-34)"},{"n":"31","t":"İsa, Onikiler'i* bir yana çekip onlara şöyle dedi: \"Şimdi Yeruşalim'e gidiyoruz. Peygamberlerin İnsanoğlu'yla* ilgili yazdıklarının tümü yerine gelecektir."},{"n":"32-33","t":"O, öteki uluslara teslim edilecek. O'nunla alay edecek, O'na hakaret edecekler; üzerine tükürecek ve O'nu kamçılayıp öldürecekler. Ne var ki O, üçüncü gün dirilecek.\""},{"n":"34","t":"Öğrenciler bu sözlerden hiçbir şey anlamadılar. Bu sözlerin anlamı onlardan gizlenmişti, anlatılanları kavrayamıyorlardı. Bir Körün Gözleri Açılıyor (Mat.20:29-34; Mar.10:46-52)"},{"n":"35","t":"İsa Eriha'ya yaklaşırken kör bir adam yol kenarında oturmuş dileniyordu."},{"n":"36","t":"Adam oradan geçen kalabalığı duyunca, \"Ne oluyor?\" diye sordu."},{"n":"37","t":"Ona, \"Nasıralı İsa geçiyor\" dediler."},{"n":"38","t":"O da, \"Ey Davut Oğlu İsa, halime acı!\" diye bağırdı."},{"n":"39","t":"Önden gidenler onu azarlayarak susturmak istedilerse de o, \"Ey Davut Oğlu, halime acı!\" diyerek daha çok bağırdı."},{"n":"40-41","t":"İsa durup adamın kendisine getirilmesini buyurdu. Adam yaklaşınca İsa, \"Senin için ne yapmamı istiyorsun?\" diye sordu. O da, \"Ya Rab, gözlerim görsün\" dedi."},{"n":"42","t":"İsa, \"Gözlerin görsün\" dedi. \"İmanın seni kurtardı.\""},{"n":"43","t":"Adam o anda yeniden görmeye başladı ve Tanrı'yı yücelterek İsa'nın ardından gitti. Bunu gören bütün halk Tanrı'ya övgüler sundu."}]},{"ch":19,"verses":[{"n":"1","t":"İsa Eriha'ya girdi. Kentin içinden geçiyordu."},{"n":"2","t":"Orada vergi görevlilerinin* başı olan, Zakkay adında zengin bir adam vardı."},{"n":"3","t":"İsa'nın kim olduğunu görmek istiyor, ama boyu kısa olduğu için kalabalıktan ötürü göremiyordu."},{"n":"4","t":"İsa'yı görebilmek için önden koşup bir yabanıl incir ağacına tırmandı. Çünkü İsa oradan geçecekti."},{"n":"5","t":"İsa oraya varınca yukarı bakıp, \"Zakkay, çabuk aşağı in!\" dedi. \"Bugün senin evinde kalmam gerekiyor.\""},{"n":"6","t":"Zakkay hızla aşağı indi ve sevinç içinde İsa'yı evine buyur etti."},{"n":"7","t":"Bunu görenlerin hepsi söylenmeye başladı: \"Gidip günahkâr birine konuk oldu!\" dediler."},{"n":"8","t":"Zakkay ayağa kalkıp Rab'be şöyle dedi: \"Ya Rab, işte malımın yarısını yoksullara veriyorum. Bir kimseden haksızlıkla bir şey aldımsa, dört katını geri vereceğim.\""},{"n":"9","t":"İsa dedi ki, \"Bu ev bugün kurtuluşa kavuştu. Çünkü bu adam da İbrahim'in oğludur."},{"n":"10","t":"Nitekim İnsanoğlu*, kaybolanı arayıp kurtarmak için geldi.\" Güvenilirlik Sınavı (Mat.25:14-30)"},{"n":"11","t":"Oradakiler bu sözleri dinlerken İsa konuşmasını bir benzetmeyle sürdürdü. Çünkü Yeruşalim'e yaklaşmıştı ve onlar, Tanrı'nın Egemenliği'nin hemen ortaya çıkacağını sanıyorlardı."},{"n":"12","t":"Bu nedenle İsa şöyle dedi: \"Soylu bir adam, kral atanıp dönmek üzere uzak bir ülkeye gitti."},{"n":"13","t":"Gitmeden önce kölelerinden onunu çağırıp onlara birer mina verdi. 'Ben dönünceye dek bu paraları işletin' dedi."},{"n":"14","t":"\"Ne var ki, ülkesinin halkı adamdan nefret ediyordu. Arkasından temsilciler göndererek, 'Bu adamın üzerimize kral olmasını istemiyoruz' diye haber ilettiler."},{"n":"15","t":"\"Adam kral atanmış olarak geri döndüğünde, parayı vermiş olduğu köleleri çağırtıp ne kazandıklarını öğrenmek istedi."},{"n":"16","t":"Birincisi geldi, 'Efendimiz' dedi, 'Senin bir minan on mina daha kazandı.'"},{"n":"17","t":"\"Efendisi ona, 'Aferin, iyi köle!' dedi. 'En küçük işte güvenilir olduğunu gösterdiğin için on kent üzerinde yetkili olacaksın.'"},{"n":"18","t":"\"İkincisi gelip, 'Efendimiz, senin bir minan beş mina daha kazandı' dedi."},{"n":"19","t":"\"Efendisi ona da, 'Sen beş kent üzerinde yetkili olacaksın' dedi."},{"n":"20","t":"\"Başka biri geldi, 'Efendimiz' dedi, 'İşte senin minan! Onu bir mendile sarıp sakladım."},{"n":"21","t":"Çünkü senden korktum, sert adamsın; kendinden koymadığını alır, ekmediğini biçersin.'"},{"n":"22","t":"\"Efendisi ona, 'Ey kötü köle, seni kendi ağzından çıkan sözle yargılayacağım' dedi. 'Kendinden koymadığını alan, ekmediğini biçen sert bir adam olduğumu bildiğine göre,"},{"n":"23","t":"neden paramı faize vermedin? Ben de geldiğimde onu faiziyle geri alırdım.'"},{"n":"24","t":"\"Sonra çevrede duranlara, 'Elindeki minayı alın, on minası olana verin' dedi."},{"n":"25","t":"\"Ona, 'Efendimiz' dediler, 'Onun zaten on minası var!'"},{"n":"26","t":"\"O da, 'Size şunu söyleyeyim, kimde varsa ona daha çok verilecek. Ama kimde yoksa, kendisinde olan da elinden alınacak' dedi."},{"n":"27","t":"'Beni kral olarak istemeyen o düşmanlarıma gelince, onları buraya getirin ve gözümün önünde kılıçtan geçirin!'\" İsa'nın Yeruşalim'e Girişi (Mat.21:1-11; Mar.11:1-11; Yu.12:12-19)"},{"n":"28","t":"İsa, bu sözleri söyledikten sonra önden yürüyerek Yeruşalim'e doğru ilerledi."},{"n":"29-30","t":"Zeytin Dağı'nın yamacındaki Beytfaci ile Beytanya'ya yaklaştığında iki öğrencisini önden gönderdi. Onlara, \"Karşıdaki köye gidin\" dedi, \"Köye girince, üzerine daha hiç kimsenin binmediği, bağlı duran bir sıpa bulacaksınız. Onu çözüp bana getirin."},{"n":"31","t":"Biri size, 'Onu niçin çözüyorsunuz?' diye sorarsa, 'Rab'bin ona ihtiyacı var' dersiniz.\""},{"n":"32","t":"Gönderilen öğrenciler gittiler, her şeyi İsa'nın kendilerine anlattığı gibi buldular."},{"n":"33","t":"Sıpayı çözerlerken hayvanın sahipleri onlara, \"Sıpayı niye çözüyorsunuz?\" dediler."},{"n":"34","t":"Onlar da, \"Rab'bin ona ihtiyacı var\" karşılığını verdiler."},{"n":"35","t":"Sıpayı İsa'ya getirdiler, üzerine kendi giysilerini atarak İsa'yı üstüne bindirdiler."},{"n":"36","t":"İsa ilerlerken halk, giysilerini yola seriyordu."},{"n":"37","t":"İsa Zeytin Dağı'ndan aşağı inen yola yaklaştığı sırada, öğrencilerinden oluşan kalabalığın tümü, görmüş oldukları bütün mucizelerden ötürü, sevinç içinde yüksek sesle Tanrı'yı övmeye başladılar."},{"n":"38","t":"\"Rab'bin adıyla gelen Kral'a övgüler olsun! Gökte esenlik, en yücelerde yücelik olsun!\" diyorlardı."},{"n":"39","t":"Kalabalığın içinden bazı Ferisiler O'na, \"Öğretmen, öğrencilerini sustur!\" dediler."},{"n":"40","t":"İsa, \"Size şunu söyleyeyim, bunlar susacak olsa, taşlar bağıracaktır!\" diye karşılık verdi. İsa Yeruşalim için Ağlıyor"},{"n":"41","t":"İsa Yeruşalim'e yaklaşıp kenti görünce ağladı."},{"n":"42","t":"\"Keşke bugün sen de esenliğe giden yolu bilseydin\" dedi. \"Ama şimdilik bu senin gözlerinden gizlendi."},{"n":"43","t":"Senin için öyle günler gelecek ki, düşmanların seni setlerle çevirecek, kuşatıp her yandan sıkıştıracaklar."},{"n":"44","t":"Seni de, bağrındaki çocukları da yere çalacaklar. Sende taş üstünde taş bırakmayacaklar. Çünkü Tanrı'nın senin yardımına geldiği zamanı farketmedin.\" İsa Satıcıları Tapınaktan Kovuyor (Mat.21:12-17; Mar.11:15-19; Yu.2:12-22)"},{"n":"45","t":"Sonra İsa tapınağın avlusuna girerek satıcıları dışarı kovmaya başladı."},{"n":"46","t":"Onlara, \"'Evim dua evi olacak' diye yazılmıştır. Ama siz onu haydut inine çevirdiniz\" dedi."},{"n":"47-48","t":"İsa her gün tapınakta öğretiyordu. Başkâhinler, din bilginleri ve halkın ileri gelenleri ise O'nu yok etmek istiyor, ama bunu nasıl yapacaklarını bilemiyorlardı. Çünkü bütün halk O'nu can kulağıyla dinliyordu."}]},{"ch":20,"verses":[{"n":"1","t":"O günlerden birinde, İsa tapınakta halka öğretip Müjde'yi duyururken, başkâhinler ve din bilginleri*, ileri gelenlerle birlikte çıkageldiler."},{"n":"2","t":"O'na, \"Söyle bize, bunları hangi yetkiyle yapıyorsun? Bu yetkiyi sana kim verdi?\" diye sordular."},{"n":"3-4","t":"İsa onlara şu karşılığı verdi: \"Ben de size bir soru soracağım. Söyleyin bana, Yahya'nın vaftiz* etme yetkisi Tanrı'dan*fx* mıydı, insanlardan mı?\""},{"n":"5","t":"Bunu aralarında şöyle tartıştılar: \"'Tanrı'dan' dersek, 'Ona niçin inanmadınız?' diyecek."},{"n":"6","t":"Yok eğer 'İnsanlardan' dersek, bütün halk bizi taşa tutacak. Çünkü Yahya'nın peygamber olduğuna inanmışlardır.\""},{"n":"7","t":"Sonunda, \"Nereden olduğunu bilmiyoruz\" yanıtını verdiler."},{"n":"8","t":"İsa da onlara, \"Ben de size bunları hangi yetkiyle yaptığımı söylemeyeceğim\" dedi. Bağ Kiracıları Benzetmesi (Mat.21:33-46; Mar.12:1-12)"},{"n":"9","t":"İsa sözüne devam ederek halka şu benzetmeyi anlattı: \"Adamın biri bağ dikti, bunu bağcılara kiralayıp uzun süre yolculuğa çıktı."},{"n":"10","t":"Mevsimi gelince, bağın ürününden payına düşeni vermeleri için bağcılara bir köle yolladı. Ama bağcılar köleyi dövüp eli boş gönderdiler."},{"n":"11","t":"Bağ sahibi başka bir köle daha yolladı. Bağcılar onu da dövdüler, aşağılayıp eli boş gönderdiler."},{"n":"12","t":"Adam bir üçüncüsünü yolladı, bağcılar onu da yaralayıp kovdular."},{"n":"13","t":"\"Bağın sahibi, 'Ne yapacağım?' dedi. 'Sevgili oğlumu göndereyim. Belki onu sayarlar.'"},{"n":"14","t":"\"Ama bağcılar onu görünce aralarında şöyle konuştular: 'Mirasçı budur; onu öldürelim de miras bize kalsın.'"},{"n":"15","t":"Böylece, onu bağdan dışarı atıp öldürdüler. \"Bu durumda bağın sahibi onlara ne yapacak?"},{"n":"16","t":"Gelip o bağcıları yok edecek, bağı da başkalarına verecek.\" Halk bunu duyunca, \"Tanrı korusun!\" dedi."},{"n":"17","t":"İsa gözlerinin içine bakarak şöyle dedi: \"Öyleyse Kutsal Yazılar'daki şu sözün anlamı nedir? 'Yapıcıların reddettiği taş, İşte köşenin baş taşı oldu.'"},{"n":"18","t":"O taşın üzerine düşen herkes paramparça olacak, taş da kimin üzerine düşerse onu ezip toz edecek.\""},{"n":"19","t":"İsa'nın bu benzetmeyi kendilerine karşı anlattığını farkeden din bilginleriyle başkâhinler O'nu o anda yakalamak istediler, ama halkın tepkisinden korktular. Sezar'ın Hakkı Sezar'a (Mat.22:15-22; Mar.12:13-17)"},{"n":"20","t":"İsa'yı dikkatle gözlüyorlardı. O'na, kendilerine dürüst süsü veren muhbirler gönderdiler. O'nu, söyleyeceği bir sözle tuzağa düşürmek ve böylelikle valinin yetki ve yargısına teslim etmek istiyorlardı."},{"n":"21-22","t":"Muhbirler O'na, \"Öğretmenimiz, senin doğru olanı söyleyip öğrettiğini, insanlar arasında ayrım yapmaksızın Tanrı yolunu dürüstçe öğrettiğini biliyoruz. Sezar'a* vergi vermemiz Kutsal Yasa'ya uygun mu, değil mi?\" diye sordular."},{"n":"23-24","t":"Onların hilesini anlayan İsa, \"Bana bir dinar gösterin\" dedi. \"Üzerindeki resim ve yazı kimin?\" \"Sezar'ın\" dediler."},{"n":"25","t":"O da, \"Öyleyse Sezar'ın hakkını Sezar'a, Tanrı'nın hakkını Tanrı'ya verin\" dedi."},{"n":"26","t":"İsa'yı, halkın önünde söylediği sözlerle tuzağa düşüremediler. Verdiği yanıta şaşarak susup kaldılar. Dirilişle İlgili Soru (Mat.22:23-33; Mar.12:18-27)"},{"n":"27-28","t":"Ölümden sonra dirilişi yadsıyan Sadukiler'den bazıları İsa'ya gelip şunu sordular: \"Öğretmenimiz, Musa yazılarında bize şöyle buyurmuştur: 'Eğer bir adamın evli kardeşi çocuksuz ölürse, adam ölenin karısını alıp soyunu sürdürsün.'"},{"n":"29","t":"Yedi kardeş vardı. Birincisi kendine bir eş aldı, ama çocuksuz öldü."},{"n":"30-31","t":"İkincisi de, üçüncüsü de kadını aldı; böylece kardeşlerin yedisi de çocuk bırakmadan öldü."},{"n":"32","t":"Son olarak kadın da öldü."},{"n":"33","t":"Buna göre, diriliş günü kadın bunlardan hangisinin karısı olacak? Çünkü yedisi de onunla evlendi.\""},{"n":"34","t":"İsa onlara şöyle dedi: \"Bu çağın insanları evlenip evlendirilirler."},{"n":"35","t":"Ama gelecek çağa ve ölülerin dirilişine erişmeye layık görülenler ne evlenir, ne evlendirilir."},{"n":"36","t":"Bir daha ölmeleri de söz konusu değildir. Çünkü meleklere benzerler ve dirilişin çocukları olarak Tanrı'nın çocuklarıdırlar."},{"n":"37","t":"Musa bile alevlenen çalıyla ilgili bölümde Rab için, 'İbrahim'in Tanrısı, İshak'ın Tanrısı ve Yakup'un Tanrısı' deyimini kullanarak ölülerin dirileceğine işaret etmişti."},{"n":"38","t":"Tanrı ölülerin değil, dirilerin Tanrısı'dır. Çünkü O'na göre bütün insanlar yaşamaktadır.\""},{"n":"39-40","t":"Artık O'na başka soru sormaya cesaret edemeyen din bilginlerinden bazıları, \"Öğretmenimiz, güzel konuştun\" dediler. Mesih Kimin Oğlu? (Mat.22:41-46; Mar.12:35-37)"},{"n":"41","t":"İsa onlara şöyle dedi: \"Nasıl oluyor da, 'Mesih* Davut'un Oğlu'dur' diyorlar?"},{"n":"42-43","t":"Çünkü Davut'un kendisi Mezmurlar Kitabı'nda şöyle diyor: Rab Rabbim'e dedi ki, Ben düşmanlarını Ayaklarının altına serinceye dek*fx* Sağımda otur.'"},{"n":"44","t":"Davut O'ndan 'Rab' diye söz ettiğine göre, O nasıl Davut'un Oğlu olur?\""},{"n":"45-46","t":"Bütün halk dinlerken İsa öğrencilerine şöyle dedi: \"Uzun kaftanlar içinde dolaşmaktan hoşlanan, meydanlarda selamlanmaya, havralarda en seçkin yerlere, şölenlerde başköşelere kurulmaya bayılan din bilginlerinden sakının."},{"n":"47","t":"Dul kadınların malını mülkünü sömüren, gösteriş için uzun uzun dua eden bu kişilerin cezası daha ağır olacaktır.\""}]},{"ch":21,"verses":[{"n":"1","t":"İsa başını kaldırdı ve bağış toplanan yerde bağışlarını bırakan zenginleri gördü."},{"n":"2-3","t":"Yoksul bir dul kadının oraya iki bakır para*fx* attığını görünce, \"Size gerçeği söyleyeyim\" dedi, \"Bu yoksul dul kadın herkesten daha çok verdi."},{"n":"4","t":"Çünkü bunların hepsi kutuya, zenginliklerinden artanı attılar. Bu kadın ise yoksulluğuna karşın, geçinmek için elinde ne varsa hepsini verdi.\" Sonun Belirtileri (Mat.24:1-35; Mar.13:1-31)"},{"n":"5-6","t":"Bazı kişiler tapınağın nasıl güzel taşlar ve adaklarla süslenmiş olduğundan söz edince İsa, \"Burada gördüklerinize gelince, öyle günler gelecek ki, taş üstünde taş kalmayacak, hepsi yıkılacak!\" dedi."},{"n":"7","t":"Onlar da, \"Peki, öğretmenimiz, bu dediklerin ne zaman olacak? Bunların gerçekleşmek üzere olduğunu gösteren belirti ne olacak?\" diye sordular."},{"n":"8","t":"İsa, \"Sakın sizi saptırmasınlar\" dedi. \"Birçokları, 'Ben O'yum' ve 'Zaman yaklaştı' diyerek benim adımla gelecekler. Onların ardından gitmeyin."},{"n":"9","t":"Savaş ve isyan haberleri duyunca telaşlanmayın. Önce bunların olması gerek, ama son hemen gelmeyecek.\""},{"n":"10","t":"Sonra onlara şöyle dedi: \"Ulus ulusa, devlet devlete savaş açacak."},{"n":"11","t":"Şiddetli depremler, yer yer kıtlıklar ve salgın hastalıklar, korkunç olaylar ve gökte olağanüstü belirtiler olacak."},{"n":"12","t":"\"Ama bütün bu olaylardan önce sizi yakalayıp zulmedecekler. Sizi havralara teslim edecek, zindanlara atacaklar. Benim adımdan ötürü kralların, valilerin önüne çıkarılacaksınız."},{"n":"13","t":"Bu size tanıklık etme fırsatı olacak."},{"n":"14","t":"Buna göre kendinizi nasıl savunacağınızı önceden düşünmemekte kararlı olun."},{"n":"15","t":"Çünkü ben size öyle bir konuşma yeteneği, öyle bir bilgelik vereceğim ki, size karşı çıkanların hiçbiri buna karşı direnemeyecek, bir şey diyemeyecek."},{"n":"16","t":"Anne babanız, kardeşleriniz, akraba ve dostlarınız bile sizi ele verecek ve bazılarınızı öldürtecekler."},{"n":"17","t":"Benim adımdan ötürü herkes sizden nefret edecek."},{"n":"18","t":"Ne var ki, başınızdaki saçlardan bir tel bile yok olmayacaktır."},{"n":"19","t":"Dayanmakla canlarınızı kazanacaksınız."},{"n":"20","t":"\"Yeruşalim'in ordular tarafından kuşatıldığını görünce bilin ki, kentin yıkılacağı zaman yaklaşmıştır."},{"n":"21","t":"O zaman Yahudiye'de bulunanlar dağlara kaçsın, kentte olanlar dışarı çıksın, kırdakiler kente dönmesin."},{"n":"22","t":"Çünkü o günler, yazılmış olanların tümünün gerçekleşeceği ceza günleridir."},{"n":"23","t":"O günlerde gebe olan, çocuk emziren kadınların vay haline! Çünkü ülke büyük sıkıntıya düşecek ve bu halk gazaba uğrayacaktır."},{"n":"24","t":"Kılıçtan geçirilecek, tutsak olarak bütün uluslar arasına sürülecekler. Yeruşalim, öteki ulusların dönemleri tamamlanıncaya dek onların ayakları altında çiğnenecektir."},{"n":"25","t":"\"Güneşte, ayda ve yıldızlarda belirtiler görülecek. Yeryüzünde uluslar denizin ve dalgaların uğultusundan şaşkına dönecek, dehşete düşecekler."},{"n":"26","t":"Dünyanın üzerine gelecek felaketleri bekleyen insanlar korkudan bayılacak. Çünkü göksel güçler sarsılacak."},{"n":"27","t":"O zaman İnsanoğlu'nun* bulut içinde büyük güç ve görkemle geldiğini görecekler."},{"n":"28","t":"Bu olaylar gerçekleşmeye başlayınca doğrulun ve başlarınızı kaldırın. Çünkü kurtuluşunuz yakın demektir.\""},{"n":"29","t":"İsa onlara şu benzetmeyi anlattı: \"İncir ağacına ya da herhangi bir ağaca bakın."},{"n":"30","t":"Bunların yapraklandığını gördüğünüz zaman yaz mevsiminin yakın olduğunu kendiliğinizden anlarsınız."},{"n":"31","t":"Aynı şekilde, bu olayların gerçekleştiğini gördüğünüzde bilin ki, Tanrı'nın Egemenliği yakındır."},{"n":"32","t":"Size doğrusunu söyleyeyim, bütün bunlar olmadan, bu kuşak*fx* ortadan kalkmayacak."},{"n":"33","t":"Yer ve gök ortadan kalkacak, ama benim sözlerim asla ortadan kalkmayacaktır."},{"n":"34-35","t":"\"Kendinize dikkat edin! Yürekleriniz sefahat, sarhoşluk ve bu yaşamın kaygılarıyla ağırlaşmasın. O gün, üzerinize bir tuzak gibi aniden inmesin. Çünkü o gün bütün yeryüzünde yaşayan herkesin üzerine gelecektir."},{"n":"36","t":"Her an uyanık kalın, gerçekleşmek üzere olan bütün bu olaylardan kurtulabilmek ve İnsanoğlu'nun önünde durabilmek için dua edin.\""},{"n":"37","t":"İsa gündüz tapınakta öğretiyor, geceleri ise kentten dışarı çıkıp Zeytin Dağı'nda sabahlıyordu."},{"n":"38","t":"Sabah erkenden bütün halk O'nu tapınakta dinlemek için O'na akın ediyordu."}]},{"ch":22,"verses":[{"n":"1","t":"Fısıh* denilen Mayasız Ekmek Bayramı* yaklaşmıştı."},{"n":"2","t":"Başkâhinlerle din bilginleri İsa'yı ortadan kaldırmak için bir yol arıyor, ama halktan korkuyorlardı."},{"n":"3","t":"Şeytan, Onikiler'den* biri olup İskariot diye adlandırılan Yahuda'nın yüreğine girdi."},{"n":"4","t":"Yahuda gitti, başkâhinler ve tapınak koruyucularının komutanlarıyla İsa'yı nasıl ele verebileceğini görüştü."},{"n":"5","t":"Onlar buna sevindiler ve kendisine para vermeye razı oldular."},{"n":"6","t":"Bunu kabul eden Yahuda, kalabalığın olmadığı bir zamanda İsa'yı ele vermek için fırsat kollamaya başladı. Fısıh Yemeği (Mat.26:17-35; Mar.14:12-31; Yu.13:21-30,36-38; 1Ko.11:23-25)"},{"n":"7","t":"Fısıh* kurbanının kesilmesi gereken Mayasız Ekmek Günü geldi."},{"n":"8","t":"İsa, Petrus'la Yuhanna'yı, \"Gidin, Fısıh yemeğini yiyebilmemiz için hazırlık yapın\" diyerek önden gönderdi."},{"n":"9","t":"O'na, \"Nerede hazırlık yapmamızı istersin?\" diye sordular."},{"n":"10-11","t":"İsa onlara, \"Bakın\" dedi, \"Kente girdiğinizde karşınıza su testisi taşıyan bir adam çıkacak. Adamı, gideceği eve kadar izleyin ve evin sahibine şöyle deyin: 'Öğretmen, öğrencilerimle birlikte Fısıh yemeğini yiyeceğim konuk odası nerede? diye soruyor.'"},{"n":"12","t":"Ev sahibi size üst katta, döşenmiş büyük bir oda gösterecek. Orada hazırlık yapın.\""},{"n":"13","t":"Onlar da gittiler, her şeyi İsa'nın kendilerine söylediği gibi buldular ve Fısıh yemeği için hazırlık yaptılar."},{"n":"14-15","t":"Yemek saati gelince İsa, elçileriyle birlikte sofraya oturdu ve onlara şöyle dedi: \"Ben acı çekmeden önce bu Fısıh yemeğini sizinle birlikte yemeyi çok arzulamıştım."},{"n":"16","t":"Size şunu söyleyeyim, Fısıh yemeğini, Tanrı'nın Egemenliği'nde yetkinliğe erişeceği*fx* zamana dek, bir daha yemeyeceğim.\""},{"n":"17","t":"Sonra kâseyi alarak şükretti ve, \"Bunu alın, aranızda paylaşın\" dedi."},{"n":"18","t":"\"Size şunu söyleyeyim, Tanrı'nın Egemenliği gelene dek, asmanın ürününden bir daha içmeyeceğim.\""},{"n":"19","t":"Sonra eline ekmek aldı, şükredip ekmeği böldü ve onlara verdi. \"Bu sizin uğrunuza feda edilen bedenimdir. Beni anmak için böyle yapın\" dedi."},{"n":"20","t":"Aynı şekilde, yemekten sonra kâseyi alıp şöyle dedi: \"Bu kâse, sizin uğrunuza akıtılan kanımla gerçekleşen yeni antlaşmadır."},{"n":"21","t":"Ama bana ihanet edecek kişinin eli şu anda benimkiyle birlikte sofradadır."},{"n":"22","t":"İnsanoğlu*, belirlenmiş olan yoldan gidiyor. Ama O'na ihanet eden adamın vay haline!\""},{"n":"23","t":"Elçiler, aralarında bunu kimin yapabileceğini tartışmaya başladılar."},{"n":"24","t":"Ayrıca aralarında hangisinin en üstün sayılacağı konusunda bir çekişme oldu."},{"n":"25","t":"İsa onlara, \"Ulusların kralları, kendi uluslarına egemen kesilirler. İleri gelenleri de kendilerine iyiliksever unvanını yakıştırırlar\" dedi."},{"n":"26","t":"\"Ama siz böyle olmayacaksınız. Aranızda en büyük olan, en küçük gibi olsun; yöneten, hizmet eden gibi olsun."},{"n":"27","t":"Hangisi daha büyük, sofrada oturan mı, hizmet eden mi? Sofrada oturan değil mi? Oysa ben aranızda hizmet eden biri gibi oldum."},{"n":"28","t":"Denendiğim zamanlar benimle birlikte dayanmış olanlar sizlersiniz."},{"n":"29","t":"Babam bana nasıl bir egemenlik verdiyse, ben de size bir egemenlik veriyorum."},{"n":"30","t":"Öyle ki, egemenliğimde benim soframda yiyip içesiniz ve tahtta oturarak İsrail'in on iki oymağını yargılayasınız."},{"n":"31","t":"\"Simun, Simun, Şeytan sizleri buğday gibi kalburdan geçirmek için izin almıştır."},{"n":"32","t":"Ama ben, imanını yitirmeyesin diye senin için dua ettim. Geri döndüğün zaman kardeşlerini güçlendir.\""},{"n":"33","t":"Simun İsa'ya, \"Ya Rab, ben seninle birlikte zindana da, ölüme de gitmeye hazırım\" dedi."},{"n":"34","t":"İsa, \"Sana şunu söyleyeyim, Petrus, bu gece horoz ötmeden beni tanıdığını üç kez inkâr edeceksin\" dedi."},{"n":"35","t":"Sonra İsa onlara, \"Ben sizi kesesiz, torbasız ve çarıksız gönderdiğim zaman, herhangi bir eksiğiniz oldu mu?\" diye sordu. \"Hiçbir eksiğimiz olmadı\" dediler."},{"n":"36","t":"O da onlara, \"Şimdi ise kesesi olan da, torbası olan da yanına alsın\" dedi. \"Kılıcı olmayan, abasını satıp bir kılıç alsın."},{"n":"37","t":"Size şunu söyleyeyim, yazılmış olan şu sözün yaşamımda yerine gelmesi gerekiyor: 'O, suçlularla bir sayıldı.' Gerçekten de benimle ilgili yazılmış olanlar yerine gelmektedir.\""},{"n":"38","t":"\"Ya Rab, işte burada iki kılıç var\" dediler. O da onlara, \"Yeter!\" dedi. Zeytin Dağı'ndaki Dua (Mat.26:36-46; Mar.14:32-42)"},{"n":"39","t":"İsa dışarı çıktı, her zamanki gibi Zeytin Dağı'na gitti. Öğrenciler de O'nun ardından gittiler."},{"n":"40","t":"Oraya varınca İsa onlara, \"Dua edin ki ayartılmayasınız\" dedi."},{"n":"41-42","t":"Onlardan bir taş atımı kadar uzaklaştı ve diz çökerek şöyle dua etti: \"Baba, senin isteğine uygunsa, bu kâseyi* benden uzaklaştır. Yine de benim değil, senin istediğin olsun.\""},{"n":"43","t":"Gökten bir melek İsa'ya görünerek O'nu güçlendirdi."},{"n":"44","t":"Derin bir acı içinde olan İsa daha hararetle dua etti. Teri, toprağa düşen kan damlalarını andırıyordu."},{"n":"45","t":"İsa duadan kalkıp öğrencilerin yanına dönünce onları üzüntüden uyumuş buldu."},{"n":"46","t":"Onlara, \"Niçin uyuyorsunuz?\" dedi. \"Kalkıp dua edin ki ayartılmayasınız.\" İsa Tutuklanıyor (Mat.26:47-68; Mar.14:43-50; Yu.18:3-12)"},{"n":"47-48","t":"İsa daha konuşurken bir kalabalık çıkageldi. Onikiler'den* biri, Yahuda adındaki kişi, kalabalığa öncülük ediyordu. İsa'yı öpmek üzere yaklaşınca İsa, \"Yahuda\" dedi, \"İnsanoğlu'na* bir öpücükle mi ihanet ediyorsun?\""},{"n":"49","t":"İsa'nın çevresindekiler olacakları anlayınca, \"Ya Rab, kılıçla vuralım mı?\" dediler."},{"n":"50","t":"İçlerinden biri başkâhinin kölesine vurarak sağ kulağını uçurdu."},{"n":"51","t":"Ama İsa, \"Bırakın, yeter!\" dedi, sonra kölenin kulağına dokunarak onu iyileştirdi."},{"n":"52","t":"İsa, üzerine yürüyen başkâhinlere, tapınak koruyucularının komutanlarına ve ileri gelenlere şöyle dedi: \"Niçin bir haydutmuşum gibi kılıç ve sopalarla geldiniz?"},{"n":"53","t":"Her gün tapınakta sizinle birlikteydim, bana el sürmediniz. Ama bu saat sizindir, karanlığın egemen olduğu saattir.\""},{"n":"54","t":"İsa'yı tutukladılar, alıp başkâhinin evine götürdüler. Petrus onları uzaktan izliyordu."},{"n":"55","t":"Avlunun ortasında ateş yakıp çevresinde oturduklarında Petrus da gelip onlarla birlikte oturdu."},{"n":"56","t":"Bir hizmetçi kız ateşin ışığında oturan Petrus'u gördü. Onu dikkatle süzerek, \"Bu da O'nunla birlikteydi\" dedi."},{"n":"57","t":"Ama Petrus, \"Ben O'nu tanımıyorum, kadın!\" diye inkâr etti."},{"n":"58","t":"Biraz sonra onu gören başka biri, \"Sen de onlardansın\" dedi. Petrus, \"Değilim, arkadaş!\" dedi."},{"n":"59","t":"Yaklaşık bir saat sonra yine bir başkası ısrarla, \"Gerçekten bu da O'nunla birlikteydi\" dedi. \"Çünkü Celileli'dir.\""},{"n":"60","t":"Petrus, \"Sen ne diyorsun be adam, anlamıyorum!\" dedi. Tam o anda, Petrus daha konuşurken horoz öttü."},{"n":"61-62","t":"Rab arkasına dönüp Petrus'a baktı. O zaman Petrus, Rab'bin kendisine, \"Bu gece horoz ötmeden beni üç kez inkâr edeceksin\" dediğini hatırladı ve dışarı çıkıp acı acı ağladı."},{"n":"63","t":"İsa'yı göz altında tutan adamlar O'nunla alay ediyor, O'nu dövüyorlardı."},{"n":"64","t":"Gözlerini bağlayıp, \"Peygamberliğini göster bakalım, sana vuran kim?\" diye soruyorlardı."},{"n":"65","t":"Kendisine daha bir sürü küfür yağdırdılar. İsa Yüksek Kurul'un Önünde (Mat.26:59-66; Mar.14:55-64; Yu.18:19-24)"},{"n":"66","t":"Gün doğunca halkın ileri gelenleri, başkâhinler ve din bilginleri toplandılar. İsa, bunlardan oluşan Yüksek Kurul'un* önüne çıkarıldı."},{"n":"67","t":"O'na, \"Sen Mesih* isen, söyle bize\" dediler. İsa onlara şöyle dedi: \"Size söylesem, inanmazsınız."},{"n":"68","t":"Size soru sorsam, yanıt vermezsiniz."},{"n":"69","t":"Ne var ki, bundan böyle İnsanoğlu*, kudretli Tanrı'nın sağında oturacaktır.\""},{"n":"70","t":"Onların hepsi, \"Yani, sen Tanrı'nın Oğlu musun?\" diye sordular. O da onlara, \"Söylediğiniz gibi, ben O'yum\" dedi."},{"n":"71","t":"\"Artık tanıklığa ne ihtiyacımız var?\" dediler. \"İşte kendi ağzından duyduk!\""}]},{"ch":23,"verses":[{"n":"1","t":"Sonra bütün kurul üyeleri kalkıp İsa'yı Pilatus'a götürdüler."},{"n":"2","t":"O'nu şöyle suçlamaya başladılar: \"Bu adamın ulusumuzu yoldan saptırdığını gördük. Sezar'a* vergi ödenmesine engel oluyor, kendisinin de Mesih*, yani bir kral olduğunu söylüyor.\""},{"n":"3","t":"Pilatus İsa'ya, \"Sen Yahudiler'in Kralı mısın?\" diye sordu. İsa, \"Söylediğin gibidir\" yanıtını verdi."},{"n":"4","t":"Pilatus, başkâhinlerle halka, \"Bu adamda hiçbir suç görmüyorum\" dedi."},{"n":"5","t":"Ama onlar üstelediler: \"Yahudiye'nin her tarafında öğretisini yayarak halkı kışkırtıyor; Celile'den başlayıp ta buraya kadar geldi\" dediler."},{"n":"6","t":"Pilatus bunu duyunca, \"Bu adam Celileli mi?\" diye sordu."},{"n":"7","t":"İsa'nın, Hirodes'in* yönetimindeki bölgeden geldiğini öğrenince, kendisini o sırada Yeruşalim'de bulunan Hirodes'e gönderdi."},{"n":"8","t":"Hirodes İsa'yı görünce çok sevindi. O'na ilişkin haberleri duyduğu için çoktandır O'nu görmek istiyor, gerçekleştireceği bir belirtiye tanık olmayı umuyordu."},{"n":"9","t":"O'na birçok soru sordu, ama O hiç karşılık vermedi."},{"n":"10","t":"Orada duran başkâhinlerle din bilginleri, İsa'yı ağır bir dille suçladılar."},{"n":"11","t":"Hirodes de askerleriyle birlikte O'nu aşağılayıp alay etti. O'na gösterişli bir kaftan giydirip Pilatus'a geri gönderdi."},{"n":"12","t":"Bu olaydan önce birbirine düşman olan Hirodes'le Pilatus, o gün dost oldular. Pilatus'un Kararı (Mat.27:15-26; Mar.15:6-15; Yu.18:39-19:16)"},{"n":"13-14","t":"Pilatus, başkâhinleri, yöneticileri ve halkı toplayarak onlara, \"Siz bu adamı bana, halkı saptırıyor diye getirdiniz\" dedi. \"Oysa ben bu adamı sizin önünüzde sorguya çektim ve kendisinde öne sürdüğünüz suçlardan hiçbirini bulmadım."},{"n":"15","t":"Hirodes de bulmamış olmalı ki, O'nu bize geri gönderdi. Görüyorsunuz, ölüm cezasını gerektiren hiçbir şey yapmadı."},{"n":"16-17","t":"Bu nedenle ben O'nu dövdürüp salıvereceğim.\"*fx*"},{"n":"18","t":"Ama onlar hep bir ağızdan, \"Yok et bu adamı, bize Barabba'yı salıver!\" diye bağırdılar."},{"n":"19","t":"Barabba, kentte çıkan bir ayaklanmaya katılmaktan ve adam öldürmekten hapse atılmıştı."},{"n":"20","t":"İsa'yı salıvermek isteyen Pilatus onlara yeniden seslendi."},{"n":"21","t":"Onlar ise, \"O'nu çarmıha ger, çarmıha ger!\" diye bağrışıp durdular."},{"n":"22","t":"Pilatus üçüncü kez, \"Bu adam ne kötülük yaptı ki?\" dedi. \"Ölüm cezasını gerektirecek hiçbir suç bulmadım O'nda. Bu nedenle O'nu dövdürüp salıvereceğim.\""},{"n":"23-24","t":"Ne var ki onlar, yüksek sesle bağrışarak İsa'nın çarmıha gerilmesi için direttiler. Sonunda bağırışları baskın çıktı ve Pilatus, onların isteğinin yerine getirilmesine karar verdi."},{"n":"25","t":"İstedikleri kişiyi, ayaklanmaya katılmak ve adam öldürmekten hapse atılan kişiyi salıverdi. İsa'yı ise onların isteğine bıraktı. İsa Çarmıha Geriliyor (Mat.27:32-44; Mar.15:21-32; Yu.19:17-27)"},{"n":"26","t":"Askerler İsa'yı götürürken, kırdan gelmekte olan Simun adında Kireneli bir adamı yakaladılar, çarmıhı sırtına yükleyip İsa'nın arkasından yürüttüler."},{"n":"27","t":"Büyük bir halk topluluğu da İsa'nın ardından gidiyordu. Aralarında İsa için dövünüp ağıt yakan kadınlar vardı."},{"n":"28","t":"İsa bu kadınlara dönerek, \"Ey Yeruşalim kızları, benim için ağlamayın\" dedi. \"Kendiniz ve çocuklarınız için ağlayın."},{"n":"29","t":"Çünkü öyle günler gelecek ki, 'Kısır kadınlara, hiç doğurmamış rahimlere, emzirmemiş memelere ne mutlu!' diyecekler."},{"n":"30","t":"O zaman dağlara, 'Üzerimize düşün!' ve tepelere, 'Bizi örtün!' diyecekler."},{"n":"31","t":"Çünkü yaş ağaca böyle yaparlarsa, kuruya neler olacaktır?\""},{"n":"32","t":"İsa'yla birlikte idam edilmek üzere ayrıca iki suçlu da götürülüyordu."},{"n":"33","t":"Kafatası denilen yere vardıklarında İsa'yı, biri sağında öbürü solunda olmak üzere, iki suçluyla birlikte çarmıha gerdiler."},{"n":"34","t":"İsa, \"Baba, onları bağışla\" dedi. \"Çünkü ne yaptıklarını bilmiyorlar.\" O'nun giysilerini aralarında paylaşmak için kura çektiler."},{"n":"35","t":"Halk orada durmuş, olanları seyrediyordu. Yöneticiler İsa'yla alay ederek, \"Başkalarını kurtardı; eğer Tanrı'nın Mesihi*, Tanrı'nın seçtiği O ise, kendini de kurtarsın\" diyorlardı."},{"n":"36-37","t":"Askerler de yaklaşıp İsa'yla eğlendiler. O'na ekşi şarap sunarak, \"Sen Yahudiler'in Kralı'ysan, kurtar kendini!\" dediler."},{"n":"38","t":"Başının üzerinde şu yafta vardı: YAHUDİLER'İN KRALI BUDUR"},{"n":"39","t":"Çarmıha asılan suçlulardan biri, \"Sen Mesih değil misin? Haydi, kendini de bizi de kurtar!\" diye küfür etti."},{"n":"40","t":"Ne var ki, öbür suçlu onu azarladı. \"Sende Tanrı korkusu da mı yok?\" diye karşılık verdi. \"Sen de aynı cezayı çekiyorsun."},{"n":"41","t":"Nitekim biz haklı olarak cezalandırılıyor, yaptıklarımızın karşılığını alıyoruz. Oysa bu adam hiçbir kötülük yapmadı.\""},{"n":"42","t":"Sonra, \"Ey İsa, kendi egemenliğine girdiğinde beni an\" dedi."},{"n":"43","t":"İsa ona, \"Sana doğrusunu söyleyeyim, sen bugün benimle birlikte cennette olacaksın\" dedi. İsa'nın Ölümü (Mat.27:45-56; Mar.15:33-41; Yu.19:28-30)"},{"n":"44-45","t":"Öğleyin on iki sularında güneş karardı, üçe kadar bütün ülkenin üzerine karanlık çöktü. Tapınaktaki perde* ortasından yırtıldı."},{"n":"46","t":"İsa yüksek sesle, \"Baba, ruhumu ellerine bırakıyorum!\" diye seslendi. Bunu söyledikten sonra son nefesini verdi."},{"n":"47","t":"Olanları gören yüzbaşı, \"Bu adam gerçekten doğru biriydi\" diyerek Tanrı'yı yüceltmeye başladı."},{"n":"48","t":"Olayı seyretmek için biriken halkın tümü olup bitenleri görünce göğüslerini döve döve geri döndüler."},{"n":"49","t":"Ama İsa'nın bütün tanıdıkları ve Celile'den O'nun ardından gelen kadınlar uzakta durmuş, olanları seyrediyorlardı. İsa'nın Gömülmesi (Mat.27:57-61; Mar.15:42-47; Yu.19:38-42)"},{"n":"50","t":"Yüksek Kurul* üyelerinden Yusuf adında iyi ve doğru bir adam vardı."},{"n":"51","t":"Bir Yahudi kenti olan Aramatya'dan olup Tanrı'nın Egemenliği'ni umutla bekleyen Yusuf, Kurul'un kararını ve eylemini onaylamamıştı."},{"n":"52","t":"Pilatus'a gidip İsa'nın cesedini istedi."},{"n":"53","t":"Cesedi çarmıhtan indirip keten beze sardı, hiç kimsenin konulmadığı, kayaya oyulmuş bir mezara yatırdı."},{"n":"54","t":"Hazırlık Günü'ydü* ve Şabat Günü* başlamak üzereydi."},{"n":"55","t":"İsa'yla birlikte Celile'den gelen kadınlar da Yusuf'un ardından giderek mezarı ve İsa'nın cesedinin oraya nasıl konulduğunu gördüler."},{"n":"56","t":"Evlerine dönerek baharat ve güzel kokulu yağlar hazırladılar. Ama Şabat Günü, Tanrı'nın buyruğu uyarınca dinlendiler."}]},{"ch":24,"verses":[{"n":"1","t":"Kadınlar haftanın ilk günü*, sabah çok erkenden, hazırlamış oldukları baharatı alıp mezara gittiler."},{"n":"2","t":"Taşı mezarın girişinden yuvarlanmış buldular."},{"n":"3","t":"Ama içeri girince Rab İsa'nın cesedini bulamadılar."},{"n":"4","t":"Onlar bu durum karşısında şaşırıp kalmışken, şimşek gibi parıldayan giysilere bürünmüş iki kişi yanlarında belirdi."},{"n":"5","t":"Korkuya kapılan kadınlar başlarını yere eğdiler. Adamlar ise onlara, \"Diri olanı neden ölüler arasında arıyorsunuz?\" dediler."},{"n":"6","t":"\"O burada yok, dirildi. Daha Celile'deyken size söylediğini anımsayın."},{"n":"7","t":"İnsanoğlu'nun* günahlı insanların eline verilmesi, çarmıha gerilmesi ve üçüncü gün dirilmesi gerektiğini bildirmişti.\""},{"n":"8","t":"O zaman İsa'nın sözlerini anımsadılar."},{"n":"9","t":"Mezardan dönen kadınlar bütün bunları Onbirler'e* ve ötekilerin hepsine bildirdiler."},{"n":"10","t":"Bunları elçilere anlatanlar, Mecdelli Meryem, Yohanna, Yakup'un annesi Meryem ve bunlarla birlikte bulunan öbür kadınlardı."},{"n":"11","t":"Ne var ki, bu sözler elçilere saçma geldi ve kadınlara inanmadılar."},{"n":"12","t":"Yine de, Petrus kalkıp mezara koştu. Eğilip içeri baktığında keten bezlerden başka bir şey görmedi. Olay karşısında şaşkına dönmüş bir halde oradan uzaklaştı. Emmaus Yolunda İki Öğrenci (Mar.16:12-13)"},{"n":"13","t":"Aynı gün öğrencilerden ikisi, Yeruşalim'den altmış ok atımı*fx* uzaklıkta bulunan ve Emmaus denilen bir köye gitmekteydiler."},{"n":"14","t":"Bütün bu olup bitenleri kendi aralarında konuşuyorlardı."},{"n":"15","t":"Bunları konuşup tartışırlarken İsa yanlarına geldi ve onlarla birlikte yürümeye başladı."},{"n":"16","t":"Ama onların gözleri O'nu tanıma gücünden yoksun bırakılmıştı."},{"n":"17","t":"İsa, \"Yolda birbirinizle ne tartışıp duruyorsunuz?\" dedi. Üzgün bir halde, oldukları yerde durdular."},{"n":"18","t":"Bunlardan adı Kleopas olan O'na, \"Yeruşalim'de bulunup da bu günlerde orada olup bitenleri bilmeyen tek yabancı sen misin?\" diye karşılık verdi."},{"n":"19","t":"İsa onlara, \"Hangi olup bitenleri?\" dedi. O'na, \"Nasıralı İsa'yla ilgili olayları\" dediler. \"O adam, Tanrı'nın ve bütün halkın önünde gerek söz, gerek eylemde güçlü bir peygamberdi."},{"n":"20-23","t":"Başkâhinlerle yöneticilerimiz O'nu, ölüm cezasına çarptırmak için valiye teslim ederek çarmıha gerdirdiler; oysa biz O'nun, İsrail'i kurtaracak kişi olduğunu ummuştuk. Dahası var, bu olaylar olalı üç gün oldu ve aramızdan bazı kadınlar bizi şaşkına çevirdiler. Bu sabah erkenden mezara gittiklerinde, O'nun cesedini bulamamışlar. Sonra geldiler, bir görümde, İsa'nın yaşamakta olduğunu bildiren melekler gördüklerini söylediler."},{"n":"24","t":"Bizimle birlikte olanlardan bazıları mezara gitmiş ve durumu, tam kadınların anlatmış olduğu gibi bulmuşlar. Ama O'nu görmemişler.\""},{"n":"25","t":"İsa onlara, \"Sizi akılsızlar! Peygamberlerin bütün söylediklerine inanmakta ağır davranan kişiler!"},{"n":"26","t":"Mesih'in* bu acıları çekmesi ve yüceliğine kavuşması gerekli değil miydi?\" dedi."},{"n":"27","t":"Sonra Musa'nın ve bütün peygamberlerin yazılarından başlayarak, Kutsal Yazılar'ın hepsinde kendisiyle ilgili olanları onlara açıkladı."},{"n":"28-29","t":"Gitmekte oldukları köye yaklaştıkları sırada İsa, yoluna devam edecekmiş gibi davrandı. Ama onlar, \"Bizimle kal. Neredeyse akşam olacak, gün batmak üzere\" diyerek O'nu zorladılar. Böylece İsa onlarla birlikte kalmak üzere içeri girdi."},{"n":"30","t":"Onlarla sofrada otururken İsa ekmek aldı, şükretti ve ekmeği bölüp onlara verdi."},{"n":"31","t":"O zaman onların gözleri açıldı ve kendisini tanıdılar. İsa ise gözlerinin önünden kayboldu."},{"n":"32","t":"Onlar birbirine, \"Yolda kendisi bizimle konuşurken ve Kutsal Yazılar'ı bize açıklarken yüreklerimiz nasıl da sevinçle çarpıyordu, değil mi?\" dediler."},{"n":"33","t":"Kalkıp hemen Yeruşalim'e döndüler. Onbirler'i* ve onlarla birlikte olanları toplanmış buldular."},{"n":"34","t":"Bunlar, \"Rab gerçekten dirildi, Simun'a görünmüş!\" diyorlardı."},{"n":"35","t":"Kendileri de yolda olup bitenleri ve ekmeği böldüğü zaman İsa'yı nasıl tanıdıklarını anlattılar. İsa Onbirler'e Görünüyor (Mat.28:16-20; Mar.16:14-18; Yu.20:19-23; Elç.1:6-8)"},{"n":"36","t":"Bunları anlatırlarken İsa gelip aralarında durdu. Onlara, \"Size esenlik olsun!\" dedi."},{"n":"37","t":"Ürktüler, bir hayalet gördüklerini sanarak korkuya kapıldılar."},{"n":"38","t":"İsa onlara, \"Neden telaşlanıyorsunuz? Neden kuşkular doğuyor içinizde?\" dedi."},{"n":"39","t":"\"Ellerime, ayaklarıma bakın; işte benim! Dokunun da görün. Hayaletin eti kemiği olmaz, ama görüyorsunuz, benim var.\""},{"n":"40","t":"Bunu söyledikten sonra onlara ellerini ve ayaklarını gösterdi."},{"n":"41","t":"Sevinçten hâlâ inanamayan, şaşkınlık içindeki öğrencilerine, \"Sizde yiyecek bir şey var mı?\" diye sordu."},{"n":"42","t":"Kendisine bir parça kızarmış balık verdiler."},{"n":"43","t":"İsa onu alıp gözlerinin önünde yedi."},{"n":"44","t":"Sonra onlara şöyle dedi: \"Daha sizlerle birlikteyken, 'Musa'nın Yasası'nda, peygamberlerin yazılarında ve Mezmurlar'da benimle ilgili yazılmış olanların tümünün gerçekleşmesi gerektir' demiştim.\""},{"n":"45","t":"Bundan sonra Kutsal Yazılar'ı anlayabilmeleri için zihinlerini açtı."},{"n":"46-47","t":"Onlara dedi ki, \"Şöyle yazılmıştır: Mesih acı çekecek ve üçüncü gün ölümden dirilecek; günahların bağışlanması için tövbe çağrısı da Yeruşalim'den başlayarak bütün uluslara O'nun adıyla duyurulacak."},{"n":"48","t":"Sizler bu olayların tanıklarısınız."},{"n":"49","t":"Ben de Babam'ın vaat ettiğini size göndereceğim. Ama siz, yücelerden gelecek güçle kuşanıncaya dek kentte kalın.\" İsa'nın Göğe Yükselmesi (Mar.16:19-20; Elç.1:9-11)"},{"n":"50","t":"İsa onları kentin dışına, Beytanya'nın yakınlarına kadar götürdü. Ellerini kaldırarak onları kutsadı."},{"n":"51","t":"Ve onları kutsarken yanlarından ayrıldı, göğe alındı."},{"n":"52","t":"Öğrencileri O'na tapındılar ve büyük sevinç içinde Yeruşalim'e döndüler."},{"n":"53","t":"Sürekli tapınakta bulunuyor, Tanrı'yı övüyorlardı."}]},{"ch":25,"verses":[{"n":"22","t":"\"Arınma günleri\": Lev.12:1-4'e göre bir kadın, bir erkek çocuk doğurduktan sonra kırk gün süreyle dinsel açıdan kirli sayılırdı. Bu dönemin sonunda bir kurban sunarak tekrar temiz hale"},{"n":"29","t":"\"Artık ben, kulun huzur içinde ölebilirim\": Grekçe \"Kulunu şimdi esenlikle salıveriyorsun\". 3:32 \"Salmon\": Bazı Grekçe elyazmalarında, \"Sala\" diye"},{"n":"33","t":"\"Ram oğlu\": Bazı Grekçe elyazmalarında, \"Admin oğlu, Arni oğlu\" diye"},{"n":"44","t":"\"Yahudiye'deki\": Birçok Grekçe elyazmasında, \"Celile'deki\" diye"},{"n":"45","t":"\"Petrus\": Birçok Grekçe elyazmasında, \"Petrus ve yanındakiler\" diye"},{"n":"30-31","t":"\"Ayrılış\":"},{"n":"56","t":"Bazı Grekçe elyazmalarında 54-56 ayetleri şöyle geçer: ...\"'Rab, İlyas'ın yaptığı gibi, bunları yok etmek için bir buyrukla gökten ateş yağdırmamızı ister misin?' dediler. 55 Ama İsa dönüp onları azarladı ve şöyle dedi: 'Siz hangi ruha ait olduğunuzu bilmiyorsunuz. 56 Çünkü İnsanoğlu insanları yok etmeye değil, kurtarmaya geldi.' Sonra...\" 11:41 \"Kaplarınızın içindekini\": Grekçe \"İçtekileri\". 12:25 \"Ömrünü bir anlık\" ya da \"Boyunu bir arşın\". 12:38 \"Nöbet\": Bkz. Sözlük, \"Saat\". 12:50 Bu ayette İsa vaftiz diye çarmıhtaki ölümünden söz"},{"n":"59","t":"\"Kuruş\": Grekçe \"Lepton\" (bkz. Birimler Cetveli). 13:21 \"Ölçek\": Grekçe \"Saton\" (bkz. Birimler Cetveli). 14:25-26 \"Biri bana gelip de babasını, annesini, karısını, çocuklarını, kardeşlerini, hatta kendi canını bile gözden çıkarmazsa\": Grekçe \"Biri bana gelip de babasından, annesinden, karısından, çocuklarından, kardeşlerinden, hatta kendi canından bile nefret etmezse\". 15:18,21 \"Tanrı'ya\": Grekçe \"Göğe\". 16:6 \"Ölçek\": Grekçe \"Batos\" (bkz. Birimler Cetveli). 16:7 \"Ölçek\": Grekçe \"Koros\" (bkz. Birimler Cetveli). 16:8 \"Işıkta yürüyenlerden\": Grekçe \"Işık oğullarından\". 16:9 \"Dünyanın aldatıcı serveti\": Grekçe \"Haksızlık mamonu\". Aramice'de* zenginlik anlamına gelen mamon sözcüğü, para ya da para kazanma hırsı anlamında kullanılır. Buna benzer bir deyim 11. ayette de k"},{"n":"13","t":"\"Para\": Grekçe \"Mamon\". Aramice'de* zenginlik anlamına gelen mamon sözcüğü, para ya da para kazanma hırsı anlamında"},{"n":"35-36","t":"Bazı Grekçe elyazmaları, \"Tarlada bulunan iki kişiden biri alınacak, öbürü bırakılacak\" sözlerini de içerir (bkz. Mat.24:40). 20:3-4 \"Yahya'nın vaftiz etme yetkisi Tanrı'dan\": Grekçe \"Yahya'nın vaftizi gökten\". 5. ayette de \"Tanrı'dan\" diye çevrilen sözcük Grekçe \"Gökten\" diye"},{"n":"42-43","t":"\"Ayaklarının altına serinceye dek\": Grekçe \"Ayaklarına tabure yapıncaya dek\". 21:2-3 \"Bakır para\": Grekçe \"Lepton\" (bkz. Birimler Cetveli). 21:32 \"Kuşak\" ya da \"Soy\". 22:16 \"Yetkinliğe erişeceği\": Grekçe \"Tamamlanacağı\". 23:16-17 Birçok Grekçe elyazması, \"Pilatus'un her Fısıh Bayramı'nda onlar için bir kişi salıvermesi gerekiyordu\" sözlerini de"},{"n":"13","t":"\"Altmış ok atımı\": Yaklaşık 11 km."}]}]},{"id":"yuhanna","name":"Yuhanna","chapters":[{"ch":1,"verses":[{"n":"1","t":"Başlangıçta Söz vardı. Söz Tanrı'yla birlikteydi ve Söz Tanrı'ydı."},{"n":"2","t":"Başlangıçta O, Tanrı'yla birlikteydi."},{"n":"3","t":"Her şey O'nun aracılığıyla var oldu, var olan hiçbir şey O'nsuz olmadı."},{"n":"4","t":"Yaşam O'ndaydı ve yaşam insanların ışığıydı."},{"n":"5","t":"Işık karanlıkta parlar. Karanlık onu alt edemedi*fx*."},{"n":"6","t":"Tanrı'nın gönderdiği Yahya adlı bir adam ortaya çıktı."},{"n":"7","t":"Tanıklık amacıyla, ışığa tanıklık etsin ve herkes onun aracılığıyla iman etsin diye geldi."},{"n":"8","t":"Kendisi ışık değildi, ama ışığa tanıklık etmeye geldi."},{"n":"9","t":"Dünyaya gelen, her insanı aydınlatan gerçek ışık vardı."},{"n":"10","t":"O, dünyadaydı, dünya O'nun aracılığıyla var oldu, ama dünya O'nu tanımadı."},{"n":"11","t":"Kendi yurduna geldi, ama kendi halkı O'nu kabul etmedi."},{"n":"12","t":"Kendisini kabul edip adına iman edenlerin hepsine Tanrı'nın çocukları olma hakkını verdi."},{"n":"13","t":"Onlar ne kandan, ne beden ne de insan isteğinden doğdular; tersine, Tanrı'dan doğdular."},{"n":"14","t":"Söz, insan*fx* olup aramızda yaşadı. O'nun yüceliğini Baba'dan gelen, lütuf ve gerçekle dolu biricik Oğul'un yüceliğini gördük."},{"n":"15","t":"Yahya O'na tanıklık etti. Yüksek sesle şöyle dedi: \"'Benden sonra gelen benden üstündür. Çünkü O benden önce vardı' diye sözünü ettiğim kişi budur.\""},{"n":"16","t":"Nitekim hepimiz O'nun doluluğundan lütuf üzerine lütuf aldık."},{"n":"17","t":"Kutsal Yasa Musa aracılığıyla verildi, ama lütuf ve gerçek İsa Mesih* aracılığıyla geldi."},{"n":"18","t":"Tanrı'yı hiçbir zaman hiç kimse görmedi. Baba'nın bağrında bulunan ve Tanrı olan biricik Oğul O'nu tanıttı. Yahya'nın Ortaya Çıkışı (Mat.3:112; Mar.1:18; Luk.3:118) Yu.1: 1920 Yahudi yetkililer*fx* Yahya'ya, \"Sen kimsin?\" diye sormak üzere Yeruşalim'den* kâhinlerle* Levililer'i* gönderdikleri zaman Yahya'nın tanıklığı şöyle oldu açıkça konuştu, inkâr etmedi \"Ben Mesih* değilim\" diye açıkça konuştu."},{"n":"21","t":"Onlar da kendisine, \"Öyleyse sen kimsin? İlyas mısın?\" diye sordular. O da, \"Değilim\" dedi. \"Sen beklediğimiz peygamber misin?\" sorusuna, \"Hayır\" yanıtını verdi."},{"n":"22","t":"Bu kez, \"Kim olduğunu söyle de bizi gönderenlere bir yanıt verelim\" dediler. \"Kendin için ne diyorsun?\""},{"n":"23","t":"Yahya, \"Peygamber Yeşaya'nın dediği gibi, 'Rab'bin yolunu düzleyin' diye çölde haykıranın sesiyim ben\" dedi. Yu.1: 2425 Yahya'ya gönderilen bazı Ferisiler* ona, \"Sen Mesih, İlyas ya da beklediğimiz peygamber değilsen, niye vaftiz* ediyorsun?\" diye sordular."},{"n":"26","t":"Yahya onlara şöyle yanıt verdi: \"Ben suyla vaftiz ediyorum, ama aranızda tanımadığınız biri duruyor."},{"n":"27","t":"Benden sonra gelen O'dur. Ben O'nun çarığının bağını çözmeye bile layık değilim.\""},{"n":"28","t":"Bütün bunlar Şeria Irmağı'nın ötesinde bulunan Beytanya'da, Yahya'nın vaftiz ettiği yerde oldu. Tanrı Kuzusu"},{"n":"29","t":"Yahya ertesi gün İsa'nın kendisine doğru geldiğini görünce şöyle dedi: \"İşte, dünyanın günahını ortadan kaldıran Tanrı Kuzusu!"},{"n":"30","t":"Kendisi için, 'Benden sonra biri geliyor, O benden üstündür. Çünkü O benden önce vardı' dediğim kişi işte budur."},{"n":"31","t":"Ben O'nu tanımıyordum, ama İsrail'in O'nu tanıması için ben suyla vaftiz ederek geldim.\""},{"n":"32","t":"Yahya tanıklığını şöyle sürdürdü: \"Ruh'un güvercin gibi gökten indiğini, O'nun üzerinde durduğunu gördüm."},{"n":"33","t":"Ben O'nu tanımıyordum. Ama suyla vaftiz etmek için beni gönderen, 'Ruh'un kimin üzerine inip durduğunu görürsen, Kutsal Ruh'la vaftiz eden O'dur' dedi."},{"n":"34","t":"Ben de gördüm ve 'Tanrı'nın Oğlu budur' diye tanıklık ettim.\" İsa'nın İlk Öğrencileri"},{"n":"35","t":"Ertesi gün Yahya yine öğrencilerinden ikisiyle birlikteydi."},{"n":"36","t":"Oradan geçen İsa'ya bakarak, \"İşte Tanrı Kuzusu!\" dedi."},{"n":"37","t":"Onun söylediklerini duyan iki öğrenci İsa'nın ardından gitti."},{"n":"38","t":"İsa arkasına dönüp ardından geldiklerini görünce, \"Ne arıyorsunuz?\" diye sordu. Onlar da, \"Rabbî, nerede oturuyorsun?\" dediler. Rabbî, öğretmenim anlamına gelir."},{"n":"39","t":"İsa, \"Gelin, görün\" dedi. Gidip O'nun nerede oturduğunu gördüler ve o gün O'nunla kaldılar. Saat* dört sularıydı."},{"n":"40","t":"Yahya'yı işitip İsa'nın ardından giden iki kişiden biri Simun Petrus'un kardeşi Andreas'tı."},{"n":"41","t":"Andreas önce kendi kardeşi Simun'u bularak ona, \"Biz Mesih'i bulduk\" dedi. Mesih, meshedilmiş* anlamına gelir."},{"n":"42","t":"Andreas kardeşini İsa'ya götürdü. İsa ona baktı, \"Sen Yuhanna'nın oğlu Simun'sun. Kefas diye çağrılacaksın\" dedi. Kefas, kaya*fx* anlamına gelir."},{"n":"43","t":"Ertesi gün İsa, Celile'ye gitmeye karar verdi. Filipus'u bulup ona, \"Ardımdan gel\" dedi."},{"n":"44","t":"Filipus da Andreas ile Petrus'un kenti olan Beytsayda'dandı."},{"n":"45","t":"Filipus, Natanel'i bularak ona, \"Musa'nın Kutsal Yasa'da hakkında yazdığı, peygamberlerin de sözünü ettiği kişiyi, Yusuf oğlu Nasıralı İsa'yı bulduk\" dedi."},{"n":"46","t":"Natanel Filipus'a, \"Nasıra'dan iyi bir şey çıkabilir mi?\" diye sordu. Filipus, \"Gel de gör\" dedi."},{"n":"47","t":"İsa, Natanel'in kendisine doğru geldiğini görünce onun için, \"İşte, içinde hile olmayan gerçek bir İsrailli!\" dedi."},{"n":"48","t":"Natanel, \"Beni nereden tanıyorsun?\" diye sordu. İsa, \"Filipus çağırmadan önce seni incir ağacının altında gördüm\" yanıtını verdi."},{"n":"49","t":"Natanel, \"Rabbî, sen Tanrı'nın Oğlu'sun, sen İsrail'in Kralı'sın!\" dedi."},{"n":"50","t":"İsa ona dedi ki, \"Seni incir ağacının altında gördüğümü söylediğim için mi inanıyorsun? Bunlardan daha büyük şeyler göreceksin.\""},{"n":"51","t":"Sonra da, \"Size doğrusunu söyleyeyim, göğün açıldığını, Tanrı meleklerinin İnsanoğlu* üzerinde yükselip indiklerini göreceksiniz\" dedi."}]},{"ch":2,"verses":[{"n":"1","t":"Üçüncü gün Celile'nin Kana Köyü'nde bir düğün vardı. İsa'nın annesi de oradaydı."},{"n":"2","t":"İsa'yla öğrencileri de düğüne çağrılmışlardı."},{"n":"3","t":"Şarap tükenince annesi İsa'ya, \"Şarapları kalmadı\" dedi."},{"n":"4","t":"İsa, \"Anne*fx*, benden ne istiyorsun? Benim saatim daha gelmedi\" dedi."},{"n":"5","t":"Annesi hizmet edenlere, \"Size ne derse onu yapın\" dedi."},{"n":"6","t":"Yahudiler'in geleneksel temizliği için oraya konmuş, her biri seksenle yüz yirmi litre*fx* alan altı taş küp vardı."},{"n":"7","t":"İsa hizmet edenlere, \"Küpleri suyla doldurun\" dedi. Küpleri ağızlarına kadar doldurdular."},{"n":"8","t":"Sonra hizmet edenlere, \"Şimdi biraz alıp şölen başkanına götürün\" dedi. Onlar da götürdüler."},{"n":"910","t":"Şölen başkanı, şaraba dönüşmüş suyu tattı. Bunun nereden geldiğini bilmiyordu, oysa suyu küpten alan hizmetkârlar biliyorlardı. Şölen başkanı güveyi çağırıp, \"Herkes önce iyi şarabı, çok içildikten sonra da kötüsünü sunar\" dedi, \"Ama sen iyi şarabı şimdiye dek saklamışsın.\""},{"n":"11","t":"İsa bu ilk doğaüstü belirtisini Celile'nin Kana Köyü'nde gerçekleştirdi ve yüceliğini gösterdi. Öğrencileri de O'na iman ettiler. İsa Satıcıları Tapınaktan Kovuyor (Mat.21:1213; Mar.11:1517; Luk.19:4546)"},{"n":"12","t":"Bundan sonra İsa, annesi, kardeşleri ve öğrencileri Kefarnahum'a gidip orada birkaç gün kaldılar."},{"n":"13","t":"Yahudiler'in Fısıh Bayramı* yakındı. İsa da Yeruşalim'e gitti."},{"n":"14","t":"Tapınağın avlusunda sığır, koyun ve güvercin satanları, orada oturmuş para bozanları* gördü."},{"n":"15","t":"İpten bir kamçı yaparak hepsini koyunlar ve sığırlarla birlikte tapınaktan kovdu, para bozanların paralarını döküp masalarını devirdi."},{"n":"16","t":"Güvercin satanlara, \"Bunları buradan kaldırın, Babam'ın evini pazar yerine çevirmeyin!\" dedi."},{"n":"17","t":"Öğrencileri, \"Evin için gösterdiğim gayret beni yiyip bitirecek\" diye yazılmış olan sözü hatırladılar."},{"n":"18","t":"Yahudi yetkililer İsa'ya, \"Bunları yaptığına göre, bize nasıl bir belirti göstereceksin?\" diye sordular."},{"n":"19","t":"İsa şu yanıtı verdi: \"Bu tapınağı yıkın, üç günde onu yeniden kuracağım.\""},{"n":"20","t":"Yahudi yetkililer, \"Bu tapınak kırk altı yılda yapıldı, sen onu üç günde mi kuracaksın?\" dediler."},{"n":"21","t":"Ama İsa'nın sözünü ettiği tapınak kendi bedeniydi."},{"n":"22","t":"İsa ölümden dirilince öğrencileri bu sözü söylediğini hatırladılar, Kutsal Yazı'ya ve İsa'nın söylediği bu söze iman ettiler."},{"n":"23","t":"Fısıh Bayramı'nda İsa'nın Yeruşalim'de bulunduğu sırada gerçekleştirdiği belirtileri gören birçokları O'nun adına iman ettiler."},{"n":"24","t":"Ama İsa bütün insanların yüreğini bildiği için onlara güvenmiyordu."},{"n":"25","t":"İnsan hakkında kimsenin O'na bir şey söylemesine gerek yoktu. Çünkü kendisi insanın içinden geçenleri biliyordu."}]},{"ch":3,"verses":[{"n":"12","t":"Yahudiler'in Nikodim adlı bir önderi vardı. Ferisiler'den* olan bu adam bir gece İsa'ya gelerek, \"Rabbî*, senin Tanrı'dan gelmiş bir öğretmen olduğunu biliyoruz. Çünkü Tanrı kendisiyle olmadıkça kimse senin yaptığın bu mucizeleri yapamaz\" dedi."},{"n":"3","t":"İsa ona şu karşılığı verdi: \"Sana doğrusunu söyleyeyim, bir kimse yeniden*fx* doğmadıkça Tanrı'nın Egemenliği'ni göremez.\""},{"n":"4","t":"Nikodim, \"Yaşlanmış bir adam nasıl doğabilir? Annesinin rahmine ikinci kez girip doğabilir mi?\" diye sordu."},{"n":"5","t":"İsa şöyle yanıt verdi: \"Sana doğrusunu söyleyeyim, bir kimse sudan ve Ruh'tan doğmadıkça Tanrı'nın Egemenliği'ne giremez."},{"n":"6","t":"Bedenden doğan bedendir, Ruh'tan doğan ruhtur."},{"n":"7","t":"Sana, 'Yeniden doğmalısınız' dediğime şaşma."},{"n":"8","t":"Yel dilediği yerde eser; sesini işitirsin, ama nereden gelip nereye gittiğini bilemezsin. Ruh'tan doğan herkes böyledir.\""},{"n":"9","t":"Nikodim İsa'ya, \"Bunlar nasıl olabilir?\" diye sordu."},{"n":"10","t":"İsa ona şöyle yanıt verdi: \"Sen İsrail'in öğretmeni olduğun halde bunları anlamıyor musun?"},{"n":"11","t":"Sana doğrusunu söyleyeyim, biz bildiğimizi söylüyoruz, gördüğümüze tanıklık ediyoruz. Sizler ise bizim tanıklığımızı kabul etmiyorsunuz."},{"n":"12","t":"Sizlere yeryüzüyle ilgili şeyleri söylediğim zaman inanmazsanız, gökle ilgili şeyleri söylediğimde nasıl inanacaksınız?"},{"n":"13","t":"Gökten inmiş olan*fx* İnsanoğlu'ndan* başka hiç kimse göğe çıkmamıştır."},{"n":"14","t":"Musa çölde yılanı nasıl yukarı kaldırdıysa, İnsanoğlu'nun da öylece yukarı kaldırılması gerekir."},{"n":"15","t":"Öyle ki, O'na iman eden herkes sonsuz yaşama kavuşsun."},{"n":"16","t":"\"Çünkü Tanrı dünyayı o kadar çok sevdi ki, biricik Oğlu'nu verdi. Öyle ki, O'na iman edenlerin hiçbiri mahvolmasın, hepsi sonsuz yaşama kavuşsun."},{"n":"17","t":"Tanrı, Oğlu'nu dünyayı yargılamak için göndermedi, dünya O'nun aracılığıyla kurtulsun diye gönderdi."},{"n":"18","t":"O'na iman eden yargılanmaz, iman etmeyen ise zaten yargılanmıştır. Çünkü Tanrı'nın biricik Oğlu'nun adına iman etmemiştir."},{"n":"19","t":"Yargı da şudur: Dünyaya ışık geldi, ama insanlar ışık yerine karanlığı sevdiler. Çünkü yaptıkları işler kötüydü."},{"n":"20","t":"Kötülük yapan herkes ışıktan nefret eder ve yaptıkları açığa çıkmasın diye ışığa yaklaşmaz."},{"n":"21","t":"Ama gerçeği uygulayan kişi yaptıklarını, Tanrı'ya dayanarak yaptığını göstermek için ışığa gelir.\" Yahya'nın Tanıklığı"},{"n":"22","t":"Bundan sonra İsa'yla öğrencileri Yahudiye diyarına gittiler. İsa onlarla birlikte orada bir süre kalarak vaftiz* etti."},{"n":"23","t":"Yahya da Salim yakınındaki Aynon'da vaftiz ediyordu. Çünkü orada bol su vardı. İnsanlar gelip vaftiz oluyorlardı."},{"n":"24","t":"Yahya henüz hapse atılmamıştı."},{"n":"25","t":"O sıralarda Yahya'nın öğrencileriyle bir Yahudi arasında temizlenme konusunda bir tartışma çıktı."},{"n":"26","t":"Öğrencileri Yahya'ya gelerek, \"Rabbî\" dediler, \"Şeria Irmağı'nın karşı yakasında birlikte olduğun ve kendisi için tanıklık ettiğin adam var ya, işte O vaftiz ediyor, herkes de O'na gidiyor.\""},{"n":"27","t":"Yahya şöyle yanıt verdi: \"İnsan, kendisine gökten verilmedikçe hiçbir şey alamaz."},{"n":"28","t":"'Ben Mesih* değilim, ama O'nun öncüsü olarak gönderildim' dediğime siz kendiniz tanıksınız."},{"n":"29","t":"Gelin kiminse, güvey odur. Ama güveyin yanında duran ve onu dinleyen dostu onun sesini işitince çok sevinir. İşte benim sevincim böylece tamamlandı."},{"n":"30","t":"O büyümeli, bense küçülmeliyim.\""},{"n":"31","t":"Yukarıdan gelen, herkesten üstündür. Dünyadan olan dünyaya aittir ve dünyadan söz eder. Gökten gelen ise, herkesten üstündür."},{"n":"32","t":"Ne görmüş ne işitmişse ona tanıklık eder, ama tanıklığını kimse kabul etmez."},{"n":"33","t":"O'nun tanıklığını kabul eden, Tanrı'nın gerçek olduğuna mührünü basmıştır."},{"n":"34","t":"Tanrı'nın gönderdiği kişi Tanrı'nın sözlerini söyler. Çünkü Tanrı, Ruh'u ölçüyle vermez."},{"n":"35","t":"Baba Oğul'u sever; her şeyi O'na teslim etmiştir."},{"n":"36","t":"Oğul'a iman edenin sonsuz yaşamı vardır. Ama Oğul'un sözünü dinlemeyen yaşamı görmeyecektir. Tanrı'nın gazabı böylesinin üzerinde kalır."}]},{"ch":4,"verses":[{"n":"13","t":"Ferisiler*, İsa'nın Yahya'dan daha çok öğrenci edinip vaftiz* ettiğini duydular aslında İsa'nın kendisi değil, öğrencileri vaftiz ediyorlardı İsa bunu öğrenince Yahudiye'den ayrılıp yine Celile'ye gitti."},{"n":"4","t":"Giderken Samiriye'den geçmesi gerekiyordu."},{"n":"5","t":"Böylece Samiriye'nin Sihar denilen kentine geldi. Burası Yakup'un kendi oğlu Yusuf'a vermiş olduğu toprağın yakınındaydı."},{"n":"6","t":"Yakup'un kuyusu da oradaydı. İsa, yolculuktan yorulmuş olduğu için kuyunun yanına oturmuştu. Saat* on iki sularıydı."},{"n":"7","t":"Samiriyeli* bir kadın su çekmeye geldi. İsa ona, \"Bana su ver, içeyim\" dedi."},{"n":"8","t":"İsa'nın öğrencileri yiyecek satın almak için kente gitmişlerdi."},{"n":"9","t":"Samiriyeli kadın, \"Sen Yahudi'sin, bense Samiriyeli bir kadınım\" dedi, \"Nasıl olur da benden su istersin?\" Çünkü Yahudiler'in Samiriyeliler'le ilişkileri yoktur."},{"n":"10","t":"İsa kadına şu yanıtı verdi: \"Eğer sen Tanrı'nın armağanını ve sana, 'Bana su ver, içeyim' diyenin kim olduğunu bilseydin, sen O'ndan dilerdin, O da sana yaşam suyunu verirdi.\""},{"n":"11","t":"Kadın, \"Efendim\" dedi, \"Su çekecek bir şeyin yok, kuyu da derin, yaşam suyunu nereden bulacaksın?"},{"n":"12","t":"Sen, bu kuyuyu bize vermiş, kendisi, oğulları ve davarları ondan içmiş olan atamız Yakup'tan daha mı büyüksün?\""},{"n":"13","t":"İsa şöyle yanıt verdi: \"Bu sudan her içen yine susayacak."},{"n":"14","t":"Oysa benim vereceğim sudan içen sonsuza dek susamaz. Benim vereceğim su, içende sonsuz yaşam için fışkıran bir pınar olacak.\""},{"n":"15","t":"Kadın, \"Efendim\" dedi, \"Bu suyu bana ver. Böylece ne susayayım, ne de su çekmek için buraya kadar geleyim.\""},{"n":"16","t":"İsa, \"Git, kocanı çağır ve buraya gel\" dedi."},{"n":"17","t":"Kadın, \"Kocam yok\" diye yanıtladı. İsa, \"Kocam yok demekle doğruyu söyledin\" dedi."},{"n":"18","t":"\"Beş kocaya vardın. Şimdi birlikte yaşadığın adam kocan değil. Doğruyu söyledin.\""},{"n":"19","t":"Kadın, \"Efendim, anlıyorum, sen bir peygambersin\" dedi."},{"n":"20","t":"\"Atalarımız bu dağda tapındılar, ama sizler tapılması gereken yerin Yeruşalim'de olduğunu söylüyorsunuz.\""},{"n":"21","t":"İsa ona şöyle dedi: \"Kadın, bana inan, öyle bir saat geliyor ki, Baba'ya ne bu dağda, ne de Yeruşalim'de tapınacaksınız!"},{"n":"22","t":"Siz bilmediğinize tapıyorsunuz, biz bildiğimize tapıyoruz. Çünkü kurtuluş Yahudiler'dendir."},{"n":"23","t":"Ama içtenlikle tapınanların Baba'ya ruhta ve gerçekte tapınacakları saat geliyor. İşte, o saat şimdidir. Baba da kendisine böyle tapınanları arıyor."},{"n":"24","t":"Tanrı ruhtur, O'na tapınanlar da ruhta ve gerçekte tapınmalıdırlar.\""},{"n":"25","t":"Kadın İsa'ya, \"Mesih denilen meshedilmiş* Olan'ın geleceğini biliyorum\" dedi, \"O gelince bize her şeyi bildirecek.\""},{"n":"26","t":"İsa, \"Seninle konuşan ben, O'yum\" dedi."},{"n":"27","t":"Bu sırada İsa'nın öğrencileri geldiler. O'nun bir kadınla konuşmasına şaştılar. Bununla birlikte hiçbiri, \"Ne istiyorsun?\" ya da, \"O kadınla neden konuşuyorsun?\" demedi. Yu.4: 2829 Sonra kadın su testisini bırakarak kente gitti ve halka şöyle dedi: \"Gelin, yaptığım her şeyi bana söyleyen adamı görün. Acaba Mesih bu mudur?\""},{"n":"30","t":"Halk da kentten çıkıp İsa'ya doğru gelmeye başladı."},{"n":"31","t":"Bu arada öğrencileri O'na, \"Rabbî*, yemek ye!\" diye rica ediyorlardı."},{"n":"32","t":"Ama İsa, \"Benim, sizin bilmediğiniz bir yiyeceğim var\" dedi."},{"n":"33","t":"Öğrenciler birbirlerine, \"Acaba biri O'na yiyecek mi getirdi?\" diye sordular."},{"n":"34","t":"İsa, \"Benim yemeğim, beni gönderenin isteğini yerine getirmek ve O'nun işini tamamlamaktır\" dedi."},{"n":"35","t":"\"Sizler, 'Ekinleri biçmeye daha dört ay var' demiyor musunuz? İşte, size söylüyorum, başınızı kaldırıp tarlalara bakın. Ekinler sararmış, biçilmeye hazır!"},{"n":"36","t":"Eken ve biçen birlikte sevinsinler diye, biçen kişi şimdiden ücretini alır ve sonsuz yaşam için ürün toplar."},{"n":"37","t":"'Biri eker, başkası biçer' sözü bu durumda doğrudur."},{"n":"38","t":"Ben sizi, emek vermediğiniz bir ürünü biçmeye gönderdim. Başkaları emek verdiler, siz ise onların emeğinden yararlandınız.\""},{"n":"39","t":"O kentten birçok Samiriyeli, \"Yaptığım her şeyi bana söyledi\" diye tanıklık eden kadının sözü üzerine İsa'ya iman etti."},{"n":"40","t":"Samiriyeliler O'na gelip yanlarında kalması için rica ettiler. O da orada iki gün kaldı."},{"n":"41","t":"O'nun sözü üzerine daha birçokları iman etti."},{"n":"42","t":"Bunlar kadına, \"Bizim iman etmemizin nedeni artık senin sözlerin değil\" diyorlardı. \"Kendimiz işittik, O'nun gerçekten dünyanın Kurtarıcısı olduğunu biliyoruz.\" Bir Memurun Oğlu İyileştiriliyor"},{"n":"43","t":"Bu iki günden sonra İsa oradan ayrılıp Celile'ye gitti."},{"n":"44","t":"İsa'nın kendisi, bir peygamberin kendi memleketinde saygı görmediğine tanıklık etmişti."},{"n":"45","t":"Celile'ye geldiği zaman Celileliler O'nu iyi karşıladılar. Çünkü onlar da bayram için gitmişler ve bayramda O'nun Yeruşalim'de yaptığı her şeyi görmüşlerdi."},{"n":"46","t":"İsa yine, suyu şaraba çevirdiği Celile'nin Kana Köyü'ne geldi. Orada saraya bağlı bir memur vardı. Oğlu Kefarnahum'da hastaydı."},{"n":"47","t":"Adam, İsa'nın Yahudiye'den Celile'ye geldiğini işitince yanına gitti, evine gelip ölmek üzere olan oğlunu iyileştirmesi için O'na yalvardı."},{"n":"48","t":"İsa adama, \"Sizler belirtiler ve harikalar görmedikçe iman etmeyeceksiniz\" dedi."},{"n":"49","t":"Saray memuru İsa'ya, \"Efendim, çocuğum ölmeden yetiş!\" dedi."},{"n":"50","t":"İsa, \"Git, oğlun yaşayacak\" dedi. Adam, İsa'nın söylediği söze iman ederek gitti."},{"n":"51","t":"Daha yoldayken köleleri onu karşılayıp oğlunun yaşadığını bildirdiler."},{"n":"52","t":"Adam onlara, oğlunun iyileşmeye başladığı saati sordu. \"Dün öğle üstü saat* birde ateşi düştü\" dediler."},{"n":"53","t":"Baba bunun, İsa'nın, \"Oğlun yaşayacak\" dediği saat olduğunu anladı. Kendisi ve bütün ev halkı iman etti."},{"n":"54","t":"İsa, bu ikinci belirtiyi de Yahudiye'den Celile'ye döndükten sonra gerçekleştirdi."}]},{"ch":5,"verses":[{"n":"1","t":"İsa bundan sonra Yahudiler'in bir bayramı nedeniyle Yeruşalim'e gitti."},{"n":"2","t":"Yeruşalim'de Koyun Kapısı yanında, İbranice'de* Beytesta denilen beş eyvanlı bir havuz vardır."},{"n":"34","t":"Bu eyvanların altında kör, kötürüm, felçli hastalardan bir kalabalık yatardı.*fx*"},{"n":"5","t":"Orada otuz sekiz yıldır hasta olan bir adam vardı."},{"n":"6","t":"İsa hasta yatan bu adamı görünce ve uzun zamandır bu durumda olduğunu anlayınca, \"İyi olmak ister misin?\" diye sordu."},{"n":"7","t":"Hasta şöyle yanıt verdi: \"Efendim, su çalkandığı zaman beni havuza indirecek kimsem yok, tam gireceğim an benden önce başkası giriyor.\""},{"n":"8","t":"İsa ona, \"Kalk, şilteni topla ve yürü\" dedi."},{"n":"9","t":"Adam o anda iyileşti. Şiltesini toplayıp yürümeye başladı. O gün Şabat Günü'ydü*."},{"n":"10","t":"Bu yüzden Yahudi yetkililer iyileşen adama, \"Bugün Şabat Günü\" dediler, \"Şilteni toplaman yasaktır.\""},{"n":"11","t":"Ama adam onlara şöyle yanıt verdi: \"Beni iyileştiren kişi bana, 'Şilteni topla ve yürü' dedi.\""},{"n":"12","t":"\"Sana, 'Şilteni topla ve yürü' diyen adam kim?\" diye sordular."},{"n":"13","t":"İyileşen adam ise O'nun kim olduğunu bilmiyordu. Orası kalabalıktı, İsa da çekilip gitmişti."},{"n":"14","t":"İsa daha sonra adamı tapınakta buldu. \"Bak, iyi oldun. Artık günah işleme de başına daha kötü bir şey gelmesin\" dedi."},{"n":"15","t":"Adam gidip Yahudi yetkililere kendisini iyileştirenin İsa olduğunu bildirdi."},{"n":"16","t":"Şabat Günü böyle şeyler yaptığı için İsa'ya zulmetmeye başladılar."},{"n":"17","t":"Ama İsa onlara şu karşılığı verdi: \"Babam hâlâ çalışmaktadır, ben de çalışıyorum.\""},{"n":"18","t":"İşte bu nedenle Yahudi yetkililer O'nu öldürmek için daha çok gayret ettiler. Çünkü yalnız Şabat Günü düzenini bozmakla kalmamış, Tanrı'nın kendi Babası olduğunu söyleyerek kendisini Tanrı'ya eşit kılmıştı. Oğul'un Yetkisi"},{"n":"19","t":"İsa Yahudi yetkililere şöyle karşılık verdi: \"Size doğrusunu söyleyeyim, Oğul, Baba'nın yaptıklarını görmedikçe kendiliğinden bir şey yapamaz. Baba ne yaparsa Oğul da aynı şeyi yapar."},{"n":"20","t":"Çünkü Baba Oğul'u sever ve yaptıklarının hepsini O'na gösterir. Şaşasınız diye O'na bunlardan daha büyük işler de gösterecektir."},{"n":"21","t":"Baba nasıl ölüleri diriltip onlara yaşam veriyorsa, Oğul da dilediği kimselere yaşam verir."},{"n":"22","t":"Baba kimseyi yargılamaz, bütün yargılama işini Oğul'a vermiştir."},{"n":"23","t":"Öyle ki, herkes Baba'yı onurlandırdığı gibi Oğul'u onurlandırsın. Oğul'u onurlandırmayan, O'nu gönderen Baba'yı da onurlandırmaz."},{"n":"24","t":"\"Size doğrusunu söyleyeyim, sözümü işitip beni gönderene iman edenin sonsuz yaşamı vardır. Böyle biri yargılanmaz, ölümden yaşama geçmiştir."},{"n":"25","t":"Size doğrusunu söyleyeyim, ölülerin Tanrı Oğlu'nun sesini işitecekleri ve işitenlerin yaşayacakları saat geliyor, geldi bile."},{"n":"26","t":"Çünkü Baba, kendisinde yaşam olduğu gibi, Oğul'a da kendisinde yaşam olma özelliğini verdi."},{"n":"27","t":"O'na yargılama yetkisini de verdi. Çünkü O İnsanoğlu'dur*."},{"n":"28","t":"Buna şaşmayın. Mezarda olanların hepsinin O'nun sesini işitecekleri saat geliyor."},{"n":"29","t":"Ve onlar mezarlarından çıkacaklar. İyilik yapmış olanlar yaşamak, kötülük yapmış olanlar yargılanmak üzere dirilecekler.\" İsa'ya Tanıklık Edenler"},{"n":"30","t":"\"Ben kendiliğimden hiçbir şey yapamam. İşittiğim gibi yargılarım ve benim yargım adildir. Çünkü amacım kendi istediğimi değil, beni gönderenin istediğini yapmaktır."},{"n":"31","t":"Eğer kendim için ben tanıklık edersem, tanıklığım geçerli olmaz."},{"n":"32","t":"Ama benim için tanıklık eden başka biri vardır. O'nun benim için ettiği tanıklığın geçerli olduğunu bilirim."},{"n":"33","t":"Siz Yahya'ya adamlar gönderdiniz, o da gerçeğe tanıklık etti."},{"n":"34","t":"İnsanın tanıklığını kabul ettiğim için değil, kurtulmanız için bunları söylüyorum."},{"n":"35","t":"Yahya, yanan ve ışık saçan bir çıraydı. Sizler onun ışığında bir süre için coşmak istediniz."},{"n":"36","t":"Ama benim, Yahya'nınkinden daha büyük bir tanıklığım var. Tamamlamam için Baba'nın bana verdiği işler, şu yaptığım işler, beni Baba'nın gönderdiğine tanıklık ediyor."},{"n":"37","t":"Beni gönderen Baba da benim için tanıklık etmiştir. Siz hiçbir zaman ne O'nun sesini işittiniz, ne de şeklini gördünüz."},{"n":"38","t":"O'nun sözü sizde yaşamıyor. Çünkü O'nun gönderdiği kişiye iman etmiyorsunuz."},{"n":"39","t":"Kutsal Yazılar'ı araştırıyorsunuz. Çünkü bunlar aracılığıyla sonsuz yaşama sahip olduğunuzu sanıyorsunuz. Bana tanıklık eden de bu yazılardır!"},{"n":"40","t":"Öyleyken siz, yaşama kavuşmak için bana gelmek istemiyorsunuz."},{"n":"41","t":"\"İnsanlardan övgü kabul etmiyorum."},{"n":"42","t":"Ama ben sizi bilirim, içinizde Tanrı sevgisi yoktur."},{"n":"43","t":"Ben Babam'ın adına geldim, ama beni kabul etmiyorsunuz. Oysa başka birisi kendi adına gelirse, onu kabul edeceksiniz."},{"n":"44","t":"Birbirinizden övgüler kabul ediyor, ama tek olan Tanrı'nın övgüsünü kazanmaya çalışmıyorsunuz. Bu durumda nasıl iman edebilirsiniz?"},{"n":"45","t":"Baba'nın önünde sizi suçlayacağımı sanmayın. Sizi suçlayan, umut bağladığınız Musa'dır."},{"n":"46","t":"Musa'ya iman etmiş olsaydınız, bana da iman ederdiniz. Çünkü o benim hakkımda yazmıştır."},{"n":"47","t":"Ama onun yazılarına iman etmezseniz, benim sözlerime nasıl iman edeceksiniz?\""}]},{"ch":6,"verses":[{"n":"1","t":"Bundan sonra İsa, Celile Taberiye Gölü'nün karşı yakasına geçti."},{"n":"2","t":"Ardından büyük bir kalabalık gidiyordu. Çünkü hastalar üzerinde yaptığı mucizeleri görmüşlerdi."},{"n":"3","t":"İsa dağa çıkıp orada öğrencileriyle birlikte oturdu."},{"n":"4","t":"Yahudiler'in Fısıh Bayramı* yakındı."},{"n":"5","t":"İsa başını kaldırıp büyük bir kalabalığın kendisine doğru geldiğini görünce Filipus'a, \"Bunları doyurmak için nereden ekmek alalım?\" diye sordu."},{"n":"6","t":"Bu sözü onu denemek için söyledi, aslında kendisi ne yapacağını biliyordu."},{"n":"7","t":"Filipus O'na şu yanıtı verdi: \"Her birinin bir lokma yiyebilmesi için iki yüz dinarlık ekmek bile yetmez.\""},{"n":"89","t":"Öğrencilerinden biri, Simun Petrus'un kardeşi Andreas, İsa'ya dedi ki, \"Burada beş arpa ekmeğiyle iki balığı olan bir çocuk var. Ama bu kadar adam için bunlar nedir ki?\""},{"n":"10","t":"İsa, \"Halkı yere oturtun\" dedi. Orası çayırlıktı. Böylece halk yere oturdu. Yaklaşık beş bin erkek vardı."},{"n":"11","t":"İsa ekmekleri aldı, şükrettikten sonra oturanlara dağıttı. Balıklardan da istedikleri kadar verdi."},{"n":"12","t":"Herkes doyunca İsa öğrencilerine, \"Artakalan parçaları toplayın, hiçbir şey ziyan olmasın\" dedi."},{"n":"13","t":"Onlar da topladılar. Yedikleri beş arpa ekmeğinden artakalan parçalarla on iki sepet doldurdular."},{"n":"14","t":"Halk, İsa'nın yaptığı mucizeyi görünce, \"Gerçekten dünyaya gelecek olan peygamber budur\" dedi."},{"n":"15","t":"İsa onların gelip kendisini kral yapmak üzere zorla götüreceklerini bildiğinden tek başına yine dağa çekildi. İsa Su Üstünde Yürüyor (Mat.14:2233; Mar.6:4552)"},{"n":"16","t":"Akşam olunca öğrencileri göle indiler."},{"n":"17","t":"Bir tekneye binerek gölün karşı yakasındaki Kefarnahum'a doğru yol aldılar. Karanlık basmış, İsa henüz yanlarına gelmemişti."},{"n":"18","t":"Güçlü bir rüzgar estiğinden göl kabarmaya başladı."},{"n":"19","t":"Öğrenciler üç mil kadar*fx* kürek çektikten sonra, İsa'nın gölün üstünde yürüyerek tekneye yaklaştığını görünce korktular."},{"n":"20","t":"Ama İsa, \"Korkmayın, benim!\" dedi."},{"n":"21","t":"Bunun üzerine O'nu tekneye almak istediler. O anda tekne gidecekleri kıyıya ulaştı."},{"n":"22","t":"Ertesi gün, gölün karşı yakasında kalan halk, önceden orada sadece bir tek tekne bulunduğunu, İsa'nın kendi öğrencileriyle birlikte bu tekneye binmediğini, öğrencilerinin yalnız gittiklerini anladı."},{"n":"23","t":"Rab'bin şükretmesinden sonra halkın ekmek yediği yerin yakınına Taberiye'den başka tekneler geldi."},{"n":"24","t":"Halk, İsa'nın ve öğrencilerinin orada olmadığını görünce teknelere binerek Kefarnahum'a, İsa'yı aramaya gitti."},{"n":"25","t":"O'nu gölün karşı yakasında buldukları zaman, \"Rabbî*, buraya ne zaman geldin?\" diye sordular. Yaşam Ekmeği"},{"n":"26","t":"İsa şöyle yanıt verdi: \"Size doğrusunu söyleyeyim, doğaüstü belirtiler gördüğünüz için değil, ekmeklerden yiyip doyduğunuz için beni arıyorsunuz."},{"n":"27","t":"Geçici yiyecek için değil, sonsuz yaşam boyunca kalıcı yiyecek için çalışın. Bunu size İnsanoğlu* verecek. Çünkü Baba Tanrı O'na bu onayı vermiştir*fx*.\""},{"n":"28","t":"Onlar da şunu sordular: \"Tanrı'nın istediği işleri yapmak için ne yapmalıyız?\""},{"n":"29","t":"İsa, \"Tanrı'nın işi O'nun gönderdiği kişiye iman etmenizdir\" diye yanıt verdi."},{"n":"30","t":"Bunun üzerine, \"Görüp sana iman etmemiz için nasıl bir belirti gerçekleştireceksin? Ne yapacaksın?\" dediler."},{"n":"31","t":"\"Atalarımız çölde man* yediler. Yazılmış olduğu gibi, 'Yemeleri için onlara gökten ekmek verdi.'\""},{"n":"32","t":"İsa onlara dedi ki, \"Size doğrusunu söyleyeyim, gökten ekmeği size Musa vermedi, gökten size gerçek ekmeği Babam verir."},{"n":"33","t":"Çünkü Tanrı'nın ekmeği, gökten inen ve dünyaya yaşam verendir.\""},{"n":"34","t":"Onlar da, \"Efendimiz, bizlere her zaman bu ekmeği ver!\" dediler."},{"n":"35","t":"İsa, \"Yaşam ekmeği Ben'im. Bana gelen asla acıkmaz, bana iman eden hiçbir zaman susamaz\" dedi."},{"n":"36","t":"\"Ama ben size dedim ki, 'Beni gördünüz, yine de iman etmiyorsunuz.'"},{"n":"37","t":"Baba'nın bana verdiklerinin hepsi bana gelecek ve bana geleni asla kovmam."},{"n":"38","t":"Çünkü kendi isteğimi değil, beni gönderenin isteğini yerine getirmek için gökten indim."},{"n":"39","t":"Beni gönderenin isteği, bana verdiklerinden hiçbirini yitirmemem, son gün hepsini diriltmemdir."},{"n":"40","t":"Çünkü Babam'ın isteği, Oğul'u gören ve O'na iman eden herkesin sonsuz yaşama kavuşmasıdır. Ben de böylelerini son günde dirilteceğim.\""},{"n":"41","t":"\"Gökten inmiş olan ekmek Ben'im\" dediği için Yahudiler O'na karşı söylenmeye başladılar."},{"n":"42","t":"\"Yusuf oğlu İsa değil mi bu?\" diyorlardı. \"Annesini de, babasını da tanıyoruz. Şimdi nasıl oluyor da, 'Gökten indim' diyor?\""},{"n":"43","t":"İsa, \"Aranızda söylenmeyin\" dedi."},{"n":"44","t":"\"Beni gönderen Baba bir kimseyi bana çekmedikçe, o kimse bana gelemez. Bana geleni de son günde dirilteceğim."},{"n":"45","t":"Peygamberlerin yazdığı gibi, 'Tanrı onların hepsine kendi yollarını öğretecektir.' Baba'yı işiten ve O'ndan öğrenen herkes bana gelir."},{"n":"46","t":"Bu, bir kimsenin Baba'yı gördüğü anlamına gelmez. Baba'yı sadece Tanrı'dan gelen görmüştür."},{"n":"47","t":"Size doğrusunu söyleyeyim, iman edenin sonsuz yaşamı vardır."},{"n":"48","t":"Yaşam ekmeği Ben'im."},{"n":"49","t":"Atalarınız çölde man yediler, yine de öldüler."},{"n":"50","t":"Gökten inen öyle bir ekmek var ki, ondan yiyen ölmeyecek."},{"n":"51","t":"Gökten inmiş olan diri ekmek Ben'im. Bu ekmekten yiyen sonsuza dek yaşayacak. Dünyanın yaşamı uğruna vereceğim ekmek de benim bedenimdir.\""},{"n":"52","t":"Bunun üzerine Yahudiler, \"Bu adam yememiz için bedenini bize nasıl verebilir?\" diyerek birbirleriyle çekişmeye başladılar."},{"n":"53","t":"İsa onlara şöyle dedi: \"Size doğrusunu söyleyeyim, İnsanoğlu'nun bedenini yiyip kanını içmedikçe, sizde yaşam olmaz."},{"n":"54","t":"Bedenimi yiyenin, kanımı içenin sonsuz yaşamı vardır ve ben onu son günde dirilteceğim."},{"n":"55","t":"Çünkü bedenim gerçek yiyecek, kanım gerçek içecektir."},{"n":"56","t":"Bedenimi yiyip kanımı içen bende yaşar, ben de onda."},{"n":"57","t":"Yaşayan Baba beni gönderdiği ve ben Baba'nın aracılığıyla yaşadığım gibi, bedenimi yiyen de benim aracılığımla yaşayacak."},{"n":"58","t":"İşte gökten inmiş olan ekmek budur. Atalarınızın yedikleri man gibi değildir. Atalarınız öldüler. Oysa bu ekmeği yiyen sonsuza dek yaşar.\""},{"n":"59","t":"İsa bu sözleri Kefarnahum'da havrada öğretirken söyledi. Birçok Kişi İsa'yı Terk Ediyor"},{"n":"60","t":"Öğrencilerinin birçoğu bunu işitince, \"Bu söz çok çetin, kim kabul edebilir?\" dediler."},{"n":"61","t":"Öğrencilerinin buna karşı söylendiğini anlayan İsa, \"Bu sizi şaşırtıyor mu?\" dedi."},{"n":"62","t":"\"Ya İnsanoğlu'nun* önceden bulunduğu yere yükseldiğini görürseniz...?"},{"n":"63","t":"Yaşam veren Ruh'tur. Beden bir yarar sağlamaz. Sizlere söylediğim sözler ruhtur, yaşamdır."},{"n":"64","t":"Yine de aranızda iman etmeyenler var.\" İsa iman etmeyenlerin ve kendisine ihanet edecek kişinin kim olduğunu baştan beri biliyordu."},{"n":"65","t":"\"Sizlere, 'Baba'nın bana yöneltmediği hiç kimse bana gelemez'*fx* dememin nedeni budur\" dedi."},{"n":"66","t":"Bunun üzerine öğrencilerinin birçoğu geri döndüler, artık O'nunla dolaşmaz oldular."},{"n":"67","t":"İsa o zaman Onikiler'e*, \"Siz de mi ayrılmak istiyorsunuz?\" diye sordu."},{"n":"68","t":"Simun Petrus şu yanıtı verdi: \"Rab, biz kime gidelim? Sonsuz yaşamın sözleri sendedir."},{"n":"69","t":"İman ediyor ve biliyoruz ki, sen Tanrı'nın Kutsalı'sın.\""},{"n":"70","t":"İsa onlara şu karşılığı verdi: \"Siz Onikiler'i seçen ben değil miyim? Buna karşın içinizden biri iblistir.\""},{"n":"71","t":"Simun İskariot'un oğlu Yahuda'dan söz ediyordu. Çünkü Yahuda Onikiler'den biri olduğu halde İsa'ya ihanet edecekti."}]},{"ch":7,"verses":[{"n":"1","t":"Bundan sonra İsa Celile'de dolaşmaya başladı. Yahudi yetkililer O'nu öldürmeyi amaçladıkları için Yahudiye'de dolaşmak istemiyordu."},{"n":"2","t":"Yahudiler'in Çardak Bayramı* yaklaşmıştı."},{"n":"3","t":"Bu nedenle İsa'nın kardeşleri O'na, \"Buradan ayrıl, Yahudiye'ye git\" dediler, \"Öğrencilerin de yaptığın işleri görsünler."},{"n":"4","t":"Çünkü kendini açıkça tanıtmak isteyen bir kimse yaptıklarını gizlemez. Mademki bu şeyleri yapıyorsun, kendini dünyaya göster!\""},{"n":"5","t":"Kardeşleri bile O'na iman etmiyorlardı."},{"n":"6","t":"İsa onlara, \"Benim zamanım daha gelmedi\" dedi, \"Oysa sizin için zaman hep uygundur."},{"n":"7","t":"Dünya sizden nefret edemez, ama benden nefret ediyor. Çünkü yaptıklarının kötü olduğuna tanıklık ediyorum."},{"n":"8","t":"Siz bu bayramı kutlamaya gidin. Ben şimdilik gitmeyeceğim. Çünkü benim zamanım daha dolmadı.\""},{"n":"9","t":"İsa bu sözleri söyleyip Celile'de kaldı."},{"n":"10","t":"Ne var ki, kardeşleri bayramı kutlamaya gidince, kendisi de gitti. Ancak açıktan açığa değil, gizlice gitti."},{"n":"11","t":"Yahudi yetkililer O'nu bayram sırasında arıyor, \"O nerede?\" diye soruyorlardı."},{"n":"12","t":"Kalabalık arasında O'nunla ilgili bir sürü laf fısıldanıyordu. Bazıları, \"İyi adamdır\", bazıları da, \"Hayır, tam tersine, halkı saptırıyor\" diyorlardı."},{"n":"13","t":"Bununla birlikte yetkililerden korktukları için, hiç kimse O'ndan açıkça söz etmiyordu."},{"n":"14","t":"Bayramın yarısı geçmişti. İsa tapınağa gidip öğretmeye başladı."},{"n":"15","t":"Yahudiler şaşırdılar. \"Bu adam hiç öğrenim görmediği halde, nasıl bu kadar bilgili olabilir*fx*?\" dediler."},{"n":"16","t":"İsa onlara, \"Benim öğretim benim değil, beni gönderenindir\" diye karşılık verdi."},{"n":"17","t":"\"Eğer bir kimse Tanrı'nın isteğini yerine getirmek istiyorsa, bu öğretinin Tanrı'dan mı olduğunu, yoksa kendiliğimden mi konuştuğumu bilecektir."},{"n":"18","t":"Kendiliğinden konuşan kendini yüceltmek ister, ama kendisini göndereni yüceltmek isteyen doğrudur ve O'nda haksızlık yoktur."},{"n":"19","t":"Musa size Kutsal Yasa'yı vermedi mi? Yine de hiçbiriniz Yasa'yı yerine getirmiyor. Neden beni öldürmek istiyorsunuz?\""},{"n":"20","t":"Kalabalık, \"Cin çarpmış seni!\" dedi. \"Seni öldürmek isteyen kim?\""},{"n":"21","t":"İsa, \"Ben bir mucize*fx* yaptım, hepiniz şaşkına döndünüz\" diye yanıt verdi."},{"n":"22","t":"\"Musa size sünneti buyurduğu için aslında bu, Musa'dan değil, atalarınızdan kalmadır Şabat Günü* birini sünnet edersiniz."},{"n":"23","t":"Musa'nın Yasası bozulmasın diye Şabat Günü biri sünnet ediliyor da, Şabat Günü bir adamı tamamen iyileştirdim diye bana neden kızıyorsunuz?"},{"n":"24","t":"Dış görünüşe göre yargılamayın, yargınız adil olsun.\" İsa, Mesih Midir?"},{"n":"25","t":"Yeruşalimliler'in bazıları, \"Öldürmek istedikleri adam bu değil mi?\" diyorlardı."},{"n":"26","t":"\"Bakın, açıkça konuşuyor, O'na bir şey demiyorlar. Yoksa önderler O'nun Mesih* olduğunu gerçekten kabul ettiler mi?"},{"n":"27","t":"Ama biz bu adamın nereden geldiğini biliyoruz. Oysa Mesih geldiği zaman O'nun nereden geldiğini kimse bilmeyecek.\""},{"n":"28","t":"O sırada tapınakta öğreten İsa yüksek sesle şöyle dedi: \"Hem beni tanıyorsunuz, hem de nereden olduğumu biliyorsunuz! Ben kendiliğimden gelmedim. Beni gönderen gerçektir. O'nu siz tanımıyorsunuz."},{"n":"29","t":"Ben O'nu tanırım. Çünkü ben O'ndanım, beni O gönderdi.\""},{"n":"30","t":"Bunun üzerine O'nu yakalamak istediler, ama kimse O'na el sürmedi. Çünkü O'nun saati henüz gelmemişti."},{"n":"31","t":"Halktan birçok kişi ise O'na iman etti. \"Mesih gelince, bunun yaptıklarından daha mı çok mucize yapacak?\" diyorlardı."},{"n":"32","t":"Ferisiler* halkın İsa hakkında böyle fısıldaştığını duydular. Başkâhinler ve Ferisiler O'nu yakalamak için görevliler gönderdiler."},{"n":"33","t":"İsa, \"Kısa bir süre daha sizinleyim\" dedi, \"Sonra beni gönderene gideceğim."},{"n":"34","t":"Beni arayacaksınız ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz.\""},{"n":"35","t":"Bunun üzerine Yahudiler birbirlerine, \"Bu adam nereye gidecek de biz O'nu bulamayacağız?\" dediler. \"Yoksa Grekler* arasında dağılmış olanlara gidip Grekler'e mi öğretecek?"},{"n":"36","t":"'Beni arayacaksınız ama bulamayacaksınız. Ve benim bulunduğum yere siz gelemezsiniz' diyor. Ne demek istiyor?\""},{"n":"37","t":"Bayramın son ve en önemli günü İsa ayağa kalktı, yüksek sesle şöyle dedi: \"Bir kimse susamışsa bana gelsin, içsin."},{"n":"38","t":"Kutsal Yazı'da dendiği gibi, bana iman edenin 'içinden diri su ırmakları akacaktır.'\""},{"n":"39","t":"Bunu, kendisine iman edenlerin alacağı Ruh'la ilgili olarak söylüyordu. Ruh henüz verilmemişti. Çünkü İsa henüz yüceltilmemişti."},{"n":"40","t":"Halktan bazıları bu sözleri işitince, \"Gerçekten beklediğimiz peygamber budur\" dediler."},{"n":"41","t":"Bazıları da, \"Bu Mesih'tir\" diyorlardı. Başkaları ise, \"Olamaz! Mesih Celile'den mi gelecek?\" dediler."},{"n":"42","t":"\"Kutsal Yazı'da, 'Mesih, Davut'un soyundan, Davut'un yaşadığı Beytlehem Kenti'nden gelecek' denmemiş midir?\""},{"n":"43","t":"Böylece İsa'dan dolayı halk arasında ayrılık doğdu."},{"n":"44","t":"Bazıları O'nu yakalamak istedilerse de, kimse O'na el sürmedi. Yahudi Önderlerin İmansızlığı"},{"n":"45","t":"Görevliler geri dönünce, başkâhinlerle Ferisiler, \"Niçin O'nu getirmediniz?\" diye sordular."},{"n":"46","t":"Görevliler, \"Hiç kimse hiçbir zaman bu adamın konuştuğu gibi konuşmamıştır\" karşılığını verdiler."},{"n":"47","t":"Ferisiler, \"Yoksa siz de mi aldandınız?\" dediler."},{"n":"48","t":"\"Önderlerden ya da Ferisiler'den O'na iman eden oldu mu hiç?"},{"n":"49","t":"Kutsal Yasa'yı bilmeyen bu halk lanetlidir.\" Yu.7: 5051 İçlerinden biri, daha önce İsa'ya gelen Nikodim, onlara şöyle dedi: \"Yasamıza göre, bir adamı dinlemeden, ne yaptığını öğrenmeden onu yargılamak doğru mu?\""},{"n":"52","t":"Ona, \"Yoksa sen de mi Celile'densin?\" diye karşılık verdiler. \"Araştır, bak, Celile'den peygamber çıkmaz.\" Zinada Yakalanan Kadın"},{"n":"53","t":"Bundan sonra herkes evine gitti."}]},{"ch":8,"verses":[{"n":"1","t":"İsa ise Zeytin Dağı'na gitti."},{"n":"2","t":"Ertesi sabah erkenden yine tapınağa döndü. Bütün halk O'nun yanına geliyordu. O da oturup onlara öğretmeye başladı."},{"n":"34","t":"Din bilginleri* ve Ferisiler*, zina ederken yakalanmış bir kadın getirdiler. Kadını orta yere çıkararak İsa'ya, \"Öğretmen, bu kadın tam zina ederken yakalandı\" dediler."},{"n":"5","t":"\"Musa, Yasa'da bize böyle kadınların taşlanmasını buyurdu, sen ne dersin?\""},{"n":"6","t":"Bunları İsa'yı denemek amacıyla söylüyorlardı; O'nu suçlayabilmek için bir neden arıyorlardı. İsa eğilmiş, parmağıyla toprağa yazı yazıyordu."},{"n":"7","t":"Durmadan aynı soruyu sormaları üzerine doğruldu ve, \"İçinizde kim günahsızsa, ilk taşı o atsın!\" dedi."},{"n":"8","t":"Sonra yine eğildi, toprağa yazmaya başladı."},{"n":"9","t":"Bunu işittikleri zaman, başta yaşlılar olmak üzere, birer birer dışarı çıkıp İsa'yı yalnız bıraktılar. Kadın ise orta yerde duruyordu."},{"n":"10","t":"İsa doğrulup ona, \"Kadın, nerede onlar? Hiçbiri seni yargılamadı mı?\" diye sordu."},{"n":"11","t":"Kadın, \"Hiçbiri, Efendim\" dedi. İsa, \"Ben de seni yargılamıyorum\" dedi. \"Git, artık bundan sonra günah işleme!\"*fx* Geçerli Tanıklık"},{"n":"12","t":"İsa yine halka seslenip şöyle dedi: \"Ben dünyanın ışığıyım. Benim ardımdan gelen, asla karanlıkta yürümez, yaşam ışığına sahip olur.\""},{"n":"13","t":"Ferisiler, \"Sen kendin için tanıklık ediyorsun, tanıklığın geçerli değil\" dediler."},{"n":"14","t":"İsa onlara şu karşılığı verdi: \"Kendim için tanıklık etsem bile tanıklığım geçerlidir. Çünkü nereden geldiğimi ve nereye gideceğimi biliyorum. Oysa siz nereden geldiğimi, nereye gideceğimi bilmiyorsunuz."},{"n":"15","t":"Siz insan gözüyle yargılıyorsunuz. Ben kimseyi yargılamam."},{"n":"16","t":"Yargılasam bile benim yargım doğrudur. Çünkü ben yalnız değilim, ben ve beni gönderen Baba, birlikte yargılarız."},{"n":"17","t":"Yasanızda da, 'İki kişinin tanıklığı geçerlidir' diye yazılmıştır."},{"n":"18","t":"Kendim için tanıklık eden bir ben varım, bir de beni gönderen Baba benim için tanıklık ediyor.\""},{"n":"19","t":"O zaman O'na, \"Baban nerede?\" diye sordular. İsa şu karşılığı verdi: \"Siz ne beni tanırsınız, ne de Babam'ı. Beni tanısaydınız, Babam'ı da tanırdınız.\""},{"n":"20","t":"İsa bu sözleri tapınakta öğretirken, bağış toplanan yerde söyledi. Kimse O'nu yakalamadı. Çünkü saati henüz gelmemişti."},{"n":"21","t":"İsa yine onlara, \"Ben gidiyorum. Beni arayacaksınız ve günahınızın içinde öleceksiniz. Benim gideceğim yere siz gelemezsiniz\" dedi."},{"n":"22","t":"Yahudi yetkililer, \"Yoksa kendini mi öldürecek?\" dediler. \"Çünkü, 'Benim gideceğim yere siz gelemezsiniz' diyor.\""},{"n":"23","t":"İsa onlara, \"Siz aşağıdansınız, ben yukarıdanım\" dedi. \"Siz bu dünyadansınız, ben bu dünyadan değilim."},{"n":"24","t":"İşte bu nedenle size, 'Günahlarınızın içinde öleceksiniz' dedim. Benim O olduğuma*fx* iman etmezseniz, günahlarınızın içinde öleceksiniz.\""},{"n":"25","t":"O'na, \"Sen kimsin?\" diye sordular. İsa, \"Başlangıçtan beri size ne söyledimse, O'yum\" dedi."},{"n":"26","t":"\"Sizinle ilgili söyleyecek ve sizleri yargılayacak çok şeyim var. Beni gönderen gerçektir. Ben O'ndan işittiklerimi dünyaya bildiriyorum.\""},{"n":"27","t":"İsa'nın kendilerine Baba'dan söz ettiğini anlamadılar."},{"n":"28","t":"Bu nedenle İsa şöyle dedi: \"İnsanoğlu'nu* yukarı kaldırdığınız zaman benim O olduğumu, kendiliğimden hiçbir şey yapmadığımı, ama tıpkı Baba'nın bana öğrettiği gibi konuştuğumu anlayacaksınız."},{"n":"29","t":"Beni gönderen benimledir, O beni yalnız bırakmadı. Çünkü ben her zaman O'nu hoşnut edeni yaparım.\""},{"n":"30","t":"Bu sözler üzerine birçokları O'na iman etti. İbrahim'in Çocukları, İblis'in Çocukları Yu.8: 31- 32 İsa kendisine iman etmiş olan Yahudiler'e, \"Eğer benim sözüme bağlı kalırsanız, gerçekten öğrencilerim olursunuz. Gerçeği bileceksiniz ve gerçek sizi özgür kılacak\" dedi."},{"n":"33","t":"\"Biz İbrahim'in soyundanız\" diye karşılık verdiler, \"Hiçbir zaman kimseye kölelik etmedik. Nasıl oluyor da sen, 'Özgür olacaksınız' diyorsun?\""},{"n":"34","t":"İsa, \"Size doğrusunu söyleyeyim, günah işleyen herkes günahın kölesidir\" dedi."},{"n":"35","t":"\"Köle ev halkının sürekli bir üyesi değildir, ama oğul sürekli üyesidir."},{"n":"36","t":"Bunun için, Oğul sizi özgür kılarsa, gerçekten özgür olursunuz."},{"n":"37","t":"İbrahim'in soyundan olduğunuzu biliyorum. Yine de beni öldürmek istiyorsunuz. Çünkü yüreğinizde sözüme yer vermiyorsunuz."},{"n":"38","t":"Ben Babam'ın yanında gördüklerimi söylüyorum, siz de babanızdan işittiklerinizi yapıyorsunuz.\""},{"n":"39","t":"\"Bizim babamız İbrahim'dir\" diye karşılık verdiler. İsa, \"İbrahim'in çocukları olsaydınız, İbrahim'in yaptıklarını yapardınız\" dedi."},{"n":"40","t":"\"Ama şimdi beni Tanrı'dan işittiği gerçeği sizlere bildireni öldürmek istiyorsunuz. İbrahim bunu yapmadı."},{"n":"41","t":"Siz babanızın yaptıklarını yapıyorsunuz.\" \"Biz zinadan doğmadık. Bir tek Babamız var, o da Tanrı'dır\" dediler."},{"n":"42","t":"İsa, \"Tanrı Babanız olsaydı, beni severdiniz\" dedi. \"Çünkü ben Tanrı'dan çıkıp geldim. Kendiliğimden gelmedim, beni O gönderdi."},{"n":"43","t":"Söylediklerimi neden anlamıyorsunuz? Benim sözümü dinlemeye dayanamıyorsunuz da ondan."},{"n":"44","t":"Siz babanız İblis'tensiniz ve babanızın arzularını yerine getirmek istiyorsunuz. O başlangıçtan beri katildi. Gerçeğe bağlı kalmadı. Çünkü onda gerçek yoktur. Yalan söylemesi doğaldır*fx*. Çünkü o yalancıdır ve yalanın babasıdır."},{"n":"45","t":"Ama ben gerçeği söylüyorum. İşte bunun için bana iman etmiyorsunuz."},{"n":"46","t":"Hanginiz bana günahlı olduğumu kanıtlayabilir? Gerçeği söylüyorsam, niçin bana iman etmiyorsunuz?"},{"n":"47","t":"Tanrı'dan olan, Tanrı'nın sözlerini dinler. İşte siz Tanrı'dan olmadığınız için dinlemiyorsunuz.\" İsa'nın Yüceliği"},{"n":"48","t":"Yahudiler O'na şu karşılığı verdiler: \"'Sen, cin çarpmış bir Samiriyeli'sin*' demekte haklı değil miyiz?\""},{"n":"49","t":"İsa, \"Beni cin çarpmadı\" dedi. \"Ben Babam'ı onurlandırıyorum, ama siz beni aşağılıyorsunuz."},{"n":"50","t":"Ben kendimi yüceltmek istemiyorum, ama bunu isteyen ve yargılayan biri vardır."},{"n":"51","t":"Size doğrusunu söyleyeyim, bir kimse sözüme uyarsa, ölümü asla görmeyecektir.\""},{"n":"52","t":"Yahudiler, \"Seni cin çarptığını şimdi anlıyoruz\" dediler. \"İbrahim öldü, peygamberler de öldü. Oysa sen, 'Bir kimse sözüme uyarsa, ölümü asla tatmayacaktır' diyorsun."},{"n":"53","t":"Yoksa sen babamız İbrahim'den üstün müsün? O öldü, peygamberler de öldü. Sen kendini kim sanıyorsun?\""},{"n":"54","t":"İsa şu karşılığı verdi: \"Eğer ben kendimi yüceltirsem, yüceliğim hiçtir. Beni yücelten, 'Tanrımız' diye çağırdığınız Babam'dır."},{"n":"55","t":"Siz O'nu tanımıyorsunuz, ama ben tanıyorum. O'nu tanımadığımı söylersem, sizin gibi yalancı olurum. Ama ben O'nu tanıyor ve sözüne uyuyorum."},{"n":"56","t":"Babanız İbrahim günümü göreceği için sevinçle coşmuştu. Gördü ve sevindi.\""},{"n":"57","t":"Yahudiler, \"Sen daha elli yaşında bile değilsin. İbrahim'i de mi gördün?\" dediler."},{"n":"58","t":"İsa, \"Size doğrusunu söyleyeyim, İbrahim doğmadan önce ben varım\" dedi."},{"n":"59","t":"O zaman İsa'yı taşlamak için yerden taş aldılar, ama O gizlenip tapınaktan çıktı."}]},{"ch":9,"verses":[{"n":"1","t":"İsa yolda giderken doğuştan kör bir adam gördü."},{"n":"2","t":"Öğrencileri İsa'ya, \"Rabbî*, kim günah işledi de bu adam kör doğdu? Kendisi mi, yoksa annesi babası mı?\" diye sordular."},{"n":"3","t":"İsa şu yanıtı verdi: \"Ne kendisi, ne de annesi babası günah işledi. Tanrı'nın işleri onun yaşamında görülsün diye kör doğdu."},{"n":"4","t":"Beni gönderenin işlerini vakit daha gündüzken yapmalıyız. Gece geliyor, o zaman kimse çalışamaz."},{"n":"5","t":"Dünyada olduğum sürece dünyanın ışığı Ben'im.\""},{"n":"6","t":"Bu sözleri söyledikten sonra yere tükürdü, tükürükle çamur yaptı ve çamuru adamın gözlerine sürdü."},{"n":"7","t":"Adama, \"Git, Şiloah Havuzu'nda yıkan\" dedi. Şiloah, gönderilmiş anlamına gelir. Adam gidip yıkandı, gözleri açılmış olarak döndü."},{"n":"8","t":"Komşuları ve onu daha önce dilenirken görenler, \"Oturup dilenen adam değil mi bu?\" dediler."},{"n":"9","t":"Kimi, \"Evet, odur\" dedi, kimi de \"Hayır, ama ona benziyor\" dedi. Kendisi ise, \"Ben oyum\" dedi."},{"n":"10","t":"\"Öyleyse, gözlerin nasıl açıldı?\" diye sordular."},{"n":"11","t":"O da şöyle yanıt verdi: \"İsa adındaki adam çamur yapıp gözlerime sürdü ve bana, 'Şiloah'a git, yıkan' dedi. Ben de gidip yıkandım ve gözlerim açıldı.\""},{"n":"12","t":"Ona, \"Nerede O?\" diye sordular. \"Bilmiyorum\" dedi. Ferisiler'in Soruşturması"},{"n":"13","t":"Eskiden kör olan adamı Ferisiler'in* yanına götürdüler."},{"n":"14","t":"İsa'nın çamur yapıp adamın gözlerini açtığı gün Şabat Günü'ydü*."},{"n":"15","t":"Bu nedenle Ferisiler de adama gözlerinin nasıl açıldığını sordular. O da, \"İsa gözlerime çamur sürdü, yıkandım ve şimdi görüyorum\" dedi."},{"n":"16","t":"Bunun üzerine Ferisiler'in bazıları, \"Bu adam Tanrı'dan değildir\" dediler. \"Çünkü Şabat Günü'nü tutmuyor.\" Ama başkaları, \"Günahkâr bir adam nasıl bu tür belirtiler gerçekleştirebilir?\" dediler. Böylece aralarında ayrılık doğdu."},{"n":"17","t":"Eskiden kör olan adama yine sordular: \"Senin gözlerini açtığına göre, O'nun hakkında sen ne diyorsun?\" Adam, \"O bir peygamberdir\" dedi."},{"n":"18","t":"Yahudi yetkililer, gözleri açılan adamın annesiyle babasını çağırmadan onun daha önce kör olduğuna ve gözlerinin açıldığına inanmadılar."},{"n":"19","t":"Onlara, \"Kör doğdu dediğiniz oğlunuz bu mu? Peki, şimdi nasıl görüyor?\" diye sordular."},{"n":"20","t":"Adamın annesiyle babası şu karşılığı verdiler: \"Bunun bizim oğlumuz olduğunu ve kör doğduğunu biliyoruz."},{"n":"21","t":"Ama şimdi nasıl gördüğünü, gözlerini kimin açtığını bilmiyoruz, ona sorun. Ergin yaştadır, kendisi için kendisi konuşsun.\""},{"n":"22","t":"Yahudi yetkililerden korktukları için böyle konuştular. Çünkü yetkililer, İsa'nın Mesih* olduğunu açıkça söyleyeni havra dışı etmek için aralarında sözbirliği etmişlerdi."},{"n":"23","t":"Bundan dolayı adamın annesiyle babası, \"Ergin yaştadır, ona sorun\" dediler."},{"n":"24","t":"Eskiden kör olan adamı ikinci kez çağırıp, \"Tanrı hakkı için doğruyu söyle\"*fx* dediler, \"Biz bu adamın günahkâr olduğunu biliyoruz.\""},{"n":"25","t":"O da şöyle yanıt verdi: \"O'nun günahkâr olup olmadığını bilmiyorum. Bildiğim bir şey var, kördüm, şimdi görüyorum.\""},{"n":"26","t":"O zaman ona, \"Sana ne yaptı? Gözlerini nasıl açtı?\" dediler."},{"n":"27","t":"Onlara, \"Size demin söyledim, ama dinlemediniz\" dedi. \"Niçin yeniden işitmek istiyorsunuz? Yoksa siz de mi O'nun öğrencileri olmak niyetindesiniz?\""},{"n":"28","t":"Adama söverek, \"O'nun öğrencisi sensin!\" dediler. \"Biz Musa'nın öğrencileriyiz."},{"n":"29","t":"Tanrı'nın Musa'yla konuştuğunu biliyoruz. Ama bu adamın nereden geldiğini bilmiyoruz.\""},{"n":"30","t":"Adam onlara şu karşılığı verdi: \"Şaşılacak şey! O'nun nereden geldiğini bilmiyorsunuz, ama gözlerimi O açtı."},{"n":"31","t":"Tanrı'nın, günahkârları dinlemediğini biliriz. Ama Tanrı, kendisine tapan ve isteğini yerine getiren kişiyi dinler."},{"n":"32","t":"Dünya var olalı, bir kimsenin doğuştan kör olan birinin gözlerini açtığı duyulmamıştır."},{"n":"33","t":"Bu adam Tanrı'dan olmasaydı, hiçbir şey yapamazdı.\""},{"n":"34","t":"Onlar buna karşılık, \"Tamamen günah içinde doğdun, sen mi bize ders vereceksin?\" diyerek onu dışarı attılar. Ruhsal Körlük"},{"n":"35","t":"İsa adamı kovduklarını duydu. Onu bularak, \"Sen İnsanoğlu'na* iman ediyor musun?\" diye sordu."},{"n":"36","t":"Adam şu yanıtı verdi: \"Efendim, O kimdir? Söyle de kendisine iman edeyim.\""},{"n":"37","t":"İsa, \"O'nu gördün. Şimdi seninle konuşan O'dur\" dedi."},{"n":"38","t":"Adam, \"Rab, iman ediyorum!\" diyerek İsa'ya tapındı."},{"n":"39","t":"İsa, \"Görmeyenler görsün, görenler kör olsun diye yargıçlık etmek üzere bu dünyaya geldim\" dedi."},{"n":"40","t":"O'nun yanında bulunan bazı Ferisiler bu sözleri işitince, \"Yoksa biz de mi körüz?\" diye sordular."},{"n":"41","t":"İsa, \"Kör olsaydınız günahınız olmazdı\" dedi, \"Ama şimdi, 'Görüyoruz' dediğiniz için günahınız duruyor.\""}]},{"ch":10,"verses":[{"n":"1","t":"\"Size doğrusunu söyleyeyim, koyun ağılına kapıdan girmeyip başka yoldan giren kişi hırsız ve hayduttur."},{"n":"2","t":"Kapıdan giren ise koyunların çobanıdır."},{"n":"3","t":"Kapıyı bekleyen ona kapıyı açar. Koyunlar çobanın sesini işitirler, o da kendi koyunlarını adlarıyla çağırır ve onları dışarı götürür."},{"n":"4","t":"Kendi koyunlarının hepsini dışarı çıkarınca önlerinden gider, koyunlar da onu izler. Çünkü onun sesini tanırlar."},{"n":"5","t":"Bir yabancının peşinden gitmezler, ondan kaçarlar. Çünkü yabancıların sesini tanımazlar.\""},{"n":"6","t":"İsa onlara bu örneği anlattıysa da, ne demek istediğini anlamadılar."},{"n":"7","t":"Bunun için İsa yine, \"Size doğrusunu söyleyeyim\" dedi, \"Ben koyunların kapısıyım."},{"n":"8","t":"Benden önce gelenlerin hepsi hırsız ve hayduttu, ama koyunlar onları dinlemedi."},{"n":"9","t":"Kapı Ben'im. Bir kimse benim aracılığımla içeri girerse kurtulur. Girer, çıkar ve otlak bulur."},{"n":"10","t":"Hırsız ancak çalıp öldürmek ve yok etmek için gelir. Bense insanlar yaşama, bol yaşama sahip olsunlar diye geldim."},{"n":"11","t":"Ben iyi çobanım. İyi çoban koyunları uğruna canını verir."},{"n":"12","t":"Koyunların çobanı ve sahibi olmayan ücretli adam, kurdun geldiğini görünce koyunları bırakıp kaçar. Kurt da onları kapar ve dağıtır."},{"n":"13","t":"Adam kaçar. Çünkü ücretlidir ve koyunlar için kaygı duymaz."},{"n":"14-15","t":"Ben iyi çobanım. Benimkileri tanırım. Baba beni tanıdığı, ben de Baba'yı tanıdığım gibi, benimkiler de beni tanır. Ben koyunlarımın uğruna canımı veririm."},{"n":"16","t":"Bu ağıldan olmayan başka koyunlarım var. Onları da getirmeliyim. Benim sesimi işitecekler ve tek sürü, tek çoban olacak."},{"n":"17","t":"Canımı, tekrar geri almak üzere veririm. Bunun için Baba beni sever."},{"n":"18","t":"Canımı kimse benden alamaz; ben onu kendiliğimden veririm. Onu vermeye de tekrar geri almaya da yetkim var. Bu buyruğu Babam'dan aldım.\""},{"n":"19","t":"Bu sözlerden dolayı Yahudiler arasında yine ayrılık doğdu."},{"n":"20","t":"Birçoğu, \"O'nu cin çarpmış, delidir. Niçin O'nu dinliyorsunuz?\" diyordu."},{"n":"21","t":"Başkaları ise, \"Bunlar, cin çarpmış bir adamın sözleri değil\" dediler. \"Cin, körlerin gözlerini açabilir mi?\" İsa'ya Karşı Tepkiler Büyüyor"},{"n":"22","t":"O sırada Yeruşalim'de Tapınağın Açılışını Anma Bayramı* kutlanıyordu. Mevsim kıştı."},{"n":"23","t":"İsa tapınağın avlusunda, Süleyman'ın Eyvanı'nda yürüyordu."},{"n":"24","t":"Yahudi yetkililer O'nun çevresini sararak, \"Bizi daha ne kadar zaman kuşkuda bırakacaksın?\" dediler. \"Eğer Mesih* isen, bize açıkça söyle.\""},{"n":"25","t":"İsa onlara şu karşılığı verdi: \"Size söyledim, ama iman etmiyorsunuz. Babam'ın adıyla yaptığım işler bana tanıklık ediyor."},{"n":"26","t":"Ama siz iman etmiyorsunuz. Çünkü benim koyunlarımdan değilsiniz."},{"n":"27","t":"Koyunlarım sesimi işitir. Ben onları tanırım, onlar da beni izler."},{"n":"28","t":"Onlara sonsuz yaşam veririm; asla mahvolmayacaklar. Onları hiç kimse elimden kapamaz."},{"n":"29","t":"Onları bana veren Babam her şeyden üstündür. Onları Baba'nın elinden kapmaya kimsenin gücü yetmez."},{"n":"30","t":"Ben ve Baba biriz.\""},{"n":"31","t":"Yahudi yetkililer O'nu taşlamak için yerden yine taş aldılar."},{"n":"32","t":"İsa onlara, \"Size Baba'dan kaynaklanan birçok iyi işler gösterdim\" dedi. \"Bu işlerden hangisi için beni taşlıyorsunuz?\""},{"n":"33","t":"Şöyle yanıt verdiler: \"Seni iyi işlerden ötürü değil, küfür ettiğin için taşlıyoruz. İnsan olduğun halde Tanrı olduğunu ileri sürüyorsun.\""},{"n":"34","t":"İsa şu karşılığı verdi: \"Yasanızda, 'Siz ilahlarsınız, dedim' diye yazılı değil mi?"},{"n":"35","t":"Tanrı, kendilerine sözünü gönderdiği kimseleri ilahlar diye adlandırır. Kutsal Yazı da geçerliliğini yitirmez."},{"n":"36","t":"Baba beni kendine ayırıp dünyaya gönderdi. Öyleyse 'Tanrı'nın Oğlu'yum' dediğim için bana nasıl 'Küfür ediyorsun' dersiniz?"},{"n":"37","t":"Eğer Babam'ın işlerini yapmıyorsam, bana iman etmeyin."},{"n":"38","t":"Ama yapıyorsam, bana iman etmeseniz bile, yaptığım işlere iman edin. Öyle ki, Baba'nın bende, benim de Baba'da olduğumu bilesiniz ve anlayasınız.\""},{"n":"39","t":"O'nu yine yakalamaya çalıştılarsa da, ellerinden sıyrılıp kurtuldu."},{"n":"40","t":"Tekrar Şeria Irmağı'nın karşı yakasına, Yahya'nın başlangıçta vaftiz ettiği yere gitti ve orada kaldı."},{"n":"41","t":"Birçokları, \"Yahya hiç mucize yapmadı, ama bu adam için söylediklerinin hepsi doğru çıktı\" diyerek İsa'ya geldiler."},{"n":"42","t":"Ve orada birçokları O'na iman etti."}]},{"ch":11,"verses":[{"n":"1","t":"Meryem ile kızkardeşi Marta'nın köyü olan Beytanya'dan Lazar adında bir adam hastalanmıştı."},{"n":"2","t":"Meryem, Rab'be güzel kokulu yağ sürüp saçlarıyla O'nun ayaklarını silen kadındı. Hasta Lazar ise Meryem'in kardeşiydi."},{"n":"3","t":"İki kızkardeş İsa'ya, \"Rab, sevdiğin kişi hasta\" diye haber gönderdiler."},{"n":"4","t":"İsa bunu işitince, \"Bu hastalık ölümle sonuçlanmayacak; Tanrı'nın yüceliğine, Tanrı Oğlu'nun yüceltilmesine hizmet edecek\" dedi."},{"n":"5","t":"İsa Marta'yı, kızkardeşini ve Lazar'ı severdi."},{"n":"67","t":"Bu nedenle, Lazar'ın hasta olduğunu duyunca bulunduğu yerde iki gün daha kaldıktan sonra öğrencilere, \"Yahudiye'ye dönelim\" dedi."},{"n":"8","t":"Öğrenciler, \"Rabbî*\" dediler, \"Yahudi yetkililer demin seni taşlamaya kalkıştılar. Yine oraya mı gidiyorsun?\""},{"n":"9","t":"İsa şu karşılığı verdi: \"Günün on iki saati yok mu? Gündüz yürüyen sendelemez. Çünkü bu dünyanın ışığını görür."},{"n":"10","t":"Oysa gece yürüyen sendeler. Çünkü kendisinde ışık yoktur.\""},{"n":"11","t":"Bu sözleri söyledikten sonra, \"Dostumuz Lazar uyudu\" diye ekledi, \"Onu uyandırmaya gidiyorum.\""},{"n":"12","t":"Öğrenciler, \"Ya Rab\" dediler, \"Uyuduysa iyileşecektir.\""},{"n":"13","t":"İsa Lazar'ın ölümünden söz ediyordu, ama onlar olağan uykudan söz ettiğini sanmışlardı."},{"n":"14","t":"Bunun üzerine İsa açıkça, \"Lazar öldü\" dedi."},{"n":"15","t":"\"İman edesiniz diye, orada bulunmadığıma sizin için seviniyorum. Şimdi onun yanına gidelim.\""},{"n":"16","t":"\"İkiz*fx*\" diye anılan Tomas öbür öğrencilere, \"Biz de gidelim, O'nunla birlikte ölelim!\" dedi. İsa Lazar'ı Diriltiyor"},{"n":"17","t":"İsa Beytanya'ya yaklaşınca Lazar'ın dört gündür mezarda olduğunu öğrendi."},{"n":"18","t":"Beytanya, Yeruşalim'e on beş ok atımı*fx* kadar uzaklıktaydı."},{"n":"19","t":"Birçok Yahudi, kardeşlerini yitiren Marta'yla Meryem'i avutmaya gelmişti."},{"n":"20","t":"Marta İsa'nın geldiğini duyunca O'nu karşılamaya çıktı, Meryem ise evde kaldı."},{"n":"21","t":"Marta İsa'ya, \"Ya Rab\" dedi, \"Burada olsaydın, kardeşim ölmezdi."},{"n":"22","t":"Şimdi bile, Tanrı'dan ne dilersen Tanrı'nın onu sana vereceğini biliyorum.\""},{"n":"23","t":"İsa, \"Kardeşin dirilecektir\" dedi."},{"n":"24","t":"Marta, \"Son gün, diriliş günü onun dirileceğini biliyorum\" dedi."},{"n":"25","t":"İsa ona, \"Diriliş ve yaşam Ben'im\" dedi. \"Bana iman eden kişi ölse de yaşayacaktır."},{"n":"26","t":"Yaşayan ve bana iman eden asla ölmeyecek. Buna iman ediyor musun?\""},{"n":"27","t":"Marta, \"Evet, ya Rab\" dedi. \"Senin, dünyaya gelecek olan Tanrı'nın Oğlu Mesih* olduğuna iman ettim.\""},{"n":"28","t":"Bunu söyledikten sonra gidip kızkardeşi Meryem'i gizlice çağırdı. \"Öğretmen burada, seni çağırıyor\" dedi."},{"n":"29","t":"Meryem bunu işitince hemen kalkıp İsa'nın yanına gitti."},{"n":"30","t":"İsa henüz köye varmamıştı, hâlâ Marta'nın kendisini karşıladığı yerdeydi."},{"n":"31","t":"Meryem'le birlikte evde bulunan ve kendisini teselli eden Yahudiler, onun hızla kalkıp dışarı çıktığını gördüler. Ağlamak için mezara gittiğini sanarak onu izlediler."},{"n":"32","t":"Meryem İsa'nın bulunduğu yere vardı. O'nu görünce ayaklarına kapanarak, \"Ya Rab\" dedi, \"Burada olsaydın, kardeşim ölmezdi.\""},{"n":"33","t":"Meryem'in ve onunla gelen Yahudiler'in ağladığını gören İsa'nın ruhunu hüzün kapladı, yüreği sızladı."},{"n":"34","t":"\"Onu nereye koydunuz?\" diye sordu. O'na, \"Ya Rab, gel gör\" dediler."},{"n":"35","t":"İsa ağladı."},{"n":"36","t":"Yahudiler, \"Bakın, onu ne kadar seviyormuş!\" dediler."},{"n":"37","t":"Ama içlerinden bazıları, \"Körün gözlerini açan bu kişi, Lazar'ın ölümünü de önleyemez miydi?\" dediler."},{"n":"38","t":"İsa yine derinden hüzünlenerek mezara vardı. Mezar bir mağaraydı, girişinde de bir taş duruyordu."},{"n":"39","t":"İsa, \"Taşı çekin!\" dedi. Ölenin kızkardeşi Marta, \"Rab, o artık kokmuştur, öleli dört gün oldu\" dedi."},{"n":"40","t":"İsa ona, \"Ben sana, 'İman edersen Tanrı'nın yüceliğini göreceksin' demedim mi?\" dedi."},{"n":"41","t":"Bunun üzerine taşı çektiler. İsa gözlerini gökyüzüne kaldırarak şöyle dedi: \"Baba, beni işittiğin için sana şükrediyorum."},{"n":"42","t":"Beni her zaman işittiğini biliyordum. Ama bunu, çevrede duran halk için, beni senin gönderdiğine iman etsinler diye söyledim.\""},{"n":"43","t":"Bunları söyledikten sonra yüksek sesle, \"Lazar, dışarı çık!\" diye bağırdı."},{"n":"44","t":"Ölü, elleri ayakları sargılarla bağlı, yüzü peşkirle sarılmış olarak dışarı çıktı. İsa oradakilere, \"Onu çözün, bırakın gitsin\" dedi."},{"n":"45","t":"O zaman, Meryem'e gelen ve İsa'nın yaptıklarını gören Yahudiler'in birçoğu İsa'ya iman etti."},{"n":"46","t":"Ama içlerinden bazıları Ferisiler'e* giderek İsa'nın yaptıklarını onlara bildirdiler. İsa'yı Öldürme Tasarısı (Mat.26:15; Mar.14:12; Luk.22:12)"},{"n":"47","t":"Bunun üzerine başkâhinler ve Ferisiler, Yüksek Kurul'u* toplayıp dediler ki, \"Ne yapacağız? Bu adam birçok doğaüstü belirti gerçekleştiriyor."},{"n":"48","t":"Böyle devam etmesine izin verirsek, herkes O'na iman edecek. Romalılar da gelip kutsal yerimizi ve ulusumuzu ortadan kaldıracaklar.\""},{"n":"49","t":"İçlerinden biri, o yıl başkâhin olan Kayafa, \"Hiçbir şey bilmiyorsunuz\" dedi."},{"n":"50","t":"\"Bütün ulus yok olacağına, halk uğruna bir tek adamın ölmesi sizin için daha uygun. Bunu anlamıyor musunuz?\" Yu.11: 5152 Bunu kendiliğinden söylemiyordu. O yılın başkâhini olarak İsa'nın, ulusun uğruna, ve yalnız ulusun uğruna değil, Tanrı'nın dağılmış çocuklarını toplayıp birleştirmek için de öleceğine ilişkin peygamberlikte bulunuyordu."},{"n":"53","t":"Böylece o günden itibaren İsa'yı öldürmek için düzen kurmaya başladılar."},{"n":"54","t":"Bu yüzden İsa artık Yahudiler arasında açıkça dolaşmaz oldu. Oradan ayrılarak çöle yakın bir yere, Efrayim denilen kente gitti. Öğrencileriyle birlikte orada kaldı."},{"n":"55","t":"Yahudiler'in Fısıh Bayramı* yakındı. Taşradakilerin birçoğu bayramdan önce arınmak için Yeruşalim'e gitti."},{"n":"56","t":"Orada İsa'yı arayıp durdular. Tapınaktayken birbirlerine, \"Ne dersiniz, bayrama hiç gelmeyecek mi?\" diye soruyorlardı."},{"n":"57","t":"Başkâhinlerle Ferisiler O'nu yakalayabilmek için, yerini bilenlerin haber vermesini buyurmuşlardı."}]},{"ch":12,"verses":[{"n":"1","t":"İsa, Fısıh Bayramı'ndan* altı gün önce, ölümden dirilttiği Lazar'ın bulunduğu Beytanya'ya geldi."},{"n":"2","t":"Orada kendisi için bir ziyafet düzenlediler. Marta hizmet ediyordu. İsa'yla birlikte sofrada oturanlardan biri de Lazar'dı."},{"n":"3","t":"Meryem, çok değerli saf hintsümbülü yağından yarım litre kadar*fx* getirerek İsa'nın ayaklarına sürdü ve saçlarıyla ayaklarını sildi. Ev yağın güzel kokusuyla doldu."},{"n":"45","t":"Ama öğrencilerinden biri, İsa'ya sonradan ihanet eden Yahuda İskariot, \"Bu yağ neden üç yüz dinara satılıp parası yoksullara verilmedi?\" dedi."},{"n":"6","t":"Bunu, yoksullarla ilgilendiği için değil, hırsız olduğu için söylüyordu. Ortak para kutusu ondaydı ve kutuya konulandan aşırıyordu."},{"n":"7","t":"İsa, \"Kadını rahat bırak\" dedi. \"Bunu benim gömüleceğim gün için saklasın."},{"n":"8","t":"Yoksullar her zaman aranızdadır, ama ben her zaman aranızda olmayacağım.\""},{"n":"9","t":"Yahudiler'den büyük bir kalabalık İsa'nın Beytanya'da bulunduğunu öğrendi ve yalnız İsa için değil, O'nun ölümden dirilttiği Lazar'ı da görmek için oraya geldi."},{"n":"10","t":"Başkâhinler ise Lazar'ı da öldürmeyi tasarladılar."},{"n":"11","t":"Çünkü onun yüzünden birçok Yahudi gidip İsa'ya iman ediyordu. İsa'nın Yeruşalim'e Girişi (Mat.21:111; Mar.11:111; Luk.19:2840)"},{"n":"12","t":"Ertesi gün, bayramı kutlamaya gelen büyük kalabalık İsa'nın Yeruşalim'e gelmekte olduğunu duydu."},{"n":"13","t":"Hurma dalları alarak O'nu karşılamaya çıktılar. \"Hozana*! Rab'bin adıyla gelene, İsrail'in Kralı'na övgüler olsun!\" diye bağırıyorlardı. Yu.12: 1415 İsa bir sıpa bulup üzerine bindi. Yazılmış olduğu gibi, \"Korkma, ey Siyon* kızı! İşte, Kralın sıpaya binmiş geliyor.\""},{"n":"16","t":"Öğrencileri ilkin bunları anlamadılar. Ama İsa yüceltildikten sonra bu sözlerin O'nun hakkında yazıldığını, halkın bunları O'nun için yaptığını hatırladılar."},{"n":"17","t":"Lazar'ı mezardan çağırıp ölümden dirilttiği sırada İsa'yla birlikte bulunan kalabalık buna tanıklık etti."},{"n":"18","t":"İsa'nın bu doğaüstü belirtiyi gerçekleştirdiğini duyan halk O'nu karşılamaya çıktı."},{"n":"19","t":"Ferisiler* ise birbirlerine, \"Görüyorsunuz, elinizden hiçbir şey gelmiyor. Bütün dünya O'nun peşine takıldı\" dediler. İsa Öleceğini Önceden Bildiriyor"},{"n":"20","t":"Bayramda tapınmak üzere Yeruşalim'e gidenler arasında bazı Grekler* vardı."},{"n":"21","t":"Bunlar, Celile'nin Beytsayda Kenti'nden olan Filipus'a gelerek, \"Efendimiz, İsa'yı görmek istiyoruz\" diye rica ettiler."},{"n":"22","t":"Filipus gitti, bunu Andreas'a bildirdi. Andreas ve Filipus da gidip İsa'ya haber verdiler."},{"n":"23","t":"İsa, \"İnsanoğlu'nun* yüceltileceği saat geldi\" diye karşılık verdi."},{"n":"24","t":"\"Size doğrusunu söyleyeyim, buğday tanesi toprağa düşüp ölmedikçe yalnız kalır. Ama ölürse çok ürün verir."},{"n":"25","t":"Canını seven onu yitirir. Ama bu dünyada canını gözden çıkaran*fx* onu sonsuz yaşam için koruyacaktır."},{"n":"26","t":"Bana hizmet etmek isteyen, ardımdan gelsin. Ben neredeysem bana hizmet eden de orada olacak. Baba, bana hizmet edeni onurlandıracaktır."},{"n":"27","t":"Şimdi yüreğim sıkılıyor, ne diyeyim? 'Baba, beni bu saatten kurtar' mı diyeyim? Ama ben bu amaç için bu saate geldim."},{"n":"28","t":"Baba, adını yücelt!\" Bunun üzerine gökten bir ses geldi: \"Adımı yücelttim ve yine yücelteceğim.\""},{"n":"29","t":"Orada duran ve bunu işiten kalabalık, \"Gök gürledi\" dedi. Başkaları, \"Bir melek O'nunla konuştu\" dedi."},{"n":"30","t":"İsa, \"Bu ses benim için değil, sizin içindi\" dedi."},{"n":"31","t":"\"Bu dünya şimdi yargılanıyor. Bu dünyanın egemeni*fx* şimdi dışarı atılacak."},{"n":"32","t":"Ben yerden yukarı kaldırıldığım zaman bütün insanları kendime çekeceğim.\""},{"n":"33","t":"İsa bunu, nasıl öleceğini belirtmek için söylüyordu."},{"n":"34","t":"Kalabalık O'na şöyle karşılık verdi: \"Kutsal Yasa'dan öğrendiğimize göre Mesih* sonsuza dek kalacaktır. Nasıl oluyor da sen, 'İnsanoğlu yukarı kaldırılmalıdır' diyorsun? Kimdir bu İnsanoğlu?\""},{"n":"35","t":"İsa, \"Işık kısa bir süre daha aranızdadır\" dedi. \"Karanlıkta kalmamak için ışığınız varken yürüyün. Karanlıkta yürüyen nereye gittiğini bilmez."},{"n":"36","t":"Sizde ışık varken ışığa iman edin ki, ışık oğulları olasınız.\" İsa bu sözleri söyledikten sonra uzaklaşıp onlardan gizlendi. Halkın İnadı"},{"n":"37","t":"Gözleri önünde bunca doğaüstü belirti gerçekleştirdiği halde O'na iman etmediler."},{"n":"38","t":"Bütün bunlar Peygamber Yeşaya'nın söylediği şu söz yerine gelsin diye oldu: \"Rab, verdiğimiz habere kim inandı? Rab'bin gücü kime açıklandı?\" Yu.12: 3940 İşte bu yüzden iman edemiyorlardı. Nitekim Yeşaya başka bir yerde de şöyle demişti: \"Tanrı onların gözlerini kör etti Ve yüreklerini nasırlaştırdı. Öyle ki, gözleri görmesin, Yürekleri anlamasın Ve bana dönmesinler. Dönselerdi, onları iyileştirirdim.\""},{"n":"41","t":"Bunları söyleyen Yeşaya, İsa'nın yüceliğini görmüş ve O'nun hakkında konuşmuştu."},{"n":"42","t":"Bununla birlikte, önderlerin bile birçoğu İsa'ya iman etti. Ama Ferisiler* yüzünden, havra dışı edilmemek için iman ettiklerini açıkça söylemediler."},{"n":"43","t":"Çünkü insandan gelen övgüyü, Tanrı'dan gelen övgüden daha çok seviyorlardı."},{"n":"44","t":"İsa yüksek sesle, \"Bana iman eden bana değil, beni gönderene iman etmiş olur\" dedi."},{"n":"45","t":"\"Beni gören beni göndereni de görür."},{"n":"46","t":"Bana iman eden hiç kimse karanlıkta kalmasın diye, dünyaya ışık olarak geldim."},{"n":"47","t":"Sözlerimi işitip de onlara uymayanı ben yargılamam. Çünkü ben dünyayı yargılamaya değil, dünyayı kurtarmaya geldim."},{"n":"48","t":"Beni reddeden ve sözlerimi kabul etmeyen kişiyi yargılayacak biri var. O kişiyi son günde yargılayacak olan, söylediğim sözdür."},{"n":"49","t":"Çünkü ben kendiliğimden konuşmadım. Beni gönderen Baba'nın kendisi ne söylemem ve ne konuşmam gerektiğini bana buyurdu."},{"n":"50","t":"O'nun buyruğunun sonsuz yaşam olduğunu biliyorum. Bunun için ne söylüyorsam, Baba'nın bana söylediği gibi söylüyorum.\""}]},{"ch":13,"verses":[{"n":"1","t":"Fısıh Bayramı'ndan* önceydi. İsa, bu dünyadan ayrılıp Baba'ya gideceği saatin geldiğini biliyordu. Dünyada kendisine ait olanları hep sevmişti; sonuna kadar da sevdi."},{"n":"2","t":"Akşam yemeği sırasında İblis, Simun İskariot'un oğlu Yahuda'nın yüreğine İsa'ya ihanet etme isteğini koymuştu bile."},{"n":"3","t":"İsa, Baba'nın her şeyi kendisine teslim ettiğini, kendisinin Tanrı'dan çıkıp geldiğini ve Tanrı'ya döneceğini biliyordu."},{"n":"4","t":"Yemekten kalktı, üstlüğünü bir yana koydu, bir havlu alıp beline doladı."},{"n":"5","t":"Sonra bir leğene su doldurup öğrencilerin ayaklarını yıkamaya ve beline doladığı havluyla kurulamaya başladı."},{"n":"6","t":"İsa, Simun Petrus'a geldi. Simun, \"Ya Rab, ayaklarımı sen mi yıkayacaksın?\" dedi."},{"n":"7","t":"İsa ona şu yanıtı verdi: \"Ne yaptığımı şimdi anlayamazsın, ama sonra anlayacaksın.\""},{"n":"8","t":"Petrus, \"Benim ayaklarımı asla yıkamayacaksın!\" dedi. İsa, \"Yıkamazsam yanımda yerin olmaz\" diye yanıtladı."},{"n":"9","t":"Simun Petrus, \"Ya Rab, o halde yalnız ayaklarımı değil, ellerimi ve başımı da yıka!\" dedi."},{"n":"10","t":"İsa ona dedi ki, \"Yıkanmış olan tamamen temizdir; ayaklarının yıkanmasından başka şeye ihtiyacı yoktur. Sizler temizsiniz, ama hepiniz değil.\""},{"n":"11","t":"İsa, kendisine kimin ihanet edeceğini biliyordu. Bu nedenle, \"Hepiniz temiz değilsiniz\" demişti."},{"n":"12","t":"Onların ayaklarını yıkadıktan sonra giyinip yine sofraya oturdu. \"Size ne yaptığımı anlıyor musunuz?\" dedi."},{"n":"13","t":"\"Siz beni Öğretmen ve Rab diye çağırıyorsunuz. Doğru söylüyorsunuz, öyleyim."},{"n":"14","t":"Ben Rab ve Öğretmen olduğum halde ayaklarınızı yıkadım; öyleyse, sizler de birbirinizin ayaklarını yıkamalısınız."},{"n":"15","t":"Size yaptığımın aynısını yapmanız için bir örnek gösterdim."},{"n":"16","t":"Size doğrusunu söyleyeyim, köle efendisinden, elçi de kendisini gönderenden üstün değildir."},{"n":"17","t":"Bildiğiniz bu şeyleri yaparsanız, ne mutlu size!\" İsa'ya İhanet (Mat.26:2025; Mar.14:1721; Luk.22:2123)"},{"n":"18","t":"\"Hepiniz için söylemiyorum, ben seçtiklerimi bilirim. Ama, 'Ekmeğimi yiyen bana ihanet etti*fx*' diyen Kutsal Yazı'nın yerine gelmesi için böyle olacak."},{"n":"19","t":"Size şimdiden, bunlar olmadan önce söylüyorum ki, bunlar olunca, benim O olduğuma*fx* inanasınız."},{"n":"20","t":"Size doğrusunu söyleyeyim, benim gönderdiğim herhangi bir kimseyi kabul eden beni kabul etmiş olur. Beni kabul eden de beni göndereni kabul etmiş olur.\""},{"n":"21","t":"İsa bunları söyledikten sonra ruhunda derin bir sıkıntı duydu. Açıkça konuşarak, \"Size doğrusunu söyleyeyim, sizden biri bana ihanet edecek\" dedi."},{"n":"22","t":"Öğrenciler, kimden söz ettiğini merak ederek birbirlerine baktılar."},{"n":"23","t":"Öğrencilerinden biri İsa'nın göğsüne yaslanmıştı. İsa onu severdi."},{"n":"24","t":"Simun Petrus bu öğrenciye, kimden söz ettiğini İsa'ya sorması için işaret etti."},{"n":"25","t":"O da İsa'nın göğsüne yaslanmış durumda, \"Ya Rab, kimdir o?\" diye sordu."},{"n":"26","t":"İsa, \"Lokmayı sahana batırıp kime verirsem odur\" diye yanıtladı. Sonra lokmayı batırıp Simun İskariot'un oğlu Yahuda'ya verdi."},{"n":"27","t":"Yahuda lokmayı alır almaz Şeytan onun içine girdi. İsa da ona, \"Yapacağını tez yap!\" dedi."},{"n":"28","t":"Sofrada oturanların hiçbiri, İsa'nın ona bu sözleri neden söylediğini anlamadı."},{"n":"29","t":"Para kutusu Yahuda'da olduğundan, bazıları İsa'nın ona, \"Bayram için bize gerekli şeyleri al\" ya da, \"Yoksullara bir şey ver\" demek istediğini sandılar."},{"n":"30","t":"Yahuda lokmayı aldıktan hemen sonra dışarı çıktı. Gece olmuştu. Birbirinizi Sevin"},{"n":"31","t":"Yahuda dışarı çıkınca İsa, \"İnsanoğlu* şimdi yüceltildi\" dedi. \"Tanrı da O'nda yüceltildi."},{"n":"32","t":"Tanrı O'nda yüceltildiğine göre, Tanrı da O'nu kendinde yüceltecek. Hem de hemen yüceltecektir."},{"n":"33","t":"Çocuklar! Kısa bir süre daha sizinleyim. Beni arayacaksınız, ama Yahudiler'e söylediğim gibi, şimdi size de söylüyorum, benim gideceğim yere siz gelemezsiniz."},{"n":"34","t":"Size yeni bir buyruk veriyorum: Birbirinizi sevin. Sizi sevdiğim gibi siz de birbirinizi sevin."},{"n":"35","t":"Birbirinize sevginiz olursa, herkes bununla benim öğrencilerim olduğunuzu anlayacaktır.\" Petrus, İsa'yı İnkâr Edecek (Mat.26:3135; Mar.14:2731; Luk.22:3134)"},{"n":"36","t":"Simun Petrus O'na, \"Ya Rab, nereye gidiyorsun?\" diye sordu. İsa, \"Gideceğim yere şimdi ardımdan gelemezsin, ama sonra geleceksin\" diye yanıtladı."},{"n":"37","t":"Petrus, \"Ya Rab, neden şimdi senin ardından gelemeyeyim? Senin için canımı veririm!\" dedi."},{"n":"38","t":"İsa şöyle yanıtladı: \"Benim için canını mı vereceksin? Sana doğrusunu söyleyeyim, horoz ötmeden beni üç kez inkâr edeceksin.\""}]},{"ch":14,"verses":[{"n":"1","t":"\"Yüreğiniz sıkılmasın. Tanrı'ya iman edin, bana da iman edin."},{"n":"2","t":"Babam'ın evinde kalacak çok yer var. Öyle olmasa size söylerdim. Çünkü size yer hazırlamaya gidiyorum."},{"n":"3","t":"Gider ve size yer hazırlarsam, siz de benim bulunduğum yerde olasınız diye yine gelip sizi yanıma alacağım."},{"n":"4","t":"Benim gideceğim yerin yolunu biliyorsunuz.\""},{"n":"5","t":"Tomas, \"Ya Rab, senin nereye gideceğini bilmiyoruz, yolu nasıl bilebiliriz?\" dedi."},{"n":"6","t":"İsa, \"Yol, gerçek ve yaşam Ben'im\" dedi. \"Benim aracılığım olmadan Baba'ya kimse gelemez."},{"n":"7","t":"Beni tanısaydınız, Babam'ı da tanırdınız. Artık O'nu tanıyorsunuz, O'nu gördünüz.\""},{"n":"8","t":"Filipus, \"Ya Rab, bize Baba'yı göster, bu bize yeter\" dedi."},{"n":"9","t":"İsa, \"Filipus\" dedi, \"Bunca zamandır sizinle birlikteyim. Beni daha tanımadın mı? Beni görmüş olan, Baba'yı görmüştür. Sen nasıl, 'Bize Baba'yı göster' diyorsun?"},{"n":"10","t":"Benim Baba'da, Baba'nın da bende olduğuna inanmıyor musun? Size söylediğim sözleri kendiliğimden söylemiyorum, ama bende yaşayan Baba kendi işlerini yapıyor."},{"n":"11","t":"Bana iman edin; ben Baba'dayım, Baba da bendedir. Hiç değilse bu işlerden dolayı iman edin."},{"n":"12","t":"Size doğrusunu söyleyeyim, benim yaptığım işleri, bana iman eden de yapacak; hatta daha büyüklerini yapacaktır. Çünkü ben Baba'ya gidiyorum."},{"n":"13","t":"Baba Oğul'da yüceltilsin diye, benim adımla dilediğiniz her şeyi yapacağım."},{"n":"14","t":"Benim adımla benden ne dilerseniz yapacağım.\" Kutsal Ruh"},{"n":"15","t":"\"Beni seviyorsanız, buyruklarımı yerine getirirsiniz. Yu.14: 1617 Ben de Baba'dan dileyeceğim. O sonsuza dek sizinle birlikte olsun diye size başka bir Yardımcı*, Gerçeğin Ruhu'nu verecek. Dünya O'nu kabul edemez. Çünkü O'nu ne görür, ne de tanır. Siz O'nu tanıyorsunuz. Çünkü O aranızda yaşıyor ve içinizde olacaktır."},{"n":"18","t":"Sizi öksüz bırakmayacağım, size geri döneceğim."},{"n":"19","t":"Az sonra dünya artık beni görmeyecek, ama siz beni göreceksiniz. Ben yaşadığım için siz de yaşayacaksınız."},{"n":"20","t":"O gün anlayacaksınız ki, ben Babam'dayım, siz bendesiniz, ben de sizdeyim."},{"n":"21","t":"Kim buyruklarımı bilir ve yerine getirirse, işte beni seven odur. Beni seveni Babam da sevecektir. Ben de onu seveceğim ve kendimi ona göstereceğim.\""},{"n":"22","t":"Yahuda İskariot değil O'na, \"Ya Rab, nasıl olur da kendini dünyaya göstermeyip bize göstereceksin?\" diye sordu."},{"n":"23","t":"İsa ona şu karşılığı verdi: \"Beni seven sözüme uyar, Babam da onu sever. Biz de ona gelir, onunla birlikte yaşarız."},{"n":"24","t":"Beni sevmeyen, sözlerime uymaz. İşittiğiniz söz benim değil, beni gönderen Baba'nındır."},{"n":"25","t":"\"Ben daha aranızdayken size bunları söyledim."},{"n":"26","t":"Ama Baba'nın benim adımla göndereceği Yardımcı, Kutsal Ruh, size her şeyi öğretecek, bütün söylediklerimi size hatırlatacak."},{"n":"27","t":"Size esenlik bırakıyorum, size kendi esenliğimi veriyorum. Ben size dünyanın verdiği gibi vermiyorum. Yüreğiniz sıkılmasın ve korkmasın."},{"n":"28","t":"Size, 'Gidiyorum, ama yanınıza döneceğim' dediğimi işittiniz. Beni sevseydiniz, Baba'ya gideceğim için sevinirdiniz. Çünkü Baba benden üstündür."},{"n":"29","t":"Bunları size şimdiden, her şey olup bitmeden önce söyledim. Öyle ki, bunlar olunca inanasınız."},{"n":"30","t":"Artık sizinle uzun uzun konuşmayacağım. Çünkü bu dünyanın egemeni*fx* geliyor. Onun benim üzerimde hiçbir yetkisi yoktur."},{"n":"31","t":"Ama dünyanın, Baba'yı sevdiğimi ve Baba'nın bana buyurduğu her şeyi yerine getirdiğimi anlamasını istiyorum. Haydi kalkın, buradan gidelim.\""}]},{"ch":15,"verses":[{"n":"1","t":"\"Ben gerçek asmayım ve Babam bağcıdır."},{"n":"2","t":"Bende meyve vermeyen her çubuğu kesip atar, meyve veren her çubuğu ise daha çok meyve versin diye budayıp temizler."},{"n":"3","t":"Size söylediğim sözle siz şimdiden temizsiniz."},{"n":"4","t":"Bende kalın, ben de sizde kalayım. Çubuk asmada kalmazsa kendiliğinden meyve veremez. Bunun gibi, siz de bende kalmazsanız meyve veremezsiniz."},{"n":"5","t":"Ben asmayım, siz çubuklarsınız. Bende kalan ve benim kendisinde kaldığım kişi çok meyve verir. Bensiz hiçbir şey yapamazsınız."},{"n":"6","t":"Bir kimse bende kalmazsa, çubuk gibi dışarı atılır ve kurur. Böylelerini toplar, ateşe atıp yakarlar."},{"n":"7","t":"Eğer bende kalırsanız ve sözlerim sizde kalırsa, ne isterseniz dileyin, size verilecektir."},{"n":"8","t":"Babam çok meyve vermenizle yüceltilir. Böylelikle öğrencilerim olursunuz."},{"n":"9","t":"\"Baba'nın beni sevdiği gibi, ben de sizi sevdim. Benim sevgimde kalın."},{"n":"10","t":"Eğer buyruklarımı yerine getirirseniz sevgimde kalırsınız, tıpkı benim de Babam'ın buyruklarını yerine getirdiğim ve sevgisinde kaldığım gibi..."},{"n":"11","t":"Bunları size, sevincim sizde olsun ve sevinciniz tamamlansın diye söyledim."},{"n":"12","t":"Benim buyruğum şudur: Sizi sevdiğim gibi birbirinizi sevin."},{"n":"13","t":"Hiç kimsede, insanın, dostları uğruna canını vermesinden daha büyük bir sevgi yoktur."},{"n":"14","t":"Size buyurduklarımı yaparsanız, benim dostlarım olursunuz."},{"n":"15","t":"Artık size kul demiyorum. Çünkü kul efendisinin ne yaptığını bilmez. Size dost dedim. Çünkü Babam'dan bütün işittiklerimi size bildirdim."},{"n":"16","t":"Siz beni seçmediniz, ben sizi seçtim. Gidip meyve veresiniz, meyveniz de kalıcı olsun diye sizi ben atadım. Öyle ki, benim adımla Baba'dan ne dilerseniz size versin."},{"n":"17","t":"Size şu buyruğu veriyorum: Birbirinizi sevin!\" Dünyanın Nefreti"},{"n":"18","t":"\"Dünya sizden nefret ederse, sizden önce benden nefret etmiş olduğunu bilin."},{"n":"19","t":"Dünyadan olsaydınız, dünya kendisine ait olanı severdi. Ne var ki, dünyanın değilsiniz; ben sizi dünyadan seçtim. Bunun için dünya sizden nefret ediyor."},{"n":"20","t":"Size söylediğim sözü hatırlayın: 'Köle efendisinden üstün değildir.' Bana zulmettilerse, size de zulmedecekler. Benim sözüme uydularsa, sizinkine de uyacaklar."},{"n":"21","t":"Bütün bunları size benim adımdan ötürü yapacaklar. Çünkü beni göndereni tanımıyorlar."},{"n":"22","t":"Eğer gelmemiş ve onlara söylememiş olsaydım, günahları olmazdı; ama şimdi günahları için özürleri yoktur."},{"n":"23","t":"Benden nefret eden, Babam'dan da nefret eder."},{"n":"24","t":"Başka hiç kimsenin yapmadığı işleri onların arasında yapmamış olsaydım, günahları olmazdı. Şimdiyse yaptıklarımı gördükleri halde hem benden hem de Babam'dan nefret ettiler."},{"n":"25","t":"Bu, yasalarında yazılı, 'Yok yere benden nefret ettiler' sözü yerine gelsin diye oldu."},{"n":"26","t":"\"Baba'dan size göndereceğim Yardımcı*, yani Baba'dan çıkan Gerçeğin Ruhu geldiği zaman, bana tanıklık edecek."},{"n":"27","t":"Siz de tanıklık edeceksiniz. Çünkü başlangıçtan beri benimle birliktesiniz."}]},{"ch":16,"verses":[{"n":"1","t":"\"Bunları size, sendeleyip düşmeyesiniz diye söyledim."},{"n":"2","t":"Sizi havra dışı edecekler. Evet, öyle bir saat geliyor ki, sizi öldüren herkes Tanrı'ya hizmet ettiğini sanacak."},{"n":"3","t":"Bunları, Baba'yı ve beni tanımadıkları için yapacaklar."},{"n":"4","t":"Bunları size şimdiden bildiriyorum. Öyle ki, saati gelince bunları size söylediğimi hatırlayasınız. Başlangıçta bunları size söylemedim. Çünkü sizinle birlikteydim.\" Kutsal Ruh'un İşleyişi"},{"n":"5","t":"\"Şimdiyse beni gönderenin yanına gidiyorum. Ne var ki, içinizden hiçbiri bana, 'Nereye gidiyorsun?' diye sormuyor."},{"n":"6","t":"Ama bunları söylediğim için yüreğiniz kederle doldu."},{"n":"7","t":"Size gerçeği söylüyorum, benim gidişim sizin yararınızadır. Gitmezsem, Yardımcı* size gelmez. Ama gidersem, O'nu size gönderirim."},{"n":"8","t":"O gelince günah, doğruluk ve gelecek yargı konusunda dünyayı suçlu olduğuna ikna edecektir:"},{"n":"9","t":"Günah konusunda, çünkü bana iman etmezler;"},{"n":"10","t":"doğruluk konusunda, çünkü Baba'ya gidiyorum, artık beni görmeyeceksiniz;"},{"n":"11","t":"yargı konusunda, çünkü bu dünyanın egemeni*fx* yargılanmış bulunuyor."},{"n":"12","t":"\"Size daha çok söyleyeceklerim var, ama şimdi bunlara dayanamazsınız."},{"n":"13","t":"Ne var ki O, yani Gerçeğin Ruhu gelince, sizi tüm gerçeğe yöneltecek. Çünkü kendiliğinden konuşmayacak, yalnız duyduklarını söyleyecek ve gelecekte olacakları size bildirecek."},{"n":"14","t":"O beni yüceltecek. Çünkü benim olandan alıp size bildirecek."},{"n":"15","t":"Baba'nın nesi varsa benimdir. 'Benim olandan alıp size bildirecek' dememin nedeni budur."},{"n":"16","t":"\"Kısa süre sonra beni artık görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz.\" Kederiniz Sevince Dönüşecek"},{"n":"17","t":"Öğrencilerinden bazıları birbirlerine, \"Ne demek istiyor?\" diye sordular. \"'Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz' diyor. Ayrıca, 'Çünkü Baba'ya gidiyorum' diyor.\""},{"n":"18","t":"Onun için, \"Bu 'kısa süre' dediği nedir? Söylediklerini anlamıyoruz\" deyip durdular."},{"n":"19","t":"İsa kendisine soru sormak istediklerini anladı. Onlara dedi ki, \"'Kısa süre sonra beni görmeyeceksiniz; yine kısa süre sonra beni göreceksiniz' dememi mi tartışıyorsunuz?"},{"n":"20","t":"Size doğrusunu söyleyeyim, siz ağlayıp yas tutacaksınız, dünya ise sevinecektir. Kederleneceksiniz, ama kederiniz sevince dönüşecek."},{"n":"21","t":"Kadın doğum yapacağı zaman ağrı çeker. Çünkü saati gelmiştir. Ama doğurunca, dünyaya bir çocuk getirmenin sevinciyle çektiği acıyı unutur."},{"n":"22","t":"Bunun gibi, siz de şimdi kederleniyorsunuz, ama sizi yine göreceğim. O zaman yürekten sevineceksiniz. Sevincinizi kimse sizden alamaz."},{"n":"23","t":"O gün bana hiçbir şey sormayacaksınız. Size doğrusunu söyleyeyim, benim adımla Baba'dan ne dilerseniz, size verecektir."},{"n":"24","t":"Şimdiye dek benim adımla bir şey dilemediniz. Dileyin, alacaksınız. Öyle ki, sevinciniz tam olsun."},{"n":"25","t":"\"Size bunları örneklerle anlattım. Öyle bir saat geliyor ki, artık örneklerle konuşmayacağım; Baba'yı size açıkça tanıtacağım."},{"n":"26","t":"O gün dileyeceğinizi benim adımla dileyeceksiniz. Sizin için Baba'dan istekte bulunacağımı söylemiyorum."},{"n":"27","t":"Çünkü beni sevdiğiniz ve Baba'dan çıkıp geldiğime iman ettiğiniz için Baba'nın kendisi sizi seviyor."},{"n":"28","t":"Ben Baba'dan çıkıp dünyaya geldim. Şimdi dünyayı bırakıp Baba'ya dönüyorum.\""},{"n":"29","t":"Öğrencileri, \"İşte, şimdi açıkça konuşuyorsun, hiç örnek kullanmıyorsun\" dediler."},{"n":"30","t":"\"Şimdi senin her şeyi bildiğini anlıyoruz. Kimsenin sana soru sormasına gerek yok. Tanrı'dan geldiğine bunun için iman ediyoruz.\""},{"n":"31","t":"İsa onlara, \"Şimdi iman ediyor musunuz?\" diye karşılık verdi."},{"n":"32","t":"\"İşte, hepinizin evlerinize gitmek üzere dağılacağınız ve beni yalnız bırakacağınız saat geliyor, geldi bile. Ama ben yalnız değilim, Baba benimle birliktedir."},{"n":"33","t":"Bunları size, bende esenliğiniz olsun diye söyledim. Dünyada sıkıntınız olacak. Ama cesur olun, ben dünyayı yendim!\""}]},{"ch":17,"verses":[{"n":"1","t":"İsa bunları söyledikten sonra, gözlerini gökyüzüne kaldırıp şöyle dedi: \"Baba, saat geldi. Oğlun'u yücelt ki, Oğul da seni yüceltsin."},{"n":"2","t":"Çünkü sen O'na bütün insanlık üzerinde yetki verdin. Öyle ki, O'na verdiklerinin hepsine sonsuz yaşam versin."},{"n":"3","t":"Sonsuz yaşam, tek gerçek Tanrı olan seni ve gönderdiğin İsa Mesih'i tanımalarıdır."},{"n":"4","t":"Yapmam için bana verdiğin işi tamamlamakla seni yeryüzünde yücelttim."},{"n":"5","t":"Baba, dünya var olmadan önce ben senin yanındayken sahip olduğum yücelikle şimdi beni yanında yücelt."},{"n":"6","t":"\"Dünyadan bana verdiğin insanlara senin adını açıkladım. Onlar senindiler, bana verdin ve senin sözüne uydular."},{"n":"7","t":"Bana verdiğin her şeyin senden olduğunu şimdi biliyorlar."},{"n":"8","t":"Çünkü bana ilettiğin sözleri onlara ilettim, onlar da kabul ettiler. Senden çıkıp geldiğimi gerçekten anladılar, beni senin gönderdiğine iman ettiler."},{"n":"9","t":"Onlar için istekte bulunuyorum. Dünya için değil, bana verdiğin kimseler için istekte bulunuyorum. Çünkü onlar senindir."},{"n":"10","t":"Benim olan her şey senindir, seninkiler de benimdir. Ben onlarda yüceltildim."},{"n":"11","t":"Ben artık dünyada değilim, ama onlar dünyadalar. Ben sana geliyorum. Kutsal Baba, onları bana verdiğin kendi adınla koru ki, bizim gibi bir olsunlar."},{"n":"12","t":"Kendileriyle birlikte olduğum sürece, bana verdiğin kendi adınla onları esirgeyip korudum. Kutsal Yazı yerine gelsin diye, mahva giden adamdan*fx* başka içlerinden hiçbiri mahvolmadı."},{"n":"13","t":"\"İşte şimdi sana geliyorum. Sevincimin onlarda tamamlanması için bunları ben dünyadayken söylüyorum."},{"n":"14","t":"Ben onlara senin sözünü ilettim, dünya ise onlardan nefret etti. Çünkü ben dünyadan olmadığım gibi, onlar da dünyadan değiller."},{"n":"15","t":"Onları dünyadan uzaklaştırmanı değil, kötü olandan* korumanı istiyorum."},{"n":"16","t":"Ben dünyadan olmadığım gibi, onlar da dünyadan değiller."},{"n":"17","t":"Onları gerçekle kutsal kıl. Senin sözün gerçektir."},{"n":"18","t":"Sen beni dünyaya gönderdiğin gibi, ben de onları dünyaya gönderdim."},{"n":"19","t":"Onlar da gerçekle kutsal kılınsınlar diye kendimi onların uğruna adıyorum*fx*. Yu.17: 2021 \"Yalnız onlar için değil, onların sözüyle bana iman edenler için de istekte bulunuyorum, hepsi bir olsunlar. Baba, senin bende olduğun ve benim sende olduğum gibi, onlar da bizde olsunlar. Dünya da beni senin gönderdiğine iman etsin."},{"n":"22","t":"Bana verdiğin yüceliği onlara verdim. Öyle ki, bizim bir olduğumuz gibi bir olsunlar."},{"n":"23","t":"Ben onlarda, sen bende olmak üzere tam bir birlik içinde bulunsunlar ki, dünya beni senin gönderdiğini, beni sevdiğin gibi onları da sevdiğini anlasın."},{"n":"24","t":"Baba, bana verdiklerinin de bulunduğum yerde benimle birlikte olmalarını ve benim yüceliğimi, bana verdiğin yüceliği görmelerini istiyorum. Çünkü dünyanın kuruluşundan önce sen beni sevdin."},{"n":"25","t":"Adil Baba, dünya seni tanımıyor, ama ben seni tanıyorum. Bunlar da beni senin gönderdiğini biliyorlar."},{"n":"26","t":"Bana beslediğin sevgi onlarda olsun, ben de onlarda olayım diye senin adını onlara bildirdim ve bildirmeye devam edeceğim.\""}]},{"ch":18,"verses":[{"n":"1","t":"İsa bu sözleri söyledikten sonra öğrencileriyle birlikte dışarı çıkıp Kidron Vadisi'nin ötesine geçti. Orada bir bahçe vardı. İsa'yla öğrencileri bu bahçeye girdiler."},{"n":"2","t":"O'na ihanet eden Yahuda da burayı biliyordu. Çünkü İsa, öğrencileriyle orada sık sık buluşurdu."},{"n":"3","t":"Böylece Yahuda yanına bir bölük askerle başkâhinlerin ve Ferisiler'in* gönderdiği görevlileri alarak oraya geldi. Onların ellerinde fenerler, meşaleler ve silahlar vardı."},{"n":"4","t":"İsa, başına geleceklerin hepsini biliyordu. Öne çıkıp onlara, \"Kimi arıyorsunuz?\" diye sordu."},{"n":"5","t":"\"Nasıralı İsa'yı\" diye karşılık verdiler. İsa onlara, \"Benim\" dedi. O'na ihanet eden Yahuda da onlarla birlikte duruyordu."},{"n":"6","t":"İsa, \"Benim\" deyince gerileyip yere düştüler."},{"n":"7","t":"Bunun üzerine İsa onlara yine, \"Kimi arıyorsunuz?\" diye sordu. \"Nasıralı İsa'yı\" dediler."},{"n":"8","t":"İsa, \"Size söyledim, benim\" dedi. \"Eğer beni arıyorsanız, bunları bırakın gitsinler.\""},{"n":"9","t":"Kendisinin daha önce söylediği, \"Senin bana verdiklerinden hiçbirini yitirmedim\" şeklindeki sözü yerine gelsin diye böyle konuştu."},{"n":"10","t":"Simun Petrus yanında taşıdığı kılıcı çekti, başkâhinin Malkus adındaki kölesine vurup sağ kulağını kopardı."},{"n":"11","t":"İsa Petrus'a, \"Kılıcını kınına koy! Baba'nın bana verdiği kâseden* içmeyeyim mi?\" dedi."},{"n":"12","t":"Bunun üzerine komutanla buyruğundaki asker bölüğü ve Yahudi görevliler İsa'yı tutup bağladılar."},{"n":"13","t":"O'nu önce, o yıl başkâhin olan Kayafa'nın kayınbabası Hanan'a götürdüler."},{"n":"14","t":"Halkın uğruna bir tek adamın ölmesinin daha uygun olacağını Yahudi yetkililere telkin eden Kayafa idi. Petrus'un İlk İnkârı (Mat.26:6970; Mar.14:6668; Luk.22:5557)"},{"n":"15","t":"Simun Petrus'la başka bir öğrenci İsa'nın ardından gidiyorlardı. O öğrenci başkâhinin tanıdığı olduğu için İsa'yla birlikte başkâhinin avlusuna girdi."},{"n":"16","t":"Petrus ise dışarıda, kapının yanında duruyordu. Başkâhinin tanıdığı öğrenci dışarı çıkıp kapıcı kızla konuştu ve Petrus'u içeri getirdi."},{"n":"17","t":"Kapıcı kız Petrus'a, \"Sen de bu adamın öğrencilerinden değil misin?\" diye sordu. Petrus, \"Hayır, değilim\" dedi."},{"n":"18","t":"Hava soğuk olduğu için köleler ve nöbetçiler yaktıkları kömür ateşinin çevresinde durmuş ısınıyorlardı. Petrus da onlarla birlikte ayakta ısınıyordu. Başkâhinin Soruşturması (Mat.26:5966; Mar.14:5564; Luk.22:6671)"},{"n":"19","t":"Başkâhin İsa'ya, öğrencileri ve öğretisiyle ilgili sorular sordu."},{"n":"20","t":"İsa onu şöyle yanıtladı: \"Ben söylediklerimi dünyaya açıkça söyledim. Her zaman bütün Yahudiler'in toplandıkları havralarda ve tapınakta öğrettim. Gizli hiçbir şey söylemedim."},{"n":"21","t":"Beni neden sorguya çekiyorsun? Konuştuklarımı işitenlerden sor. Onlar ne söylediğimi biliyorlar.\""},{"n":"22","t":"İsa bunları söyleyince, yanında duran görevlilerden biri, \"Başkâhine nasıl böyle karşılık verirsin?\" diyerek O'na bir tokat attı."},{"n":"23","t":"İsa ona, \"Eğer yanlış bir şey söyledimse, yanlışımı göster!\" diye yanıtladı. \"Ama söylediklerim doğruysa, niçin bana vuruyorsun?\""},{"n":"24","t":"Bunun üzerine Hanan, O'nu bağlı olarak başkâhin Kayafa'ya gönderdi. Petrus'un İkinci ve Üçüncü İnkârı (Mat.26:7175; Mar.14:6972; Luk.22:5862)"},{"n":"25","t":"Simun Petrus hâlâ ateşin yanında durmuş ısınıyordu. O'na, \"Sen de O'nun öğrencilerinden değil misin?\" dediler. \"Hayır, değilim\" diyerek inkâr etti."},{"n":"26","t":"Başkâhinin kölelerinden biri, Petrus'un, kulağını kestiği adamın akrabasıydı. Bu köle Petrus'a, \"Bahçede, seni O'nunla birlikte görmedim mi?\" diye sordu."},{"n":"27","t":"Petrus yine inkâr etti ve tam o anda horoz öttü. İsa, Vali Pilatus'un Önünde (Mat.27:12,1131; Mar.15:120; Luk.23:15,1325)"},{"n":"28","t":"Sabah erkenden Yahudi yetkililer İsa'yı Kayafa'nın yanından alarak vali konağına götürdüler. Dinsel kuralları bozmamak*fx* ve Fısıh* yemeğini yiyebilmek için kendileri vali konağına girmediler."},{"n":"29","t":"Bunun üzerine Pilatus dışarı çıkıp yanlarına geldi. \"Bu adamı neyle suçluyorsunuz?\" diye sordu."},{"n":"30","t":"Ona şu karşılığı verdiler: \"Bu adam kötülük eden biri olmasaydı, O'nu sana getirmezdik.\""},{"n":"31","t":"Pilatus, \"O'nu siz alın, kendi yasanıza göre yargılayın\" dedi. Yahudi yetkililer, \"Bizim hiç kimseyi ölüm cezasına çarptırmaya yetkimiz yok\" dediler."},{"n":"32","t":"Bu, İsa'nın nasıl öleceğini belirtmek için söylediği sözler yerine gelsin diye oldu."},{"n":"33","t":"Pilatus yine vali konağına girdi. İsa'yı çağırıp O'na, \"Sen Yahudiler'in Kralı mısın?\" diye sordu."},{"n":"34","t":"İsa şöyle karşılık verdi: \"Bunu kendiliğinden mi söylüyorsun, yoksa başkaları mı sana söyledi?\""},{"n":"35","t":"Pilatus, \"Ben Yahudi miyim?\" dedi. \"Seni bana kendi ulusun ve başkâhinlerin teslim ettiler. Ne yaptın?\""},{"n":"36","t":"İsa, \"Benim krallığım bu dünyadan değildir\" diye karşılık verdi. \"Krallığım bu dünyadan olsaydı, yandaşlarım, Yahudi yetkililere teslim edilmemem için savaşırlardı. Oysa benim krallığım buradan değildir.\""},{"n":"37","t":"Pilatus, \"Demek sen bir kralsın, öyle mi?\" dedi. İsa, \"Kral olduğumu sen söylüyorsun\" karşılığını verdi. \"Ben gerçeğe tanıklık etmek için doğdum, bunun için dünyaya geldim. Gerçekten yana olan herkes benim sesimi işitir.\""},{"n":"38","t":"Pilatus O'na, \"Gerçek nedir?\" diye sordu. Bunu söyledikten sonra Pilatus yine dışarıya, Yahudiler'in yanına çıktı. Onlara, \"Ben O'nda hiçbir suç görmüyorum\" dedi."},{"n":"39","t":"\"Ama sizin bir geleneğiniz var, her Fısıh Bayramı'nda sizin için birini salıveriyorum. Yahudiler'in Kralı'nı sizin için salıvermemi ister misiniz?\""},{"n":"40","t":"Onlar yine, \"Bu adamı değil, Barabba'yı isteriz!\" diye bağrıştılar. Oysa Barabba bir hayduttu."}]},{"ch":19,"verses":[{"n":"1","t":"O zaman Pilatus İsa'yı tutup kamçılattı."},{"n":"2","t":"Askerler de dikenlerden bir taç örüp O'nun başına geçirdiler. Sonra O'na mor bir kaftan giydirdiler."},{"n":"3","t":"Önüne geliyor, \"Selam, ey Yahudiler'in Kralı!\" diyor, yüzüne tokat atıyorlardı."},{"n":"4","t":"Pilatus yine dışarı çıktı. Yahudiler'e, \"İşte, O'nu dışarıya, size getiriyorum. O'nda hiçbir suç bulmadığımı bilesiniz\" dedi."},{"n":"5","t":"Böylece İsa, başındaki dikenli taç ve üzerindeki mor kaftanla dışarı çıktı. Pilatus onlara, \"İşte o adam!\" dedi."},{"n":"6","t":"Başkâhinler ve görevliler İsa'yı görünce, \"Çarmıha ger, çarmıha ger!\" diye bağrıştılar. Pilatus, \"O'nu siz alıp çarmıha gerin!\" dedi. \"Ben O'nda bir suç bulamıyorum!\""},{"n":"7","t":"Yahudiler şu karşılığı verdiler: \"Bizim bir yasamız var, bu yasaya göre O'nun ölmesi gerekir. Çünkü kendisinin Tanrı Oğlu olduğunu ileri sürüyor.\""},{"n":"8","t":"Pilatus bu sözü işitince daha çok korktu."},{"n":"9","t":"Yine vali konağına girip İsa'ya, \"Sen nereden geliyorsun?\" diye sordu. İsa ona yanıt vermedi."},{"n":"10","t":"Pilatus, \"Benimle konuşmayacak mısın?\" dedi. \"Seni salıvermeye de, çarmıha germeye de yetkim olduğunu bilmiyor musun?\""},{"n":"11","t":"İsa, \"Sana gökten verilmeseydi, benim üzerimde hiçbir yetkin olmazdı\" diye karşılık verdi. \"Bu nedenle beni sana teslim edenin günahı daha büyüktür.\""},{"n":"12","t":"Bunun üzerine Pilatus İsa'yı salıvermek istedi. Ama Yahudiler, \"Bu adamı salıverirsen, Sezar'ın* dostu değilsin!\" diye bağrıştılar. \"Kral olduğunu ileri süren herkes Sezar'a karşı gelmiş olur.\""},{"n":"13","t":"Pilatus bu sözleri işitince İsa'yı dışarı çıkardı. Taş Döşeme*fx* İbranice'de* Gabbata denilen yerde yargı kürsüsüne oturdu."},{"n":"14","t":"Fısıh Bayramı'na* Hazırlık Günü'ydü*. Saat* on iki sularıydı. Pilatus Yahudiler'e, \"İşte, sizin Kralınız!\" dedi."},{"n":"15","t":"Onlar, \"Yok et O'nu! Yok et, çarmıha ger!\" diye bağrıştılar. Pilatus, \"Kralınızı mı çarmıha gereyim?\" diye sordu. Başkâhinler, \"Sezar'dan başka kralımız yok!\" karşılığını verdiler."},{"n":"16","t":"Bunun üzerine Pilatus İsa'yı, çarmıha gerilmek üzere onlara teslim etti. İsa Çarmıha Geriliyor (Mat.27:3244; Mar.15:2132; Luk.23:2643)"},{"n":"17","t":"Askerler İsa'yı alıp götürdüler. İsa çarmıhını kendisi taşıyıp Kafatası İbranice'de* Golgota denilen yere çıktı."},{"n":"18","t":"Orada O'nu ve iki kişiyi daha çarmıha gerdiler. Biri bir yanda, öbürü öteki yanda, İsa ise ortadaydı."},{"n":"19","t":"Pilatus bir de yafta yazıp çarmıhın üzerine astırdı. Yaftada şöyle yazılıydı: NASIRALI İSA YAHUDİLER'İN KRALI"},{"n":"20","t":"İsa'nın çarmıha gerildiği yer kente yakındı. Böylece İbranice, Latince ve Grekçe yazılan bu yaftayı Yahudiler'in birçoğu okudu."},{"n":"21","t":"Bu yüzden Yahudi başkâhinler Pilatus'a, \"'Yahudiler'in Kralı' diye yazma\" dediler. \"Kendisi, 'Ben Yahudiler'in Kralı'yım dedi' diye yaz.\""},{"n":"22","t":"Pilatus, \"Ne yazdımsa yazdım\" karşılığını verdi."},{"n":"23","t":"Askerler İsa'yı çarmıha gerdikten sonra giysilerini alıp her birine birer pay düşecek biçimde dört parçaya böldüler. Mintanını da aldılar. Mintan boydan boya tek parça dikişsiz bir dokumaydı."},{"n":"24","t":"Birbirlerine, \"Bunu yırtmayalım\" dediler, \"Kime düşecek diye kura çekelim.\" Bu olay, şu Kutsal Yazı yerine gelsin diye oldu: \"Giysilerimi aralarında paylaştılar, Elbisem üzerine kura çektiler.\" Bunları askerler yaptı."},{"n":"25","t":"İsa'nın çarmıhının yanında ise annesi, teyzesi, Klopas'ın karısı Meryem ve Mecdelli Meryem duruyordu."},{"n":"26","t":"İsa, annesiyle sevdiği öğrencinin yakınında durduğunu görünce annesine, \"Anne*fx*, işte oğlun!\" dedi."},{"n":"27","t":"Sonra öğrenciye, \"İşte, annen!\" dedi. O andan itibaren bu öğrenci İsa'nın annesini kendi evine aldı. İsa'nın Ölümü (Mat.27:4556; Mar.15:3341; Luk.23:4449)"},{"n":"28","t":"Daha sonra İsa, her şeyin artık tamamlandığını bilerek Kutsal Yazı yerine gelsin diye, \"Susadım!\" dedi."},{"n":"29","t":"Orada ekşi şarap dolu bir kap vardı. Şaraba batırılmış bir süngeri mercanköşk dalına takarak O'nun ağzına uzattılar."},{"n":"30","t":"İsa şarabı tadınca, \"Tamamlandı!\" dedi ve başını eğerek ruhunu teslim etti."},{"n":"31","t":"Yahudi yetkililer Pilatus'tan çarmıha gerilenlerin bacaklarının kırılmasını ve cesetlerin kaldırılmasını istediler. Hazırlık Günü* olduğundan, cesetlerin Şabat Günü* çarmıhta kalmasını istemiyorlardı. Çünkü o Şabat Günü büyük bayramdı."},{"n":"32","t":"Bunun üzerine askerler gidip birinci adamın, sonra da İsa'yla birlikte çarmıha gerilen öteki adamın bacaklarını kırdılar."},{"n":"33","t":"İsa'ya gelince O'nun ölmüş olduğunu gördüler. Bu yüzden bacaklarını kırmadılar."},{"n":"34","t":"Ama askerlerden biri O'nun böğrünü mızrakla deldi. Böğründen hemen kan ve su aktı."},{"n":"35","t":"Bunu gören adam tanıklık etmiştir ve tanıklığı doğrudur. Doğruyu söylediğini bilir. Siz de iman edesiniz diye tanıklık etmiştir."},{"n":"36","t":"Bunlar, \"O'nun bir tek kemiği kırılmayacak\" diyen Kutsal Yazı'nın yerine gelmesi için oldu."},{"n":"37","t":"Yine başka bir Yazı'da, \"Bedenini deştiklerine bakacaklar\" deniyor. İsa'nın Gömülmesi (Mat.27:5761; Mar.15:4247; Luk.23:5056)"},{"n":"38","t":"Bundan sonra Aramatyalı Yusuf, İsa'nın cesedini kaldırmak için Pilatus'a başvurdu. Yusuf, İsa'nın öğrencisiydi, ama Yahudi yetkililerden korktuğundan bunu gizli tutuyordu. Pilatus izin verince, Yusuf gelip İsa'nın cesedini kaldırdı."},{"n":"39","t":"Daha önce geceleyin İsa'nın yanına gelen Nikodim de otuz litre*fx* kadar karışık mür* ve sarısabır özü alarak geldi."},{"n":"40","t":"İkisi, İsa'nın cesedini alıp Yahudiler'in gömme geleneğine uygun olarak onu baharatla keten bezlere sardılar."},{"n":"41","t":"İsa'nın çarmıha gerildiği yerde bir bahçe, bu bahçenin içinde de henüz hiç kimsenin konulmadığı yeni bir mezar* vardı."},{"n":"42","t":"O gün Yahudiler'in Hazırlık Günü'ydü*. Mezar da yakın olduğundan İsa'yı oraya koydular."}]},{"ch":20,"verses":[{"n":"1","t":"Haftanın ilk günü* erkenden, ortalık daha karanlıkken Mecdelli Meryem mezara gitti. Taşın mezarın girişinden kaldırılmış olduğunu gördü."},{"n":"2","t":"Koşarak Simun Petrus'a ve İsa'nın sevdiği öbür öğrenciye geldi. \"Rab'bi mezardan almışlar, nereye koyduklarını da bilmiyoruz\" dedi."},{"n":"3","t":"Bunun üzerine Petrus'la öteki öğrenci dışarı çıkıp mezara yöneldiler."},{"n":"4","t":"İkisi birlikte koşuyordu. Ama öteki öğrenci Petrus'tan daha hızlı koşarak mezara önce vardı."},{"n":"5","t":"Eğilip içeri baktı, keten bezleri orada serili gördü, ama içeri girmedi."},{"n":"67","t":"Ardından Simun Petrus geldi ve mezara girdi. Orada serili duran bezleri ve İsa'nın başına sarılmış olan peşkiri gördü. Peşkir keten bezlerle birlikte değildi, ayrı bir yerde dürülmüş duruyordu."},{"n":"8","t":"O zaman mezara ilk varan öteki öğrenci de içeri girdi. Olanları gördü ve iman etti."},{"n":"9","t":"İsa'nın ölümden dirilmesi gerektiğini belirten Kutsal Yazı'yı henüz anlamamışlardı. İsa, Mecdelli Meryem'e Görünüyor (Mat.28:910; Mar.16:911)"},{"n":"10","t":"Bundan sonra öğrenciler yine evlerine döndüler."},{"n":"11","t":"Meryem ise mezarın dışında durmuş ağlıyordu. Ağlarken eğilip mezarın içine baktı."},{"n":"12","t":"Beyazlara bürünmüş iki melek gördü; biri İsa'nın cesedinin yattığı yerin başucunda, öteki ayakucunda oturuyordu."},{"n":"13","t":"Meryem'e, \"Kadın, niçin ağlıyorsun?\" diye sordular. Meryem, \"Rabbim'i almışlar\" dedi. \"O'nu nereye koyduklarını bilmiyorum.\""},{"n":"14","t":"Bunları söyledikten sonra arkasına döndü, İsa'nın orada, ayakta durduğunu gördü. Ama O'nun İsa olduğunu anlamadı."},{"n":"15","t":"İsa, \"Kadın, niçin ağlıyorsun?\" dedi. \"Kimi arıyorsun?\" Meryem O'nu bahçıvan sanarak, \"Efendim\" dedi, \"Eğer O'nu sen götürdünse, nereye koyduğunu söyle de gidip O'nu alayım.\""},{"n":"16","t":"İsa ona, \"Meryem!\" dedi. O da döndü, İsa'ya İbranice*, \"Rabbuni!\" dedi. Rabbuni, öğretmenim demektir."},{"n":"17","t":"İsa, \"Bana dokunma!\" dedi. \"Çünkü daha Baba'nın yanına çıkmadım. Kardeşlerime git ve onlara söyle, benim Babam'ın ve sizin Babanız'ın, benim Tanrım'ın ve sizin Tanrınız'ın yanına çıkıyorum.\""},{"n":"18","t":"Mecdelli Meryem öğrencilerin yanına gitti. Onlara, \"Rab'bi gördüm!\" dedi. Sonra Rab'bin kendisine söylediklerini onlara anlattı. İsa Öğrencilerine Görünüyor (Mat.28:1620; Mar.16:1418; Luk.24:3649)"},{"n":"19","t":"Haftanın o ilk günü akşam olunca, öğrencilerin Yahudi yetkililerden korkusu nedeniyle bulundukları yerin kapıları kapalıyken İsa geldi, ortalarında durup, \"Size esenlik olsun!\" dedi."},{"n":"20","t":"Bunu söyledikten sonra onlara ellerini ve böğrünü gösterdi. Öğrenciler Rab'bi görünce sevindiler."},{"n":"21","t":"İsa yine onlara, \"Size esenlik olsun!\" dedi. \"Baba beni gönderdiği gibi, ben de sizi gönderiyorum.\""},{"n":"22","t":"Bunu söyledikten sonra onların üzerine üfleyerek, \"Kutsal Ruh'u alın!\" dedi."},{"n":"23","t":"\"Kimin günahlarını bağışlarsanız, bağışlanmış olur; kimin günahlarını bağışlamazsanız, bağışlanmamış kalır.\" İsa Tomas'a Görünüyor"},{"n":"24","t":"Onikiler'den* biri, \"İkiz*fx*\" diye anılan Tomas, İsa geldiğinde onlarla birlikte değildi."},{"n":"25","t":"Öbür öğrenciler ona, \"Biz Rab'bi gördük!\" dediler. Tomas ise, \"O'nun ellerinde çivilerin izini görmedikçe, çivilerin izine parmağımla dokunmadıkça ve elimi böğrüne sokmadıkça inanmam\" dedi."},{"n":"26","t":"Sekiz gün sonra İsa'nın öğrencileri yine evdeydiler. Tomas da onlarla birlikteydi. Kapılar kapalıyken İsa gelip ortalarında durdu, \"Size esenlik olsun!\" dedi."},{"n":"27","t":"Sonra Tomas'a, \"Parmağını uzat\" dedi, \"Ellerime bak, elini uzat, böğrüme koy. İmansız olma, imanlı ol!\""},{"n":"28","t":"Tomas O'na, \"Rabbim ve Tanrım!\" diye yanıtladı."},{"n":"29","t":"İsa, \"Beni gördüğün için mi iman ettin?\" dedi. \"Görmeden iman edenlere ne mutlu!\""},{"n":"30","t":"İsa, öğrencilerinin önünde, bu kitapta yazılı olmayan başka birçok doğaüstü belirti gerçekleştirdi."},{"n":"31","t":"Ne var ki yazılanlar, İsa'nın, Tanrı'nın Oğlu Mesih* olduğuna iman edesiniz ve iman ederek O'nun adıyla yaşama kavuşasınız diye yazılmıştır."}]},{"ch":21,"verses":[{"n":"12","t":"Bundan sonra İsa Taberiye Gölü'nün kenarında öğrencilerine yine göründü. Bu da şöyle oldu: Simun Petrus, \"İkiz*fx*\" diye anılan Tomas, Celile'nin Kana Köyü'nden Natanel, Zebedi'nin oğulları ve İsa'nın öğrencilerinden iki kişi daha birlikte bulunuyorlardı."},{"n":"3","t":"Simun Petrus ötekilere, \"Ben balık tutmaya gidiyorum\" dedi. Onlar, \"Biz de seninle geliyoruz\" dediler. Dışarı çıkıp tekneye bindiler. Ama o gece bir şey tutamadılar."},{"n":"4","t":"Sabah olurken İsa kıyıda duruyordu. Ne var ki öğrenciler, O'nun İsa olduğunu anlamadılar."},{"n":"5","t":"İsa, \"Çocuklar, balığınız yok mu?\" diye sordu. \"Yok\" dediler."},{"n":"6","t":"İsa, \"Ağı teknenin sağ yanına atın, tutarsınız\" dedi. Bunun üzerine ağı attılar. O kadar çok balık tuttular ki, artık ağı çekemez olmuşlardı."},{"n":"7","t":"İsa'nın sevdiği öğrenci, Petrus'a, \"Bu Rab'dir!\" dedi. Simun Petrus O'nun Rab olduğunu işitince üzerinden çıkarmış olduğu üstlüğü giyip göle atladı."},{"n":"8","t":"Öbür öğrenciler balık dolu ağı çekerek tekneyle geldiler. Çünkü karadan ancak iki yüz arşın*fx* kadar uzaktaydılar."},{"n":"9","t":"Karaya çıkınca orada yanan bir kömür ateşi, ateşin üzerinde balık ve ekmek gördüler."},{"n":"10","t":"İsa onlara, \"Şimdi tuttuğunuz balıklardan getirin\" dedi."},{"n":"11","t":"Simun Petrus tekneye atladı ve tam yüz elli üç iri balıkla yüklü ağı karaya çekti. Bu kadar çok balık olduğu halde ağ yırtılmamıştı."},{"n":"12","t":"İsa onlara, \"Gelin, yemek yiyin\" dedi. Öğrencilerden hiçbiri O'na, \"Sen kimsin?\" diye sormaya cesaret edemedi. Çünkü O'nun Rab olduğunu biliyorlardı."},{"n":"13","t":"İsa gidip ekmeği aldı, onlara verdi. Aynı şekilde balıkları da verdi."},{"n":"14","t":"İşte bu, İsa'nın ölümden dirildikten sonra öğrencilere üçüncü görünüşüydü. İsa ile Petrus"},{"n":"15","t":"Yemekten sonra İsa, Simun Petrus'a, \"Yuhanna oğlu Simun, beni bunlardan daha çok seviyor musun?\" diye sordu. Petrus, \"Evet, ya Rab\" dedi, \"Seni sevdiğimi bilirsin.\" İsa ona, \"Kuzularımı otlat\" dedi."},{"n":"16","t":"İkinci kez yine ona, \"Yuhanna oğlu Simun, beni seviyor musun?\" diye sordu. O da, \"Evet, ya Rab, seni sevdiğimi bilirsin\" dedi. İsa ona, \"Koyunlarımı güt\" dedi."},{"n":"17","t":"Üçüncü kez ona, \"Yuhanna oğlu Simun, beni seviyor musun?\" diye sordu. Petrus kendisine üçüncü kez, \"Beni seviyor musun?\" diye sormasına üzüldü. \"Ya Rab, sen her şeyi bilirsin, seni sevdiğimi de bilirsin\" dedi. İsa ona, \"Koyunlarımı otlat\" dedi."},{"n":"18","t":"\"Sana doğrusunu söyleyeyim, gençliğinde kendi kuşağını kendin bağlar, istediğin yere giderdin. Ama yaşlanınca ellerini uzatacaksın, başkası seni bağlayacak ve istemediğin yere götürecek.\""},{"n":"19","t":"Bunu, Tanrı'yı ne tür bir ölümle yücelteceğini belirtmek için söyledi. Sonra ona, \"Ardımdan gel\" dedi."},{"n":"20","t":"Petrus arkasına döndü, İsa'nın sevdiği öğrencinin kendilerini izlediğini gördü. Bu öğrenci, akşam yemeğinde İsa'nın göğsüne yaslanan ve, \"Ya Rab, sana kim ihanet edecek?\" diye soran öğrencidir."},{"n":"21","t":"Petrus onu görünce İsa'ya, \"Ya Rab, ya bu ne olacak?\" diye sordu."},{"n":"22","t":"İsa, \"Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?\" dedi. \"Sen ardımdan gel!\""},{"n":"23","t":"Bu yüzden kardeşler arasında o öğrencinin ölmeyeceğine dair bir söylenti çıktı. Ama İsa Petrus'a, \"O ölmeyecek\" dememişti. Sadece, \"Ben gelinceye dek onun yaşamasını istiyorsam, bundan sana ne?\" demişti."},{"n":"24","t":"Bütün bunlara tanıklık eden ve bunları yazan öğrenci budur. Onun tanıklığının doğru olduğunu biliyoruz."},{"n":"25","t":"İsa'nın yaptığı daha başka çok şey vardır. Bunlar tek tek yazılsaydı, sanırım yazılan kitaplar dünyaya sığmazdı."}]},{"ch":22,"verses":[{"n":"42","t":"\"Kaya\": Grekçe \"Petros\". 2:4 \"Anne\": Grekçe \"Kadın\". 2:6 \"Seksenle yüz yirmi litre\": Grekçe \"İki üç metritis\" (bkz. Birimler Cetveli). 3:3 \"Yeniden\" ya da \"Yukarıdan\". 3:13 \"Gökten inmiş olan\": Bazı Grekçe elyazmalarında, \"Gökten inmiş ve gökte olan\" diye"},{"n":"34","t":"Birçok Grekçe elyazmasında ayet şöyle devam eder: \"Havuzun çalkanmasını beklerlerdi. Çünkü Rab'bin bir meleği zaman zaman havuzun içine iner, suyu çalkardı. Suyun çalkanmasından sonra havuza ilk giren, tutulduğu herhangi bir hastalıktan kurtulurdu.\" 6:19 \"Üç mil kadar\": Grekçe \"Yirmi beş ile otuz stadion\" bkz. Birimler Cetveli). 6:27 \"Bu onayı vermiştir\" ya da \"Mühür basmıştır\". 6:65 \"Baba'nın bana yöneltmediği hiç kimse bana gelemez\": Grekçe \"Kendisine Baba'dan verilmedikçe hiç kimse bana gelemez\". 7:15 \"Nasıl bu kadar bilgili olabilir?\" ya da \"Kutsal Yazılar'ı nasıl biliyor?\" 7:21 \"Mucize\": Grekçe \"İş\" (bkz. Yu.5: 116). 8:11 Birçok Grekçe elyazmasında 7:538:11 ayetleri"},{"n":"24","t":"\"Benim O olduğuma\": Grekçe \"Ben olduğuma\" (bkz. Çık.3:14). Aynı ifade 28. ve 58. ayetlerde de"},{"n":"44","t":"\"Yalan söylemesi doğaldır\": Grekçe \"Yalan söylediği zaman kendininkilerden söyler\". 9:24 \"Tanrı hakkı için doğruyu söyle\": Grekçe \"Tanrı'ya yücelik ver\". Bu deyim, birine ant içirmek için kullanılırdı (bkz. Yşu.7:19). 11:16 \"İkiz\": Grekçe \"Didimos\". 11:18 \"On beş ok atımı\": Yaklaşık 2.8"},{"n":"3","t":"\"Yarım litre kadar\": Grekçe \"Bir litra\" (bkz. Birimler Cetveli). 12:25 \"Canını gözden çıkaran\": Grekçe \"Canından nefret eden\". 12:31 \"Bu dünyanın egemeni\":"},{"n":"18","t":"\"Bana ihanet etti\": Grekçe \"Bana karşı ökçesini kaldırdı\". 13:19 \"Benim O olduğuma\": Grekçe \"Ben olduğuma\" (bkz. Çık.3:14). 14:30 \"Bu dünyanın egemeni\":"},{"n":"11","t":"\"Bu dünyanın egemeni\":"},{"n":"12","t":"\"Mahva giden adamdan\": Grekçe \"Mahv oğlundan\". 17:19 \"Adıyorum\" ya da \"Kutsal kılıyorum\". 18:28 \"Dinsel kuralları bozmamak\": Grekçe \"Kirlenmemek\". Yahudi olmayanlarla yakın ilişkilerde bulunan Yahudiler dinsel açıdan kirli sayılır, kutsal Fısıh Bayramı'nı"},{"n":"13","t":"\"Taş Döşeme\": Yeruşalim'deki vali konağının taş döşenmiş"},{"n":"26","t":"\"Anne\": Grekçe \"Kadın\". 19:39 \"Otuz litre\": Grekçe \"Yüz litra\" (bkz. Birimler Cetveli). 20:24 \"İkiz\": Grekçe \"Didimos\". 21:12 \"İkiz\": Grekçe \"Didimos\". 21:8 \"İki yüz arşın\": Yaklaşık 105 m._"}]}]}];
